module.exports = [{"id":"cat-pol-7a-1-1","title":"第1课 开启初中生活","subtitle":"七年级上册 · 第一单元 少年有梦","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 少年有梦"},{"k":"课题","v":"第1课 开启初中生活"},{"k":"框题","v":"奏响中学序曲 / 规划初中生活"}]},{"type":"note","title":"本课在单元中的位置","text":"中学时代是人生发展的一个新阶段：认识自己、学会学习、带着梦想努力前行，既是初中三年成长的起点，也是中考考查「认识自我」「学会学习」等成长类试题的教材依据。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["奏响中学序曲","规划初中生活"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"中学时代是人生发展的一个新阶段，中学时代见证着一个人从少年到青年的生命进阶，为我们的一生奠定重要基础。","explain":"常在选择题中问「对中学时代的认识」，也在材料题中问「进入初中意味着什么」。就写这两句规范表述，只写「中学很重要、要好好珍惜」不得分。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["中学时代是人生发展的一个新阶段，为我们的一生奠定重要基础。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["把欣赏自己当成骄傲自大，认为「欣赏自己就是只看自己的优点、不接受任何批评」。","欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定；骄傲自大是只看到自己的长处、目中无人。","选择题最爱用「骄傲自大」「目中无人」替换「欣赏自己」设错，二者性质完全不同。"],["认为「学习就是在学校里读书考试，走上社会就不用学习了」。","学习不仅仅局限在学校，我们所看、所听、所尝试、所接触，都可以是学习；学习伴随我们成长，是终身的过程。","教材明确「学习不仅仅局限在学校」，此类绝对化、封闭化的说法在选择题中都是错的。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["认识自我类情境题","以填写「自我认识卡片」「同学互评」「成长手册评语」等情境切入，考查认识自己的途径与如何正确对待他人评价。答题要点：自我评价（自我观察和分析、与他人比较）＋他人评价（重视但不盲从、客观冷静分析）。"],["学会学习类建议题","以学习方法交流、自主学习、参加社团等情境考查「怎样学会学习」。作答必须落到「发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式」三个规范短语，每条尽量结合材料举例。"],["梦想与努力的认识题","以榜样人物事迹作材料，问「少年的梦想为什么与时代的脉搏紧密相连」。落脚点：把个人梦想与中国梦结合起来，靠努力与坚持实现梦想。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 少年有梦：开启初中生活·正确认识自我·梦想始于当下","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-1-q1","type":"choice","stem":"「中学时代是人生发展的一个新阶段。」对这句话理解正确的是","answer":"B","explain":"B 与教材表述一致。A 夸大了中学时代的作用，「最重要、决定命运」属于绝对化表述；C 错误，中学阶段我们仍需要父母、老师的帮助与引导；D 错误，中学时代是人生发展的新阶段，见证从少年到青年的生命进阶。","options":["中学时代是我们一生中最重要、决定命运的时期","中学时代见证着一个人从少年到青年的生命进阶，为我们的一生奠定重要基础","进入中学，我们就完全独立了，不再需要父母和老师的帮助","中学时代只是小学的简单延续，对我们的成长影响不大"],"difficulty":1,"tags":["中学时代"]},{"id":"pol-growth-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中学时代是人生发展的一个新阶段，中学时代见证着一个人从少年到青年的生命进阶，为我…\n② 少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分；努…\n③ 学会学习，需要发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式。\n④ 把欣赏自己当成骄傲自大，认为「欣赏自己就是只看自己的优点、不接受任何批评」。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——选择题最爱用「骄傲自大」「目中无人」替换「欣赏自己」设错，二者性质完全不同；正确表述应为：欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定；骄傲自大是只看到自己的长处、目中无人。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["少年有梦：开启初中生活·正确认识自我·梦想始于当下"]},{"id":"pol-growth-1-q2","type":"choice","stem":"下列对学习的认识正确的是","answer":"D","explain":"D 是教材关于学习体验的基本结论。A 错在把学习局限在学校，学习不仅仅局限在学校，是终身的过程；B 忽视科学学习方法的重要意义；C 否认合作学习等不同学习方式的价值。","options":["学习只是在学校里读书、听课和考试，离开学校就不用学习了","只要考试成绩好就说明会学习，学习方法无关紧要","学习只能靠自己埋头苦读，不需要与他人合作","学习中有快乐，也有辛苦，是一个苦乐交织的过程"],"difficulty":1,"tags":["学会学习"]},{"id":"cat-pol-7a-1-1-short","type":"short","stem":"某班围绕「开启初中生活」开展主题探究活动，围绕「奏响中学序曲」、「规划初中生活」。请运用本课所学，谈谈你的认识。","answer":"中学时代是人生发展的一个新阶段，中学时代见证着一个人从少年到青年的生命进阶，为我们的一生奠定重要基础。","explain":"","rubric":["中学时代是人生发展的一个新阶段，中学时代见证着一个人从少年到青年的生命进阶，为我…"],"tags":["开启初中生活"]},{"id":"pol-growth-1-q3","type":"choice","stem":"小丽每周写日记回顾自己的表现，发现自己做事比以前更有条理、也更会安排时间了。小丽认识自己的途径是","answer":"A","explain":"通过自我观察和分析、与他人比较来认识自己，属于自我评价；他人评价是别人（老师、同学、父母）对我们的态度和看法。题干中小丽是通过写日记反思认识自己，故选 A。","options":["自我评价","他人评价","心理测评","老师的观察"],"difficulty":1,"tags":["认识自己","自我评价"]}]},{"id":"cat-pol-7a-1-2","title":"第2课 正确认识自我","subtitle":"七年级上册 · 第一单元 少年有梦","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 少年有梦"},{"k":"课题","v":"第2课 正确认识自我"},{"k":"框题","v":"认识自己 / 做更好的自己"}]},{"type":"note","title":"本课在单元中的位置","text":"中学时代是人生发展的一个新阶段：认识自己、学会学习、带着梦想努力前行，既是初中三年成长的起点，也是中考考查「认识自我」「学会学习」等成长类试题的教材依据。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["认识自己","做更好的自己"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"认识自己可以通过自我评价和他人评价两条途径；正确认识自己，可以促进自我发展，也可以促进与他人的交往。","explain":"选择题常考「通过自我观察和分析、与他人比较」属于哪种途径；问「怎样正确对待他人评价」要答「重视他人的态度与评价，但也要客观冷静分析，既不能盲从，也不能忽视」。"},{"level":"次重点","text":"接纳自己需要接纳自己的全部，既接纳自己的优点，也接纳自己的不完美；欣赏自己的独特、优点、努力和为他人的奉献。","explain":"两条常被互换设错：接纳自己是「接受全部」，欣赏自己是「为自己鼓掌」。选项里出现「只接纳优点」「欣赏自己就是骄傲自大」都是错的。"},{"level":"次重点","text":"做更好的自己，需要扬长避短、主动改正缺点、不断激发自己的潜能。","explain":"「怎样激发潜能」的标准答法：珍视自己的兴趣爱好，专注自己喜爱的领域；广泛参与多方面的活动，发现他人和社会对自己的需要；通过积极合作，与他人共同完成任务。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["他人评价是我们认识自己的一面镜子，我们要重视他人的态度与评价，但也要客观冷静分析，既不能盲从，也不能忽视。","做更好的自己，需要扬长避短、主动改正缺点、不断激发自己的潜能。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「他人评价必须完全听从」，或者反过来认为「他人的评价与自己无关」。","他人评价是我们认识自己的一面镜子，我们要重视他人的态度与评价，但也要客观冷静分析，既不能盲从，也不能忽视。","两种极端表述都错，正确态度是「重视＋客观冷静分析」，这也是材料题给分点。"],["把欣赏自己当成骄傲自大，认为「欣赏自己就是只看自己的优点、不接受任何批评」。","欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定；骄傲自大是只看到自己的长处、目中无人。","选择题最爱用「骄傲自大」「目中无人」替换「欣赏自己」设错，二者性质完全不同。"]]},{"type":"table","title":"接纳自己与欣赏自己：一字之差，两回事（同一课内的概念辨析）（本单元概念对比）","head":["比较项","接纳自己","欣赏自己"],"rows":[["对象","自己的全部：优点与不完美、性格与外貌、现在与过去","自己的独特、优点、努力以及为他人的奉献"],["心态要求","需要乐观的心态，更需要勇气和智慧","为自己鼓掌，自我鼓励与自我肯定"],["容易设错的说法","「只接纳自己的优点」（错）","「欣赏自己就是骄傲自大」（错）"],["共同指向","都是正确认识自己、做更好的自己的要求","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["认识自我类情境题","以填写「自我认识卡片」「同学互评」「成长手册评语」等情境切入，考查认识自己的途径与如何正确对待他人评价。答题要点：自我评价（自我观察和分析、与他人比较）＋他人评价（重视但不盲从、客观冷静分析）。"],["学会学习类建议题","以学习方法交流、自主学习、参加社团等情境考查「怎样学会学习」。作答必须落到「发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式」三个规范短语，每条尽量结合材料举例。"],["梦想与努力的认识题","以榜样人物事迹作材料，问「少年的梦想为什么与时代的脉搏紧密相连」。落脚点：把个人梦想与中国梦结合起来，靠努力与坚持实现梦想。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 少年有梦：开启初中生活·正确认识自我·梦想始于当下","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-1-m1-q1","type":"short","stem":"（1）结合材料一，说说小华是通过哪些途径认识自己的，他应该怎样正确对待老师的评语？（4 分）","answer":"途径：通过自我评价认识自己，他观察到自己数学成绩不如同学、不敢举手回答问题；通过他人评价认识自己，老师的成长手册评语就是一面镜子。正确对待他人评价：重视老师的评语，客观冷静地分析，既不盲从，也不忽视；把老师的肯定作为鼓励，把「更大胆地表达自己」作为改进方向，主动改正自己的不足。","explain":"","tags":["认识自己","他人评价"],"rubric":["答出自我评价（自我观察和分析、与他人比较）","答出他人评价（老师的评语是一面镜子）","答出重视他人评价并客观冷静分析","答出既不盲从也不忽视，把评语转化为改进方向"]},{"id":"pol-growth-1-m1-q3","type":"short","stem":"（3）结合材料三，谈谈小华怎样才能把梦想变成现实、做更好的自己。（6 分）","answer":"①梦想的实现需要努力，努力是梦想与现实之间的桥梁，要把梦想落实到每天的具体行动中，如每周坚持练画、记录进步；②少年的梦想应与个人的人生目标紧密相连，与时代的脉搏紧密相连，把成为设计师的个人梦想与国家发展需要结合起来；③做更好的自己，需要扬长避短，发挥自己的兴趣特长；需要主动改正缺点；需要不断激发自己的潜能，珍视自己的兴趣爱好、专注自己喜爱的领域，广泛参与多方面的活动，通过积极合作与他人共同完成任务。","explain":"","tags":["少年梦想","做更好的自己","激发潜能"],"rubric":["答出努力是梦想与现实之间的桥梁","答出落实到具体行动、坚持不懈","答出梦想与个人人生目标、时代脉搏、中国梦相连","答出扬长避短或主动改正缺点","答出激发潜能的具体做法"]},{"id":"pol-growth-1-q3","type":"choice","stem":"小丽每周写日记回顾自己的表现，发现自己做事比以前更有条理、也更会安排时间了。小丽认识自己的途径是","answer":"A","explain":"通过自我观察和分析、与他人比较来认识自己，属于自我评价；他人评价是别人（老师、同学、父母）对我们的态度和看法。题干中小丽是通过写日记反思认识自己，故选 A。","options":["自我评价","他人评价","心理测评","老师的观察"],"difficulty":1,"tags":["认识自己","自我评价"]},{"id":"pol-growth-1-q4","type":"choice","stem":"面对同学「你太内向了」的评价，下列做法最恰当的是","answer":"C","explain":"他人评价是我们认识自己的一面镜子，我们要重视他人的态度与评价，但也要客观冷静分析，既不能盲从，也不能忽视。A、D 是拒绝他人评价，B 是盲从，都不可取。","options":["当场反驳，认为同学是在故意贬低自己","完全听从同学的看法，从此不敢在同学面前说话","客观冷静地分析，既重视同学的看法，又不因此否定自己","不予理睬，认为别人的评价与自己无关"],"difficulty":2,"tags":["他人评价","认识自己"]},{"id":"pol-growth-1-q5","type":"choice","stem":"下列做法体现「欣赏自己」的是","answer":"B","explain":"欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定，B 符合。A 是骄傲自大、自以为是；C 是不能接纳自己；D 是放任缺点，都不属于欣赏自己。","options":["小刚认为自己什么都比同学强，从不接受别人的意见","小美看到自己做事细心、乐于帮助同学，为此感到自豪，并继续努力","小明觉得自己的身高不如同学，非常自卑，不愿参加集体活动","小强认为自己的缺点是天生的，没有必要改正"],"difficulty":2,"tags":["欣赏自己","接纳自己"]},{"id":"pol-growth-1-q6","type":"choice","stem":"做更好的自己，需要我们不断激发自己的潜能。下列做法可取的是","answer":"D","explain":"激发潜能的方法包括：珍视自己的兴趣爱好、专注自己喜爱的领域；广泛参与多方面的活动，发现他人和社会对自己的需要；通过积极合作，与他人共同完成任务。D 符合。A 过于封闭，B 放弃了兴趣这一潜能来源，C 忽视自身实际。","options":["只专注于自己已经擅长的领域，不再接触新事物","把全部时间都用在学习上，放弃所有兴趣爱好","完全照搬成绩好的同学的做法，不加选择","珍视自己的兴趣爱好、专注自己喜爱的领域，并广泛参与多方面的活动"],"difficulty":2,"tags":["激发潜能","做更好的自己"]}]},{"id":"cat-pol-7a-1-3","title":"第3课 梦想始于当下","subtitle":"七年级上册 · 第一单元 少年有梦","grade":"7a","tags":["七年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第一单元 少年有梦"},{"k":"课题","v":"第3课 梦想始于当下"},{"k":"框题","v":"做有梦想的少年 / 学习成就梦想"}]},{"type":"note","title":"本课在单元中的位置","text":"中学时代是人生发展的一个新阶段：认识自己、学会学习、带着梦想努力前行，既是初中三年成长的起点，也是中考考查「认识自我」「学会学习」等成长类试题的教材依据。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["做有梦想的少年","学习成就梦想"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分；努力是梦想与现实之间的桥梁。","explain":"以榜样人物事迹作材料时，落脚点一定是「把个人梦想与国家和民族的梦想结合起来」「用努力把梦想变成现实」。凡答「梦想靠运气」「只要想就能实现」都错。"},{"level":"重点","text":"学会学习，需要发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式。","explain":"材料题问「给小华提学习建议」时按这三点分条作答，每条必须出现「兴趣」「学习方法」「学习方式」这些规范词；写成「多做题、多背书、少玩手机」拿不到分。"},{"level":"次重点","text":"接纳自己需要接纳自己的全部，既接纳自己的优点，也接纳自己的不完美；欣赏自己的独特、优点、努力和为他人的奉献。","explain":"两条常被互换设错：接纳自己是「接受全部」，欣赏自己是「为自己鼓掌」。选项里出现「只接纳优点」「欣赏自己就是骄傲自大」都是错的。"},{"level":"了解","text":"学习不仅仅局限在学校，我们所看、所听、所尝试、所接触，都可以是学习；学习中有快乐，也有辛苦，是一个苦乐交织的过程。","explain":"作为背景判断出现：只要题干说「离开学校就不用学习了」「学习只有痛苦」，该说法即为错误。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分；努力是梦想与现实之间的桥梁。","学会学习，需要发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把欣赏自己当成骄傲自大，认为「欣赏自己就是只看自己的优点、不接受任何批评」。","欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定；骄傲自大是只看到自己的长处、目中无人。","选择题最爱用「骄傲自大」「目中无人」替换「欣赏自己」设错，二者性质完全不同。"],["认为「学习就是在学校里读书考试，走上社会就不用学习了」。","学习不仅仅局限在学校，我们所看、所听、所尝试、所接触，都可以是学习；学习伴随我们成长，是终身的过程。","教材明确「学习不仅仅局限在学校」，此类绝对化、封闭化的说法在选择题中都是错的。"]]},{"type":"table","title":"接纳自己与欣赏自己：一字之差，两回事（同一课内的概念辨析）（本单元概念对比）","head":["比较项","接纳自己","欣赏自己"],"rows":[["对象","自己的全部：优点与不完美、性格与外貌、现在与过去","自己的独特、优点、努力以及为他人的奉献"],["心态要求","需要乐观的心态，更需要勇气和智慧","为自己鼓掌，自我鼓励与自我肯定"],["容易设错的说法","「只接纳自己的优点」（错）","「欣赏自己就是骄傲自大」（错）"],["共同指向","都是正确认识自己、做更好的自己的要求","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["认识自我类情境题","以填写「自我认识卡片」「同学互评」「成长手册评语」等情境切入，考查认识自己的途径与如何正确对待他人评价。答题要点：自我评价（自我观察和分析、与他人比较）＋他人评价（重视但不盲从、客观冷静分析）。"],["学会学习类建议题","以学习方法交流、自主学习、参加社团等情境考查「怎样学会学习」。作答必须落到「发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式」三个规范短语，每条尽量结合材料举例。"],["梦想与努力的认识题","以榜样人物事迹作材料，问「少年的梦想为什么与时代的脉搏紧密相连」。落脚点：把个人梦想与中国梦结合起来，靠努力与坚持实现梦想。"]]},{"type":"quote","text":"【材料一】小华的自述：进入初中后，我发现自己的数学成绩不如同学，上课也不敢举手回答问题，总觉得别人都比自己强。老师在成长手册上给我写下评语：「你做事认真、有责任感，若能更大胆地表达自己的想法，你会更出色。」\n【材料二】小华与同桌的对话。同桌说：「我每天学习到很晚，成绩却上不去。」小华回答：「我试过用思维导图梳理知识、和同学互相讲解，还参加了学校的科技创新社团，觉得学得有意思多了。」\n【材料三】小华的周记：我喜欢画画，也想成为一名设计师。老师说，梦想需要用努力去实现。我打算每周坚持练画三次，把每一点进步都记下来。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 少年有梦：开启初中生活·正确认识自我·梦想始于当下","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-1-m1-q2","type":"short","stem":"（2）材料二中小华的学习经验给你什么启示？请就「学会学习」向同桌提出三条建议。（6 分）","answer":"启示：学习中有辛苦也有快乐，是一个苦乐交织的过程，不能只靠拼时间，要学会学习。建议：①发现并保持学习兴趣，把学习和自己的兴趣结合起来，觉得「学得有意思」才学得久；②掌握科学的学习方法，如用思维导图梳理知识、整理错题、及时复习、和同学互相讲解；③善于运用不同的学习方式，如合作学习、参加社团在实践中学、借助网络等多种资源学习。","explain":"","tags":["学会学习","学习方法"],"rubric":["答出学习是苦乐交织的过程、不能只靠拼时间","写出「发现并保持学习兴趣」并结合材料","写出「掌握科学的学习方法」并举例","写出「善于运用不同的学习方式」并举例","建议具体、可操作"]},{"id":"pol-growth-1-m1-q3","type":"short","stem":"（3）结合材料三，谈谈小华怎样才能把梦想变成现实、做更好的自己。（6 分）","answer":"①梦想的实现需要努力，努力是梦想与现实之间的桥梁，要把梦想落实到每天的具体行动中，如每周坚持练画、记录进步；②少年的梦想应与个人的人生目标紧密相连，与时代的脉搏紧密相连，把成为设计师的个人梦想与国家发展需要结合起来；③做更好的自己，需要扬长避短，发挥自己的兴趣特长；需要主动改正缺点；需要不断激发自己的潜能，珍视自己的兴趣爱好、专注自己喜爱的领域，广泛参与多方面的活动，通过积极合作与他人共同完成任务。","explain":"","tags":["少年梦想","做更好的自己","激发潜能"],"rubric":["答出努力是梦想与现实之间的桥梁","答出落实到具体行动、坚持不懈","答出梦想与个人人生目标、时代脉搏、中国梦相连","答出扬长避短或主动改正缺点","答出激发潜能的具体做法"]},{"id":"pol-growth-1-q2","type":"choice","stem":"下列对学习的认识正确的是","answer":"D","explain":"D 是教材关于学习体验的基本结论。A 错在把学习局限在学校，学习不仅仅局限在学校，是终身的过程；B 忽视科学学习方法的重要意义；C 否认合作学习等不同学习方式的价值。","options":["学习只是在学校里读书、听课和考试，离开学校就不用学习了","只要考试成绩好就说明会学习，学习方法无关紧要","学习只能靠自己埋头苦读，不需要与他人合作","学习中有快乐，也有辛苦，是一个苦乐交织的过程"],"difficulty":1,"tags":["学会学习"]},{"id":"pol-growth-1-q5","type":"choice","stem":"下列做法体现「欣赏自己」的是","answer":"B","explain":"欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定，B 符合。A 是骄傲自大、自以为是；C 是不能接纳自己；D 是放任缺点，都不属于欣赏自己。","options":["小刚认为自己什么都比同学强，从不接受别人的意见","小美看到自己做事细心、乐于帮助同学，为此感到自豪，并继续努力","小明觉得自己的身高不如同学，非常自卑，不愿参加集体活动","小强认为自己的缺点是天生的，没有必要改正"],"difficulty":2,"tags":["欣赏自己","接纳自己"]},{"id":"pol-growth-1-q6","type":"choice","stem":"做更好的自己，需要我们不断激发自己的潜能。下列做法可取的是","answer":"D","explain":"激发潜能的方法包括：珍视自己的兴趣爱好、专注自己喜爱的领域；广泛参与多方面的活动，发现他人和社会对自己的需要；通过积极合作，与他人共同完成任务。D 符合。A 过于封闭，B 放弃了兴趣这一潜能来源，C 忽视自身实际。","options":["只专注于自己已经擅长的领域，不再接触新事物","把全部时间都用在学习上，放弃所有兴趣爱好","完全照搬成绩好的同学的做法，不加选择","珍视自己的兴趣爱好、专注自己喜爱的领域，并广泛参与多方面的活动"],"difficulty":2,"tags":["激发潜能","做更好的自己"]},{"id":"pol-growth-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中学时代是人生发展的一个新阶段，中学时代见证着一个人从少年到青年的生命进阶，为我…\n② 少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分；努…\n③ 学会学习，需要发现并保持学习兴趣、掌握科学的学习方法、善于运用不同的学习方式。\n④ 把欣赏自己当成骄傲自大，认为「欣赏自己就是只看自己的优点、不接受任何批评」。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——选择题最爱用「骄傲自大」「目中无人」替换「欣赏自己」设错，二者性质完全不同；正确表述应为：欣赏自己是欣赏自己的独特、优点、努力和为他人的奉献，是自我鼓励与自我肯定；骄傲自大是只看到自己的长处、目中无人。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["少年有梦：开启初中生活·正确认识自我·梦想始于当下"]}]},{"id":"cat-pol-7a-2-1","title":"第4课 幸福和睦的家庭","subtitle":"七年级上册 · 第二单元 成长的时空","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 成长的时空"},{"k":"课题","v":"第4课 幸福和睦的家庭"},{"k":"框题","v":"家的意味 / 让家更美好"}]},{"type":"note","title":"本课在单元中的位置","text":"友谊是平等的、双向的、不能没有原则的珍贵关系；学会建立和呵护友谊、理性对待网上交友，是中考人际交往类试题与价值观判断题最常出现的情境。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["家的意味","让家更美好"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"孝亲敬长是中华民族的传统美德，也是每个中国公民的法定义务；尽孝在当下，要尊敬父母长辈、倾听他们的意见、以行动表达感恩。","explain":"原因答「传统美德＋法定义务」（我国宪法规定，成年子女有赡养扶助父母的义务），做法答「尽孝在当下＋从现在和小事做起」。答「等长大挣钱了再孝敬」是常见错误。"},{"level":"次重点","text":"家是我们身心的寄居之所，是我们心灵的港湾；在中国人的心目中，家是代代传承、血脉相连的生活共同体。","explain":"选择题常借名言（如「家和万事兴」）考查对「家」的理解，要点是「不只是居住场所，更是情感的归宿与精神的依托」。"},{"level":"次重点","text":"进入初中后，我们与父母之间有时会产生冲突（爱的碰撞），这往往与我们的独立意识增强、渴望被尊重，以及双方在观念和沟通方式上的差异有关。","explain":"问「亲子冲突的原因」：青少年独立意识增强、希望父母尊重自己的独立和自主；父母出于关爱管理较细；双方缺乏有效沟通。答「说明父母不爱我了」是根本性错误。"},{"level":"次重点","text":"化解亲子冲突需要双方的努力：子女要理解父母的爱，主动沟通、换位思考、控制情绪、注意语气和态度，选择合适的时机与方式；构建和谐家庭需要家庭成员之间和睦相处、相互理解、信任、体谅和包容。","explain":"材料题问「怎样化解与父母的矛盾」，按「理解—沟通—行动」三层作答，忌只写「多沟通」三个字。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["孝亲敬长是中华民族的传统美德，也是每个中国公民的法定义务；尽孝在当下，要从现在做起、从小事做起。","家是我们身心的寄居之所，是我们心灵的港湾；构建和谐家庭需要家庭成员相互理解、信任、体谅和包容。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「父母和我们发生冲突，说明父母不再爱我们了」。","亲子冲突是成长中难以回避的问题，往往源于独立意识增强与双方在观念、沟通方式上的差异；冲突中父母的严格要求多数是关爱的表现，需要双方相互理解、加强沟通。","把冲突归因于「父母不爱我」既违背事实也背离亲情之爱的教材立场，是材料题中常被要求辨析的错误观点。"],["认为「孝亲敬长就是父母说什么就做什么，子女不能有自己的想法」。","孝亲敬长要尊敬父母长辈、倾听他们的意见、体谅他们的辛劳，但也要明辨是非；对父母不合理甚至违法的要求，要耐心说明理由、进行劝告，不能盲目服从。","孝不是盲从（愚孝），这是价值观判断的关键分界，也是「怎样孝敬父母」类试题的加分点。"]]},{"type":"table","title":"与老师沟通和与父母沟通（同一沟通能力在两种关系中的运用）（本单元概念对比）","head":["比较项","师生交往","亲子沟通"],"rows":[["关系基础","彼此尊重是我们与老师建立良好关系的开始","孝亲敬长是传统美德与法定义务，爱是亲子关系的基石"],["常见摩擦","被老师批评后不服气、不愿与老师交流","因学习、交友、使用手机等问题与父母意见不合"],["化解方法","自我反思、相信善意、坦诚相待、求同存异，主动关心老师","主动沟通、换位思考、控制情绪、注意语气与态度、选择合适时机与方式"],["共同点","都要主动沟通、彼此尊重、换位思考，用行动赢得理解","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["友谊澄清类情境判断题","给出「朋友要我帮忙作弊」「朋友和别人竞争」「朋友犯错要我保密」等情境，判断哪种做法正确。判分口诀：友谊是平等的、双向的；友谊不能没有原则；竞争并不必然伤害友谊。"],["网上交友的安全教育题","以网友索要个人信息、约见面、诱导转账等情境考查网上交友的注意事项，答案必须包含「理性辨别、慎重选择」「增强自我保护意识」「不轻易透露个人信息」「及时告诉父母、老师或报警」等规范表述。"],["呵护友谊的做法题","问「与朋友发生矛盾后怎么办」，按「用心关怀对方—学会尊重对方—正确处理冲突—正确对待受到的伤害」四点作答，处理冲突再补上保持冷静、坦诚交流、及时处理、勇于承担责任、换位思考。"]]},{"type":"quote","text":"【材料一】小刚上课时偷偷看课外书，被老师发现后批评了几句。小刚觉得自己只是「放松一下」，心里很不服气，一整天都没和老师说话。\n【材料二】放学回家，妈妈问小刚作业写完没有，并说要检查他的手机。小刚大声说：「我已经长大了，你们不要什么都管！」说完就摔门进了房间。事后他在日记里写道：我知道妈妈是为我好，可我就是不想被管着……\n【材料三】班主任在班会上说：「孝亲敬长是中华民族的传统美德，也是我们每个公民的法定义务。孝敬不必等到将来挣了钱，现在给父母倒一杯水、认真听他们把话说完，都是孝。」","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 友谊之树常青：建立与呵护友谊·网上交友的智慧","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-2"},{"t":"专题精讲 · 幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-3"},{"t":"专题精讲 · 在集体中成长：集体的力量·集体生活成就我·共建美好集体","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-3-m1-q2","type":"short","stem":"（2）材料二中小刚与妈妈之间发生了冲突。请分析产生这种冲突的原因，并谈谈小刚应该怎么做。（6 分）","answer":"原因：①进入初中后，小刚的独立意识不断增强，希望父母尊重自己的独立和自主，不希望父母过多干涉自己的生活；②妈妈出于关心和担心，对小刚的学习和生活管理较细，双方在观念和沟通方式上存在差异；③小刚没有控制好自己的情绪，也没有主动与妈妈沟通，说话方式和态度不当，使冲突升级。做法：①理解妈妈的严格要求源于关爱，主动与妈妈沟通，说明自己的想法；②换位思考，控制情绪，注意语气和态度，选择合适的时间与方式交流；③用行动让父母放心，如按计划完成作业、主动汇报学习和交友情况，争取父母的理解与尊重。","explain":"","tags":["亲情之爱","亲子冲突","沟通"],"rubric":["答出独立意识增强、渴望被尊重（青春期特点）","答出父母关爱与双方观念、沟通方式的差异","答出小刚未控制情绪、缺乏主动沟通","答出主动沟通、换位思考、控制情绪、注意语气态度","答出用行动让父母放心"]},{"id":"pol-growth-3-m1-q3","type":"short","stem":"（3）结合材料三，说说我们为什么要孝亲敬长，以及怎样做到「尽孝在当下」。（4 分）","answer":"原因：孝亲敬长是中华民族的传统美德，在中国人的家庭文化中「孝」是重要的精神内涵；孝亲敬长也是每个中国公民的法定义务（我国宪法规定，成年子女有赡养扶助父母的义务）。做法：尽孝在当下，从现在做起、从小事做起——尊敬父母长辈，认真倾听他们的意见；体谅父母的辛劳，主动分担家务；以恰当方式表达感恩，与父母一起建设和谐家庭。","explain":"","tags":["孝亲敬长","法定义务"],"rubric":["答出孝亲敬长是中华民族的传统美德","答出孝亲敬长也是公民的法定义务","答出尽孝在当下、从现在和小事做起","答出具体行动（倾听、分担家务、表达感恩）"]},{"id":"pol-growth-3-q4","type":"choice","stem":"关于孝敬父母长辈，下列说法正确的是","answer":"B","explain":"B 是教材的规范表述。A 忽视了尽孝在当下、从现在和小事做起；C 把孝误解为盲从，对父母不合理的要求应当劝告；D 把孝简化为物质给予，忽视了尊敬、倾听与精神关怀。","options":["孝敬父母是将来的事，现在只要把学习搞好就行","孝亲敬长是中华民族的传统美德，也是每个中国公民的法定义务，尽孝在当下","父母说的都是对的，我们必须无条件服从","只要给父母足够的钱，就算孝敬父母了"],"difficulty":2,"tags":["孝亲敬长"]},{"id":"pol-growth-3-q5","type":"choice","stem":"「家是我们身心的寄居之所，是我们心灵的港湾。」这句话说明","answer":"A","explain":"家是我们身心的寄居之所，也是我们心灵的港湾，是代代传承、血脉相连的生活共同体，亲情是我们心灵的依靠。B 忽视了家的情感意义；C 把家的形式绝对化；D 把幸福等同于物质条件。","options":["家不仅是我们居住的场所，更是我们情感的归宿和精神的依托","家只是一个居住的场所，与情感无关","只有和父母住在一起才算是家","家里的物质条件越好，家庭就越幸福"],"difficulty":1,"tags":["家的意味"]},{"id":"pol-growth-3-q6","type":"choice","stem":"与父母发生矛盾时，下列做法有助于化解矛盾的是","answer":"A","explain":"化解亲子冲突要理解父母的爱，主动沟通、换位思考、控制情绪、注意语气和态度，选择合适的时机与方式。B、C、D 都是回避沟通或激化矛盾的做法，还可能带来安全风险。","options":["换位思考，控制情绪，选择合适的时间与方式与父母沟通","关上房门拒绝交流，等父母先低头","离家出走，让父母着急","把不满情绪发在社交平台上，让同学来评理"],"difficulty":1,"tags":["亲子冲突","沟通","处理冲突"]},{"id":"pol-growth-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 教师作为教育工作者，是人类文明的主要传承者之一，承担着教书育人的使命；新时代的好…\n② 教与学是师生相互陪伴、相互促进、共同成长的过程（教学相长）；面对老师的引领和指导…\n③ 老师的表扬意味着肯定、鼓励和期待，激励我们更好地学习和发展；老师的批评意味着关心…\n④ 把老师的批评理解为「故意刁难」，于是顶撞老师、疏远老师，或者从此不听他的课。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——情境题里凡出现「顶撞老师」「当面指责老师」「从此不理老师」的做法都错，正确路径是「接受内容—反省改进—主动沟通」；正确表述应为：批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足；对待批评要把注意力放在批评的内容上，理解老师的良苦用心，主动与老师沟通。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往"]}]},{"id":"cat-pol-7a-2-2","title":"第5课 和谐的师生关系","subtitle":"七年级上册 · 第二单元 成长的时空","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 成长的时空"},{"k":"课题","v":"第5课 和谐的师生关系"},{"k":"框题","v":"走近老师 / 珍惜师生情谊"}]},{"type":"note","title":"本课在单元中的位置","text":"友谊是平等的、双向的、不能没有原则的珍贵关系；学会建立和呵护友谊、理性对待网上交友，是中考人际交往类试题与价值观判断题最常出现的情境。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["走近老师","珍惜师生情谊"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"教与学是师生相互陪伴、相互促进、共同成长的过程（教学相长）；面对老师的引领和指导，主动参与、勤学好问的态度有助于我们与老师相互交流。","explain":"问「怎样与老师交流」时，除主动沟通外，还要写出「主动参与、勤学好问」「坦诚相待，注意沟通方式」「求同存异，主动关心」等要点。"},{"level":"重点","text":"老师的表扬意味着肯定、鼓励和期待，激励我们更好地学习和发展；老师的批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足。对待批评要把注意力放在批评的内容上，理解老师的良苦用心。","explain":"情境题最爱考「被老师批评后怎么办」。凡是「顶撞老师」「从此不听他的课」「背后继续我行我素」的选项都是错的。"},{"level":"了解","text":"彼此尊重，是我们与老师建立良好关系的开始；与老师交往要礼貌待师、注意场合、勿失分寸。","explain":"作为行为要求出现，常与「尊重老师的人格和劳动」「课堂上认真听讲、课下主动问好」等具体表现一起考。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["老师的表扬是肯定、鼓励和期待，批评是关心、提醒和劝诫，我们要正确对待老师的表扬和批评。","教与学是师生相互陪伴、相互促进、共同成长的过程，我们要主动参与、勤学好问，与老师坦诚交流。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把老师的批评理解为「故意刁难」，于是顶撞老师、疏远老师，或者从此不听他的课。","批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足；对待批评要把注意力放在批评的内容上，理解老师的良苦用心，主动与老师沟通。","情境题里凡出现「顶撞老师」「当面指责老师」「从此不理老师」的做法都错，正确路径是「接受内容—反省改进—主动沟通」。"],["把网上交友等同于现实交往，轻信网友、透露家庭住址与学校名称，或独自赴约。","网上交往具有虚拟性，带有很多不确定因素；网上交友要理性辨别、慎重选择，增强自我保护意识，不轻易透露个人信息，不轻易与网友见面，遇到侵害及时求助。","材料题常设「网友约见」情境，答案不写「自我保护」与「及时告诉父母、老师或报警」就会丢分。"]]},{"type":"table","title":"「讲义气」与讲原则的友谊（同一情境下的是非判断）（本单元概念对比）","head":["比较项","「讲义气」「够朋友」","讲原则的友谊"],"rows":[["面对朋友的错误","帮忙隐瞒、替人遮掩、甚至替人顶包","劝阻并帮助改正，必要时告诉老师或家长"],["面对违纪违法的要求","有求必应，一起参与","坚持原则、拒绝参与，并说明理由"],["结果","朋友在错误的路上越走越远，友谊也难以长久","既对朋友负责，也让友谊更加牢固"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["友谊澄清类情境判断题","给出「朋友要我帮忙作弊」「朋友和别人竞争」「朋友犯错要我保密」等情境，判断哪种做法正确。判分口诀：友谊是平等的、双向的；友谊不能没有原则；竞争并不必然伤害友谊。"],["网上交友的安全教育题","以网友索要个人信息、约见面、诱导转账等情境考查网上交友的注意事项，答案必须包含「理性辨别、慎重选择」「增强自我保护意识」「不轻易透露个人信息」「及时告诉父母、老师或报警」等规范表述。"],["呵护友谊的做法题","问「与朋友发生矛盾后怎么办」，按「用心关怀对方—学会尊重对方—正确处理冲突—正确对待受到的伤害」四点作答，处理冲突再补上保持冷静、坦诚交流、及时处理、勇于承担责任、换位思考。"]]},{"type":"quote","text":"【材料一】小丽在网上认识了一位很聊得来的网友，这位网友多次要小丽的家庭住址和学校名称，还约她周末单独见面，并表示可以送她礼物。\n【材料二】小刚和小宇是好朋友。期中考试前，小宇请小刚在考试时「关照」一下，说自己考不好会被家长批评。小刚拒绝了他，还利用课余时间帮小宇梳理错题，小宇的成绩有了进步。\n【材料三】小敏和好朋友小雯都参加了学校的演讲比赛，小雯获得一等奖。小敏心里有点失落，但她还是第一个为小雯鼓掌，并请小雯教自己演讲的技巧。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 友谊之树常青：建立与呵护友谊·网上交友的智慧","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-2"},{"t":"专题精讲 · 幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-3"},{"t":"专题精讲 · 在集体中成长：集体的力量·集体生活成就我·共建美好集体","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-3-m1-q1","type":"short","stem":"（1）结合材料一，请你告诉小刚应该怎样正确对待老师的批评。（4 分）","answer":"①老师的批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足，小刚应认识到上课看课外书违反了课堂纪律；②对待批评要把注意力放在批评的内容上，理解老师的良苦用心，不因受批评就顶撞老师、疏远老师；③要主动与老师沟通，坦诚说明自己的想法，注意沟通方式，及时改正错误；④彼此尊重是我们与老师建立良好关系的开始。","explain":"","tags":["师生交往","正确对待批评"],"rubric":["答出批评意味着关心、提醒和劝诫","答出把注意力放在批评的内容上、理解老师的良苦用心","答出主动沟通、注意沟通方式","答出反省并改正错误（上课不再违纪）"]},{"id":"pol-growth-3-q1","type":"choice","stem":"对教师职业的认识，下列说法正确的是","answer":"C","explain":"C 与教材表述一致。A 否认了教师教书育人的使命；B 否认了教师作为我们学习指导者和成长引路人的作用；D 把尊重的标准简化为教龄，不符合彼此尊重的要求。","options":["教师只是把知识传授给学生，不承担育人的责任","随着网络的发展，教师在我们的成长中已经不重要了","教师作为教育工作者，是人类文明的主要传承者之一，承担着教书育人的使命","只有教龄长的老师才值得我们尊重"],"difficulty":1,"tags":["教师职业","走近老师"]},{"id":"pol-growth-3-q2","type":"choice","stem":"「教学相长」告诉我们","answer":"D","explain":"教学相长指教与学相互促进、共同成长：我们的学习离不开老师的引领和指导，我们与老师交流互动也能促进老师更好地教。A、B 各取一端，C 否认了良好的师生关系可以成为朋友式的融洽关系。","options":["学生只需要听老师讲，不必发表自己的见解","老师可以从学生那里学到东西，学生不必向老师学习","师生之间只能保持距离，不可能成为朋友","教与学是师生相互陪伴、相互促进、共同成长的过程"],"difficulty":2,"tags":["教学相长","师生交往"]},{"id":"pol-growth-3-q3","type":"choice","stem":"面对老师的批评，下列做法恰当的是","answer":"B","explain":"批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足。正确态度是把注意力放在批评的内容上，理解老师的良苦用心，主动沟通、及时改正。A、C、D 都是拒绝批评或阳奉阴违的做法。","options":["认为老师故意跟自己过不去，从此不再听他的课","把注意力放在批评的内容上，理解老师的良苦用心，及时改正","当面顶撞老师，证明自己没有错","表面上接受，背后继续我行我素"],"difficulty":1,"tags":["正确对待批评"]},{"id":"pol-growth-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 教师作为教育工作者，是人类文明的主要传承者之一，承担着教书育人的使命；新时代的好…\n② 教与学是师生相互陪伴、相互促进、共同成长的过程（教学相长）；面对老师的引领和指导…\n③ 老师的表扬意味着肯定、鼓励和期待，激励我们更好地学习和发展；老师的批评意味着关心…\n④ 把老师的批评理解为「故意刁难」，于是顶撞老师、疏远老师，或者从此不听他的课。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——情境题里凡出现「顶撞老师」「当面指责老师」「从此不理老师」的做法都错，正确路径是「接受内容—反省改进—主动沟通」；正确表述应为：批评意味着关心、提醒和劝诫，可以帮助我们反省自己、改进不足；对待批评要把注意力放在批评的内容上，理解老师的良苦用心，主动与老师沟通。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往"]}]},{"id":"cat-pol-7a-2-3","title":"第6课 友谊之树常青","subtitle":"七年级上册 · 第二单元 成长的时空","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 成长的时空"},{"k":"课题","v":"第6课 友谊之树常青"},{"k":"框题","v":"友谊的真谛 / 交友的智慧"}]},{"type":"note","title":"本课在单元中的位置","text":"友谊是平等的、双向的、不能没有原则的珍贵关系；学会建立和呵护友谊、理性对待网上交友，是中考人际交往类试题与价值观判断题最常出现的情境。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["友谊的真谛","交友的智慧"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"呵护友谊，需要用心去关怀对方、学会尊重对方、学会正确处理冲突、学会正确对待交友中受到的伤害。","explain":"这一条既是选择题的「正确做法」，也是材料题问「怎样呵护友谊」的四点标准答案，每个要点后面最好补一句具体做法。"},{"level":"次重点","text":"处理朋友间冲突要讲究策略：保持冷静、坦诚交流、及时处理、勇于承担自己的责任、换位思考。","explain":"材料题问「与朋友闹矛盾后怎么办」，除「呵护友谊」四点外，写全这五个策略可以多拿踩分点。"},{"level":"重点","text":"朋友对我们的影响很大，我们的言谈举止、兴趣爱好甚至性格都或多或少地受到朋友的影响；与正直、诚信和见识广的人交朋友，是有益的。","explain":"选择题常问「为什么说朋友很重要」「什么样的人值得交朋友」。记住结论：朋友影响我们的成长，交友要有所选择。"},{"level":"重点","text":"友谊需要信任和忠诚，但不能没有原则：友谊不是不加分辨地为朋友做任何事，「讲义气」「够朋友」并不等于帮朋友隐瞒错误、一起违纪违法。","explain":"最常考的情境是「朋友抄作业要我保密」「朋友约我一起去网吧」「朋友考试要我传答案」。正确做法是劝阻并帮助改正，必要时告诉老师或家长——这不叫不忠诚，而是对朋友负责。"},{"level":"次重点","text":"网上交往具有虚拟、平等、自主等特点，带有很多不确定因素；网上交友要理性辨别、慎重选择，增强自我保护意识。","explain":"常考「网友索要家庭信息」「网友约单独见面」「网友诱导转账」等情境。正确做法要写全：不轻易透露个人信息，不轻易与网友见面，遇到侵害及时告诉父母、老师或报警。"},{"level":"了解","text":"建立友谊，需要开放自己，需要持续的行动；竞争并不必然伤害友谊，关键是我们对待竞争的态度。","explain":"「竞争必然伤害友谊」这一绝对化说法必错；正确表述是坦然接受并欣赏朋友的成就，在竞争中互相激励、共同进步。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["呵护友谊，需要用心去关怀对方、学会尊重对方、学会正确处理冲突、学会正确对待交友中受到的伤害。","友谊不能没有原则；友谊需要信任和忠诚，但「讲义气」「够朋友」并不等于不加分辨地为朋友做任何事。","网上交往具有虚拟、平等、自主等特点，网上交友要理性辨别、慎重选择，增强自我保护意识。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「为朋友两肋插刀」才是真友谊，朋友犯了错也要替他隐瞒、帮他遮掩。","友谊不能没有原则。真正的友谊要明辨是非，朋友犯错时应当劝阻、帮助他改正，这才是对朋友负责。","选择题常把「讲义气」包装成「忠诚」。凡要求「帮朋友隐瞒错误、一起违纪违法」的选项一律错误。"],["认为「朋友之间有了竞争，友谊就一定会受到伤害」。","竞争并不必然伤害友谊，关键是我们对待竞争的态度：在竞争中坦然接受并欣赏朋友的成就，做到自我反省和激励，我们会收获更多。","「必然」「一定」这类绝对化词语是选择题的常见陷阱，看到就要警惕。"],["把网上交友等同于现实交往，轻信网友、透露家庭住址与学校名称，或独自赴约。","网上交往具有虚拟性，带有很多不确定因素；网上交友要理性辨别、慎重选择，增强自我保护意识，不轻易透露个人信息，不轻易与网友见面，遇到侵害及时求助。","材料题常设「网友约见」情境，答案不写「自我保护」与「及时告诉父母、老师或报警」就会丢分。"]]},{"type":"table","title":"现实交往与网上交往（同一行为在两种场景中的对比）（本单元概念对比）","head":["比较项","现实中的朋友交往","网上交往"],"rows":[["特点","面对面交流，可以直接观察对方的言行","具有虚拟、平等、自主等特点，带有很多不确定因素"],["积极影响","朋友见证我们的成长历程，带来真诚的陪伴与支持","开辟了交往的新通道，可以拓展交往圈、学习新知识"],["主要风险","冲突处理不当会伤害友谊","信息不真实，可能遭遇诈骗、隐私泄露乃至人身安全风险"],["正确态度","用心关怀、学会尊重、正确处理冲突、正确对待伤害","理性辨别、慎重选择，增强自我保护意识，不轻易与网友见面"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["友谊澄清类情境判断题","给出「朋友要我帮忙作弊」「朋友和别人竞争」「朋友犯错要我保密」等情境，判断哪种做法正确。判分口诀：友谊是平等的、双向的；友谊不能没有原则；竞争并不必然伤害友谊。"],["网上交友的安全教育题","以网友索要个人信息、约见面、诱导转账等情境考查网上交友的注意事项，答案必须包含「理性辨别、慎重选择」「增强自我保护意识」「不轻易透露个人信息」「及时告诉父母、老师或报警」等规范表述。"],["呵护友谊的做法题","问「与朋友发生矛盾后怎么办」，按「用心关怀对方—学会尊重对方—正确处理冲突—正确对待受到的伤害」四点作答，处理冲突再补上保持冷静、坦诚交流、及时处理、勇于承担责任、换位思考。"]]},{"type":"quote","text":"【材料一】小丽在网上认识了一位很聊得来的网友，这位网友多次要小丽的家庭住址和学校名称，还约她周末单独见面，并表示可以送她礼物。\n【材料二】小刚和小宇是好朋友。期中考试前，小宇请小刚在考试时「关照」一下，说自己考不好会被家长批评。小刚拒绝了他，还利用课余时间帮小宇梳理错题，小宇的成绩有了进步。\n【材料三】小敏和好朋友小雯都参加了学校的演讲比赛，小雯获得一等奖。小敏心里有点失落，但她还是第一个为小雯鼓掌，并请小雯教自己演讲的技巧。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 友谊之树常青：建立与呵护友谊·网上交友的智慧","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-2"},{"t":"专题精讲 · 幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-3"},{"t":"专题精讲 · 在集体中成长：集体的力量·集体生活成就我·共建美好集体","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-2-m1-q1","type":"short","stem":"（1）结合材料一，请你提醒小丽在网上交友时应注意什么。（4 分）","answer":"网上交往具有虚拟、平等、自主等特点，带有很多不确定因素，因此要理性辨别、慎重选择。具体做到：①增强自我保护意识，不轻易透露家庭住址、学校名称、联系方式等个人真实信息；②对网友的邀请和承诺保持警惕，不轻易答应与网友单独见面，更不接受陌生人的礼物；③遇到索要隐私信息、约见等情况，要及时告诉父母或老师，必要时报警求助。","explain":"","tags":["网上交友","自我保护"],"rubric":["答出网上交往具有虚拟性、带有很多不确定因素","答出不轻易透露个人真实信息","答出不轻易与网友见面、慎重对待网友邀请","答出及时告诉父母、老师或报警求助"]},{"id":"pol-growth-2-m1-q2","type":"short","stem":"（2）材料二中小刚的做法是否「不够朋友」？请说明理由。（4 分）","answer":"不是。友谊需要信任和忠诚，但友谊不能没有原则，「讲义气」「够朋友」并不等于不加分辨地为朋友做任何事。考试作弊违反考试纪律，答应「关照」会让小宇失去诚信，在错误的路上越走越远，这不是真正的友谊。小刚拒绝作弊并帮助小宇梳理错题、共同进步，是对朋友负责的表现，这样的友谊才能长久。","explain":"","tags":["友谊不能没有原则","交友的智慧"],"rubric":["明确判断：不是不够朋友","答出友谊不能没有原则","答出「讲义气」不等于不加分辨地为朋友做任何事","指出作弊违纪、不利于朋友的成长","答出帮助朋友改正、共同进步才是对朋友负责"]},{"id":"pol-growth-2-q1","type":"choice","stem":"「友谊是平等的、双向的。」下列做法与这一观点相符的是","answer":"A","explain":"友谊是平等的、双向的，接受帮助也要学会帮助对方，分享快乐也要分担烦恼。B 是单向索取，C 是要求对方服从，D 否认了友谊是心灵的相遇，均不符合。","options":["小文与朋友互相倾听、互相帮助，分享快乐，分担烦恼","小文只在需要朋友帮助时才联系朋友，从不主动关心对方","小文认为朋友就应该事事听从自己的安排","小文觉得朋友之间不必有真诚的交流，维持表面和气就好"],"difficulty":1,"tags":["友谊的特质"]},{"id":"pol-growth-2-q2","type":"choice","stem":"考试时同桌请你把答案传给他。作为朋友，最恰当的做法是","answer":"B","explain":"友谊不能没有原则，考试作弊违反考试纪律，帮朋友作弊不是真正的友谊。正确做法是拒绝作弊并帮助朋友提高成绩。A、C 是丧失原则，D 虽拒绝但没有尊重对方、方式不当。","options":["悄悄把答案传过去，帮助朋友才叫讲义气","拒绝传答案，考试后帮他一起分析错题、复习功课","把答案传过去，但要求他不要告诉别人","当场大声拒绝并指责同桌，让全班同学都知道"],"difficulty":2,"tags":["友谊不能没有原则"]},{"id":"pol-growth-2-q3","type":"choice","stem":"网上交往具有虚拟、平等、自主等特点。对初中生来说，下列做法正确的是","answer":"D","explain":"网上交友要理性辨别、慎重选择，增强自我保护意识。A 泄露隐私信息，B 独自赴约有安全风险，C 关闭了现实交往之路，都不正确。","options":["与网友聊得投机，就把家庭住址、学校名称告诉对方","网友约见面，为了不错过机会，独自一人赴约","把网络当作唯一的情感寄托，不再与身边的同学交往","提高自我保护意识，不轻易透露个人信息，不轻易与网友见面"],"difficulty":1,"tags":["网上交友","自我保护"]},{"id":"pol-growth-2-q4","type":"choice","stem":"与好朋友因误会产生矛盾后，下列做法有助于化解矛盾的是","answer":"A","explain":"处理冲突的基本策略是保持冷静、坦诚交流、及时处理、勇于承担自己的责任、换位思考。B、C、D 都会扩大矛盾、伤害友谊。","options":["保持冷静、坦诚交流，主动承担自己的责任","从此不再理睬对方，用冷战表达不满","在班级群里发消息，让其他同学来评理","表面和好，心里记恨，寻找机会报复"],"difficulty":1,"tags":["呵护友谊","处理冲突","沟通"]}]},{"id":"cat-pol-7a-2-4","title":"第7课 在集体中成长","subtitle":"七年级上册 · 第二单元 成长的时空","grade":"7a","tags":["七年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第二单元 成长的时空"},{"k":"课题","v":"第7课 在集体中成长"},{"k":"框题","v":"集体生活成就我 / 共建美好集体"}]},{"type":"note","title":"本课在单元中的位置","text":"友谊是平等的、双向的、不能没有原则的珍贵关系；学会建立和呵护友谊、理性对待网上交友，是中考人际交往类试题与价值观判断题最常出现的情境。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["集体生活成就我","共建美好集体"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"了解","text":"在集体中，个人利益与集体利益本质上是一致的；当二者发生冲突时，应把集体利益放在个人利益之上，坚持集体主义，同时集体也应尊重和保护个人的正当利益；反对把少数人的利益置于集体利益之上的小团体主义。","explain":"区分度最高的一条：既能考「坚持集体主义」，也能考「小团体主义不是集体主义」——为哥们义气护短、帮同学隐瞒错误，都属于小团体主义，必须反对。答「讲集体就要完全放弃个人利益」同样是错的。"},{"level":"重点","text":"集体的力量来源于成员共同的目标和团结协作；个人的力量是分散的、有限的，但在集体中汇聚就会变得强大；团结的集体才有凝聚力和战斗力。","explain":"「团结就是力量」类材料题必须写出「共同目标 + 团结协作」两个来源，只答「人多力量大」不得分——集体力量不是个人力量的简单相加：人心不齐，人再多也是一盘散沙。"},{"level":"次重点","text":"美好集体拥有共同的愿景，是民主的、公正的，是充满关怀与友爱的，是善于合作的，是充满活力的。","explain":"「美好集体有哪些特征」要把这几个词语答全；其中「民主」「公正」常与班规共订、班委选举、评优公平等情境对应考查，材料里出现「投票决定」「轮流值日」就要往这两个词上靠。"},{"level":"次重点","text":"建设美好集体需要我们共同确定愿景和目标、共同商定集体的规则与制度、共同创造良好的集体氛围，做到自主建设、自我管理。","explain":"做法建议类设问的模板句。注意「共同」二字：规则与制度要由成员共同商定，不能理解成「等老师定、我们照做」；材料里出现「全班讨论后定下公约」就是这一条。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["在集体中，个人利益与集体利益本质上是一致的；当二者发生冲突时，应把集体利益放在个人利益之上，坚持集体主义，反对小团体主义。","集体的力量来源于成员共同的目标和团结协作；团结的集体才有凝聚力和战斗力。","美好集体拥有共同的愿景，是民主的、公正的，是充满关怀与友爱的，是善于合作的，是充满活力的。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把个人利益与集体利益对立起来：讲集体利益就要完全放弃个人利益。","在集体中个人利益与集体利益本质上是一致的；当二者发生冲突时，应把集体利益放在个人利益之上，同时集体也应尊重和保护个人的正当利益。","材料题常要求「既讲集体主义，又不否定个人的正当利益」，只答一半会丢分；把两者对立起来同样被判错。"],["认为「集体就是许多人聚在一起」，人数越多集体力量就越大。","集体是人们联合起来的有组织的整体，有共同目标、分工明确；集体并不是成员的简单相加，集体的力量来源于成员共同的目标和团结协作。","这是选择题最常见的设误方式：用「人多」替换「团结」。人心不齐、各行其是，人再多也难以形成强大的集体力量。"],["把「小团体主义」当成集体主义：为小圈子护短、帮同学隐瞒错误，认为「这才是够朋友、够义气」。","小团体主义是把少数人的利益置于集体利益之上，是扩大了的个人主义，必须反对；真正的集体主义以集体的共同利益为重，同学有错应劝其改正。","「讲义气护着哥们」这类情境判断题就是专门考这个区分：看似维护小集体，实际损害的是真正的集体利益和他人的成长。"]]},{"type":"table","title":"个人力量与集体力量（个人与集体的关系）（本单元概念对比）","head":["比较项","个人","集体"],"rows":[["力量特点","个人的力量是分散的、有限的","集体的力量来源于成员共同的目标和团结协作"],["能做成的事","许多复杂任务单靠个人难以完成","团结的集体可以完成个人无法完成的事情"],["相互依存","个人的成长离不开集体这个平台","集体的发展也离不开每个成员的智慧和力量"],["易错点","把集体当成许多人的简单相加","集体力量不是个人力量的简单相加，团结才有力量"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["友谊澄清类情境判断题","给出「朋友要我帮忙作弊」「朋友和别人竞争」「朋友犯错要我保密」等情境，判断哪种做法正确。判分口诀：友谊是平等的、双向的；友谊不能没有原则；竞争并不必然伤害友谊。"],["网上交友的安全教育题","以网友索要个人信息、约见面、诱导转账等情境考查网上交友的注意事项，答案必须包含「理性辨别、慎重选择」「增强自我保护意识」「不轻易透露个人信息」「及时告诉父母、老师或报警」等规范表述。"],["呵护友谊的做法题","问「与朋友发生矛盾后怎么办」，按「用心关怀对方—学会尊重对方—正确处理冲突—正确对待受到的伤害」四点作答，处理冲突再补上保持冷静、坦诚交流、及时处理、勇于承担责任、换位思考。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 友谊之树常青：建立与呵护友谊·网上交友的智慧","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-2"},{"t":"专题精讲 · 幸福和睦的家庭·和谐的师生关系：亲情之爱与师生交往","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-3"},{"t":"专题精讲 · 在集体中成长：集体的力量·集体生活成就我·共建美好集体","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-6-m1-q1","type":"short","stem":"（1）结合材料一，说明七年级（3）班是怎样建设美好集体的。（4 分）","answer":"①共同确定愿景和目标：全班共同商定参赛曲目，为同一个目标努力；②通过民主的方式协商集体事务：先让每个人表达想法，再投票决定，少数服从多数；③善于合作、团结协作：落选的同学也一起把歌唱好，利用课余时间共同排练；④共同创造良好的集体氛围：同学之间相互支持、彼此配合，共同感受集体的温暖。","explain":"","tags":["共建美好集体","民主商定","善于合作"],"rubric":["答出共同确定愿景和目标（共同商定曲目）","答出民主协商、共同商定集体事务（投票决定、少数服从多数）","答出善于合作、团结协作（一起排练、落选同学也认真唱）","结合材料具体内容作答，分点规范表述"]},{"id":"pol-growth-6-m1-q2","type":"short","stem":"（2）结合材料二，谈谈集体生活对小凯的成长起到了什么作用。（6 分）","answer":"①集体生活涵养品格：辩论队的训练让他学会倾听他人意见、尊重不同看法，培养了人际交往的基本态度和能力；②集体生活发展个性：他在查资料、与队友讨论和当众表达的过程中展示了自己，从不敢说话到能够当众表达观点，个性得到丰富和发展；③集体生活为他搭建起与他人、与周围世界交往的平台，提供了锻炼自我、展示自我的机会；④在与队友的配合中，他体会到集体的力量，增强了合作意识与责任意识。","explain":"","tags":["集体生活涵养品格","在集体中发展个性","材料分析"],"rubric":["答出集体生活涵养品格（学会倾听、尊重，提高交往能力）","答出集体生活发展个性（敢于表达、展示自我，个性得到丰富）","答出集体为个人成长提供平台与机会","答出合作意识或责任意识等具体作用","分层作答、结合材料，语言规范"]},{"id":"pol-growth-6-q1","type":"choice","stem":"下列关于集体的说法正确的是","answer":"A","explain":"集体是人们联合起来的有组织的整体，集体并不是成员的简单相加，而是有共同目标、分工明确的整体，A 正确。B 把人数多少当成集体力量的标准；C 混淆了集体力量与个人力量的简单相加；D 忽略了集体需要有共同目标和组织，不会因为「在同一个班」就自然形成。","options":["集体是人们联合起来的有组织的整体，有共同目标、分工明确","集体就是许多人聚在一起，人数越多集体的力量就越大","集体的力量就是个人力量的简单相加","只要在同一个班级里，每个人就自然形成了集体"],"difficulty":1,"tags":["集体的含义","集体的力量"]},{"id":"pol-growth-6-q2","type":"choice","stem":"「团结就是力量。」对这句话理解正确的是","answer":"D","explain":"集体的力量来源于成员共同的目标和团结协作，团结的集体才有凝聚力和战斗力，D 正确。A、B 把人数当成力量的来源，忽略了团结协作；C 夸大了集体的力量，说法绝对。","options":["只要人多，集体的力量就一定强大","集体力量的大小只取决于成员人数的多少","集体的力量是无限的，可以完成任何事情","集体的力量来源于成员共同的目标和团结协作"],"difficulty":1,"tags":["集体的力量","团结协作"]},{"id":"pol-growth-6-q3","type":"choice","stem":"进入初中后，小美参加了班级合唱队，从不敢在同学面前唱歌，到能在全校演出中担任领唱。这主要说明","answer":"B","explain":"集体生活为我们搭建起与他人、与周围世界交往的平台，在集体活动中我们能够展示自我、发展个性，B 正确。A 否认了集体对个人成长的作用；C 把参加活动与成功划等号，说法绝对；D 把集体理解成对个性的压制，与「在集体中发展个性」相违背。","options":["个人的成长完全依靠自己努力，与集体无关","集体生活为我们搭建起与他人交往的平台，有助于我们发展个性","只要参加集体活动，就一定能取得成功","在集体中应当收敛个性，服从多数人的意见"],"difficulty":2,"tags":["在集体中发展个性","集体的作用"]},{"id":"pol-growth-6-q4","type":"choice","stem":"某班要制定班级公约，下列做法最恰当的是","answer":"C","explain":"建设美好集体需要共同商定集体的规则与制度，通过民主的方式让每个成员参与其中，C 正确。A、B 让规则变成少数人制定、多数人服从，不符合民主与自治精神；D 用成绩决定话语权，违背公正原则。","options":["由班主任直接制定，同学们照着执行即可","由班干部商量决定，其他同学不必参与","组织全班同学共同讨论、共同商定，大家共同遵守","按照考试成绩排名，成绩靠前的同学意见优先"],"difficulty":1,"tags":["共建美好集体","民主商定"]}]},{"id":"cat-pol-7a-3-1","title":"第8课 生命可贵","subtitle":"七年级上册 · 第三单元 珍爱我们的生命","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 珍爱我们的生命"},{"k":"课题","v":"第8课 生命可贵"},{"k":"框题","v":"认识生命 / 敬畏生命"}]},{"type":"note","title":"本课在单元中的位置","text":"生命来之不易、独特而不可逆，我们要敬畏生命、守护生命、增强生命的韧性，在平凡的生活中创造和贡献，活出生命的精彩——这是中考生命教育类材料题的核心考点，也是价值观考查的必答落点。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["认识生命","敬畏生命"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"我们对生命要有一种敬畏的情怀，意识到生命价值高于一切；敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人。","explain":"「敬畏生命就是只珍爱自己的生命」是典型干扰项。材料题要写到「休戚与共」：每个人的生命都与他人、与社会息息相关。"},{"level":"重点","text":"生命来之不易、独特、不可逆、短暂；在人类生命的接续中，我们总能为自己的生命找到一个位置，担当一份使命。","explain":"选择题常以「生命可以重来」「别人的生命与我无关」等表述设错。生命有接续：每个人的生命不仅仅是「我」的生命，还是「我们」的生命。"},{"level":"重点","text":"守护生命首先要关注自己的身体，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法；同时要关注并养护精神，用优秀文化滋养心灵。","explain":"材料题凡涉及溺水、火灾、交通、食品安全等情境，都要答「增强安全意识、提高安全防范能力、掌握基本的自救自护方法」，再补「关注并养护精神」。"},{"level":"重点","text":"人生的意义在于创造和贡献；当我们将个体生命和他人的、集体的、国家的命运联系在一起时，生命便会从平凡中闪耀出伟大。","explain":"这是生命类材料题的价值升华句。问「怎样让生命更有意义」必须落到「创造和贡献」与「把个人生命与他人、集体、国家联系起来」，只写「好好学习」不得分。"},{"level":"次重点","text":"挫折是我们生命成长的一部分；面对挫折，不同的态度会产生不同的结果，挫折具有两面性，要以积极的态度对待挫折。","explain":"「挫折越多越好」「经历挫折一定会成功」都是绝对化错误表述；正确答法是「挫折既可能使人意志消沉，也可能磨炼意志、增长才干，关键在态度和应对方式」。"},{"level":"次重点","text":"增强生命的韧性，需要发掘自身的生命力量，培养面对困难的勇气和坚强的意志；也可以通过欣赏和培养幽默感、与自己信任的人谈心、关心帮助他人、培养某方面的兴趣等方法来增强生命韧性。","explain":"材料题第二问的「做法」层：既要有「意志与勇气」的内在力量，也要有「求助他人、自我调节」的具体方法，两层都写才拿满分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["生命是独特的、不可逆的、短暂的，我们对生命要有一种敬畏的情怀，意识到生命价值高于一切。","敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人。","守护生命首先要关注自己的身体，养成健康的生活方式，提高安全防范能力，掌握基本的自救自护方法。","挫折是我们生命成长的一部分，我们要以积极的态度面对挫折，发掘自身的生命力量，增强生命的韧性。","人生的意义在于创造和贡献；当我们将个体生命和他人的、集体的、国家的命运联系在一起时，生命便会从平凡中闪耀出伟大。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「敬畏生命就是珍爱自己的生命，别人的生命与我无关」。","敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人；每个人的生命都与他人、与社会息息相关，休戚与共。","「与我无关」「各人自扫门前雪」是价值观判断题的常见错误倾向，看到就要否定。"],["认为「只有做出惊天动地的大事，生命才有意义和价值」。","人生的意义在于创造和贡献，平凡的生命同样可以创造价值；用认真、勤劳、善良、坚持、责任、勇敢书写自己的生命价值，生命便能从平凡中闪耀出伟大。","这是生命类材料题最常设的错误观点，要先明确否认，再给出正确表述。"]]},{"type":"table","title":"守护生命与养护精神（珍视生命的两个方面）（本单元概念对比）","head":["比较项","守护生命（身体）","养护精神（精神）"],"rows":[["关注对象","自己的身体与安全","自己的精神生活与内心需求"],["具体要求","关注身体状况，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法","关注精神生活，用优秀文化滋养心灵，传承优秀传统文化、发扬民族精神"],["常见情境","溺水、火灾、交通事故、食品安全等自我防护","阅读经典、参加文化活动、遭遇挫折时进行心理调适"],["共同点","都是珍视生命的表现，身体健康与精神充实缺一不可","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["敬畏生命与生命价值判断题","以救援、见义勇为、志愿服务等情境考查「生命价值高于一切」「从珍爱自己的生命走向关怀他人的生命」，并常要求辨析「别人的生命与我无关」等错误观点。"],["挫折与生命韧性题","以「遭遇挫折后重新振作」的模拟情境（比赛失利、伤病、家庭变故等）考查对待挫折的正确态度与增强生命韧性的方法，答「态度＋内在力量＋求助与自我调节」三层。"],["生命的平凡与伟大题","以普通劳动者、志愿者的公开报道为材料，问「平凡人怎样让生命有意义」，答案必须包含「创造和贡献」与「把个体生命与他人、集体、国家的命运联系在一起」。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 珍爱我们的生命：守护生命安全·保持身心健康","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-4-m1-q1","type":"short","stem":"（1）结合材料一，谈谈我们应如何守护生命、敬畏生命。（6 分）","answer":"守护生命：①首先要关注自己的身体，养成健康的生活方式，运动前做好准备活动，增强安全意识、提高安全防范能力、掌握基本的自救自护方法；②住院期间要关注自己的内在感受，学会调适不良情绪，关注并养护自己的精神。敬畏生命：生命是脆弱的、艰难的，也是坚强的、有力量的，我们对生命要有一种敬畏的情怀，意识到生命价值高于一切；敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人。","explain":"","tags":["珍视生命","敬畏生命","守护生命"],"rubric":["答出关注身体、养成健康的生活方式","答出增强安全意识、提高安全防范能力、掌握基本自救自护方法","答出关注内在感受、养护精神","答出对生命有敬畏情怀、生命价值高于一切","答出从珍爱自己的生命走向关怀他人的生命"]},{"id":"pol-growth-4-m1-q2","type":"short","stem":"（2）康复训练中，小雯表现出怎样的生命态度？我们应怎样增强生命的韧性？（6 分）","answer":"生命态度：她以积极、坚强的态度面对挫折，没有消沉放弃，表现出对生命的热爱和坚强的意志。增强生命韧性的方法：①正确认识挫折，挫折是我们生命成长的一部分，要以积极的态度对待挫折；②发掘自身的生命力量，培养面对困难的勇气和坚强的意志；③学会向他人求助，与父母、老师、朋友交流，必要时寻求专业帮助；④运用自我调节的方法，如欣赏和培养幽默感、给自己积极的心理暗示、关心帮助他人、培养某方面的兴趣等。","explain":"","tags":["挫折","生命的韧性"],"rubric":["概括出积极面对挫折的生命态度","答出挫折是生命成长的一部分、要正确对待挫折","答出发掘自身的生命力量、培养勇气和坚强意志","答出向他人求助或寻求专业帮助","答出自我调节的具体方法（幽默感、积极暗示、关心他人、培养兴趣等）"]},{"id":"pol-growth-4-q1","type":"choice","stem":"下列关于生命的认识正确的是","answer":"A","explain":"A 是教材关于生命特点的规范表述。B 由「短暂」推出「及时行乐」，是对生命的错误态度；C 否认了生命之间的休戚与共；D 违背了生命不可逆的特点。","options":["生命是独特的、不可逆的、短暂的，我们要珍爱生命","生命是短暂的，所以要及时行乐，不必努力","生命属于自己，怎样度过与他人无关","生命是可以重来的，犯过的错可以随意弥补"],"difficulty":1,"tags":["探问生命"]},{"id":"pol-growth-4-q2","type":"choice","stem":"下列做法体现敬畏生命的是","answer":"C","explain":"敬畏生命要求我们谨慎地对待生命关系、处理生命问题，尊重、关注、关怀和善待身边的每一个人。A 是无视安全警示；B、D 是对他人生命的冷漠，都不符合敬畏生命。","options":["看到「禁止游泳」的警示牌仍然下水游泳","同学摔倒受伤，因为怕被误会而绕开走","看到同学在楼梯上追逐打闹，及时劝阻并提醒注意安全","认为别人遇到的困难与自己无关"],"difficulty":1,"tags":["敬畏生命"]},{"id":"pol-growth-4-q3","type":"choice","stem":"守护生命首先要关注自己的身体。下列做法不符合这一要求的是","answer":"C","explain":"本题为反向选择。养成健康的生活方式要求合理饮食、适量运动、规律作息，C 熬夜打游戏、靠饮料提神损害身体健康，不符合守护生命的要求。","options":["合理安排作息，坚持适度锻炼","生病时及时就医，按医嘱服药","经常熬夜打游戏，靠饮料提神","不吸烟、不喝酒，远离毒品"],"difficulty":1,"tags":["守护生命","健康生活方式"]},{"id":"pol-growth-4-q4","type":"choice","stem":"对挫折的认识正确的是","answer":"B","explain":"挫折具有两面性，它可能使我们意志消沉，也可能磨炼意志、增长才干，关键在态度和应对方式。A 绝对化，C 否认求助的意义，D 只看到消极面，均错误。","options":["挫折越多越好，经历挫折就一定能成功","挫折是我们生命成长的一部分，关键是以积极的态度对待挫折","遇到挫折只能自己扛着，向他人求助是软弱的表现","挫折只会给我们带来痛苦，没有任何积极作用"],"difficulty":2,"tags":["挫折","生命的韧性"]}]},{"id":"cat-pol-7a-3-2","title":"第9课 守护生命安全","subtitle":"七年级上册 · 第三单元 珍爱我们的生命","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 珍爱我们的生命"},{"k":"课题","v":"第9课 守护生命安全"},{"k":"框题","v":"增强安全意识 / 提高防护能力"}]},{"type":"note","title":"本课在单元中的位置","text":"生命来之不易、独特而不可逆，我们要敬畏生命、守护生命、增强生命的韧性，在平凡的生活中创造和贡献，活出生命的精彩——这是中考生命教育类材料题的核心考点，也是价值观考查的必答落点。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["增强安全意识","提高防护能力"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"守护生命首先要关注自己的身体，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法；同时要关注并养护精神，用优秀文化滋养心灵。","explain":"材料题凡涉及溺水、火灾、交通、食品安全等情境，都要答「增强安全意识、提高安全防范能力、掌握基本的自救自护方法」，再补「关注并养护精神」。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["守护生命首先要关注自己的身体，养成健康的生活方式，提高安全防范能力，掌握基本的自救自护方法。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["认为「敬畏生命就是珍爱自己的生命，别人的生命与我无关」。","敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人；每个人的生命都与他人、与社会息息相关，休戚与共。","「与我无关」「各人自扫门前雪」是价值观判断题的常见错误倾向，看到就要否定。"],["认为「挫折越多越好」，或者认为「经历过挫折就一定会成功」。","挫折具有两面性：它可能使我们意志消沉、止步不前，也可能磨炼意志、增长才干；关键在于我们对待挫折的态度和应对方式。","凡含「一定」「必然」「越多越好」的表述基本都是错的，要改写成「关键在态度和应对方式」。"]]},{"type":"table","title":"守护生命与养护精神（珍视生命的两个方面）（本单元概念对比）","head":["比较项","守护生命（身体）","养护精神（精神）"],"rows":[["关注对象","自己的身体与安全","自己的精神生活与内心需求"],["具体要求","关注身体状况，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法","关注精神生活，用优秀文化滋养心灵，传承优秀传统文化、发扬民族精神"],["常见情境","溺水、火灾、交通事故、食品安全等自我防护","阅读经典、参加文化活动、遭遇挫折时进行心理调适"],["共同点","都是珍视生命的表现，身体健康与精神充实缺一不可","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["敬畏生命与生命价值判断题","以救援、见义勇为、志愿服务等情境考查「生命价值高于一切」「从珍爱自己的生命走向关怀他人的生命」，并常要求辨析「别人的生命与我无关」等错误观点。"],["挫折与生命韧性题","以「遭遇挫折后重新振作」的模拟情境（比赛失利、伤病、家庭变故等）考查对待挫折的正确态度与增强生命韧性的方法，答「态度＋内在力量＋求助与自我调节」三层。"],["生命的平凡与伟大题","以普通劳动者、志愿者的公开报道为材料，问「平凡人怎样让生命有意义」，答案必须包含「创造和贡献」与「把个体生命与他人、集体、国家的命运联系在一起」。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 珍爱我们的生命：守护生命安全·保持身心健康","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-4-m1-q1","type":"short","stem":"（1）结合材料一，谈谈我们应如何守护生命、敬畏生命。（6 分）","answer":"守护生命：①首先要关注自己的身体，养成健康的生活方式，运动前做好准备活动，增强安全意识、提高安全防范能力、掌握基本的自救自护方法；②住院期间要关注自己的内在感受，学会调适不良情绪，关注并养护自己的精神。敬畏生命：生命是脆弱的、艰难的，也是坚强的、有力量的，我们对生命要有一种敬畏的情怀，意识到生命价值高于一切；敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人。","explain":"","tags":["珍视生命","敬畏生命","守护生命"],"rubric":["答出关注身体、养成健康的生活方式","答出增强安全意识、提高安全防范能力、掌握基本自救自护方法","答出关注内在感受、养护精神","答出对生命有敬畏情怀、生命价值高于一切","答出从珍爱自己的生命走向关怀他人的生命"]},{"id":"pol-growth-4-q3","type":"choice","stem":"守护生命首先要关注自己的身体。下列做法不符合这一要求的是","answer":"C","explain":"本题为反向选择。养成健康的生活方式要求合理饮食、适量运动、规律作息，C 熬夜打游戏、靠饮料提神损害身体健康，不符合守护生命的要求。","options":["合理安排作息，坚持适度锻炼","生病时及时就医，按医嘱服药","经常熬夜打游戏，靠饮料提神","不吸烟、不喝酒，远离毒品"],"difficulty":1,"tags":["守护生命","健康生活方式"]},{"id":"pol-growth-4-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 生命来之不易、独特、不可逆、短暂；在人类生命的接续中，我们总能为自己的生命找到一…\n② 我们对生命要有一种敬畏的情怀，意识到生命价值高于一切；敬畏生命，要从对自我生命的…\n③ 守护生命首先要关注自己的身体，养成健康的生活方式，增强安全意识、提高安全防范能力…\n④ 认为「敬畏生命就是珍爱自己的生命，别人的生命与我无关」。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——「与我无关」「各人自扫门前雪」是价值观判断题的常见错误倾向，看到就要否定；正确表述应为：敬畏生命，要从对自我生命的珍视走向对他人生命的关怀，尊重、关注、关怀和善待身边的每一个人；每个人的生命都与他人、与社会息息相关，休戚与共。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["珍爱我们的生命：守护生命安全·保持身心健康"]},{"id":"pol-growth-4-q2","type":"choice","stem":"下列做法体现敬畏生命的是","answer":"C","explain":"敬畏生命要求我们谨慎地对待生命关系、处理生命问题，尊重、关注、关怀和善待身边的每一个人。A 是无视安全警示；B、D 是对他人生命的冷漠，都不符合敬畏生命。","options":["看到「禁止游泳」的警示牌仍然下水游泳","同学摔倒受伤，因为怕被误会而绕开走","看到同学在楼梯上追逐打闹，及时劝阻并提醒注意安全","认为别人遇到的困难与自己无关"],"difficulty":1,"tags":["敬畏生命"]},{"id":"pol-growth-4-q4","type":"choice","stem":"对挫折的认识正确的是","answer":"B","explain":"挫折具有两面性，它可能使我们意志消沉，也可能磨炼意志、增长才干，关键在态度和应对方式。A 绝对化，C 否认求助的意义，D 只看到消极面，均错误。","options":["挫折越多越好，经历挫折就一定能成功","挫折是我们生命成长的一部分，关键是以积极的态度对待挫折","遇到挫折只能自己扛着，向他人求助是软弱的表现","挫折只会给我们带来痛苦，没有任何积极作用"],"difficulty":2,"tags":["挫折","生命的韧性"]}]},{"id":"cat-pol-7a-3-3","title":"第10课 保持身心健康","subtitle":"七年级上册 · 第三单元 珍爱我们的生命","grade":"7a","tags":["七年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第三单元 珍爱我们的生命"},{"k":"课题","v":"第10课 保持身心健康"},{"k":"框题","v":"爱护身体 / 滋养心灵"}]},{"type":"note","title":"本课在单元中的位置","text":"生命来之不易、独特而不可逆，我们要敬畏生命、守护生命、增强生命的韧性，在平凡的生活中创造和贡献，活出生命的精彩——这是中考生命教育类材料题的核心考点，也是价值观考查的必答落点。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["爱护身体","滋养心灵"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"守护生命首先要关注自己的身体，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法；同时要关注并养护精神，用优秀文化滋养心灵。","explain":"材料题凡涉及溺水、火灾、交通、食品安全等情境，都要答「增强安全意识、提高安全防范能力、掌握基本的自救自护方法」，再补「关注并养护精神」。"},{"level":"次重点","text":"挫折是我们生命成长的一部分；面对挫折，不同的态度会产生不同的结果，挫折具有两面性，要以积极的态度对待挫折。","explain":"「挫折越多越好」「经历挫折一定会成功」都是绝对化错误表述；正确答法是「挫折既可能使人意志消沉，也可能磨炼意志、增长才干，关键在态度和应对方式」。"},{"level":"次重点","text":"增强生命的韧性，需要发掘自身的生命力量，培养面对困难的勇气和坚强的意志；也可以通过欣赏和培养幽默感、与自己信任的人谈心、关心帮助他人、培养某方面的兴趣等方法来增强生命韧性。","explain":"材料题第二问的「做法」层：既要有「意志与勇气」的内在力量，也要有「求助他人、自我调节」的具体方法，两层都写才拿满分。"},{"level":"次重点","text":"拒绝贫乏，充盈生命：敞开胸怀，不断尝试与他人、与社会、与自然建立联系，丰富生命的道德体验，提高对生命的感受力和理解力。","explain":"与「拒绝冷漠」配对出现，常用来分析「宅在家里、封闭自我」式情境的问题所在。"},{"level":"了解","text":"拒绝冷漠，关切他人：人与人在相互依存和彼此关切中感受温暖、传递温暖，我们要设身处地地思考并善待他人。","explain":"常与志愿服务、关爱他人等情境结合，答案落点是「关切他人生命、传递温暖」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["挫折是我们生命成长的一部分，我们要以积极的态度面对挫折，发掘自身的生命力量，增强生命的韧性。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「挫折越多越好」，或者认为「经历过挫折就一定会成功」。","挫折具有两面性：它可能使我们意志消沉、止步不前，也可能磨炼意志、增长才干；关键在于我们对待挫折的态度和应对方式。","凡含「一定」「必然」「越多越好」的表述基本都是错的，要改写成「关键在态度和应对方式」。"]]},{"type":"table","title":"守护生命与养护精神（珍视生命的两个方面）（本单元概念对比）","head":["比较项","守护生命（身体）","养护精神（精神）"],"rows":[["关注对象","自己的身体与安全","自己的精神生活与内心需求"],["具体要求","关注身体状况，养成健康的生活方式，增强安全意识、提高安全防范能力、掌握基本的自救自护方法","关注精神生活，用优秀文化滋养心灵，传承优秀传统文化、发扬民族精神"],["常见情境","溺水、火灾、交通事故、食品安全等自我防护","阅读经典、参加文化活动、遭遇挫折时进行心理调适"],["共同点","都是珍视生命的表现，身体健康与精神充实缺一不可","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["敬畏生命与生命价值判断题","以救援、见义勇为、志愿服务等情境考查「生命价值高于一切」「从珍爱自己的生命走向关怀他人的生命」，并常要求辨析「别人的生命与我无关」等错误观点。"],["挫折与生命韧性题","以「遭遇挫折后重新振作」的模拟情境（比赛失利、伤病、家庭变故等）考查对待挫折的正确态度与增强生命韧性的方法，答「态度＋内在力量＋求助与自我调节」三层。"],["生命的平凡与伟大题","以普通劳动者、志愿者的公开报道为材料，问「平凡人怎样让生命有意义」，答案必须包含「创造和贡献」与「把个体生命与他人、集体、国家的命运联系在一起」。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 珍爱我们的生命：守护生命安全·保持身心健康","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-growth-4-m1-q2","type":"short","stem":"（2）康复训练中，小雯表现出怎样的生命态度？我们应怎样增强生命的韧性？（6 分）","answer":"生命态度：她以积极、坚强的态度面对挫折，没有消沉放弃，表现出对生命的热爱和坚强的意志。增强生命韧性的方法：①正确认识挫折，挫折是我们生命成长的一部分，要以积极的态度对待挫折；②发掘自身的生命力量，培养面对困难的勇气和坚强的意志；③学会向他人求助，与父母、老师、朋友交流，必要时寻求专业帮助；④运用自我调节的方法，如欣赏和培养幽默感、给自己积极的心理暗示、关心帮助他人、培养某方面的兴趣等。","explain":"","tags":["挫折","生命的韧性"],"rubric":["概括出积极面对挫折的生命态度","答出挫折是生命成长的一部分、要正确对待挫折","答出发掘自身的生命力量、培养勇气和坚强意志","答出向他人求助或寻求专业帮助","答出自我调节的具体方法（幽默感、积极暗示、关心他人、培养兴趣等）"]},{"id":"pol-growth-4-q4","type":"choice","stem":"对挫折的认识正确的是","answer":"B","explain":"挫折具有两面性，它可能使我们意志消沉，也可能磨炼意志、增长才干，关键在态度和应对方式。A 绝对化，C 否认求助的意义，D 只看到消极面，均错误。","options":["挫折越多越好，经历挫折就一定能成功","挫折是我们生命成长的一部分，关键是以积极的态度对待挫折","遇到挫折只能自己扛着，向他人求助是软弱的表现","挫折只会给我们带来痛苦，没有任何积极作用"],"difficulty":2,"tags":["挫折","生命的韧性"]},{"id":"pol-growth-4-q6","type":"choice","stem":"下列做法有利于养护精神的是","answer":"B","explain":"养护精神需要关注自己的精神生活，用优秀文化滋养心灵，传承优秀传统文化。A 只重物质享受，C 沉迷游戏、作息混乱，D 忽视了青少年同样需要精神养护。","options":["只重视物质享受，一味追求名牌与美食","阅读经典书籍、参加文化活动，用优秀文化滋养心灵","一有烦恼就打游戏，通宵不出门","认为养护精神只是成年人的事，青少年不必在意"],"difficulty":2,"tags":["养护精神","珍视生命"]},{"id":"pol-growth-4-q5","type":"choice","stem":"「平凡的生命也能创造伟大。」下列理解正确的是","answer":"D","explain":"人生的意义在于创造和贡献，平凡的生命同样可以创造价值。A 忽视了平凡中的伟大，B 把生命意义缩小为个人生活，C 否认了生命意义需要自己发现和创造。","options":["只有做出惊天动地的成就，生命才有价值","平凡的人只要过好自己的生活，就是生命的全部意义","生命的意义是与生俱来的，不需要自己去发现和创造","当我们将个体生命和他人的、集体的、国家的命运联系在一起时，生命便会从平凡中闪耀出伟大"],"difficulty":2,"tags":["生命的意义","平凡与伟大"]},{"id":"cat-pol-7a-3-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 守护生命首先要关注自己的身体，养成健康的生活方式，增强安全意识、提高安全防范能力…\n② 挫折是我们生命成长的一部分；面对挫折，不同的态度会产生不同的结果，挫折具有两面性…\n③ 增强生命的韧性，需要发掘自身的生命力量，培养面对困难的勇气和坚强的意志；也可以通…\n④ 认为「挫折越多越好」，或者认为「经历过挫折就一定会成功」。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——凡含「一定」「必然」「越多越好」的表述基本都是错的，要改写成「关键在态度和应对方式」；正确表述应为：挫折具有两面性：它可能使我们意志消沉、止步不前，也可能磨炼意志、增长才干；关键在于我们对待挫折的态度和应对方式。","difficulty":3,"tags":["第10课 保持身心健康"]}]},{"id":"cat-pol-7a-4-1","title":"第11课 确立人生目标","subtitle":"七年级上册 · 第四单元 追求美好人生","grade":"7a","tags":["七年级上册","第四单元","教材新增"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 追求美好人生"},{"k":"课题","v":"第11课 确立人生目标"},{"k":"框题","v":"探问人生目标 / 树立正确的人生目标"}]},{"type":"note","title":"内容说明","text":"本课属 2024 版七上第四单元。现有道法模块尚未单列本单元条目，以下内容按教材框题整理，具体表述以正式课本为准。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["探问人生目标","树立正确的人生目标"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"人生目标体现着人在社会实践中对未来的向往和追求，决定着人生道路和发展方向。","explain":"选择题常问「人生目标有什么作用」，材料题常问「为什么要树立人生目标」。规范表述落在「决定人生道路和发展方向」，不要写成「决定人生成败」这类绝对化说法。"},{"level":"重点","text":"树立正确的人生目标，要结合自身实际，考虑个人条件和社会需要，把个人发展与社会进步、国家需要结合起来。","explain":"材料题问「怎样确立人生目标」时，按「自身实际—社会需要—国家需要」三层作答，只写「定一个远大目标」不得分。"},{"level":"次重点","text":"人生目标可以分为长远目标和近期目标；近期目标是长远目标的具体分解，实现长远目标要从近期目标做起。","explain":"选择题常考二者的关系：长远目标指明方向，近期目标便于落实，二者不是互不相干，也不是只看眼前。"},{"level":"了解","text":"少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分；努力是梦想与现实之间的桥梁。","explain":"这一表述与第 3 课相通：把个人梦想融入国家和民族的梦想，用努力把梦想变成现实。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["人生目标体现着人在社会实践中对未来的向往和追求，决定着人生道路和发展方向。","树立正确的人生目标，要结合自身实际，把个人发展与社会进步、国家需要结合起来。","实现人生目标需要脚踏实地、坚持不懈，从近期目标做起。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「人生目标一旦确立就永远不能调整」，或者认为「目标定得越高越好，不必考虑自身条件」。","人生目标要结合自身实际和社会需要来确立，并在实践中根据实际情况合理调整；目标不是越高越好。","两种说法都把「目标」理解成僵化或空想，忽略了目标的确立要立足实际、服务社会。"],["认为「只要有长远目标就够了，近期目标可有可无」。","长远目标指明方向，近期目标是长远目标的具体分解；实现长远目标要从完成一个个近期目标做起。","选择题常用「只看长远、不顾眼前」设错，正确理解是二者相互联系、层层落实。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 少年有梦：开启初中生活·正确认识自我·梦想始于当下","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"cat-pol-7a-4-1-q1","type":"choice","stem":"人生目标对个人成长具有重要意义。下列对人生目标的认识正确的是","options":["人生目标一旦确立就不能改变","人生目标决定着人生道路和发展方向","人生目标越高越好，不必考虑自身条件","人生目标只是对未来的美好想象，与现实无关"],"answer":"B","explain":"教材表述：人生目标体现着人对未来的向往和追求，决定着人生道路和发展方向。A 错在僵化，C 错在脱离实际，D 否认了人生目标对现实的指导作用。","difficulty":2,"tags":["人生目标"]},{"id":"cat-pol-7a-4-1-q2","type":"choice","stem":"树立正确的人生目标，下列做法恰当的是","options":["只考虑自己的兴趣爱好，不顾社会需要","结合自身实际，把个人发展与社会需要、国家发展结合起来","照搬他人的目标，别人做什么自己就做什么","只定长远目标，不需要近期目标"],"answer":"B","explain":"树立人生目标要立足自身实际，同时考虑社会需要和国家发展。A 只顾个人，C 缺乏自我认识，D 割裂了长远目标与近期目标。","difficulty":2,"tags":["人生目标","树立目标"]},{"id":"cat-pol-7a-4-1-q3","type":"choice","stem":"关于长远目标与近期目标的关系，下列理解正确的是","options":["二者互不相干，各定各的","近期目标是长远目标的具体分解，实现长远目标要从近期目标做起","只要有长远目标，近期目标可有可无","近期目标比长远目标更重要"],"answer":"B","explain":"长远目标指明方向，近期目标便于落实。二者相互联系，不能割裂，也不能简单比较谁更重要。","difficulty":2,"tags":["人生目标","近期目标"]},{"id":"cat-pol-7a-4-1-q4","type":"choice","stem":"「少年的梦想，与个人的人生目标紧密相连，与时代的脉搏紧密相连，与中国梦密不可分。」这启示我们","options":["个人梦想只要考虑自己即可","把个人梦想融入国家和民族的梦想","梦想与现实之间没有距离","梦想不需要努力就能实现"],"answer":"B","explain":"少年的梦想与时代、与中国梦紧密相连，要把个人梦想融入国家和民族的梦想，并用努力架起梦想与现实的桥梁。","difficulty":2,"tags":["梦想","人生目标"]},{"id":"cat-pol-7a-4-1-q5","type":"short","stem":"进入中学后，小文想成为一名医生。她既制定了「考上理想高中」的近期目标，也憧憬着将来救死扶伤的长远目标，但遇到困难时常常想放弃。请运用本课所学，谈谈小文应如何确立并实现人生目标。（6 分）","answer":"①人生目标要结合自身实际，考虑个人条件和社会需要，把个人发展与社会进步、国家需要结合起来；②把长远目标与近期目标结合起来，用近期目标落实长远目标；③脚踏实地、坚持不懈，遇到困难不轻易放弃，在努力中把目标变成现实。","explain":"","rubric":["答出结合自身实际和社会需要确立目标","答出把个人发展与社会进步、国家需要结合","答出长远目标与近期目标相结合","答出脚踏实地、坚持不懈"],"tags":["人生目标"]}]},{"id":"cat-pol-7a-4-2","title":"第12课 端正人生态度","subtitle":"七年级上册 · 第四单元 追求美好人生","grade":"7a","tags":["七年级上册","第四单元","教材新增"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 追求美好人生"},{"k":"课题","v":"第12课 端正人生态度"},{"k":"框题","v":"拥有积极的人生态度 / 正确对待顺境和逆境"}]},{"type":"note","title":"内容说明","text":"本课属 2024 版七上第四单元。现有道法模块尚未单列本单元条目，以下内容按教材框题整理，具体表述以正式课本为准。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["拥有积极的人生态度","正确对待顺境和逆境"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"人生态度是人在生活实践中形成的对人生的看法和态度，影响着人的行为方式和生活质量。","explain":"选择题常问「人生态度有什么影响」，规范表述落在「影响行为方式和生活质量」，不要写成「决定人生一切」。"},{"level":"重点","text":"积极的人生态度表现为乐观向上、认真务实、勤奋进取。","explain":"材料题问「我们应该以怎样的人生态度面对生活」时，按「乐观向上—认真务实—勤奋进取」三点作答。"},{"level":"重点","text":"顺境和逆境是人生道路上两种不同的境遇；顺境时不骄傲，逆境时不气馁，把逆境转化为成长的动力。","explain":"选择题常用「顺境一定好、逆境一定坏」设错；正确理解是两种境遇都能促进成长，关键在态度。"},{"level":"次重点","text":"挫折是我们生命成长的一部分，挫折具有两面性；面对挫折要冷静分析原因，积极应对，增强生命的韧性。","explain":"这一表述与七上第三单元相通：挫折既带来压力，也能磨炼意志、增长才干。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["人生态度影响着人的行为方式和生活质量。","积极的人生态度表现为乐观向上、认真务实、勤奋进取。","顺境时不骄傲，逆境时不气馁，把逆境转化为成长的动力。","挫折具有两面性，面对挫折要冷静分析、积极应对。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「顺境一定有利于成长，逆境一定有害」，或者认为「遇到逆境只能等待别人帮助」。","顺境和逆境都是人生道路上的境遇，关键在于以积极的人生态度对待；逆境可以磨炼意志、增长才干。","把境遇好坏绝对化，忽略了人的主观态度在成长中的作用。"],["认为「积极的人生态度就是从不失败、从不难过」。","积极的人生态度是乐观向上、认真务实、勤奋进取，遇到挫折也能冷静分析、积极应对。","积极不等于没有负面情绪，而是能以建设性态度面对困难。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 珍爱我们的生命：守护生命安全·保持身心健康","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"cat-pol-7a-4-2-q1","type":"choice","stem":"人生态度影响着人的行为方式和生活质量。下列属于积极人生态度表现的是","options":["遇到困难就抱怨、退缩","乐观向上、认真务实、勤奋进取","取得成绩就骄傲自满","凡事得过且过"],"answer":"B","explain":"积极的人生态度表现为乐观向上、认真务实、勤奋进取。A、C、D 都是消极或片面的态度。","difficulty":1,"tags":["人生态度"]},{"id":"cat-pol-7a-4-2-q2","type":"choice","stem":"面对顺境和逆境，下列态度正确的是","options":["顺境时骄傲自满，逆境时自暴自弃","顺境不骄，逆境不馁，把逆境转化为成长的动力","只希望人生一帆风顺，不能接受挫折","逆境都是坏事，只能等待别人帮助"],"answer":"B","explain":"顺境和逆境都是人生境遇，正确态度是顺境不骄、逆境不馁，把逆境转化为成长动力。","difficulty":1,"tags":["人生态度","顺境","逆境"]},{"id":"cat-pol-7a-4-2-q3","type":"choice","stem":"「挫折是我们生命成长的一部分。」对这句话理解正确的是","options":["挫折只会给人带来痛苦","挫折具有两面性，正确对待挫折能使人得到锻炼和成长","经历挫折越多越好","遇到挫折应尽量回避"],"answer":"B","explain":"挫折具有两面性：既可能带来压力和痛苦，也能磨炼意志、增长才干。关键在如何对待，不是越多越好，也不能一味回避。","difficulty":2,"tags":["挫折"]},{"id":"cat-pol-7a-4-2-q4","type":"choice","stem":"下列做法体现正确对待逆境的是","options":["小刚考试失利后一蹶不振","小林比赛失败后认真总结原因，继续训练","小华遇到困难就把责任推给别人","小美被批评后从此不再参加活动"],"answer":"B","explain":"正确对待逆境要冷静分析原因、积极应对。A、C、D 都是逃避或推卸责任的表现。","difficulty":1,"tags":["逆境","人生态度"]},{"id":"cat-pol-7a-4-2-q5","type":"short","stem":"小雯在一次重要比赛中失利，情绪低落，觉得自己什么都不行。请你运用本课所学，帮助小雯端正人生态度。（6 分）","answer":"①人生难免有挫折，挫折具有两面性，要正确看待失利；②保持积极的人生态度，乐观向上、认真务实、勤奋进取；③冷静分析失败原因，总结教训，改进方法；④把逆境转化为成长的动力，增强生命的韧性，继续努力。","explain":"","rubric":["答出挫折具有两面性","答出保持积极的人生态度","答出冷静分析原因、总结教训","答出把逆境转化为成长动力"],"tags":["人生态度","挫折"]}]},{"id":"cat-pol-7a-4-3","title":"第13课 实现人生价值","subtitle":"七年级上册 · 第四单元 追求美好人生","grade":"7a","tags":["七年级上册","第四单元","教材新增"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级上册"},{"k":"单元","v":"第四单元 追求美好人生"},{"k":"课题","v":"第13课 实现人生价值"},{"k":"框题","v":"在劳动中创造人生价值 / 在奉献中成就精彩人生"}]},{"type":"note","title":"内容说明","text":"本课属 2024 版七上第四单元。现有道法模块尚未单列本单元条目，以下内容按教材框题整理，具体表述以正式课本为准。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["在劳动中创造人生价值","在奉献中成就精彩人生"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"劳动是财富的源泉，也是幸福的源泉；人世间的美好梦想，都是通过劳动实现的。","explain":"选择题常考「劳动的意义」，规范表述落在「财富的源泉、幸福的源泉」，不要写成「劳动只是为了挣钱」。"},{"level":"重点","text":"人生价值在于创造和贡献；评价一个人的人生价值，主要看他对社会的贡献。","explain":"材料题问「怎样评价一个人的人生价值」时，要答「看他对社会的贡献」，不能以财富、名气、职位作为标准。"},{"level":"重点","text":"在奉献中成就精彩人生：服务社会、奉献社会，在平凡岗位上尽职尽责，同样能实现人生价值。","explain":"常与「平凡与伟大」结合考查：平凡岗位上的坚守和奉献，就是创造人生价值。"},{"level":"次重点","text":"当我们将个体生命和他人的、集体的、国家的命运联系在一起时，生命便会从平凡中闪耀出伟大。","explain":"这一表述与七上第三单元相通，材料题落脚点常是「把个人命运与国家、社会联系起来」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["劳动是财富的源泉，也是幸福的源泉。","人生价值在于创造和贡献，评价人生价值主要看对社会的贡献。","在平凡岗位上尽职尽责、服务社会、奉献社会，同样能实现人生价值。","把个体生命与他人的、集体的、国家的命运联系在一起，生命会从平凡中闪耀出伟大。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为「只有做出惊天动地的大事，人生才有意义和价值」。","人生价值在于创造和贡献；在平凡岗位上尽职尽责、服务社会、奉献社会，同样能实现人生价值。","把「伟大」等同于「轰动」，忽略了平凡岗位上的坚守和奉献也是创造价值。"],["认为「劳动就是体力劳动，只有体力劳动者才是劳动者」。","无论是脑力劳动者还是体力劳动者，都是国家的建设者，都值得我们尊敬和学习。","劳动包括体力劳动和脑力劳动，二者都在创造社会财富。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 珍爱我们的生命：守护生命安全·保持身心健康","url":"/learn/politics/pages/detail/detail?moduleId=pol-growth&entryId=pol-growth-4"},{"t":"专题精讲 · 第9课 积极奉献社会（责任与角色同在 · 关爱他人 · 服务社会）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"cat-pol-7a-4-3-q1","type":"choice","stem":"「劳动是财富的源泉，也是幸福的源泉。」这告诉我们","options":["只有体力劳动才创造价值","人生价值在劳动中创造，要尊重劳动、热爱劳动","劳动只是为了获得金钱","脑力劳动不算劳动"],"answer":"B","explain":"劳动是财富和幸福的源泉，人生价值在劳动中创造。体力劳动和脑力劳动都是劳动，劳动的意义不只是获得金钱。","difficulty":1,"tags":["劳动","人生价值"]},{"id":"cat-pol-7a-4-3-q2","type":"choice","stem":"评价一个人的人生价值，主要应看","options":["他拥有多少财富","他获得多少荣誉","他对社会的贡献","他的职位高低"],"answer":"C","explain":"教材表述：评价一个人的人生价值，主要看他对社会的贡献，而不是财富、荣誉或职位。","difficulty":1,"tags":["人生价值","贡献"]},{"id":"cat-pol-7a-4-3-q3","type":"choice","stem":"「平凡的生命也能创造伟大。」下列理解正确的是","options":["只有做出惊天动地的大事，人生才有价值","在平凡岗位上尽职尽责、服务社会，同样能实现人生价值","平凡的人不可能有精彩人生","实现人生价值只能靠机遇"],"answer":"B","explain":"平凡岗位上的坚守和奉献同样能创造人生价值。A、C 把伟大绝对化，D 否认了主观努力。","difficulty":2,"tags":["人生价值","平凡与伟大"]},{"id":"cat-pol-7a-4-3-q4","type":"choice","stem":"中学生积极参加社区志愿服务，其意义在于","options":["只是为了获得表扬","服务社会、奉献社会，在奉献中实现人生价值","会耽误学习，没有意义","只有成年人才能服务社会"],"answer":"B","explain":"服务社会、奉献社会是实现人生价值的重要途径。参加志愿服务不是为了表扬，也不会因年龄而失去意义。","difficulty":1,"tags":["奉献","服务社会"]},{"id":"cat-pol-7a-4-3-q5","type":"short","stem":"在抗击自然灾害、保障群众生活的过程中，许多普通劳动者坚守岗位、默默奉献。请运用本课所学，谈谈你对「在劳动和奉献中实现人生价值」的理解。（6 分）","answer":"①劳动是财富的源泉，也是幸福的源泉，人生价值在劳动中创造；②人生价值在于创造和贡献，评价人生价值主要看对社会的贡献；③在平凡岗位上尽职尽责、服务社会、奉献社会，同样能实现人生价值；④把个人生命与他人的、集体的、国家的命运联系起来，在奉献中成就精彩人生。","explain":"","rubric":["答出劳动是财富和幸福的源泉","答出人生价值在于创造和贡献","答出平凡岗位也能实现人生价值","答出服务社会、奉献社会"],"tags":["人生价值","劳动","奉献"]}]},{"id":"cat-pol-7b-1-1","title":"第1课 青春正当时","subtitle":"七年级下册 · 第一单元 珍惜青春时光","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 珍惜青春时光"},{"k":"课题","v":"第1课 青春正当时"},{"k":"框题","v":"青春的邀约 / 男生女生 / 学会自我保护"}]},{"type":"note","title":"本课在单元中的位置","text":"青春期是身体发育与心理发展急剧变化的关键时期：身体迅速变化、自我意识增强、情绪起伏明显，同时要面对心理矛盾、异性交往与自我保护等现实问题；学会管理情绪、品味美好情感、增强自我保护能力，既是个人健康成长的需要，也是中考心理调适与道德修养类试题最稳定的给分点。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["青春的邀约","男生女生","学会自我保护"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"男生女生各自拥有自身的性别优势，可以相互理解、相互帮助、取长补短；我们要正确对待性别刻板印象，不过于受性别刻板印象的影响，因为它可能影响我们自身潜能的发挥；与异性交往有助于我们了解异性的思维方式、情感特征，看到对方的优点、相互取长补短，让自己变得更加优秀，交往时要做到内心坦荡、言谈得当、举止得体。","explain":"认识类设问考「怎样看待男生女生的差异」，做法类设问考「怎样与异性交往」。答案必须写出「内心坦荡、言谈得当、举止得体」这三个短语；写「不要和异性来往」「男女差别决定谁只能做什么」都是错的。"},{"level":"重点","text":"青春期我们的身体变化主要表现在三个方面：身体外形的变化、身体内部器官的完善、性机能的成熟；受遗传、营养、锻炼等因素的影响，每个人的发育节律不同，有早有晚，我们要正视身体的变化，不因发育早晚而自卑或焦虑。","explain":"选择题常把「发育节律完全相同」「发育晚就是不健康」「身体发育是自己的隐私，遇到困惑只能自己解决」设为干扰项。判断时先分清它说的是身体变化（外形、内部器官、性机能）还是心理变化（认知、自我意识、情感），再把正确态度落到「正视差异、注重内在修养、有困惑向父母老师求助」上。"},{"level":"重点","text":"青春期我们的心理也在发生变化：认知能力得到发展，自我意识不断增强，情感世界愈加丰富；同时往往会出现反抗与依赖、闭锁与开放、勇敢与怯懦等矛盾心理，这些矛盾心理是我们成长过程中正常的心理现象，它有时让我们烦恼，也为我们的成长提供了契机。","explain":"心理认识类设问的第一句话必须是「这是成长过程中正常的心理现象」，再说明它既可能成为发展的阻力，也可能成为发展的动力。凡说「心理有病」「性格有缺陷」「不正常」的选项一律错误，这是价值观判断的直接失分点。"},{"level":"次重点","text":"面对青春期的心理矛盾，我们可以通过参加集体活动、在集体的温暖中放松自己，通过求助他人、学习化解烦恼的方法，通过自我调节、成为自己的「心理保健医生」等途径积极面对和正确处理。","explain":"做法建议类设问的骨干答案，三个途径要写全。具体做法都要能归到这三条之下：参加文体活动、社团与志愿服务属于参加集体活动；向父母、老师、朋友倾诉属于求助他人；写日记、自我暗示、换个角度看问题属于自我调节。只写「想开点」「别多想」不得分。"},{"level":"次重点","text":"青春的创造是多姿多彩的，我们要开发自己的创造潜力：敢于打破常规，追求创新与生活的丰富多彩；社会实践是创造的源泉，要在实践中开发自己的创造潜力。","explain":"常以校园科技节、创意设计、小发明等材料考查，落脚点是「敢于打破常规」与「积极参加社会实践」。只答「要有想象力」「要多动脑」不够，必须落到实践这一层。"},{"level":"重点","text":"我们要增强自我保护意识，提高自我保护能力：了解身体的界限，知道身体的隐私部位不容他人随意触碰；对不当的身体接触要勇敢说「不」，并及时拒绝、尽快离开；实施侵害的人可能是陌生人，也可能是认识的人，不能因为是熟人就放松警惕；遇到侵害要第一时间告知父母、老师等信任的人并报警，注意保留相关证据，不能因为害怕或羞耻而隐瞒——受到侵害不是受害者的过错。","explain":"「学会自我保护」的必答内容，考法与表述都要求严肃、具体、可操作。答题按「拒绝—离开—告知信任的人—报警—保留证据」的顺序写，切忌写成「躲着点」「小心点」这类空话，也不能出现「是自己不小心」这类归责于受害者的表述。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["青春期我们的身体变化主要表现在身体外形的变化、身体内部器官的完善、性机能的成熟，每个人的发育节律不同，要正视自己的身体变化。","我们要增强自我保护意识，提高自我保护能力，了解身体的界限，对不当的身体接触勇敢说「不」，遇到侵害要及时告知父母、老师等信任的人并报警，注意保留相关证据。","青春期情绪的特点是反应强烈、波动与固执、细腻性、闭锁性、表现性；情绪影响着我们的观念和行动，但情绪是可以调节的。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为男生女生之间的正常交往会影响学习，为了避免早恋，男女生最好不要有任何交往。","男生女生各自拥有自身的性别优势，与异性交往有助于我们了解异性的思维方式、情感特征，相互取长补短，让自己变得更加优秀；交往时要做到内心坦荡、言谈得当、举止得体。","把正常异性交往等同于早恋，是认识类试题的常见错误。答题必须正面写出异性交往的意义与三个交往要求，不能只写「保持距离」。"],["认为青春期出现反抗与依赖、闭锁与开放、勇敢与怯懦等心理矛盾，说明「心理不健康」「性格有缺陷」。","这些矛盾心理是我们成长过程中正常的心理现象，它有时让我们烦恼，也为我们的成长提供了契机；可以通过参加集体活动、求助他人、自我调节等方式积极面对和正确处理。","把正常现象说成疾病或缺陷，是心理认识类试题最常见的错误，也是价值观判断的直接失分点。只要题干中出现「有病」「不正常」「无法改变」，一律排除。"]]},{"type":"table","title":"青春期的身体变化与心理变化（青春期两个方面的对比）（本单元概念对比）","head":["比较项","身体变化","心理变化"],"rows":[["主要表现","身体外形的变化、身体内部器官的完善、性机能的成熟","认知能力得到发展，自我意识不断增强，情感世界愈加丰富"],["突出矛盾","发育节律有早有晚，个体差异明显","反抗与依赖、闭锁与开放、勇敢与怯懦等矛盾心理并存"],["正确态度","正视身体的变化与个体差异，不因发育早晚自卑或焦虑，注重内在修养","认识到这是成长过程中正常的心理现象，参加集体活动、求助他人、自我调节"],["共同点","都是青春期成长的正常表现，都需要以积极的心态面对","同左"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["青春期心理矛盾的认识与调适","以「不愿和父母谈心却又渴望被理解」「想自己做决定又离不开父母」等情境，考查矛盾心理的表现与调适方法。作答时先判断「这是成长过程中正常的心理现象」，再从参加集体活动、求助他人、自我调节三条途径给出办法，缺了第一句判断就会丢掉价值判断的分。"],["情绪调节方法「对号入座」","给出一段情境问「他用了哪种调节情绪的方法」，要求把方法名称与情境一一对应。答题必须写规范术语（改变认知评价、转移注意、合理宣泄、放松训练），写「想开点」「忍一忍」「哭一场就好了」不得分。"],["情绪与情感的辨析","给出「一时激动」与「长期形成的深厚感情」两类描述，要求判断并说明理由，答题必须写清「短暂、不稳定、随情境变化」与「逐渐积累、相对稳定」的区别，再补上情感的作用。"],["自我保护类做法建议题","以校园欺凌、不当身体接触等情境考查「你该怎么办」。防范性侵害按「拒绝—离开—告知信任的人—报警—保留证据」作答；防范校园欺凌按「不做受害者、不做欺凌者、不做冷漠的旁观者」三个层次作答，并指出欺凌他人要承担道德责任和法律责任。表述要严肃、具体、可操作。"],["青春期情绪特点的情境分析","给出一段情绪起伏的情境材料，问「反映了青春期情绪的哪些特点」。答题要先把材料中的表现与反应强烈、波动与固执、细腻性、闭锁性、表现性等术语对应起来，再落到「情绪影响着我们的观念和行动，要学会调节情绪」。"],["异性交往与男女优势互补的认识题","以班级活动、学习互助小组等情境考查对性别差异与异性交往的认识。正确答法是先肯定「男生女生各自拥有自身的性别优势，交往有助于取长补短、让自己变得更加优秀」，再写出「内心坦荡、言谈得当、举止得体」的交往要求。"]]},{"type":"quote","text":"【材料一】小琳的同桌因为说话有些口吃，被班上几名同学起了侮辱性的绰号，课间还常被故意撞倒。小琳觉得这样不对，但怕被一起嘲笑，一直没有说什么，也没有告诉老师。\n【材料二】学校开展「学会自我保护」专题教育。老师告诉同学们：背心和短裤遮盖的部位是身体的隐私部位，任何人都不能随意触碰；如果有人以「帮忙」「带你出去玩」为由，试图把你带到没人的地方，或者对你做出让你不舒服的身体接触，要立即拒绝、尽快离开，并在第一时间告诉父母或老师。老师特别提醒，实施侵害的人可能是陌生人，也可能是认识的人；遇到侵害要勇敢说出来并报警，注意保留相关证据。\n【材料三】专题教育后，小琳把同桌被欺凌的情况报告了班主任，学校对相关同学进行了批评教育。小琳还学会了在上学路上与同学结伴而行，遇到有人尾随就走进附近的商店或人多的地方。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·珍惜青春时光（第1—2课：青春正当时 · 做情绪情感的主人）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-1-m1-q1","type":"short","stem":"（1）结合材料一，指出小宇的情绪表现反映了青春期情绪的哪些特点。（4 分）","answer":"①反应强烈：考试前紧张得睡不着觉，被同学误解后气得一整天不说话，说明青春期情绪来得快、强度大；②闭锁性：他有时很想把烦恼告诉父母，可话到嘴边又觉得说不出口，说明他不愿轻易把内心情绪告诉别人。可见青春期情绪具有反应强烈、波动与固执、细腻性、闭锁性、表现性等特点，情绪影响着我们的观念和行动，我们需要学会调节情绪。","explain":"","tags":["青春期情绪特点","情绪的觉察"],"rubric":["答出「反应强烈」并结合材料一说明（考试前紧张、被误解后生气）","答出「闭锁性」并结合材料一说明（想说却说不出口）","使用青春期情绪特点的规范术语，而不是只描述现象","答出情绪影响着我们的观念和行动、需要学会调节情绪"]},{"id":"pol-youth-1-m2-q3","type":"short","stem":"（3）结合材料二，说说我们应当怎样防范性侵害、保护自己。（6 分）","answer":"①增强自我保护意识，提高自我保护能力，了解身体的界限，知道背心和短裤遮盖的隐私部位不容他人随意触碰。②对不当的身体接触要勇敢说「不」，立即拒绝并尽快离开；实施侵害的人可能是陌生人，也可能是认识的人，不能因为是熟人就放松警惕。③不轻易接受陌生人的食物、饮料和礼物，不跟他人到没人的地方去，外出时尽量结伴而行并告知父母自己的去向。④遇到侵害要第一时间告知父母、老师等信任的人并报警，注意保留相关证据。⑤受到侵害不是受害者的过错，不能因为害怕或羞耻而隐瞒，隐瞒会使自己得不到及时保护，也会让侵害者继续作恶。","explain":"","tags":["学会自我保护","防范性侵害"],"rubric":["答出增强自我保护意识、提高自我保护能力，了解身体的界限与隐私部位","答出对不当的身体接触勇敢说「不」，及时拒绝并离开","答出警惕熟人作案，不轻信、不跟他人到没人的地方、外出结伴并告知去向","答出及时告知父母、老师等信任的人并报警，注意保留相关证据","答出受到侵害不是受害者的过错，不能因为害怕或羞耻而隐瞒"]},{"id":"pol-youth-1-q1","type":"choice","stem":"进入青春期，我们身体变化的主要表现是","answer":"A","explain":"教材指出青春期身体变化主要表现在三个方面：身体外形的变化、身体内部器官的完善、性机能的成熟。B 只说出了身体外形变化中的两个现象，不全面；C 描述的是青春期情绪的特点，D 描述的是心理变化中的自我意识增强，二者都不属于身体变化。","options":["身体外形的变化、身体内部器官的完善、性机能的成熟","只有身高迅速增长、体重明显增加","情绪容易激动，对人对事的感受变得更加细腻","自我意识不断增强，渴望独立和自由"],"difficulty":1,"tags":["青春的邀约","青春期身体变化"]},{"id":"pol-youth-1-q2","type":"choice","stem":"对青春期出现的反抗与依赖、闭锁与开放、勇敢与怯懦等心理矛盾，下列认识正确的是","answer":"C","explain":"这些矛盾心理是成长过程中正常的心理现象，它有时让我们烦恼，也为我们的成长提供了契机；可以通过参加集体活动、求助他人、自我调节等途径积极面对和正确处理。A、B 把正常现象说成疾病或缺陷；D 以盲从代替调适，都不能真正化解矛盾。","options":["这说明我们的心理不健康，必须立即就医","这说明我们性格有严重缺陷，无法改变","这是成长过程中正常的心理现象，可以通过参加集体活动、求助他人、自我调节来调适","只要完全按父母和老师的要求去做，这些矛盾就会消失"],"difficulty":2,"tags":["青春期心理变化","心理矛盾的调适"]},{"id":"pol-youth-1-q4","type":"choice","stem":"对独立思考与批判精神的认识，正确的是","answer":"B","explain":"独立思考并不等同于一味追求独特，而是表现为不人云亦云，有自己独到的见解，同时能接纳他人合理、正确的意见；批判性思维敢于表达不同观点、敢于对不合理的事情说「不」，但只针对事情本身，不是对人的攻击，要考虑他人的感受，做到有则改之、无则加勉。A 把独立思考等同于标新立异，C 把批判等同于否定一切，D 忽视了批判也要考虑他人感受。","options":["独立思考就是一味追求独特，处处与别人不一样","独立思考表现为不人云亦云、有自己独到的见解，同时能接纳他人合理、正确的意见；批判只针对事情本身，不攻击他人","批判就是敢于否定一切，对别人的观点一律说「不」","只要敢于表达不同观点，就不必考虑他人的感受"],"difficulty":2,"tags":["青春的邀约","独立思考与批判精神"]},{"id":"pol-youth-1-q5","type":"choice","stem":"对男生女生的差异与交往，认识正确的是","answer":"A","explain":"男生女生各自拥有自身的性别优势，正常的异性交往有助于我们了解异性的思维方式、情感特征，相互取长补短，让自己变得更加优秀，交往时要做到内心坦荡、言谈得当、举止得体。B 是受性别刻板印象影响的表现，性别刻板印象可能影响我们自身潜能的发挥；C、D 否认了正常异性交往的意义。","options":["男生女生各自拥有自身的性别优势，相互取长补短有助于我们变得更加优秀；与异性交往要做到内心坦荡、言谈得当、举止得体","男女生的差别决定了男生只能做体力型的事情、女生只能做细致的事情","为了避免早恋，男生女生之间最好不要有任何交往","与异性交往一定会影响学习，应当完全拒绝"],"difficulty":2,"tags":["男生女生","异性交往"]}]},{"id":"cat-pol-7b-1-2","title":"第2课 做情绪情感的主人","subtitle":"七年级下册 · 第一单元 珍惜青春时光","grade":"7b","tags":["七年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第一单元 珍惜青春时光"},{"k":"课题","v":"第2课 做情绪情感的主人"},{"k":"框题","v":"揭开情绪的面纱 / 学会管理情绪 / 品味美好情感"}]},{"type":"note","title":"本课在单元中的位置","text":"青春期是身体发育与心理发展急剧变化的关键时期：身体迅速变化、自我意识增强、情绪起伏明显，同时要面对心理矛盾、异性交往与自我保护等现实问题；学会管理情绪、品味美好情感、增强自我保护能力，既是个人健康成长的需要，也是中考心理调适与道德修养类试题最稳定的给分点。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["揭开情绪的面纱","学会管理情绪","品味美好情感"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"情感与情绪紧密相关：我们对某些人或者事物的情绪，随着时间的推移形成比较稳定的倾向，就可能产生某种情感；情绪是短暂的、不稳定的，会随着情境的改变而变化，情感则是在生活中不断强化、逐渐积累的，相对稳定。情感是人最基本的精神需求，它反映我们对人和对事的态度、观念，影响我们的判断和选择，驱使我们做出行动，美好的情感促进我们的精神发展。","explain":"本单元最典型的易混点。判断口诀是先看稳定性、再看产生方式：题干说「一时冲动」「随情境变化」是情绪，说「逐渐积累、长期形成、相对稳定」是情感。问「情感的作用」就按「最基本的精神需求—影响判断和选择—促进精神发展」三点作答。"},{"level":"了解","text":"美好情感是在人的社会交往、互动中自然引发的，不能强迫；我们可以通过阅读、与人交往、参与有意义的社会活动等方式获得美好的情感，在生活中不断创造美好的情感体验，用自己的热情和行动来影响环境，学会关心他人，传递情感正能量。","explain":"常与志愿服务、公益活动、阅读经典等材料结合，落脚点是「创造美好的情感体验」与「学会关心他人（关注他人的需求、体察他人的感受）」。只写「要开心一点」不踩点。"},{"level":"重点","text":"青春期我们的身体变化主要表现在三个方面：身体外形的变化、身体内部器官的完善、性机能的成熟；受遗传、营养、锻炼等因素的影响，每个人的发育节律不同，有早有晚，我们要正视身体的变化，不因发育早晚而自卑或焦虑。","explain":"选择题常把「发育节律完全相同」「发育晚就是不健康」「身体发育是自己的隐私，遇到困惑只能自己解决」设为干扰项。判断时先分清它说的是身体变化（外形、内部器官、性机能）还是心理变化（认知、自我意识、情感），再把正确态度落到「正视差异、注重内在修养、有困惑向父母老师求助」上。"},{"level":"重点","text":"青春期我们的心理也在发生变化：认知能力得到发展，自我意识不断增强，情感世界愈加丰富；同时往往会出现反抗与依赖、闭锁与开放、勇敢与怯懦等矛盾心理，这些矛盾心理是我们成长过程中正常的心理现象，它有时让我们烦恼，也为我们的成长提供了契机。","explain":"心理认识类设问的第一句话必须是「这是成长过程中正常的心理现象」，再说明它既可能成为发展的阻力，也可能成为发展的动力。凡说「心理有病」「性格有缺陷」「不正常」的选项一律错误，这是价值观判断的直接失分点。"},{"level":"次重点","text":"男生女生各自拥有自身的性别优势，可以相互理解、相互帮助、取长补短；我们要正确对待性别刻板印象，不过于受性别刻板印象的影响，因为它可能影响我们自身潜能的发挥；与异性交往有助于我们了解异性的思维方式、情感特征，看到对方的优点、相互取长补短，让自己变得更加优秀，交往时要做到内心坦荡、言谈得当、举止得体。","explain":"认识类设问考「怎样看待男生女生的差异」，做法类设问考「怎样与异性交往」。答案必须写出「内心坦荡、言谈得当、举止得体」这三个短语；写「不要和异性来往」「男女差别决定谁只能做什么」都是错的。"},{"level":"次重点","text":"情绪是一种综合的心理状态，包括内在体验、外显表情和生理反应；喜、怒、哀、惧是人的基本情绪；我们的情绪受个人的生理周期、对某件事情的预期、周围的舆论氛围、自然环境等因素的影响，随着周围情况的变化，情绪也经常变化。","explain":"选择题常考「情绪的成分」与「影响情绪的因素」，两者不能混：内在体验、外显表情、生理反应是情绪的构成成分；个人的生理周期、对事情的预期、舆论氛围、自然环境是影响情绪的因素。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["青春期情绪的特点是反应强烈、波动与固执、细腻性、闭锁性、表现性；情绪影响着我们的观念和行动，但情绪是可以调节的。","调节情绪常用的方法有改变认知评价、转移注意、合理宣泄、放松训练；我们要接受自己的情绪，以恰当的方式表达情绪，保持积极的心态。","情感反映我们对人和对事的态度、观念，影响我们的判断和选择，驱使我们做出行动；我们要在生活中不断创造美好的情感体验，学会关心他人，传递情感正能量。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把情绪当成情感，例如把「小明今天因被误解而非常生气」判断为「小明对同学产生了深厚的情感」。","情绪是短暂的、不稳定的，会随着情境的改变而变化；情感是在生活中不断强化、逐渐积累的，相对稳定。一时的生气属于情绪，长期形成的对父母、老师、家乡的深厚感情才是情感。","这是本单元最典型的易混点，选择题常把「短暂、随情境变化」与「逐渐积累、相对稳定」互换设错。判断顺序是先看稳定性，再看产生方式。"],["认为男生女生之间的正常交往会影响学习，为了避免早恋，男女生最好不要有任何交往。","男生女生各自拥有自身的性别优势，与异性交往有助于我们了解异性的思维方式、情感特征，相互取长补短，让自己变得更加优秀；交往时要做到内心坦荡、言谈得当、举止得体。","把正常异性交往等同于早恋，是认识类试题的常见错误。答题必须正面写出异性交往的意义与三个交往要求，不能只写「保持距离」。"]]},{"type":"table","title":"情绪与情感：一字之差，两点不同（同一单元内的核心概念辨析）（本单元概念对比）","head":["比较项","情绪","情感"],"rows":[["稳定性","短暂的、不稳定的，会随着情境的改变而变化","在生活中不断强化、逐渐积累，相对稳定"],["产生方式","对某一情境的直接反应，来得快、去得也快","由情绪随着时间推移形成比较稳定的倾向而发展而来"],["典型表现","喜、怒、哀、惧，如一时的高兴、生气、害怕、紧张","安全感、道德感、爱的情感，对家乡和祖国的深厚感情"],["对行动的作用","影响我们的观念和行动，可能激励我们努力向上，也可能让我们止步不前","反映我们对人和对事的态度、观念，影响判断和选择，驱使我们做出行动，促进精神发展"],["调节与培养","可以通过改变认知评价、转移注意、合理宣泄、放松训练来调节","在阅读、与人交往、参与有意义的社会活动中获得和培养"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["青春期心理矛盾的认识与调适","以「不愿和父母谈心却又渴望被理解」「想自己做决定又离不开父母」等情境，考查矛盾心理的表现与调适方法。作答时先判断「这是成长过程中正常的心理现象」，再从参加集体活动、求助他人、自我调节三条途径给出办法，缺了第一句判断就会丢掉价值判断的分。"],["情绪调节方法「对号入座」","给出一段情境问「他用了哪种调节情绪的方法」，要求把方法名称与情境一一对应。答题必须写规范术语（改变认知评价、转移注意、合理宣泄、放松训练），写「想开点」「忍一忍」「哭一场就好了」不得分。"],["情绪与情感的辨析","给出「一时激动」与「长期形成的深厚感情」两类描述，要求判断并说明理由，答题必须写清「短暂、不稳定、随情境变化」与「逐渐积累、相对稳定」的区别，再补上情感的作用。"],["自我保护类做法建议题","以校园欺凌、不当身体接触等情境考查「你该怎么办」。防范性侵害按「拒绝—离开—告知信任的人—报警—保留证据」作答；防范校园欺凌按「不做受害者、不做欺凌者、不做冷漠的旁观者」三个层次作答，并指出欺凌他人要承担道德责任和法律责任。表述要严肃、具体、可操作。"],["青春期情绪特点的情境分析","给出一段情绪起伏的情境材料，问「反映了青春期情绪的哪些特点」。答题要先把材料中的表现与反应强烈、波动与固执、细腻性、闭锁性、表现性等术语对应起来，再落到「情绪影响着我们的观念和行动，要学会调节情绪」。"],["异性交往与男女优势互补的认识题","以班级活动、学习互助小组等情境考查对性别差异与异性交往的认识。正确答法是先肯定「男生女生各自拥有自身的性别优势，交往有助于取长补短、让自己变得更加优秀」，再写出「内心坦荡、言谈得当、举止得体」的交往要求。"]]},{"type":"quote","text":"【材料一】小宇升入初中后，情绪起伏比小学时大得多：考试前会紧张得睡不着觉，被同学误解时会气得一整天不说话。他有时很想把心里的烦恼告诉父母，可话到嘴边又觉得说不出口。\n【材料二】在班主任的建议下，小宇参加了学校的篮球队，每次训练结束他都觉得心里轻松了许多。他还学会了在心里对自己说：「一次没考好，不说明我不行，把错题弄懂才是要紧的。」他也开始把烦恼写进日记本，写完就觉得不那么难受了。\n【材料三】周末，小宇跟着爸爸到社区参加志愿服务，为独居老人送餐。看到老人拉着他的手不停道谢，小宇心里暖暖的。他说：「原来被需要是这样一种感觉，我以后想常来。」","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·珍惜青春时光（第1—2课：青春正当时 · 做情绪情感的主人）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-1-m1-q1","type":"short","stem":"（1）结合材料一，指出小宇的情绪表现反映了青春期情绪的哪些特点。（4 分）","answer":"①反应强烈：考试前紧张得睡不着觉，被同学误解后气得一整天不说话，说明青春期情绪来得快、强度大；②闭锁性：他有时很想把烦恼告诉父母，可话到嘴边又觉得说不出口，说明他不愿轻易把内心情绪告诉别人。可见青春期情绪具有反应强烈、波动与固执、细腻性、闭锁性、表现性等特点，情绪影响着我们的观念和行动，我们需要学会调节情绪。","explain":"","tags":["青春期情绪特点","情绪的觉察"],"rubric":["答出「反应强烈」并结合材料一说明（考试前紧张、被误解后生气）","答出「闭锁性」并结合材料一说明（想说却说不出口）","使用青春期情绪特点的规范术语，而不是只描述现象","答出情绪影响着我们的观念和行动、需要学会调节情绪"]},{"id":"pol-youth-1-m1-q2","type":"short","stem":"（2）结合材料二，指出小宇调节情绪的方法，并再为他推荐两种调节情绪的方法。（6 分）","answer":"小宇使用的方法：①转移注意——参加篮球队，通过打球把注意力从引起不良情绪的事情上转移出来；②改变认知评价——告诉自己一次没考好不说明自己不行，换个角度看问题；③合理宣泄——把烦恼写进日记本，把不良情绪释放出来。再推荐：④放松训练——通过深呼吸、肌肉放松、听舒缓的音乐等方式，使身体和情绪平静下来；⑤合理宣泄的另一种方式——向信任的父母、老师、朋友倾诉（宣泄要合理，不能伤害自己，不能损害他人和集体的利益，不能违反道德和法律）。","explain":"","tags":["调节情绪的方法","改变认知评价","转移注意"],"rubric":["答出「转移注意」并结合材料说明（参加篮球队）","答出「改变认知评价」并结合材料说明（换个角度看待考试失利）","答出「合理宣泄」并结合材料说明（写日记）","再推荐两种方法并写出规范的方法名称（放松训练、合理宣泄等）","说明宣泄要合理的边界，或明确写出情绪要以恰当的方式表达"]},{"id":"pol-youth-1-q1","type":"choice","stem":"进入青春期，我们身体变化的主要表现是","answer":"A","explain":"教材指出青春期身体变化主要表现在三个方面：身体外形的变化、身体内部器官的完善、性机能的成熟。B 只说出了身体外形变化中的两个现象，不全面；C 描述的是青春期情绪的特点，D 描述的是心理变化中的自我意识增强，二者都不属于身体变化。","options":["身体外形的变化、身体内部器官的完善、性机能的成熟","只有身高迅速增长、体重明显增加","情绪容易激动，对人对事的感受变得更加细腻","自我意识不断增强，渴望独立和自由"],"difficulty":1,"tags":["青春的邀约","青春期身体变化"]},{"id":"pol-youth-1-q3","type":"choice","stem":"小凯被同学误解后非常生气，他对自己说：「也许他不是故意的，等问清楚再说。」小凯调节情绪的方法是","answer":"D","explain":"改变认知评价是从另一个角度认识和评价事情，从而改变自己的情绪，小凯提醒自己「也许他不是故意的」正属于这种方法。转移注意是把注意力从引起不良情绪的事情上转到其他事物上；合理宣泄是通过倾诉、写日记、适当运动等方式释放不良情绪；放松训练是通过深呼吸、肌肉放松、听舒缓音乐等方式使身体和情绪平静下来。","options":["合理宣泄","转移注意","放松训练","改变认知评价"],"difficulty":2,"tags":["调节情绪的方法","改变认知评价"]},{"id":"pol-youth-1-q8","type":"choice","stem":"关于情感的作用，下列说法正确的是","answer":"C","explain":"情感是人最基本的精神需求，它反映我们对人和对事的态度、观念，影响我们的判断和选择，驱使我们做出行动；丰富、深刻的情感有助于我们更全面地观察事物、探索未知，美好的情感促进我们的精神发展。A 描述的是情绪的特点，不是情感的特点；B、D 否认了情感的作用和来源，美好情感正是在人的社会交往、互动中自然引发的。","options":["情感是短暂的、不稳定的，会随着情境的改变而变化","情感与我们的判断和选择无关，只影响人的情绪","情感反映我们对人和对事的态度、观念，影响我们的判断和选择，驱使我们做出行动，美好的情感促进我们的精神发展","情感不需要在生活中培养，与我们的社会交往没有关系"],"difficulty":2,"tags":["情感的作用","情绪与情感"]},{"id":"pol-youth-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 青春期我们的身体变化主要表现在三个方面：身体外形的变化、身体内部器官的完善、性机…\n② 青春期我们的心理也在发生变化：认知能力得到发展，自我意识不断增强，情感世界愈加丰…\n③ 面对青春期的心理矛盾，我们可以通过参加集体活动、在集体的温暖中放松自己，通过求助…\n④ 认为青春期出现反抗与依赖、闭锁与开放、勇敢与怯懦等心理矛盾，说明「心理不健康」「…","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——把正常现象说成疾病或缺陷，是心理认识类试题最常见的错误，也是价值观判断的直接失分点。只要题干中出现「有病」「不正常」「无法改变」，一律排除；正确表述应为：这些矛盾心理是我们成长过程中正常的心理现象，它有时让我们烦恼，也为我们的成长提供了契机；可以通过参加集体活动、求助他人、自我调节等方式积极面对和正确处理。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第一单元·珍惜青春时光（第1—2课：青春正当时 · 做情绪情感的主人）"]}]},{"id":"cat-pol-7b-2-1","title":"第3课 人贵自尊","subtitle":"七年级下册 · 第二单元 焕发青春活力","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 焕发青春活力"},{"k":"课题","v":"第3课 人贵自尊"},{"k":"框题","v":"人须有自尊 / 做自尊的人"}]},{"type":"note","title":"本课在单元中的位置","text":"青春是人一生中最有活力也最需要立起精神脊梁的阶段：自尊让我们懂得自我尊重、知廉耻懂荣辱，从而守住做人的底线；自信让我们肯定自身的能力与价值，敢于展示自己、坚持把事情做下去；自强让我们奋发向上、积极进取，靠坚强的意志、进取的精神和不懈的坚持把理想变成现实。三者中自尊是前提、自信是动力、自强是行动，统一于青春的成长，最终要落到把个人奋斗融入国家发展、做自强不息的中国人。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人须有自尊","做自尊的人"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"自尊是对自我价值的肯定，是一个人自我尊重并期望受到他人、集体和社会尊重的心理状态；自尊既表现为自我尊重（看得起自己、维护自己的人格尊严），也表现为希望得到他人的尊重。","explain":"最基础的识记题，考查「什么是自尊」。判断的关键有两层：一是对内的自我尊重，二是对外希望被尊重的心理需求。凡是只强调「我要别人尊重我」而丢掉自我尊重的说法，都不是完整意义上的自尊。"},{"level":"重点","text":"自尊的人知廉耻、懂荣辱，有所为、有所不为；「行己有耻」要求我们凡自己认为可耻的事就不去做，不做有损自己人格和他人、社会利益的事。","explain":"常以情境题出现：抄袭作业、考试作弊、拿别人的缺陷取笑、为占小便宜说谎等，设问「这说明了什么」「我们应该怎么做」。答题要点是「知廉耻、懂荣辱」「有所为、有所不为」，并把具体行为对号入座，不能只写「要讲道德」。"},{"level":"重点","text":"做自尊的人，要维护自己的人格尊严，不卑不亢，既不容许别人歧视、侮辱自己，也不去歧视、侮辱他人；要尊重他人，平等对待他人，不揭人之短，不歧视他人；要正确对待他人的评价，做到有则改之、无则加勉。","explain":"做法建议类设问的骨干答案，也是本课最容易答漏的一条：必须同时写出维护自尊、尊重他人、正确对待他人评价三个层面。只写「要尊重自己」或只写「要尊重别人」都只能拿一半分。"},{"level":"次重点","text":"自卑和自负都是不自信的表现：自卑表现为轻视自己，看不到自己的长处和优势，不敢尝试；自负表现为过高估计自己，看不起别人，听不进不同意见。真正的自信是实事求是地看待自己，既看到自己的优点，也看到自己的不足。","explain":"选择题的高频陷阱，常给一段人物描写让考生判断属于自信、自负还是自卑。判断方法：看他对自己的评价是否与实际相符、是否尊重和看得起别人。看不起别人是自负，看不到自己是自卑，既如实看自己又尊重别人才是自信。"},{"level":"次重点","text":"自尊、自信、自强相互联系、相互促进：自尊是前提，只有尊重自己、守住做人的底线，才谈得上自信与自强；自信是动力，让人敢于尝试、勇于坚持；自强是行动，把对自我的肯定变成实实在在的努力。三者统一于青春的成长。","explain":"单元总结型试题与观点评析题的通用框架，也常作为材料题最后一问的升华。作答时要把三者的定位分清，不能把「前提」「动力」「行动」互换位置。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["自尊是对自我价值的肯定，是自我尊重并期望受到他人、集体和社会尊重的心理状态。","自尊的人知廉耻、懂荣辱，有所为、有所不为；行己有耻，不做有损人格的事。","做自尊的人要维护自己的人格尊严，不卑不亢，既不容许别人歧视、侮辱自己，也不去歧视、侮辱他人。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把自尊理解为只顾自己的面子：听不进任何批评，谁提意见就跟谁急，宁可硬撑着出错也不肯认错、不肯请教。","自尊是对自我价值的肯定和维护自己的人格尊严，不等于爱面子、护短；自尊的人能够正确对待他人的评价，做到有则改之、无则加勉，也能坦然承认自己的不足。","这是本课最典型的陷阱，与「行己有耻」又容易混。要分清：为了面子文过饰非、死要面子，本质是虚荣而不是自尊；真正自尊的人恰恰有勇气面对自己的错误。"],["认为自信就是自负，相信自己就是不把别人放在眼里。","自信是对自身能力与价值的肯定，是实事求是地看待自己，既看到优点也看到不足，并且尊重他人；自负则是过高估计自己、看不起别人、听不进不同意见，两者有本质区别。","选择题常给一段人物描写让判断「自信还是自负」。判断标准是两点：对自己的评价是否与自身实际相符，是否看得起别人。只要出现「看不起别人」「谁都不如我」，一律判为自负。"],["把尊重他人与自尊对立起来，认为尊重别人就是低声下气、一味迎合，会让自己没面子。","尊重他人与自尊是统一的：自尊的人懂得平等对待他人、不揭人之短、不歧视他人；尊重他人恰恰是自尊的表现，而一味迎合、失去自我的讨好，既不是尊重他人，也不是真正的自尊。","常与「同学之间产生了矛盾怎么办」的情境结合考查。答题要写出「相互尊重」这一层：维护自己的人格尊严，同时尊重他人的人格尊严，二者并不矛盾。"]]},{"type":"table","title":"自信与自负、自卑：真正的自信什么样（三种自我认识：同一场考试失利后的三种反应）（本单元概念对比）","head":["比较项","自信","自负与自卑（都是不自信的表现）"],"rows":[["对自己的认识","实事求是地看待自己，既看到优点和进步，也看到不足","自负：过高估计自己，只看到长处；自卑：轻视自己，只盯着短处"],["对他人的态度","尊重他人，虚心向他人学习，能听取不同意见","自负：看不起别人，听不进不同意见；自卑：不敢与人交往，害怕被比较"],["面对困难与失败","敢于尝试，把挫折当作成长的财富，坚持把事情做下去","自负：把失败归咎于外界，不肯反思；自卑：轻易放弃，认为自己「肯定不行」"],["行为表现","会答的问题敢于举手，主动参加活动、展示自己","自负：抢着表现却准备不足；自卑：明明会做也不敢举手、不敢报名"],["结果","激发潜能，不断进步，是成功的基石","自负容易栽跟头，自卑错失锻炼和成长的机会"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["情境判断类：判断某种言行体现的是自尊还是虚荣，是自信还是自负、自卑","给出一段人物描写或一个班级情境（被起外号、考试失利、被同学取笑、有人抢着表现），设问「这体现了什么心理品质」「他的做法是否恰当」。作答分两步：先点明品质名称（自尊／虚荣／自信／自负／自卑），再对号入座说明理由——判断自信与自负看是否实事求是、是否看得起别人；判断自尊与虚荣看是维护人格尊严还是只顾表面光彩。只说「他很有个性」这类模糊表述不得分。"],["意义作用类：自尊、自信、自强对个人成长的意义","设问常写「结合材料，说明自尊（自信／自强）对他成长的作用」。作答必须用规范表述：自尊让人知廉耻、懂荣辱，守住做人的底线，赢得他人的尊重和信任；自信让人自强，是成功的基石，能激发潜能、让人敢于尝试、勇于坚持；自强让青春奋进的步伐永不停息。意义类设问不要写成「心情变好了」这类生活化表达，要落到「成长」「进步」「实现人生价值」上。"],["做法建议类：怎样做自尊的人、自信的人、自强不息的中国人","本单元分值最高的一类设问，通常要求「结合材料并联系自身实际提建议」。三个人的固定答案框架分别是：做自尊的人——维护自己的人格尊严、不卑不亢，尊重他人、平等对待、不揭短不歧视，正确对待他人的评价、有则改之无则加勉；做自信的人——看到自己的进步与长处，增强信心与实力，虚心学习，正确面对挫折与失败；做自强不息的中国人——树立远大理想，战胜自我、超越自我，在苦干实干中磨砺意志，把个人奋斗融入国家发展、与祖国同行。建议必须可操作，写「每天坚持体育锻炼」「把不懂的题一道道弄懂」这类具体做法才踩分。"],["观点评析类：辨析「自尊就是只顾自己的面子」「自强就是不服输、绝不求助」等片面观点","按「判断—合理之处—片面之处—正确观点」四步作答。例如评析「自强就是不服输」：先承认自强确实需要坚强的意志和不懈的坚持，再指出把自强等同于盲目蛮干、拒绝帮助是片面的，最后给出自强的正确含义与要求。评析题最忌讳只表态不讲理，一定要把「为什么不对」写清楚。"],["价值引领类：把个人奋斗融入国家发展，做自强不息的中国人","以青年科技工作者、返乡创业青年、志愿服务、技能大赛等正面材料设题，最后一问多半是「作为新时代青少年，你打算怎样做」。作答在「自尊自信自强」三条做法之上，必须有升华句：树立远大理想，把个人奋斗融入国家发展，与祖国同行，做有理想、敢担当、能吃苦、肯奋斗的新时代好青年。只答个人层面的努力而没有价值升华，最高分拿不到。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·焕发青春活力（第3—5课：人贵自尊 · 自信给人力量 · 人生当自强）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-2"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-2-m1-q2","type":"short","stem":"（2）结合材料二、材料三，谈谈我们应当怎样做自尊的人、自信的人。（8 分）","answer":"①做自尊的人要维护自己的人格尊严，不卑不亢：小雅面对同学的玩笑，平静地说出「这样说话让我很不舒服」，既没有自卑退缩，也没有以牙还牙。②做自尊的人要尊重他人，平等对待他人，不揭人之短，不歧视他人：小雅在同学有困难时主动帮忙，从不拿别人的缺点取笑别人。③做自尊的人要正确对待他人的评价，做到有则改之、无则加勉：小航没有被外号困住，而是把精力放回学习和锻炼上。④做自信的人要看到自己的进步与长处，增强信心与实力：小航用「进步清单」记下自己的每一个进步，每天整理错题、向老师和同学请教，用实实在在的努力提高了成绩。⑤做自信的人要虚心学习，正确面对挫折与失败：演讲比赛只得了鼓励奖，他没有气馁，而是想着下次该怎么改。","explain":"","tags":["做自尊的人","做自信的人","做法建议"],"rubric":["答出维护自己的人格尊严、不卑不亢（结合小雅平静表达感受）","答出尊重他人、平等对待他人、不揭短不歧视（结合小雅主动帮忙、不取笑他人）","答出正确对待他人的评价，有则改之、无则加勉（结合小航不再被外号困扰）","答出看到自己的进步与长处、增强信心与实力（结合小航的进步清单与每天的努力）","答出虚心学习、正确面对挫折与失败（结合比赛得鼓励奖后的态度）"]},{"id":"pol-youth-2-m1-q3","type":"short","stem":"（3）结合材料，说明自尊与自信的联系。（4 分）","answer":"①自尊是对自我价值的肯定，自信是对自身能力与价值的肯定，二者都是对自我的积极认识。②自尊是自信的基础和前提：一个人只有尊重自己、守住自己的人格尊严，才会有勇气相信自己、展示自己；小雅不因别人的玩笑而否定自己，才守住了对自己的肯定。③自信又是自尊的重要支撑：小航在一点一滴的进步中增强了信心，也就更有底气肯定自己，不再被别人的议论左右。④二者相互联系、相互促进，共同帮助我们以积极的心态面对成长中的问题。","explain":"","tags":["自尊与自信的关系","观点说明"],"rubric":["答出自尊与自信都是对自我的积极肯定","答出自尊是自信的基础和前提","答出自信支撑自尊，二者相互促进","结合材料中的小航、小雅的具体表现作答"]},{"id":"pol-youth-2-q1","type":"choice","stem":"下列关于自尊的说法，正确的是","answer":"C","explain":"自尊是对自我价值的肯定，既包括自我尊重，也包括期望受到他人、集体和社会的尊重。A 项把自尊等同于爱面子、护短，那是虚荣；B 项丢掉了尊重他人这一面，自尊的人懂得平等对待他人；D 项把维护自尊变成了听不进任何意见，自尊的人应当正确对待他人的评价，有则改之、无则加勉。","options":["自尊就是只顾自己的面子，做错了事也不能认错","自尊就是只要求别人尊重自己，不必去尊重别人","自尊是对自我价值的肯定，是自我尊重并期望受到他人、集体和社会尊重的心理状态","自尊就是谁批评我我就反驳谁，绝不吃亏"],"difficulty":1,"tags":["自尊的含义"]},{"id":"pol-youth-2-q2","type":"choice","stem":"自习课上，同桌把一张写着答案的纸条推给小华。小华想起「行己有耻」这句话，把纸条还了回去，自己独立完成了练习。小华的做法主要体现了","answer":"A","explain":"「行己有耻」要求我们知廉耻、懂荣辱，凡自己认为可耻的事就不去做，有所为、有所不为。抄答案应付作业是有损自己人格和学业的行为，小华拒绝抄答案，是自尊与知耻的表现。B 项混淆是非；C 项把维护底线的行为说成虚荣；D 项与题意无关，这里的拒绝与自信没有关系。","options":["知廉耻、懂荣辱，有所为、有所不为","过于死板，不懂同学之间的互帮互助","为了在老师面前表现自己，属于虚荣","缺乏自信，不敢接受别人的帮助"],"difficulty":2,"tags":["行己有耻","自尊的表现"]},{"id":"pol-youth-2-q3","type":"choice","stem":"小美成绩中等，她既清楚自己基础扎实、思路灵活的长处，也承认自己计算容易出错，于是每天坚持做十道计算题，成绩稳步提升。小美的表现属于","answer":"D","explain":"自信是对自身能力与价值的肯定，其特点是实事求是地看待自己，既看到优点和进步，也看到不足，并在此基础上努力改进。小美既看到长处又承认短处，还坚持练习提高，属于自信。自负表现为过高估计自己、看不起别人；自卑表现为轻视自己、看不到长处；虚荣追求的是表面的光彩，三者都不符合小美的表现。","options":["自负，过高估计了自己的能力","自卑，看不到自己的长处和优势","虚荣，只是想得到老师和同学的表扬","自信，能够实事求是地看待自己"],"difficulty":2,"tags":["自信与自负、自卑的区别"]},{"id":"pol-youth-2-q5","type":"choice","stem":"晓琳的脸上有一块胎记，有同学拿这件事开玩笑。下列晓琳的做法中，最恰当的是","answer":"D","explain":"做自尊的人要维护自己的人格尊严，不卑不亢：既不容许别人歧视、侮辱自己，也不去歧视、侮辱他人。D 项既明确表达了自己的感受，守住了人格尊严，又没有自卑退缩、以牙还牙，是恰当的做法。A 项是自卑退缩，B 项是不尊重他人、以错对错，C 项一味迎合失去了自我，都不是自尊的表现。","options":["从此不敢抬头见人，把自己封闭起来，尽量不与人交往","用同样的方式取笑对方的缺点，让对方也难堪一次","为了不被嘲笑而处处迎合同学，不敢表达自己的想法","平静地告诉对方这样说话让自己很不舒服，同时不因此否定自己，继续认真做好自己的事情"],"difficulty":2,"tags":["做自尊的人","维护人格尊严"]}]},{"id":"cat-pol-7b-2-2","title":"第4课 自信给人力量","subtitle":"七年级下册 · 第二单元 焕发青春活力","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 焕发青春活力"},{"k":"课题","v":"第4课 自信给人力量"},{"k":"框题","v":"人要有自信 / 做自信的人"}]},{"type":"note","title":"本课在单元中的位置","text":"青春是人一生中最有活力也最需要立起精神脊梁的阶段：自尊让我们懂得自我尊重、知廉耻懂荣辱，从而守住做人的底线；自信让我们肯定自身的能力与价值，敢于展示自己、坚持把事情做下去；自强让我们奋发向上、积极进取，靠坚强的意志、进取的精神和不懈的坚持把理想变成现实。三者中自尊是前提、自信是动力、自强是行动，统一于青春的成长，最终要落到把个人奋斗融入国家发展、做自强不息的中国人。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人要有自信","做自信的人"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"自卑和自负都是不自信的表现：自卑表现为轻视自己，看不到自己的长处和优势，不敢尝试；自负表现为过高估计自己，看不起别人，听不进不同意见。真正的自信是实事求是地看待自己，既看到自己的优点，也看到自己的不足。","explain":"选择题的高频陷阱，常给一段人物描写让考生判断属于自信、自负还是自卑。判断方法：看他对自己的评价是否与实际相符、是否尊重和看得起别人。看不起别人是自负，看不到自己是自卑，既如实看自己又尊重别人才是自信。"},{"level":"重点","text":"自信是对自身能力与价值的肯定，相信自己能做成事；自信让人自强，自信是成功的基石——自信的人能看到自己的进步、敢于尝试新事物，遇到困难能够坚持下去。","explain":"考「自信的作用」时按「相信自己—敢于尝试—坚持到底—激发潜能—取得成功」的思路展开，并回扣教材结论「自信让人自强，是成功的基石」。材料题若问「自信对他有什么意义」，不要只写「心情好」。"},{"level":"重点","text":"做自信的人，要看到自己的进步与长处，增强信心与实力；要虚心学习，不断充实和提高自己；要正确面对挫折与失败，把挫折当作成长的财富。自信的青春需要实力支撑，自信不是凭空产生的，而是靠踏踏实实的努力换来的。","explain":"命题最爱考「自信从哪里来」：答案不是「多想好事」，而是「看到进步与长处＋增强实力＋虚心学习＋正确面对挫折」。答题时一定要落到「实力」二字，这一层是本课区别于空洞鼓励的关键得分点。"},{"level":"次重点","text":"自尊、自信、自强相互联系、相互促进：自尊是前提，只有尊重自己、守住做人的底线，才谈得上自信与自强；自信是动力，让人敢于尝试、勇于坚持；自强是行动，把对自我的肯定变成实实在在的努力。三者统一于青春的成长。","explain":"单元总结型试题与观点评析题的通用框架，也常作为材料题最后一问的升华。作答时要把三者的定位分清，不能把「前提」「动力」「行动」互换位置。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["自信是对自身能力与价值的肯定，自信让人自强，是成功的基石；自信的青春需要实力支撑。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为自信就是自负，相信自己就是不把别人放在眼里。","自信是对自身能力与价值的肯定，是实事求是地看待自己，既看到优点也看到不足，并且尊重他人；自负则是过高估计自己、看不起别人、听不进不同意见，两者有本质区别。","选择题常给一段人物描写让判断「自信还是自负」。判断标准是两点：对自己的评价是否与自身实际相符，是否看得起别人。只要出现「看不起别人」「谁都不如我」，一律判为自负。"]]},{"type":"table","title":"自信与自负、自卑：真正的自信什么样（三种自我认识：同一场考试失利后的三种反应）（本单元概念对比）","head":["比较项","自信","自负与自卑（都是不自信的表现）"],"rows":[["对自己的认识","实事求是地看待自己，既看到优点和进步，也看到不足","自负：过高估计自己，只看到长处；自卑：轻视自己，只盯着短处"],["对他人的态度","尊重他人，虚心向他人学习，能听取不同意见","自负：看不起别人，听不进不同意见；自卑：不敢与人交往，害怕被比较"],["面对困难与失败","敢于尝试，把挫折当作成长的财富，坚持把事情做下去","自负：把失败归咎于外界，不肯反思；自卑：轻易放弃，认为自己「肯定不行」"],["行为表现","会答的问题敢于举手，主动参加活动、展示自己","自负：抢着表现却准备不足；自卑：明明会做也不敢举手、不敢报名"],["结果","激发潜能，不断进步，是成功的基石","自负容易栽跟头，自卑错失锻炼和成长的机会"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["情境判断类：判断某种言行体现的是自尊还是虚荣，是自信还是自负、自卑","给出一段人物描写或一个班级情境（被起外号、考试失利、被同学取笑、有人抢着表现），设问「这体现了什么心理品质」「他的做法是否恰当」。作答分两步：先点明品质名称（自尊／虚荣／自信／自负／自卑），再对号入座说明理由——判断自信与自负看是否实事求是、是否看得起别人；判断自尊与虚荣看是维护人格尊严还是只顾表面光彩。只说「他很有个性」这类模糊表述不得分。"],["意义作用类：自尊、自信、自强对个人成长的意义","设问常写「结合材料，说明自尊（自信／自强）对他成长的作用」。作答必须用规范表述：自尊让人知廉耻、懂荣辱，守住做人的底线，赢得他人的尊重和信任；自信让人自强，是成功的基石，能激发潜能、让人敢于尝试、勇于坚持；自强让青春奋进的步伐永不停息。意义类设问不要写成「心情变好了」这类生活化表达，要落到「成长」「进步」「实现人生价值」上。"],["做法建议类：怎样做自尊的人、自信的人、自强不息的中国人","本单元分值最高的一类设问，通常要求「结合材料并联系自身实际提建议」。三个人的固定答案框架分别是：做自尊的人——维护自己的人格尊严、不卑不亢，尊重他人、平等对待、不揭短不歧视，正确对待他人的评价、有则改之无则加勉；做自信的人——看到自己的进步与长处，增强信心与实力，虚心学习，正确面对挫折与失败；做自强不息的中国人——树立远大理想，战胜自我、超越自我，在苦干实干中磨砺意志，把个人奋斗融入国家发展、与祖国同行。建议必须可操作，写「每天坚持体育锻炼」「把不懂的题一道道弄懂」这类具体做法才踩分。"],["观点评析类：辨析「自尊就是只顾自己的面子」「自强就是不服输、绝不求助」等片面观点","按「判断—合理之处—片面之处—正确观点」四步作答。例如评析「自强就是不服输」：先承认自强确实需要坚强的意志和不懈的坚持，再指出把自强等同于盲目蛮干、拒绝帮助是片面的，最后给出自强的正确含义与要求。评析题最忌讳只表态不讲理，一定要把「为什么不对」写清楚。"],["价值引领类：把个人奋斗融入国家发展，做自强不息的中国人","以青年科技工作者、返乡创业青年、志愿服务、技能大赛等正面材料设题，最后一问多半是「作为新时代青少年，你打算怎样做」。作答在「自尊自信自强」三条做法之上，必须有升华句：树立远大理想，把个人奋斗融入国家发展，与祖国同行，做有理想、敢担当、能吃苦、肯奋斗的新时代好青年。只答个人层面的努力而没有价值升华，最高分拿不到。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·焕发青春活力（第3—5课：人贵自尊 · 自信给人力量 · 人生当自强）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-2"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-2-m1-q1","type":"short","stem":"（1）结合材料一，说明小航的表现反映了哪些心理，并简要分析这些心理对他的影响。（4 分）","answer":"①自卑心理：他看不到自己的长处和优势，觉得自己「肯定不行」，连运动会都不敢报名。②缺乏自信：明明会做的题因为害怕答错被笑话而不敢举手，不敢相信自己的能力。③过于在意他人的评价：被起过外号之后总觉得别人在议论自己，上课连头都不敢抬，把注意力从学习和锻炼上转移到了别人的眼光上。影响：这些心理使他不能实事求是地认识自己，不能真实地展示自己的能力，白白放弃了锻炼和成长的机会，长此以往不利于他的健康成长和进步。","explain":"","tags":["自卑与自信","材料分析"],"rubric":["答出自卑：看不到自己的长处，认为自己「肯定不行」","答出缺乏自信：会做的题也不敢举手，不相信自己的能力","答出过于在意他人的评价，被外号困扰、不敢抬头","答出对成长的影响：不敢尝试、错失锻炼机会，不利于健康成长和进步"]},{"id":"pol-youth-2-m1-q2","type":"short","stem":"（2）结合材料二、材料三，谈谈我们应当怎样做自尊的人、自信的人。（8 分）","answer":"①做自尊的人要维护自己的人格尊严，不卑不亢：小雅面对同学的玩笑，平静地说出「这样说话让我很不舒服」，既没有自卑退缩，也没有以牙还牙。②做自尊的人要尊重他人，平等对待他人，不揭人之短，不歧视他人：小雅在同学有困难时主动帮忙，从不拿别人的缺点取笑别人。③做自尊的人要正确对待他人的评价，做到有则改之、无则加勉：小航没有被外号困住，而是把精力放回学习和锻炼上。④做自信的人要看到自己的进步与长处，增强信心与实力：小航用「进步清单」记下自己的每一个进步，每天整理错题、向老师和同学请教，用实实在在的努力提高了成绩。⑤做自信的人要虚心学习，正确面对挫折与失败：演讲比赛只得了鼓励奖，他没有气馁，而是想着下次该怎么改。","explain":"","tags":["做自尊的人","做自信的人","做法建议"],"rubric":["答出维护自己的人格尊严、不卑不亢（结合小雅平静表达感受）","答出尊重他人、平等对待他人、不揭短不歧视（结合小雅主动帮忙、不取笑他人）","答出正确对待他人的评价，有则改之、无则加勉（结合小航不再被外号困扰）","答出看到自己的进步与长处、增强信心与实力（结合小航的进步清单与每天的努力）","答出虚心学习、正确面对挫折与失败（结合比赛得鼓励奖后的态度）"]},{"id":"pol-youth-2-q2","type":"choice","stem":"自习课上，同桌把一张写着答案的纸条推给小华。小华想起「行己有耻」这句话，把纸条还了回去，自己独立完成了练习。小华的做法主要体现了","answer":"A","explain":"「行己有耻」要求我们知廉耻、懂荣辱，凡自己认为可耻的事就不去做，有所为、有所不为。抄答案应付作业是有损自己人格和学业的行为，小华拒绝抄答案，是自尊与知耻的表现。B 项混淆是非；C 项把维护底线的行为说成虚荣；D 项与题意无关，这里的拒绝与自信没有关系。","options":["知廉耻、懂荣辱，有所为、有所不为","过于死板，不懂同学之间的互帮互助","为了在老师面前表现自己，属于虚荣","缺乏自信，不敢接受别人的帮助"],"difficulty":2,"tags":["行己有耻","自尊的表现"]},{"id":"pol-youth-2-q3","type":"choice","stem":"小美成绩中等，她既清楚自己基础扎实、思路灵活的长处，也承认自己计算容易出错，于是每天坚持做十道计算题，成绩稳步提升。小美的表现属于","answer":"D","explain":"自信是对自身能力与价值的肯定，其特点是实事求是地看待自己，既看到优点和进步，也看到不足，并在此基础上努力改进。小美既看到长处又承认短处，还坚持练习提高，属于自信。自负表现为过高估计自己、看不起别人；自卑表现为轻视自己、看不到长处；虚荣追求的是表面的光彩，三者都不符合小美的表现。","options":["自负，过高估计了自己的能力","自卑，看不到自己的长处和优势","虚荣，只是想得到老师和同学的表扬","自信，能够实事求是地看待自己"],"difficulty":2,"tags":["自信与自负、自卑的区别"]},{"id":"pol-youth-2-q6","type":"choice","stem":"关于自尊、自信、自强三者的关系，下列说法正确的是","answer":"A","explain":"自尊、自信、自强相互联系、相互促进：自尊是前提，自信是动力，自强是行动，三者统一于青春的成长。B 项否认三者的内在联系；C 项把自信当成成功的充分条件，忽略了「自信的青春需要实力支撑」，成功还要靠踏实的努力；D 项把自强等同于盲目蛮干，自强并不排斥向他人请教。","options":["自尊是前提，自信是动力，自强是行动，三者相互联系、相互促进，统一于青春的成长","三者互不相干，只要有了自尊，就自然会自强","只要有了自信就一定能成功，不必再付出艰苦的努力","自强就是不服输，任何情况下都不能向别人请教"],"difficulty":2,"tags":["自尊、自信、自强的关系"]},{"id":"pol-youth-2-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 自尊是对自我价值的肯定，是一个人自我尊重并期望受到他人、集体和社会尊重的心理状态…\n② 自尊的人知廉耻、懂荣辱，有所为、有所不为；「行己有耻」要求我们凡自己认为可耻的事…\n③ 做自尊的人，要维护自己的人格尊严，不卑不亢，既不容许别人歧视、侮辱自己，也不去歧…\n④ 把自尊理解为只顾自己的面子：听不进任何批评，谁提意见就跟谁急，宁可硬撑着出错也不…","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本课最典型的陷阱，与「行己有耻」又容易混。要分清：为了面子文过饰非、死要面子，本质是虚荣而不是自尊；真正自尊的人恰恰有勇气面对自己的错误；正确表述应为：自尊是对自我价值的肯定和维护自己的人格尊严，不等于爱面子、护短；自尊的人能够正确对待他人的评价，做到有则改之、无则加勉，也能坦然承认自己的不足。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第二单元·焕发青春活力（第3—5课：人贵自尊 · 自信给人力量 · 人生当自强）"]}]},{"id":"cat-pol-7b-2-3","title":"第5课 人生当自强","subtitle":"七年级下册 · 第二单元 焕发青春活力","grade":"7b","tags":["七年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第二单元 焕发青春活力"},{"k":"课题","v":"第5课 人生当自强"},{"k":"框题","v":"人要自强 / 做自强不息的中国人"}]},{"type":"note","title":"本课在单元中的位置","text":"青春是人一生中最有活力也最需要立起精神脊梁的阶段：自尊让我们懂得自我尊重、知廉耻懂荣辱，从而守住做人的底线；自信让我们肯定自身的能力与价值，敢于展示自己、坚持把事情做下去；自强让我们奋发向上、积极进取，靠坚强的意志、进取的精神和不懈的坚持把理想变成现实。三者中自尊是前提、自信是动力、自强是行动，统一于青春的成长，最终要落到把个人奋斗融入国家发展、做自强不息的中国人。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人要自强","做自强不息的中国人"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"自强是对未来充满希望，奋发向上、积极进取，自强不息；自强让青春奋进的步伐永不停息；自强要靠坚强的意志、进取的精神和不懈的坚持。","explain":"考查自强的含义与重要性。「让青春奋进的步伐永不停息」是教材原文式的规范表述，材料题写「自强让我们不断进步」不如写这一句得分稳。要注意自强是长期状态，不是一次冲劲。"},{"level":"重点","text":"做自强不息的中国人，要树立远大理想，战胜自我、超越自我，在苦干实干中磨砺意志，把个人奋斗融入国家发展，与祖国同行。","explain":"这是本单元的落点，也是材料题升华段的固定答案。凡是材料出现青年扎根基层、投身科研、参加志愿服务、返乡创业等内容，都要答「把个人奋斗融入国家发展」「与祖国同行」，只答「努力学习」会丢掉价值引领分。"},{"level":"重点","text":"自信是对自身能力与价值的肯定，相信自己能做成事；自信让人自强，自信是成功的基石——自信的人能看到自己的进步、敢于尝试新事物，遇到困难能够坚持下去。","explain":"考「自信的作用」时按「相信自己—敢于尝试—坚持到底—激发潜能—取得成功」的思路展开，并回扣教材结论「自信让人自强，是成功的基石」。材料题若问「自信对他有什么意义」，不要只写「心情好」。"},{"level":"次重点","text":"自尊、自信、自强相互联系、相互促进：自尊是前提，只有尊重自己、守住做人的底线，才谈得上自信与自强；自信是动力，让人敢于尝试、勇于坚持；自强是行动，把对自我的肯定变成实实在在的努力。三者统一于青春的成长。","explain":"单元总结型试题与观点评析题的通用框架，也常作为材料题最后一问的升华。作答时要把三者的定位分清，不能把「前提」「动力」「行动」互换位置。"},{"level":"了解","text":"自强就体现在日常的学习和生活中：树立目标、克服惰性、抵制不良诱惑，坚持体育锻炼，刻苦学习，从身边的小事做起，日积月累地磨砺自己。","explain":"材料题最后一问要求「结合自身实际谈做法」时的具体落点。写「我要自强」不得分，写成「克服惰性，每天坚持体育锻炼」「刻苦学习，把不懂的题一道道弄懂」才踩分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["自信是对自身能力与价值的肯定，自信让人自强，是成功的基石；自信的青春需要实力支撑。","自强让青春奋进的步伐永不停息，自强要靠坚强的意志、进取的精神和不懈的坚持。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为自强就是不服输、盲目蛮干：任何情况下都不认输，遇到解决不了的困难也硬撑，坚决不向别人求助。","自强是奋发向上、积极进取、自强不息，靠坚强的意志、进取的精神和不懈的坚持；自强不等于盲目蛮干，遇到自己解决不了的困难，向老师和同学请教、借助帮助把问题解决，并不违背自强。","观点评析题的高频设问。评析时先承认合理之处（不轻易放弃确实是自强的表现），再指出其片面性（把自强等同于硬撑、拒绝帮助），最后给出自强的正确含义，按「是什么—为什么—怎么办」三层作答。"]]},{"type":"table","title":"自尊、自信、自强：三者的分工与统一（单元主线的三个环节：从认识到行动）（本单元概念对比）","head":["比较项","自尊（前提）与自信（动力）","自强（行动与落脚点）"],"rows":[["回答的问题","我怎样看待自己：肯定自我价值，相信自己能做成事","我怎样去做：奋发向上、积极进取，把理想变成现实"],["典型表现","知廉耻、懂荣辱，维护人格尊严，尊重他人，看到自己的进步与长处","树立目标、克服惰性、抵制诱惑，刻苦学习、坚持锻炼，战胜自我、超越自我"],["主要作用","让人守住做人的底线，获得他人的尊重，敢于尝试并坚持下去","让青春奋进的步伐永不停息，靠坚强的意志、进取的精神和不懈的坚持不断前进"],["缺失时的后果","没有自尊容易随波逐流、失去底线；没有自信容易自卑退缩，错失机会","没有自强，再好的想法也停在口头上，理想无法实现"],["怎样统一","以自尊立身、以自信立志","以自强立业，把个人奋斗融入国家发展，与祖国同行"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["情境判断类：判断某种言行体现的是自尊还是虚荣，是自信还是自负、自卑","给出一段人物描写或一个班级情境（被起外号、考试失利、被同学取笑、有人抢着表现），设问「这体现了什么心理品质」「他的做法是否恰当」。作答分两步：先点明品质名称（自尊／虚荣／自信／自负／自卑），再对号入座说明理由——判断自信与自负看是否实事求是、是否看得起别人；判断自尊与虚荣看是维护人格尊严还是只顾表面光彩。只说「他很有个性」这类模糊表述不得分。"],["意义作用类：自尊、自信、自强对个人成长的意义","设问常写「结合材料，说明自尊（自信／自强）对他成长的作用」。作答必须用规范表述：自尊让人知廉耻、懂荣辱，守住做人的底线，赢得他人的尊重和信任；自信让人自强，是成功的基石，能激发潜能、让人敢于尝试、勇于坚持；自强让青春奋进的步伐永不停息。意义类设问不要写成「心情变好了」这类生活化表达，要落到「成长」「进步」「实现人生价值」上。"],["做法建议类：怎样做自尊的人、自信的人、自强不息的中国人","本单元分值最高的一类设问，通常要求「结合材料并联系自身实际提建议」。三个人的固定答案框架分别是：做自尊的人——维护自己的人格尊严、不卑不亢，尊重他人、平等对待、不揭短不歧视，正确对待他人的评价、有则改之无则加勉；做自信的人——看到自己的进步与长处，增强信心与实力，虚心学习，正确面对挫折与失败；做自强不息的中国人——树立远大理想，战胜自我、超越自我，在苦干实干中磨砺意志，把个人奋斗融入国家发展、与祖国同行。建议必须可操作，写「每天坚持体育锻炼」「把不懂的题一道道弄懂」这类具体做法才踩分。"],["观点评析类：辨析「自尊就是只顾自己的面子」「自强就是不服输、绝不求助」等片面观点","按「判断—合理之处—片面之处—正确观点」四步作答。例如评析「自强就是不服输」：先承认自强确实需要坚强的意志和不懈的坚持，再指出把自强等同于盲目蛮干、拒绝帮助是片面的，最后给出自强的正确含义与要求。评析题最忌讳只表态不讲理，一定要把「为什么不对」写清楚。"],["价值引领类：把个人奋斗融入国家发展，做自强不息的中国人","以青年科技工作者、返乡创业青年、志愿服务、技能大赛等正面材料设题，最后一问多半是「作为新时代青少年，你打算怎样做」。作答在「自尊自信自强」三条做法之上，必须有升华句：树立远大理想，把个人奋斗融入国家发展，与祖国同行，做有理想、敢担当、能吃苦、肯奋斗的新时代好青年。只答个人层面的努力而没有价值升华，最高分拿不到。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·焕发青春活力（第3—5课：人贵自尊 · 自信给人力量 · 人生当自强）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-2"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-2-m2-q1","type":"short","stem":"（1）结合材料二，说说自强要靠什么，并指出这位学长身上体现了哪些自强的表现。（6 分）","answer":"①自强要靠坚强的意志、进取的精神和不懈的坚持。②学长身上的自强表现有：树立明确的目标，给自己定下提高英语成绩的目标；克服惰性、刻苦学习，每天早上提前半小时到校朗读，把每一篇课文读到能背下来；不怕困难、虚心请教，遇到不懂的就追着老师问；坚持不懈、战胜自我，三年如一日地坚持，英语成绩从班级末尾赶到了前列。","explain":"","tags":["自强要靠什么","材料分析"],"rubric":["答出自强要靠坚强的意志、进取的精神和不懈的坚持","答出树立目标、立志向上","答出克服惰性、刻苦学习（结合每天提前到校朗读）","答出虚心请教、不怕困难（结合追着老师问）","答出坚持不懈、战胜自我、超越自我（结合三年坚持、成绩赶上前列）"]},{"id":"pol-youth-2-m2-q2","type":"short","stem":"（2）结合材料一、材料三，谈谈我们应当怎样做自强不息的中国人。（8 分）","answer":"①树立远大理想，把个人的成长同国家的发展联系起来：学长立志学农学、回到家乡帮助乡亲们把农产品卖得更好，就是把个人理想融入国家发展。②战胜自我、超越自我：不等不靠，从改变自己做起，像学长那样把最薄弱的学科一点点补起来，在与自己的比较中不断进步。③在苦干实干中磨砺意志：自强不是空喊口号，而是每天早上提前半小时的朗读、一道一道弄懂的习题，靠实实在在的付出积累起来。④把个人奋斗融入国家发展，与祖国同行：当代中国青年生逢其时，施展才干的舞台无比广阔，我们要在服务社会、奉献社会中实现人生价值，像学长那样参加志愿服务、为他人和社会作贡献。⑤增强做中国人的志气、骨气、底气，做有理想、敢担当、能吃苦、肯奋斗的新时代好青年。","explain":"","tags":["做自强不息的中国人","做法建议"],"rubric":["答出树立远大理想，把个人成长同国家发展联系起来（结合学农学、返乡助农）","答出战胜自我、超越自我（结合补齐薄弱学科）","答出在苦干实干中磨砺意志，靠实实在在的付出（结合每天朗读、弄懂习题）","答出把个人奋斗融入国家发展、与祖国同行，在服务社会中实现人生价值（结合社区志愿服务）","答出做有理想、敢担当、能吃苦、肯奋斗的新时代好青年"]},{"id":"pol-youth-2-q4","type":"choice","stem":"下列做法中，属于自强表现的是","answer":"B","explain":"自强是对未来充满希望，奋发向上、积极进取，靠坚强的意志、进取的精神和不懈的坚持，体现在克服惰性、抵制诱惑、坚持锻炼、刻苦学习等日常努力中。A 项是依赖他人，C 项是自暴自弃，D 项是盲目蛮干、死要面子，都不是自强。","options":["遇到学习和生活上的困难，一律请家长出面解决","克服惰性，坚持体育锻炼，刻苦学习，不断提高自己","考试失利后认为题目太难，从此不再努力","为了面子硬撑着不向别人请教，明知方法不对也不肯改"],"difficulty":1,"tags":["自强的表现"]},{"id":"pol-youth-2-q6","type":"choice","stem":"关于自尊、自信、自强三者的关系，下列说法正确的是","answer":"A","explain":"自尊、自信、自强相互联系、相互促进：自尊是前提，自信是动力，自强是行动，三者统一于青春的成长。B 项否认三者的内在联系；C 项把自信当成成功的充分条件，忽略了「自信的青春需要实力支撑」，成功还要靠踏实的努力；D 项把自强等同于盲目蛮干，自强并不排斥向他人请教。","options":["自尊是前提，自信是动力，自强是行动，三者相互联系、相互促进，统一于青春的成长","三者互不相干，只要有了自尊，就自然会自强","只要有了自信就一定能成功，不必再付出艰苦的努力","自强就是不服输，任何情况下都不能向别人请教"],"difficulty":2,"tags":["自尊、自信、自强的关系"]},{"id":"pol-youth-2-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 自尊是对自我价值的肯定，是一个人自我尊重并期望受到他人、集体和社会尊重的心理状态…\n② 自尊的人知廉耻、懂荣辱，有所为、有所不为；「行己有耻」要求我们凡自己认为可耻的事…\n③ 做自尊的人，要维护自己的人格尊严，不卑不亢，既不容许别人歧视、侮辱自己，也不去歧…\n④ 把自尊理解为只顾自己的面子：听不进任何批评，谁提意见就跟谁急，宁可硬撑着出错也不…","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本课最典型的陷阱，与「行己有耻」又容易混。要分清：为了面子文过饰非、死要面子，本质是虚荣而不是自尊；真正自尊的人恰恰有勇气面对自己的错误；正确表述应为：自尊是对自我价值的肯定和维护自己的人格尊严，不等于爱面子、护短；自尊的人能够正确对待他人的评价，做到有则改之、无则加勉，也能坦然承认自己的不足。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第二单元·焕发青春活力（第3—5课：人贵自尊 · 自信给人力量 · 人生当自强）"]}]},{"id":"cat-pol-7b-3-1","title":"第6课 传承核心思想理念","subtitle":"七年级下册 · 第三单元 传承中华优秀传统文化","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 传承中华优秀传统文化"},{"k":"课题","v":"第6课 传承核心思想理念"},{"k":"框题","v":"历久弥新的思想理念 / 做核心思想理念的传承者"}]},{"type":"note","title":"本课在单元中的位置","text":"中华优秀传统文化是中华民族的精神命脉：讲仁爱、守诚信、崇正义、尚和合、求大同等核心思想理念是它的思想内核，求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念构成它的人文精神，孝悌忠信、礼义廉耻等传统美德则是它落到日常行为上的规范；三者一体，共同回答了「今天我们怎样对待中华优秀传统文化」——在坚定文化自信的同时推动创造性转化、创新性发展，从日常小事做起把理念、精神与美德变成行动。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["历久弥新的思想理念","做核心思想理念的传承者"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。","explain":"这五个词是必背的固定搭配，考试常以「下列属于中华优秀传统文化核心思想理念的是」直接考查，也常让学生在材料中指认。作答时要成串原样写出，不要改写成「要仁爱」「重信用」之类的同义替换——道法按术语给分，换了词就不踩点。"},{"level":"重点","text":"这些核心思想理念是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉；我们要推动中华优秀传统文化创造性转化、创新性发展，使其当代价值充分彰显。","explain":"「传承」不是原封不动地照搬，而是「创造性转化、创新性发展」——这两个术语是必答点，写成「改造」「创新一下」都不给分。材料给「把传统纹样做成现代文创」「用短视频讲古诗词」「用数字技术复原文物」一类事实，设问问「这说明了什么」，答法就是这一条。"},{"level":"次重点","text":"做核心思想理念的传承者：要认真学习、深入了解中华优秀传统文化，推动其创造性转化、创新性发展，并在日常学习生活中身体力行，把核心思想理念变成自己的价值追求和行为准则。","explain":"做法建议类设问的标准骨架，三个动作缺一不可：学习了解（知其然）、转化发展（使其活）、日常践行（落于行）。「践行」一定要落到具体行为上，写「我要传承中华优秀传统文化」是空话，写「主动阅读经典、参加传统文化社团、在网络平台上传播优秀传统文化」才踩点。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念，是涵养社会主义核心价值观的重要源泉。","我们要坚定文化自信，推动中华优秀传统文化创造性转化、创新性发展，做核心思想理念的传承者、中华人文精神的弘扬者、中华传统美德的践行者。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化。"],["认为传承中华优秀传统文化就是原封不动地照搬古人那一套，越古老越正宗，一个字都不能改。","传承要推动中华优秀传统文化创造性转化、创新性发展，结合时代要求继承创新，使其当代价值充分彰显；对传统文化要取其精华、去其糟粕，既不是全盘照搬，也不是全盘否定。","常以「穿汉服、读经书就是传承」「传统的东西不能改」一类观点辨析。得分点是「创造性转化、创新性发展」与「取其精华、去其糟粕」两个术语，缺一不可，也不能把「转化」写成「随意改造」。"]]},{"type":"table","title":"核心思想理念与中华人文精神（同属思想观念层面，但回答的问题不同：一个偏「信什么」，一个偏「怎样处世与生活」）（本单元概念对比）","head":["比较项","核心思想理念（第6课）","中华人文精神（第7课）"],"rows":[["回答的问题","我们应当信奉和坚守什么价值","我们应当怎样待人处世，怎样生活与审美"],["主要内容","讲仁爱、守诚信、崇正义、尚和合、求大同","求同存异、和而不同的处世方法；文以载道、以文化人的教化思想；形神兼备、情景交融的美学追求；俭约自守、中和泰和的生活理念"],["对待差异的态度","尚和合、求大同，主张和合共生、天下大同","求同存异、和而不同，尊重差异、包容多样"],["常见问法","「这体现了哪些核心思想理念」「为什么说它是涵养社会主义核心价值观的重要源泉」","「这体现了怎样的处世方法或审美追求」「怎样做中华人文精神的弘扬者」"],["共同点","都是中华优秀传统文化的重要内容，都需要推动创造性转化、创新性发展","同左：都必须在日常学习生活中身体力行，不能只停留在口头上"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["术语识记类：核心思想理念、人文精神与传统美德的固定表述","这是本单元最稳定也最容易拿满分的题型。「讲仁爱、守诚信、崇正义、尚和合、求大同」五个词、「求同存异、和而不同」「文以载道、以文化人」「形神兼备、情景交融」「俭约自守、中和泰和」四组搭配、「孝悌忠信、礼义廉耻」八个字、中华文明五个突出特性，都必须原样写出。选择题常见设错手法是替换同义词或打乱搭配（如把「文以载道、以文化人」说成生活理念）；材料题也必须按术语成串作答，同义改写不踩点。"],["评析类：怎样对待传统文化与外来文化","材料多给两种对立观点（「传统的东西都过时了，没有必要学」与「传统的东西一个字都不能改」），要求评析。作答要落在两个固定术语上：一是「取其精华、去其糟粕」，二是「推动中华优秀传统文化创造性转化、创新性发展」；涉及外来文化时再补「以我为主、为我所用」「尊重差异、包容多样」。只答一面必然扣分。"],["做法建议类：青少年怎样做传承者、弘扬者与践行者","设问基本固定为「作为中学生，你打算怎样做」。答题按第 6、7、8 课的顺序分三层组织：做传承者——认真学习、深入了解，推动创造性转化与创新性发展，并在日常学习生活中身体力行；做弘扬者——尊重差异、包容多样，在生活中传递真善美，提升审美情趣与精神境界；做践行者——从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐。每一层都要给出具体行为，只有口号不踩点。"],["情境判断类：从具体行为反推对应的理念、人文精神与德目","给一段校园、家庭或社区情境（非遗进校园、家风家训、博物馆研学、社区志愿服务、同学之间的差异与矛盾），设问「这体现了中华优秀传统文化的哪一方面内容」「这给我们什么启示」。作答分两步：先点明对应的固定表述（哪一条核心思想理念／哪一类人文精神／哪一项传统美德），再说明理由并回扣教材结论。只描述情境不作判断，或判断时用「很有文化味」这类模糊表述，都不得分。"]]},{"type":"quote","text":"【材料一】中华优秀传统文化是中华民族的精神命脉。中华文明具有突出的连续性、创新性、统一性、包容性、和平性。讲仁爱、守诚信、崇正义、尚和合、求大同等核心思想理念，求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念，共同塑造了中华民族的精神品格。\n【材料二】某中学开展「传统文化进校园」活动：同学们跟着非遗传承人学习剪纸、扎染，并把传统纹样重新设计成校运会会徽；语文课上诵读经典诗文，美术课上欣赏中国山水画，班会课上讲家风故事；有同学还把家里的家训「一粥一饭，当思来处不易」写进班级公约，带动全班同学节约粮食、不浪费水电。也有同学说：「这些东西离我们太远了，学它没什么用。」\n【材料三】某地举办「非遗新生活」创意展，传承人把传统技艺与现代设计结合起来，让老手艺走进日常生活，吸引了不少青少年参观体验。与此同时，个别地方也出现了把传统文化简单化、娱乐化，甚至随意改造、张冠李戴的现象。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-3-q3","type":"choice","stem":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的","answer":"D","explain":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念，是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉。它们属于思想理念层面，不能与中华人文精神、中华传统美德、民族精神混为一谈。","options":["传统美德","中华人文精神","民族精神","核心思想理念"],"difficulty":1,"tags":["核心思想理念"]},{"id":"pol-youth-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华文化源远流长、博大精深。中华优秀传统文化是中华民族的精神命脉，是涵养社会主义…\n② 中华文明具有突出的连续性、创新性、统一性、包容性、和平性。\n③ 讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。\n④ 认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化；正确表述应为：中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）"]},{"id":"pol-youth-3-q7","type":"choice","stem":"某校把传统纹样重新设计成校运会会徽，并用短视频向网友介绍本地非遗技艺。对这类做法认识正确的是","answer":"A","explain":"把传统纹样重新设计成校运会会徽、用短视频介绍本地非遗技艺，是在新的时代条件下赋予传统文化新的表现形式和传播方式，属于推动中华优秀传统文化创造性转化、创新性发展。B 项混淆了「创造性转化、创新性发展」与「随意改造」——随意改造是指背离传统文化的精神内核、张冠李戴；C 项否认了传统文化需要结合时代要求继承创新；D 项把学习传统文化的目的功利化，不符合题意。","options":["这是推动中华优秀传统文化创造性转化、创新性发展的表现","这是对传统文化的随意改造，破坏了传统文化的原貌","传统文化只能原样保存，任何改变都是对它的不尊重","学习传统文化主要是为了在各类比赛中获奖"],"difficulty":2,"tags":["创造性转化与创新性发展","情境判断"]},{"id":"cat-pol-7b-3-1-short","type":"short","stem":"某班围绕「传承核心思想理念」开展主题探究活动，围绕「历久弥新的思想理念」、「做核心思想理念的传承者」。请运用本课所学，谈谈你的认识。","answer":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。这些核心思想理念是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉；我们要推动中华优秀传统文化创造性转化、创新性发展，使其当代价值充分彰显。","explain":"","rubric":["讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。","这些核心思想理念是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉…","做核心思想理念的传承者：要认真学习、深入了解中华优秀传统文化，推动其创造性转化、…"],"tags":["传承核心思想理念"]},{"id":"cat-pol-7b-3-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。\n② 这些核心思想理念是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉…\n③ 做核心思想理念的传承者：要认真学习、深入了解中华优秀传统文化，推动其创造性转化、…\n④ 认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化；正确表述应为：中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","difficulty":3,"tags":["第6课 传承核心思想理念"]}]},{"id":"cat-pol-7b-3-2","title":"第7课 弘扬中华人文精神","subtitle":"七年级下册 · 第三单元 传承中华优秀传统文化","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 传承中华优秀传统文化"},{"k":"课题","v":"第7课 弘扬中华人文精神"},{"k":"框题","v":"影响深远的人文精神 / 做中华人文精神的弘扬者"}]},{"type":"note","title":"本课在单元中的位置","text":"中华优秀传统文化是中华民族的精神命脉：讲仁爱、守诚信、崇正义、尚和合、求大同等核心思想理念是它的思想内核，求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念构成它的人文精神，孝悌忠信、礼义廉耻等传统美德则是它落到日常行为上的规范；三者一体，共同回答了「今天我们怎样对待中华优秀传统文化」——在坚定文化自信的同时推动创造性转化、创新性发展，从日常小事做起把理念、精神与美德变成行动。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["影响深远的人文精神","做中华人文精神的弘扬者"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念，共同构成中华人文精神。","explain":"四个分句要与「处世方法」「教化思想」「美学追求」「生活理念」四个落脚词一一对应，考试常做搭配判断（如把「文以载道、以文化人」错配成生活理念）。材料题问「中华人文精神体现在哪里」，就从待人处世、教化育人、审美情趣、生活态度四个角度各答一句，少一个角度少一分。"},{"level":"次重点","text":"做中华人文精神的弘扬者：要尊重差异、包容多样，在生活中传递真善美，不断提升自己的审美情趣与精神境界。","explain":"「尊重差异、包容多样」承接「求同存异、和而不同」，既用于对待不同民族、不同地域的文化，也用于对待同学之间的差异；「传递真善美」「提升审美情趣与精神境界」是本课独有的落脚点，答成「好好学习」会丢分。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["求同存异、和而不同，文以载道、以文化人，形神兼备、情景交融，俭约自守、中和泰和，共同构成中华人文精神。","我们要坚定文化自信，推动中华优秀传统文化创造性转化、创新性发展，做核心思想理念的传承者、中华人文精神的弘扬者、中华传统美德的践行者。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化。"],["认为传承中华优秀传统文化就是原封不动地照搬古人那一套，越古老越正宗，一个字都不能改。","传承要推动中华优秀传统文化创造性转化、创新性发展，结合时代要求继承创新，使其当代价值充分彰显；对传统文化要取其精华、去其糟粕，既不是全盘照搬，也不是全盘否定。","常以「穿汉服、读经书就是传承」「传统的东西不能改」一类观点辨析。得分点是「创造性转化、创新性发展」与「取其精华、去其糟粕」两个术语，缺一不可，也不能把「转化」写成「随意改造」。"]]},{"type":"table","title":"核心思想理念与中华人文精神（同属思想观念层面，但回答的问题不同：一个偏「信什么」，一个偏「怎样处世与生活」）（本单元概念对比）","head":["比较项","核心思想理念（第6课）","中华人文精神（第7课）"],"rows":[["回答的问题","我们应当信奉和坚守什么价值","我们应当怎样待人处世，怎样生活与审美"],["主要内容","讲仁爱、守诚信、崇正义、尚和合、求大同","求同存异、和而不同的处世方法；文以载道、以文化人的教化思想；形神兼备、情景交融的美学追求；俭约自守、中和泰和的生活理念"],["对待差异的态度","尚和合、求大同，主张和合共生、天下大同","求同存异、和而不同，尊重差异、包容多样"],["常见问法","「这体现了哪些核心思想理念」「为什么说它是涵养社会主义核心价值观的重要源泉」","「这体现了怎样的处世方法或审美追求」「怎样做中华人文精神的弘扬者」"],["共同点","都是中华优秀传统文化的重要内容，都需要推动创造性转化、创新性发展","同左：都必须在日常学习生活中身体力行，不能只停留在口头上"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["术语识记类：核心思想理念、人文精神与传统美德的固定表述","这是本单元最稳定也最容易拿满分的题型。「讲仁爱、守诚信、崇正义、尚和合、求大同」五个词、「求同存异、和而不同」「文以载道、以文化人」「形神兼备、情景交融」「俭约自守、中和泰和」四组搭配、「孝悌忠信、礼义廉耻」八个字、中华文明五个突出特性，都必须原样写出。选择题常见设错手法是替换同义词或打乱搭配（如把「文以载道、以文化人」说成生活理念）；材料题也必须按术语成串作答，同义改写不踩点。"],["评析类：怎样对待传统文化与外来文化","材料多给两种对立观点（「传统的东西都过时了，没有必要学」与「传统的东西一个字都不能改」），要求评析。作答要落在两个固定术语上：一是「取其精华、去其糟粕」，二是「推动中华优秀传统文化创造性转化、创新性发展」；涉及外来文化时再补「以我为主、为我所用」「尊重差异、包容多样」。只答一面必然扣分。"],["做法建议类：青少年怎样做传承者、弘扬者与践行者","设问基本固定为「作为中学生，你打算怎样做」。答题按第 6、7、8 课的顺序分三层组织：做传承者——认真学习、深入了解，推动创造性转化与创新性发展，并在日常学习生活中身体力行；做弘扬者——尊重差异、包容多样，在生活中传递真善美，提升审美情趣与精神境界；做践行者——从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐。每一层都要给出具体行为，只有口号不踩点。"],["情境判断类：从具体行为反推对应的理念、人文精神与德目","给一段校园、家庭或社区情境（非遗进校园、家风家训、博物馆研学、社区志愿服务、同学之间的差异与矛盾），设问「这体现了中华优秀传统文化的哪一方面内容」「这给我们什么启示」。作答分两步：先点明对应的固定表述（哪一条核心思想理念／哪一类人文精神／哪一项传统美德），再说明理由并回扣教材结论。只描述情境不作判断，或判断时用「很有文化味」这类模糊表述，都不得分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-3-q3","type":"choice","stem":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的","answer":"D","explain":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念，是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉。它们属于思想理念层面，不能与中华人文精神、中华传统美德、民族精神混为一谈。","options":["传统美德","中华人文精神","民族精神","核心思想理念"],"difficulty":1,"tags":["核心思想理念"]},{"id":"pol-youth-3-q4","type":"choice","stem":"下列传统表述与其所属方面的搭配，正确的是","answer":"C","explain":"求同存异、和而不同是处世方法，文以载道、以文化人是教化思想，形神兼备、情景交融是美学追求，俭约自守、中和泰和是生活理念。A 项把教化思想错配成生活理念，B 项把美学追求错配成教化思想，D 项把生活理念错配成美学追求，都属于张冠李戴式设错。","options":["文以载道、以文化人——俭约自守的生活理念","形神兼备、情景交融——影响深远的教化思想","求同存异、和而不同——中华人文精神的处世方法","俭约自守、中和泰和——中华民族的美学追求"],"difficulty":2,"tags":["中华人文精神","搭配判断"]},{"id":"pol-youth-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华文化源远流长、博大精深。中华优秀传统文化是中华民族的精神命脉，是涵养社会主义…\n② 中华文明具有突出的连续性、创新性、统一性、包容性、和平性。\n③ 讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。\n④ 认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化；正确表述应为：中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）"]},{"id":"cat-pol-7b-3-2-short","type":"short","stem":"某班围绕「弘扬中华人文精神」开展主题探究活动，围绕「影响深远的人文精神」、「做中华人文精神的弘扬者」。请运用本课所学，谈谈你的认识。","answer":"求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念，共同构成中华人文精神。做中华人文精神的弘扬者：要尊重差异、包容多样，在生活中传递真善美，不断提升自己的审美情趣与精神境界。","explain":"","rubric":["求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的…","做中华人文精神的弘扬者：要尊重差异、包容多样，在生活中传递真善美，不断提升自己的…"],"tags":["弘扬中华人文精神"]},{"id":"pol-youth-3-q1","type":"choice","stem":"下列关于中华文化的说法，正确的是","answer":"B","explain":"中华文化源远流长、博大精深，中华优秀传统文化是中华民族的精神命脉。A 项错在把中华文化等同于汉族文化，中华文化是各民族在长期交流交融中共同创造的；C 项否认了中华优秀传统文化的当代价值；D 项把文化自信等同于妄自尊大、封闭排外，坚定文化自信与学习借鉴外来优秀文化并不矛盾。","options":["中华文化就是指汉族文化，少数民族的歌舞、服饰、节日不属于中华文化","中华文化源远流长、博大精深，中华优秀传统文化是中华民族的精神命脉","中华优秀传统文化已经过时，对今天的生活没有意义","坚定文化自信就是认为本民族文化什么都好，不必学习其他文化"],"difficulty":1,"tags":["中华文化的特点","文化自信"]}]},{"id":"cat-pol-7b-3-3","title":"第8课 践行中华传统美德","subtitle":"七年级下册 · 第三单元 传承中华优秀传统文化","grade":"7b","tags":["七年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第三单元 传承中华优秀传统文化"},{"k":"课题","v":"第8课 践行中华传统美德"},{"k":"框题","v":"薪火相传的传统美德 / 做中华传统美德的践行者"}]},{"type":"note","title":"本课在单元中的位置","text":"中华优秀传统文化是中华民族的精神命脉：讲仁爱、守诚信、崇正义、尚和合、求大同等核心思想理念是它的思想内核，求同存异、和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，俭约自守、中和泰和的生活理念构成它的人文精神，孝悌忠信、礼义廉耻等传统美德则是它落到日常行为上的规范；三者一体，共同回答了「今天我们怎样对待中华优秀传统文化」——在坚定文化自信的同时推动创造性转化、创新性发展，从日常小事做起把理念、精神与美德变成行动。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["薪火相传的传统美德","做中华传统美德的践行者"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"中华传统美德是中华文化的精髓，蕴含着丰富的道德资源，是世代相传的民族智慧；孝悌忠信、礼义廉耻是中华传统美德的重要内容。","explain":"「精髓」这个定位词不能改成「基础」「核心」；「孝悌忠信、礼义廉耻」八个字要成串记。中考常由家风家训、敬老孝亲、见义勇为、勤俭节约一类材料切入，设问问「这体现了哪一方面的中华传统美德」，答法是把材料对应到具体德目，再回扣「中华传统美德是中华文化的精髓」。"},{"level":"次重点","text":"做中华传统美德的践行者：美德的力量在于践行，要从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐，在一言一行中把中华传统美德传承下去。","explain":"设问几乎固定为「作为中学生，你打算怎样践行中华传统美德」。答案必须给出可核查的具体行为，四个德目各举一例：在家承担家务、体谅父母（孝亲敬长）；答应别人的事按时做到、考试不作弊（诚实守信）；不浪费粮食、节约用水用电（勤俭节约）；主动帮助有困难的同学、参加志愿服务（助人为乐）。只写口号不给分。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["中华传统美德是中华文化的精髓，蕴含着丰富的道德资源，是世代相传的民族智慧；美德的力量在于践行。","我们要坚定文化自信，推动中华优秀传统文化创造性转化、创新性发展，做核心思想理念的传承者、中华人文精神的弘扬者、中华传统美德的践行者。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为凡是传统观念都是传统美德，都应当继承。","中华传统美德是中华文化的精髓，但传统观念中既有精华也有糟粕；我们要继承和弘扬的是孝悌忠信、礼义廉耻这些经过历史检验的传统美德，对带有封建残余的错误观念要自觉抵制。","这一辨析专治「传统即美德」的思维定势。题目常给「男尊女卑」「愚孝」一类材料，问「这是否属于中华传统美德」，答法必须是「不属于」，并说明要取其精华、去其糟粕。"]]},{"type":"table","title":"思想理念、人文精神与传统美德（三者共同构成对待中华优秀传统文化的完整要求：思想内核—精神气质—行为规范）（本单元概念对比）","head":["比较项","观念层面（核心思想理念 + 中华人文精神）","行为规范层面（中华传统美德）"],"rows":[["定位","中华优秀传统文化的精神内核与精神气质","中华文化的精髓，蕴含着丰富的道德资源，是世代相传的民族智慧"],["主要内容","讲仁爱、守诚信、崇正义、尚和合、求大同；求同存异、和而不同，文以载道、以文化人，形神兼备、情景交融，俭约自守、中和泰和","孝悌忠信、礼义廉耻等"],["解决什么","解决「信什么、怎样处世与生活」的价值与精神问题","解决「怎么做人做事」的行为规范问题"],["落地方式","认真学习、深入了解，推动创造性转化、创新性发展","从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐"],["相互关系","为传统美德提供思想根基与精神滋养","是思想理念与人文精神在行为上的落实与检验，美德的力量在于践行"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["术语识记类：核心思想理念、人文精神与传统美德的固定表述","这是本单元最稳定也最容易拿满分的题型。「讲仁爱、守诚信、崇正义、尚和合、求大同」五个词、「求同存异、和而不同」「文以载道、以文化人」「形神兼备、情景交融」「俭约自守、中和泰和」四组搭配、「孝悌忠信、礼义廉耻」八个字、中华文明五个突出特性，都必须原样写出。选择题常见设错手法是替换同义词或打乱搭配（如把「文以载道、以文化人」说成生活理念）；材料题也必须按术语成串作答，同义改写不踩点。"],["评析类：怎样对待传统文化与外来文化","材料多给两种对立观点（「传统的东西都过时了，没有必要学」与「传统的东西一个字都不能改」），要求评析。作答要落在两个固定术语上：一是「取其精华、去其糟粕」，二是「推动中华优秀传统文化创造性转化、创新性发展」；涉及外来文化时再补「以我为主、为我所用」「尊重差异、包容多样」。只答一面必然扣分。"],["做法建议类：青少年怎样做传承者、弘扬者与践行者","设问基本固定为「作为中学生，你打算怎样做」。答题按第 6、7、8 课的顺序分三层组织：做传承者——认真学习、深入了解，推动创造性转化与创新性发展，并在日常学习生活中身体力行；做弘扬者——尊重差异、包容多样，在生活中传递真善美，提升审美情趣与精神境界；做践行者——从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐。每一层都要给出具体行为，只有口号不踩点。"],["情境判断类：从具体行为反推对应的理念、人文精神与德目","给一段校园、家庭或社区情境（非遗进校园、家风家训、博物馆研学、社区志愿服务、同学之间的差异与矛盾），设问「这体现了中华优秀传统文化的哪一方面内容」「这给我们什么启示」。作答分两步：先点明对应的固定表述（哪一条核心思想理念／哪一类人文精神／哪一项传统美德），再说明理由并回扣教材结论。只描述情境不作判断，或判断时用「很有文化味」这类模糊表述，都不得分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-3-q3","type":"choice","stem":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的","answer":"D","explain":"讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念，是中华优秀传统文化的核心内容，是涵养社会主义核心价值观的重要源泉。它们属于思想理念层面，不能与中华人文精神、中华传统美德、民族精神混为一谈。","options":["传统美德","中华人文精神","民族精神","核心思想理念"],"difficulty":1,"tags":["核心思想理念"]},{"id":"pol-youth-3-q5","type":"choice","stem":"「一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。」某班把这句话写进班级公约，倡导节约粮食、不浪费水电。这体现的中华传统美德是","answer":"B","explain":"这句话讲的是珍惜粮食、爱惜物力，体现的是勤俭节约这一中华传统美德。助人为乐讲的是主动帮助他人，诚实守信讲的是言行一致、信守承诺，孝亲敬长讲的是对待长辈的态度，都与题意不符。","options":["助人为乐","勤俭节约","诚实守信","孝亲敬长"],"difficulty":1,"tags":["中华传统美德","勤俭节约"]},{"id":"pol-youth-3-q6","type":"choice","stem":"关于怎样对待中华优秀传统文化，下列说法正确的是","answer":"D","explain":"对待中华优秀传统文化，要取其精华、去其糟粕，推动其创造性转化、创新性发展。A 项是文化复古主义，否认了结合时代要求继承创新的必要；B 项把一切传统观念都当成传统美德，忽略了传统观念中也有糟粕；C 项把传承狭隘化为背经典、穿古装，是形式主义，不符合传承的实质要求。","options":["传统文化越古老越正宗，应当原封不动地照搬","凡是传统观念都是传统美德，都应当继承下来","传承中华优秀传统文化就是背经典、穿古装","要取其精华、去其糟粕，推动中华优秀传统文化创造性转化、创新性发展"],"difficulty":2,"tags":["创造性转化与创新性发展","取其精华去其糟粕"]},{"id":"pol-youth-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华文化源远流长、博大精深。中华优秀传统文化是中华民族的精神命脉，是涵养社会主义…\n② 中华文明具有突出的连续性、创新性、统一性、包容性、和平性。\n③ 讲仁爱、守诚信、崇正义、尚和合、求大同，是中华优秀传统文化中的核心思想理念。\n④ 认为中华文化就是汉族文化，少数民族的歌舞、服饰、节日不属于中华文化。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最容易失分的表述错误。材料若出现少数民族的歌舞、服饰、节日或各民族文化交流的内容，必须答出「各民族文化共同构成中华文化」，绝不能把中华文化等同于汉族文化；正确表述应为：中华文化是中华民族共同创造的，各民族在长期交流交融中共同创造了中华文化，各民族文化都是中华文化的组成部分；中华文明具有突出的统一性与包容性。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·传承中华优秀传统文化（第6—8课：传承核心思想理念 · 弘扬中华人文精神 · 践行中华传统美德）"]},{"id":"cat-pol-7b-3-3-short","type":"short","stem":"某班围绕「践行中华传统美德」开展主题探究活动，围绕「薪火相传的传统美德」、「做中华传统美德的践行者」。请运用本课所学，谈谈你的认识。","answer":"中华传统美德是中华文化的精髓，蕴含着丰富的道德资源，是世代相传的民族智慧；孝悌忠信、礼义廉耻是中华传统美德的重要内容。做中华传统美德的践行者：美德的力量在于践行，要从日常小事做起，孝亲敬长、诚实守信、勤俭节约、助人为乐，在一言一行中把中华传统美德传承下去。","explain":"","rubric":["中华传统美德是中华文化的精髓，蕴含着丰富的道德资源，是世代相传的民族智慧；孝悌忠…","做中华传统美德的践行者：美德的力量在于践行，要从日常小事做起，孝亲敬长、诚实守信…"],"tags":["践行中华传统美德"]}]},{"id":"cat-pol-7b-4-1","title":"第9课 法律为我们护航","subtitle":"七年级下册 · 第四单元 生活在法治社会","grade":"7b","tags":["七年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第四单元 生活在法治社会"},{"k":"课题","v":"第9课 法律为我们护航"},{"k":"框题","v":"日益完善的法律体系 / 法律保障生活"}]},{"type":"note","title":"本课在单元中的位置","text":"我们生活在法治社会：法律是由国家制定或认可、靠国家强制力保证实施、对全体社会成员具有普遍约束力的行为规范，日益完善的法律体系为生活提供秩序与保障；民法典被称为「社会生活的百科全书」，保护我们的人身权和财产权；法不可违，违法行为要承担相应的法律责任，犯罪要受到刑罚处罚，青少年要严于律己、远离违法犯罪，学会用法律保护自己。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["日益完善的法律体系","法律保障生活"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"我国已经形成以宪法为核心的中国特色社会主义法律体系，宪法是国家的根本法，在法律体系中居于最高地位；法律体系日益完善，国家生活和社会生活的各个方面都实现了有法可依。","explain":"材料给「民法典、未成年人保护法等法律相继制定或者修改」「过去无法可依的领域现在有了明确规范」的素材，设问「说明了什么」，标准答法是：我国法律体系日益完善，坚持全面依法治国，为公民生活提供了坚实的法治保障。两个坑要避开：一是不能把民法典与宪法并列，宪法是国家的根本法，民法典是民事领域的基础性法律；二是不能写成「我国法律体系已经完美无缺」，法律体系是日益完善的。"},{"level":"重点","text":"法律具有规范作用和保护作用：法律通过规定公民的权利和义务，规范全体社会成员的行为，为我们评判、预测自己和他人的行为提供准绳；法律通过解决纠纷和制裁违法犯罪，保护公民的合法权益，维护社会秩序。我们的生活离不开法律，法律为生活提供秩序与保障，公民在法律面前一律平等。","explain":"设问「法律与我们的生活有什么关系」「结合材料说明法律怎样保障生活」，按「规范—保护—平等」三层作答：先说法律规定了什么可以做、什么必须做、什么不能做；再说法律保护人身、财产等合法权益，制裁违法犯罪、解决纠纷；最后落到「公民在法律面前一律平等，任何组织和个人都必须遵守法律，违法要承担法律责任」。只写「法律保护好人、惩罚坏人」不是教材术语，不给分。"},{"level":"重点","text":"民法典确立了平等、自愿、公平、诚信、守法与公序良俗、绿色六项基本原则。民事主体从事民事活动，法律地位一律平等，可以按照自己的意思设立、变更、终止民事法律关系，应当秉持公平、诚信，不得违反法律，不得违背公序良俗，并应当有利于节约资源、保护生态环境。","explain":"以具体情境考「体现了民法典的哪一原则」：双方自愿签订合同→自愿原则；隐瞒真实情况误导他人、不守承诺→诚信原则；一方利用优势地位使交易显失公平→公平原则；随意排放污染物影响邻居生活→绿色原则；违背公序良俗的行为不受法律保护→守法与公序良俗原则。作答时先写原则名称，再用一句话结合材料说明，只写名称拿不到全分。"},{"level":"次重点","text":"民法典保障公民的财产权：物权包括所有权、用益物权和担保物权，所有权是权利人对自己的不动产或者动产依法享有占有、使用、收益和处分的权利；依法订立的合同受法律保护，当事人应当按照约定履行自己的义务；著作权、专利权、商标权等知识产权受法律保护；继承权受法律保护，继承方式包括法定继承和遗嘱继承，公民可以依法立遗嘱处分个人财产。","explain":"常与「网购商品不合格要求退货退款」「租客擅自转租房屋」「盗用他人作品用于商业宣传」「子女争夺遗产」等情境结合命题。答题按「权利名称—法律依据—责任」写，如网购纠纷中商家不按约定履行义务，应当承担违约责任。两个易错点：所有权只是物权的一种，不能等同于全部财产权；违约责任中的赔偿不是「罚款」。"},{"level":"次重点","text":"未成年人的人身权和财产权同样受法律保护，任何组织和个人不得侵害。未成年人身心发育尚不成熟，法律给予特殊保护：父母或者其他监护人应当依法履行监护职责，保护未成年人的人身权利、财产权利以及其他合法权益；未成年人实施民事法律行为，应当与其年龄、智力相适应，超出其年龄、智力范围的事项，应当由法定代理人代理或者经其法定代理人同意、追认。","explain":"以「未成年人巨额打赏主播」「未成年人私自购买贵重物品」「他人擅自使用未成年人的肖像、姓名」等情境设问，答题要点是：未成年人的财产权、人身权受法律保护，不因年龄小而可以被随意侵害；超出其年龄、智力相适应范围的民事行为，须经法定代理人代理或者同意、追认；监护人要依法履行监护职责，不得损害被监护人的合法权益。"},{"level":"次重点","text":"当合法权益受到侵害时，要增强自我保护意识，机智求助：及时告诉家长、老师和学校，向公安机关报警或者向有关部门求助，注意保全证据（如聊天记录、转账记录、伤情照片等），必要时向人民法院提起诉讼，依法维护自己的合法权益，不以违法手段报复；同违法犯罪作斗争既要勇敢，又要机智，讲究策略，善于运用智慧和法律保护自己，不冒险硬拼。为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，属于正当防卫，不负刑事责任。","explain":"「遇到不法侵害怎么办」几乎是必考设问，答案要写全四层：向家长、老师、学校反映或者及时报警求助；注意保全证据；通过协商、投诉、诉讼等合法途径依法维权；同违法犯罪作斗争时保护自身安全、不冒险硬拼，也不能叫上朋友去打回来、在网上曝光对方隐私——以违法手段维护权益，自己也要承担法律责任。正当防卫只作了解，判断时抓住「正在进行的不法侵害」和「制止不法侵害」两个条件。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["我国已经形成以宪法为核心的中国特色社会主义法律体系，宪法是国家的根本法，在法律体系中居于最高地位。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["认为违法就是犯罪，犯罪也就是违法，二者是一回事。","违法行为包括一般违法行为和犯罪。犯罪一定是违法行为，但违法行为不一定是犯罪：只有同时具有严重社会危害性、刑事违法性、应受刑罚处罚性的行为才是犯罪。","这是本单元最高频的陷阱。判断的依据是「违反的法律 + 危害程度 + 承担的责任」：民事违法、行政违法承担民事责任或行政责任（如赔偿损失、罚款、行政拘留）；只有犯罪才承担刑事责任、受到刑罚处罚。答题时必须把两者的区别与联系都写出来，并补一句「一般违法行为与犯罪之间没有不可逾越的鸿沟」。"],["把「拘留」写成「拘役」，认为都是关起来，性质差不多。","拘役是刑罚中的主刑，由人民法院对犯罪分子依法判处；拘留（如行政拘留、司法拘留）不是刑罚，行政拘留由公安机关依法给予，属于行政处罚。","一字之差、性质完全不同：材料里出现「被公安机关给予行政拘留」，那是行政违法、承担行政责任；出现「被人民法院判处拘役」，那才是犯罪、受刑罚处罚。写反了就是概念性错误，选择题和材料题都会连带扣分。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["判断类：区分违法行为的类型与法律责任","给三到四个情境（欠债不还、闯红灯被交警处罚、散布谣言被行政拘留、盗窃被判处有期徒刑），要求判断分别属于哪类违法行为、承担什么责任。判断依据必须是「违反的法律 + 危害程度 + 承担的责任」，并把犯罪的三个基本特征与各自地位写出来。"],["情境类：民法典与我们的生活（人身权、财产权）","以网购纠纷、个人信息被泄露、肖像被擅自使用、未成年人打赏、遗产继承等情境命题，设问「侵害了什么权利」「应当承担什么责任」「怎样依法维权」。作答公式是：先定权利名称（肖像权、名誉权、隐私权、个人信息权益、财产权……），再写法律依据（民法典保护人身权、财产权），最后写责任与维权途径（停止侵害、赔礼道歉、赔偿损失、协商、投诉、诉讼）。"],["辨析类：法律与道德、法治与德治的关系","以「诚信」「孝亲敬老」「见义勇为」等既属道德要求又有法律规定的素材设问，先判断观点正误（如「只要讲道德就不需要法律」），再从「法律是成文的道德、道德是内心的法律」入手，说明二者相辅相成、相互促进，国家和社会治理需要法律和道德共同发挥作用，坚持法治与德治相结合。"],["警示与做法类：远离违法犯罪、依法自我保护","以「逃课—抽烟—结交不良朋友—打架被行政拘留—盗窃被判刑」的轨迹作材料，设问「这给我们什么警示」「遇到不法侵害怎么办」。作答两段走：预防段写杜绝不良行为、防微杜渐、增强法治观念和规则意识、抵制不良诱惑、谨慎交友；自我保护段写及时求助、报警、保全证据、依法维权，同违法犯罪作斗争要有勇有谋、不冒险硬拼。"]]},{"type":"quote","text":"【材料一】初中生小峰原本只是偶尔逃课去网吧，后来结识了几名社会青年，开始抽烟、喝酒、夜不归宿。一次因琐事与同学发生争执，他叫上「朋友」殴打同学，被公安机关依法给予行政拘留；此后仍不悔改，又伙同他人多次盗窃电动车，最终被人民法院依法判处有期徒刑。\n【材料二】初三学生小宁放学路上发现有人正在撬一辆电动车的锁。他没有上前硬拼，而是记住对方的外貌特征和离开方向，走到人多的地方后立即拨打 110 报警。民警根据他提供的信息很快抓获了嫌疑人。\n【材料三】某校开展「法治进校园」活动，邀请法官、检察官、警官走进课堂，讲解法律知识、剖析真实案例，帮助学生学会用法律保护自己。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·生活在法治社会（第9—11课：法律为我们护航 · 走近民法典 · 远离违法犯罪）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-4-m1-q1","type":"short","stem":"（1）结合材料一、材料二，说明公民的哪些权利受法律保护，并指出材料二中该工作室的说法为什么错误。（4 分）","answer":"①材料一中，小宇作为消费者，其财产权受法律保护；商家不按约定提供合格商品、拒绝退货退款，属于不履行合同义务的行为，应当依法承担相应的法律责任。②材料二中，小琳的肖像权受法律保护。肖像权是公民的人身权（人格权），未经本人同意，不得以营利为目的使用他人肖像。③该工作室「照片是我们拍的，想怎么用就怎么用」的说法是错误的：照片虽然是工作室拍摄的，但肖像权属于小琳本人，人身权与民事主体的人身密不可分，不得放弃、转让或者继承；未经同意将其照片用于门店宣传，侵害了小琳的肖像权，应当依法承担停止侵害、赔礼道歉、赔偿损失等责任。④小宇保存证据、通过合法途径维权的做法是正确的，值得我们学习。","explain":"","tags":["民法典","人身权与财产权","材料分析"],"rubric":["指出小宇的财产权（消费者合法权益）受法律保护，商家应承担不履行合同的责任","指出小琳的肖像权受法律保护","说明未经本人同意以营利为目的使用他人肖像构成侵害肖像权","指出侵害人身权应当依法承担相应的法律责任","肯定小宇保存证据、通过合法途径依法维权的做法"]},{"id":"pol-youth-4-q1","type":"choice","stem":"下列关于我国法律和民法典的说法，正确的是","answer":"A","explain":"民法典被称为「社会生活的百科全书」，是新中国第一部以「法典」命名的法律，A 项表述正确。B 项错误：宪法才是国家的根本法，具有最高的法律地位、法律权威和法律效力，民法典是民事领域的基础性法律。C 项错误：我国法律体系日益完善，国家生活和社会生活的各个方面都实现了有法可依，但仍在不断健全。D 项错误：法律对全体社会成员具有普遍约束力，法律面前人人平等。","options":["民法典是新中国第一部以「法典」命名的法律，被称为「社会生活的百科全书」","民法典是国家的根本法，具有最高的法律效力","我国的法律体系已经十分完善，不需要再继续健全","法律只对违反法律的人具有约束力，与其他人无关"],"difficulty":1,"tags":["民法典的地位","法律体系"]},{"id":"pol-youth-4-q6","type":"choice","stem":"关于公民的财产权，下列说法正确的是","answer":"D","explain":"依法订立的合同受法律保护，当事人应当按照约定履行自己的义务，D 项正确。A 项错误：物权包括所有权、用益物权和担保物权，此外还有债权、知识产权、继承权等受法律保护的财产权益。B 项错误：未成年人同样享有财产权，监护人应当依法履行监护职责，不得损害被监护人的合法权益。C 项错误：侵害他人财产权应当依法承担返还财产、赔偿损失等责任。","options":["所有权是唯一的财产权，其他财产权益不受法律保护","未成年人没有财产权，其财产可以由父母随意支配","侵害他人财产权只要赔礼道歉就可以了，不必赔偿损失","依法订立的合同受法律保护，当事人应当按照约定履行自己的义务"],"difficulty":1,"tags":["财产权","合同"]},{"id":"pol-youth-4-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 我国已经形成以宪法为核心的中国特色社会主义法律体系，宪法是国家的根本法，在法律体…\n② 法律是由国家制定或认可、靠国家强制力保证实施、对全体社会成员具有普遍约束力的行为…\n③ 法律具有规范作用和保护作用：法律通过规定公民的权利和义务，规范全体社会成员的行为…\n④ 认为违法就是犯罪，犯罪也就是违法，二者是一回事。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的陷阱。判断的依据是「违反的法律 + 危害程度 + 承担的责任」：民事违法、行政违法承担民事责任或行政责任（如赔偿损失、罚款、行政拘留）；只有犯罪才承担刑事责任、受到刑罚处罚。答题时必须把两者的区别与联系都写出来，并补一句「一般违法行为与犯罪之间没有不可逾越的鸿沟」；正确表述应为：违法行为包括一般违法行为和犯罪。犯罪一定是违法行为，但违法行为不一定是犯罪：只有同时具有严重社会危害性、刑事违法性、应受刑罚处罚性的行为才是犯罪。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·生活在法治社会（第9—11课：法律为我们护航 · 走近民法典 · 远离违法犯罪）"]},{"id":"cat-pol-7b-4-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 我国已经形成以宪法为核心的中国特色社会主义法律体系，宪法是国家的根本法，在法律体…\n② 法律具有规范作用和保护作用：法律通过规定公民的权利和义务，规范全体社会成员的行为…\n③ 民法典确立了平等、自愿、公平、诚信、守法与公序良俗、绿色六项基本原则。民事主体从…\n④ 认为违法就是犯罪，犯罪也就是违法，二者是一回事。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的陷阱。判断的依据是「违反的法律 + 危害程度 + 承担的责任」：民事违法、行政违法承担民事责任或行政责任（如赔偿损失、罚款、行政拘留）；只有犯罪才承担刑事责任、受到刑罚处罚。答题时必须把两者的区别与联系都写出来，并补一句「一般违法行为与犯罪之间没有不可逾越的鸿沟」；正确表述应为：违法行为包括一般违法行为和犯罪。犯罪一定是违法行为，但违法行为不一定是犯罪：只有同时具有严重社会危害性、刑事违法性、应受刑罚处罚性的行为才是犯罪。","difficulty":3,"tags":["第9课 法律为我们护航"]}]},{"id":"cat-pol-7b-4-2","title":"第10课 走近民法典","subtitle":"七年级下册 · 第四单元 生活在法治社会","grade":"7b","tags":["七年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第四单元 生活在法治社会"},{"k":"课题","v":"第10课 走近民法典"},{"k":"框题","v":"认识民法典 / 保护人身权 / 保障财产权"}]},{"type":"note","title":"本课在单元中的位置","text":"我们生活在法治社会：法律是由国家制定或认可、靠国家强制力保证实施、对全体社会成员具有普遍约束力的行为规范，日益完善的法律体系为生活提供秩序与保障；民法典被称为「社会生活的百科全书」，保护我们的人身权和财产权；法不可违，违法行为要承担相应的法律责任，犯罪要受到刑罚处罚，青少年要严于律己、远离违法犯罪，学会用法律保护自己。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["认识民法典","保护人身权","保障财产权"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"民法典被称为「社会生活的百科全书」，是新中国第一部以「法典」命名的法律，自 2021 年 1 月 1 日起施行。它规范民事活动，涉及经济社会生活的方方面面，同人民群众的生产生活密不可分。","explain":"「社会生活的百科全书」「新中国第一部以法典命名的法律」是固定考点，一个字都不能改；选项若写成「我国第一部法律」「我国的根本法」「宪法的重要组成部分」都判错——根本法是宪法，民法典是民事领域的基础性法律。材料题问「民法典与我们的生活有什么关系」，就从人身权、财产权两个方向举材料里的例子回答。"},{"level":"重点","text":"民法典保护公民的人身权，包括生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权等人格权，并保护自然人的个人信息。人身权与民事主体的人身密不可分，不得放弃、转让或者继承。","explain":"情境判断是高频考法：未经同意用他人照片做广告→侵害肖像权；给同学起侮辱性绰号、编造谣言诋毁他人→侵害名誉权；非法剥夺他人获得的荣誉称号→侵害荣誉权；公开他人家庭住址、电话号码、聊天记录→侵害隐私权；擅自收集、使用、买卖他人个人信息→侵害个人信息权益；殴打他人致伤→侵害生命权、身体权、健康权。答题写成「侵害了……权，应当依法承担相应的法律责任」，先定权利名称再写责任。"},{"level":"次重点","text":"民法典保障公民的财产权：物权包括所有权、用益物权和担保物权，所有权是权利人对自己的不动产或者动产依法享有占有、使用、收益和处分的权利；依法订立的合同受法律保护，当事人应当按照约定履行自己的义务；著作权、专利权、商标权等知识产权受法律保护；继承权受法律保护，继承方式包括法定继承和遗嘱继承，公民可以依法立遗嘱处分个人财产。","explain":"常与「网购商品不合格要求退货退款」「租客擅自转租房屋」「盗用他人作品用于商业宣传」「子女争夺遗产」等情境结合命题。答题按「权利名称—法律依据—责任」写，如网购纠纷中商家不按约定履行义务，应当承担违约责任。两个易错点：所有权只是物权的一种，不能等同于全部财产权；违约责任中的赔偿不是「罚款」。"},{"level":"次重点","text":"未成年人的人身权和财产权同样受法律保护，任何组织和个人不得侵害。未成年人身心发育尚不成熟，法律给予特殊保护：父母或者其他监护人应当依法履行监护职责，保护未成年人的人身权利、财产权利以及其他合法权益；未成年人实施民事法律行为，应当与其年龄、智力相适应，超出其年龄、智力范围的事项，应当由法定代理人代理或者经其法定代理人同意、追认。","explain":"以「未成年人巨额打赏主播」「未成年人私自购买贵重物品」「他人擅自使用未成年人的肖像、姓名」等情境设问，答题要点是：未成年人的财产权、人身权受法律保护，不因年龄小而可以被随意侵害；超出其年龄、智力相适应范围的民事行为，须经法定代理人代理或者同意、追认；监护人要依法履行监护职责，不得损害被监护人的合法权益。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["民法典保护公民的人身权，包括生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权等人格权，并保护自然人的个人信息。","民法典被称为「社会生活的百科全书」，是新中国第一部以「法典」命名的法律。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把民事违法行为和行政违法行为混为一谈，只看「事情大不大」。","民事违法行为违反的是民事法律（如民法典），承担民事责任，如赔偿损失、赔礼道歉、支付违约金；行政违法行为违反的是行政管理方面的法律法规，承担行政责任，如警告、罚款、行政拘留。二者合称一般违法行为，分类标准是违反的法律不同。","题目常把「欠债不还」「骑车闯红灯被处罚」「在网上散布谣言被行政拘留」放在一起让考生分类，判断的唯一依据是违反的法律与承担的责任，不是主观感觉的「严重不严重」。"],["认为民法典是「民事领域的宪法」，可以和宪法并列，甚至说民法典具有最高法律效力。","宪法是国家的根本法，具有最高的法律地位、法律权威和法律效力；民法典是民事领域的基础性法律，被称为「社会生活的百科全书」，是新中国第一部以「法典」命名的法律。","民法典的地位是高频设误点：凡是把民法典写成「根本法」「具有最高法律效力」「宪法的一部分」的选项都错；正确说法只能是「社会生活的百科全书」「新中国第一部以法典命名的法律」「民事领域的基础性法律」。"]]},{"type":"table","title":"违法行为的三种类型与法律责任（按违反的法律分类：民事违法、行政违法、刑事违法）（本单元概念对比）","head":["比较项","民事违法行为 · 行政违法行为（合称一般违法行为）","刑事违法行为（犯罪）"],"rows":[["违反的法律","民事法律（如民法典）、行政管理方面的法律法规","刑法"],["对社会的危害","相对轻微，属于一般违法行为","具有严重社会危害性——这是犯罪的最本质特征"],["承担的责任","民事责任（如赔偿损失、赔礼道歉、支付违约金）或行政责任（如警告、罚款、行政拘留）","刑事责任，受到刑罚处罚（主刑、附加刑）"],["由谁处理","行政机关依法给予行政处罚，或者由人民法院判令承担民事责任","由人民法院依法判处刑罚"],["典型情形","欠债不还、损坏他人财物、网购违约、闯红灯、扰乱公共秩序","盗窃数额较大的财物、故意伤害他人身体、抢劫"],["三者联系","民事违法与行政违法同属一般违法行为，与犯罪之间没有不可逾越的鸿沟","犯罪一定是违法行为，违法行为不一定是犯罪"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["判断类：区分违法行为的类型与法律责任","给三到四个情境（欠债不还、闯红灯被交警处罚、散布谣言被行政拘留、盗窃被判处有期徒刑），要求判断分别属于哪类违法行为、承担什么责任。判断依据必须是「违反的法律 + 危害程度 + 承担的责任」，并把犯罪的三个基本特征与各自地位写出来。"],["情境类：民法典与我们的生活（人身权、财产权）","以网购纠纷、个人信息被泄露、肖像被擅自使用、未成年人打赏、遗产继承等情境命题，设问「侵害了什么权利」「应当承担什么责任」「怎样依法维权」。作答公式是：先定权利名称（肖像权、名誉权、隐私权、个人信息权益、财产权……），再写法律依据（民法典保护人身权、财产权），最后写责任与维权途径（停止侵害、赔礼道歉、赔偿损失、协商、投诉、诉讼）。"],["辨析类：法律与道德、法治与德治的关系","以「诚信」「孝亲敬老」「见义勇为」等既属道德要求又有法律规定的素材设问，先判断观点正误（如「只要讲道德就不需要法律」），再从「法律是成文的道德、道德是内心的法律」入手，说明二者相辅相成、相互促进，国家和社会治理需要法律和道德共同发挥作用，坚持法治与德治相结合。"],["警示与做法类：远离违法犯罪、依法自我保护","以「逃课—抽烟—结交不良朋友—打架被行政拘留—盗窃被判刑」的轨迹作材料，设问「这给我们什么警示」「遇到不法侵害怎么办」。作答两段走：预防段写杜绝不良行为、防微杜渐、增强法治观念和规则意识、抵制不良诱惑、谨慎交友；自我保护段写及时求助、报警、保全证据、依法维权，同违法犯罪作斗争要有勇有谋、不冒险硬拼。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·生活在法治社会（第9—11课：法律为我们护航 · 走近民法典 · 远离违法犯罪）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-4-m1-q1","type":"short","stem":"（1）结合材料一、材料二，说明公民的哪些权利受法律保护，并指出材料二中该工作室的说法为什么错误。（4 分）","answer":"①材料一中，小宇作为消费者，其财产权受法律保护；商家不按约定提供合格商品、拒绝退货退款，属于不履行合同义务的行为，应当依法承担相应的法律责任。②材料二中，小琳的肖像权受法律保护。肖像权是公民的人身权（人格权），未经本人同意，不得以营利为目的使用他人肖像。③该工作室「照片是我们拍的，想怎么用就怎么用」的说法是错误的：照片虽然是工作室拍摄的，但肖像权属于小琳本人，人身权与民事主体的人身密不可分，不得放弃、转让或者继承；未经同意将其照片用于门店宣传，侵害了小琳的肖像权，应当依法承担停止侵害、赔礼道歉、赔偿损失等责任。④小宇保存证据、通过合法途径维权的做法是正确的，值得我们学习。","explain":"","tags":["民法典","人身权与财产权","材料分析"],"rubric":["指出小宇的财产权（消费者合法权益）受法律保护，商家应承担不履行合同的责任","指出小琳的肖像权受法律保护","说明未经本人同意以营利为目的使用他人肖像构成侵害肖像权","指出侵害人身权应当依法承担相应的法律责任","肯定小宇保存证据、通过合法途径依法维权的做法"]},{"id":"pol-youth-4-m1-q2","type":"short","stem":"（2）结合材料三，运用法律知识评析小杰的打赏行为，并说明家长可以怎样依法维权。（4 分）","answer":"①未成年人同样享有财产权，其财产权受法律保护，不因年龄小而可以被随意侵害。②小杰是未成年人，身心发育尚不成熟，打赏两万余元明显超出与其年龄、智力相适应的范围，依法应当由他的法定代理人代理，或者经其法定代理人同意、追认。③家长的正确做法是：及时保存打赏记录等证据，与直播平台协商要求退款；协商不成，可以向有关部门投诉、举报，必要时向人民法院提起诉讼，依法维护小杰的合法权益，不能采取吵闹、威胁等违法方式。④家长还应当依法履行监护职责，加强对未成年人使用网络的引导和管理，帮助孩子树立正确的消费观念，防止类似情况再次发生。","explain":"","tags":["未成年人财产权","依法维权","评析类"],"rubric":["答出未成年人的财产权受法律保护","说明大额打赏超出未成年人年龄、智力相适应的范围，须由法定代理人代理或者经其同意、追认","答出保存证据并与平台协商、向有关部门投诉或者依法提起诉讼","答出不以违法方式维权","答出家长应依法履行监护职责、加强教育引导"]},{"id":"pol-youth-4-q1","type":"choice","stem":"下列关于我国法律和民法典的说法，正确的是","answer":"A","explain":"民法典被称为「社会生活的百科全书」，是新中国第一部以「法典」命名的法律，A 项表述正确。B 项错误：宪法才是国家的根本法，具有最高的法律地位、法律权威和法律效力，民法典是民事领域的基础性法律。C 项错误：我国法律体系日益完善，国家生活和社会生活的各个方面都实现了有法可依，但仍在不断健全。D 项错误：法律对全体社会成员具有普遍约束力，法律面前人人平等。","options":["民法典是新中国第一部以「法典」命名的法律，被称为「社会生活的百科全书」","民法典是国家的根本法，具有最高的法律效力","我国的法律体系已经十分完善，不需要再继续健全","法律只对违反法律的人具有约束力，与其他人无关"],"difficulty":1,"tags":["民法典的地位","法律体系"]},{"id":"pol-youth-4-q4","type":"choice","stem":"某商家在销售商品时故意隐瞒商品的真实情况，误导消费者购买。该商家的行为主要违背了民法典规定的","answer":"D","explain":"民法典确立了平等、自愿、公平、诚信、守法与公序良俗、绿色等基本原则。故意隐瞒真实情况、误导他人，违背的是诚信原则，D 项正确。平等原则强调民事主体法律地位一律平等，自愿原则强调按照自己的意思设立、变更、终止民事法律关系，绿色原则强调有利于节约资源、保护生态环境，均与题意不符。","options":["平等原则","自愿原则","绿色原则","诚信原则"],"difficulty":2,"tags":["民法典基本原则","诚信原则"]},{"id":"pol-youth-4-q5","type":"choice","stem":"下列行为中，侵害他人隐私权的是","answer":"B","explain":"未经允许查看并转发他人的聊天记录，侵害了他人的隐私权，B 项正确。A 项未经同意以营利为目的使用他人照片，侵害的是肖像权；C 项编造谣言诋毁他人，侵害的是名誉权；D 项冒用他人姓名，侵害的是姓名权。","options":["未经同意将同学的照片印在门店宣传海报上","未经允许查看并在班级群里转发同学与他人的聊天记录","无中生有，编造同学考试作弊的谣言","冒用同学的姓名报名参加比赛"],"difficulty":1,"tags":["人身权","隐私权"]},{"id":"pol-youth-4-q6","type":"choice","stem":"关于公民的财产权，下列说法正确的是","answer":"D","explain":"依法订立的合同受法律保护，当事人应当按照约定履行自己的义务，D 项正确。A 项错误：物权包括所有权、用益物权和担保物权，此外还有债权、知识产权、继承权等受法律保护的财产权益。B 项错误：未成年人同样享有财产权，监护人应当依法履行监护职责，不得损害被监护人的合法权益。C 项错误：侵害他人财产权应当依法承担返还财产、赔偿损失等责任。","options":["所有权是唯一的财产权，其他财产权益不受法律保护","未成年人没有财产权，其财产可以由父母随意支配","侵害他人财产权只要赔礼道歉就可以了，不必赔偿损失","依法订立的合同受法律保护，当事人应当按照约定履行自己的义务"],"difficulty":1,"tags":["财产权","合同"]}]},{"id":"cat-pol-7b-4-3","title":"第11课 远离违法犯罪","subtitle":"七年级下册 · 第四单元 生活在法治社会","grade":"7b","tags":["七年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"七年级下册"},{"k":"单元","v":"第四单元 生活在法治社会"},{"k":"课题","v":"第11课 远离违法犯罪"},{"k":"框题","v":"法不可违 / 犯罪与刑罚 / 严于律己"}]},{"type":"note","title":"本课在单元中的位置","text":"我们生活在法治社会：法律是由国家制定或认可、靠国家强制力保证实施、对全体社会成员具有普遍约束力的行为规范，日益完善的法律体系为生活提供秩序与保障；民法典被称为「社会生活的百科全书」，保护我们的人身权和财产权；法不可违，违法行为要承担相应的法律责任，犯罪要受到刑罚处罚，青少年要严于律己、远离违法犯罪，学会用法律保护自己。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["法不可违","犯罪与刑罚","严于律己"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"犯罪是具有严重社会危害性、触犯刑法、应受刑罚处罚的行为。严重社会危害性是犯罪的最本质特征，刑事违法性是犯罪的法律标志，应受刑罚处罚性是犯罪的必然法律后果。刑罚分为主刑和附加刑：主刑包括管制、拘役、有期徒刑、无期徒刑、死刑，只能独立适用；附加刑包括罚金、剥夺政治权利、没收财产、驱逐出境，既可以附加于主刑适用，也可以独立适用。刑罚只能由人民法院依法判处。","explain":"「三个特征 + 三个地位」必须成组背下来，顺序和对应关系都不能互换：判断一个行为是不是犯罪，就看三个特征是否同时具备，尤其是有没有严重社会危害性、是否触犯刑法。选择题考刑罚种类时抓两条：主刑的五个名称不能与行政处罚的「罚款」「行政拘留」混用；「刑罚只能由人民法院依法判处」是排除干扰项的钥匙，选项写「由公安机关判处罚金」必错。"},{"level":"次重点","text":"预防违法犯罪要严于律己、防微杜渐：要增强法治观念和规则意识，依法自律；要杜绝不良行为，如吸烟、饮酒、多次旷课逃学、无故夜不归宿、沉迷网络、与社会上具有不良习性的人交往、进入未成年人不宜进入的场所等；对结伙斗殴、殴打辱骂他人、强拿硬要或者任意损毁他人财物、盗窃哄抢公私财物、参与赌博、吸食注射毒品等严重不良行为，要依法予以矫治；要自觉抵制不良诱惑，谨慎交友，远离违法犯罪。","explain":"材料常从逃课、抽烟、夜不归宿、结交不良朋友写起，设问「这给我们什么警示」。作答按行为轨迹说清三步：不良行为（还不是违法，但危害不小）→一般违法行为（承担民事责任或行政责任）→犯罪（受到刑罚处罚），再写出「很多犯罪都是从沾染不良习气开始的」「一般违法行为与犯罪之间没有不可逾越的鸿沟」，最后给出杜绝不良行为、增强法治观念、依法自律、抵制不良诱惑等做法。"},{"level":"次重点","text":"法律是最刚性的社会规则，不违法是人们行为的底线。违法行为是指违反法律、法规的规定，危害社会、应受法律处罚的行为；根据违反的法律，违法行为分为民事违法行为、行政违法行为和刑事违法行为，其中民事违法行为和行政违法行为称为一般违法行为。无论是一般违法还是犯罪，都要承担相应的法律责任。","explain":"判断类选择题的必经步骤：先看违反了哪部法律（民法典等民事法律→民事违法；治安管理、道路交通等行政管理法律法规→行政违法；刑法→刑事违法），再看危害程度和承担的责任。分类标准只能是「违反的法律」，写「严重的就是犯罪、不严重的就是一般违法」不得分；「大错才是违法、小错不算违法」的说法也是错的，不违法只是行为的底线。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["犯罪是具有严重社会危害性、触犯刑法、应受刑罚处罚的行为；严重社会危害性是犯罪的最本质特征。","预防违法犯罪要严于律己、防微杜渐，杜绝不良行为，增强法治观念和规则意识，自觉抵制不良诱惑。","违法行为根据违反的法律分为民事违法行为、行政违法行为和刑事违法行为，民事违法行为和行政违法行为称为一般违法行为。","遇到不法侵害要及时报警、保全证据、依法维权；同违法犯罪作斗争既要勇敢，又要机智，不冒险硬拼。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为违法就是犯罪，犯罪也就是违法，二者是一回事。","违法行为包括一般违法行为和犯罪。犯罪一定是违法行为，但违法行为不一定是犯罪：只有同时具有严重社会危害性、刑事违法性、应受刑罚处罚性的行为才是犯罪。","这是本单元最高频的陷阱。判断的依据是「违反的法律 + 危害程度 + 承担的责任」：民事违法、行政违法承担民事责任或行政责任（如赔偿损失、罚款、行政拘留）；只有犯罪才承担刑事责任、受到刑罚处罚。答题时必须把两者的区别与联系都写出来，并补一句「一般违法行为与犯罪之间没有不可逾越的鸿沟」。"],["把「拘留」写成「拘役」，认为都是关起来，性质差不多。","拘役是刑罚中的主刑，由人民法院对犯罪分子依法判处；拘留（如行政拘留、司法拘留）不是刑罚，行政拘留由公安机关依法给予，属于行政处罚。","一字之差、性质完全不同：材料里出现「被公安机关给予行政拘留」，那是行政违法、承担行政责任；出现「被人民法院判处拘役」，那才是犯罪、受刑罚处罚。写反了就是概念性错误，选择题和材料题都会连带扣分。"],["把「罚金」和「罚款」当成一回事，写成「被法院判处罚款」「被行政机关处以罚金」。","罚金是刑罚中的附加刑，由人民法院对犯罪分子依法判处；罚款是行政处罚，由行政机关依法作出。","两词读音相近、适用主体和性质完全不同。「罚金」只出现在刑事判决里，「罚款」只出现在行政处罚里，答题时先判断是「谁作出的决定」，再选词，绝不能混用。"]]},{"type":"table","title":"违法行为的三种类型与法律责任（按违反的法律分类：民事违法、行政违法、刑事违法）（本单元概念对比）","head":["比较项","民事违法行为 · 行政违法行为（合称一般违法行为）","刑事违法行为（犯罪）"],"rows":[["违反的法律","民事法律（如民法典）、行政管理方面的法律法规","刑法"],["对社会的危害","相对轻微，属于一般违法行为","具有严重社会危害性——这是犯罪的最本质特征"],["承担的责任","民事责任（如赔偿损失、赔礼道歉、支付违约金）或行政责任（如警告、罚款、行政拘留）","刑事责任，受到刑罚处罚（主刑、附加刑）"],["由谁处理","行政机关依法给予行政处罚，或者由人民法院判令承担民事责任","由人民法院依法判处刑罚"],["典型情形","欠债不还、损坏他人财物、网购违约、闯红灯、扰乱公共秩序","盗窃数额较大的财物、故意伤害他人身体、抢劫"],["三者联系","民事违法与行政违法同属一般违法行为，与犯罪之间没有不可逾越的鸿沟","犯罪一定是违法行为，违法行为不一定是犯罪"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["判断类：区分违法行为的类型与法律责任","给三到四个情境（欠债不还、闯红灯被交警处罚、散布谣言被行政拘留、盗窃被判处有期徒刑），要求判断分别属于哪类违法行为、承担什么责任。判断依据必须是「违反的法律 + 危害程度 + 承担的责任」，并把犯罪的三个基本特征与各自地位写出来。"],["情境类：民法典与我们的生活（人身权、财产权）","以网购纠纷、个人信息被泄露、肖像被擅自使用、未成年人打赏、遗产继承等情境命题，设问「侵害了什么权利」「应当承担什么责任」「怎样依法维权」。作答公式是：先定权利名称（肖像权、名誉权、隐私权、个人信息权益、财产权……），再写法律依据（民法典保护人身权、财产权），最后写责任与维权途径（停止侵害、赔礼道歉、赔偿损失、协商、投诉、诉讼）。"],["辨析类：法律与道德、法治与德治的关系","以「诚信」「孝亲敬老」「见义勇为」等既属道德要求又有法律规定的素材设问，先判断观点正误（如「只要讲道德就不需要法律」），再从「法律是成文的道德、道德是内心的法律」入手，说明二者相辅相成、相互促进，国家和社会治理需要法律和道德共同发挥作用，坚持法治与德治相结合。"],["警示与做法类：远离违法犯罪、依法自我保护","以「逃课—抽烟—结交不良朋友—打架被行政拘留—盗窃被判刑」的轨迹作材料，设问「这给我们什么警示」「遇到不法侵害怎么办」。作答两段走：预防段写杜绝不良行为、防微杜渐、增强法治观念和规则意识、抵制不良诱惑、谨慎交友；自我保护段写及时求助、报警、保全证据、依法维权，同违法犯罪作斗争要有勇有谋、不冒险硬拼。"]]},{"type":"quote","text":"【材料一】初中生小峰原本只是偶尔逃课去网吧，后来结识了几名社会青年，开始抽烟、喝酒、夜不归宿。一次因琐事与同学发生争执，他叫上「朋友」殴打同学，被公安机关依法给予行政拘留；此后仍不悔改，又伙同他人多次盗窃电动车，最终被人民法院依法判处有期徒刑。\n【材料二】初三学生小宁放学路上发现有人正在撬一辆电动车的锁。他没有上前硬拼，而是记住对方的外貌特征和离开方向，走到人多的地方后立即拨打 110 报警。民警根据他提供的信息很快抓获了嫌疑人。\n【材料三】某校开展「法治进校园」活动，邀请法官、检察官、警官走进课堂，讲解法律知识、剖析真实案例，帮助学生学会用法律保护自己。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·生活在法治社会（第9—11课：法律为我们护航 · 走近民法典 · 远离违法犯罪）","url":"/learn/politics/pages/detail/detail?moduleId=pol-youth&entryId=pol-youth-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-youth-4-m2-q1","type":"short","stem":"（1）结合材料一，指出小峰的行为分别属于什么性质，并说明判断犯罪的基本特征。（4 分）","answer":"①逃课去网吧、抽烟、喝酒、夜不归宿属于不良行为，还不是违法行为，但危害不小，很多犯罪都是从沾染不良习气开始的。②叫上他人殴打同学被公安机关给予行政拘留，属于行政违法行为，与民事违法行为同属一般违法行为，违反的是行政管理方面的法律法规，危害相对轻微，承担行政责任。③伙同他人多次盗窃电动车被人民法院判处有期徒刑，属于刑事违法行为，即犯罪。④犯罪具有严重社会危害性、刑事违法性、应受刑罚处罚性三个基本特征：严重社会危害性是犯罪的最本质特征，刑事违法性是犯罪的法律标志，应受刑罚处罚性是犯罪的必然法律后果。⑤小峰从不良行为一步步走上犯罪道路，说明一般违法行为与犯罪之间没有不可逾越的鸿沟。","explain":"","tags":["违法行为分类","犯罪的特征","材料分析"],"rubric":["指出逃课、抽烟、夜不归宿属于不良行为，并说明不良行为与犯罪的关系","判断被行政拘留属于行政违法行为（一般违法行为），并说明依据","判断盗窃被判刑属于犯罪（刑事违法行为）","完整答出犯罪的三个基本特征及其地位","答出一般违法行为与犯罪之间没有不可逾越的鸿沟"]},{"id":"pol-youth-4-m2-q2","type":"short","stem":"（2）结合材料二，说明小宁的做法为什么值得学习。（3 分）","answer":"①同违法犯罪作斗争既要勇敢，又要机智，讲究策略：小宁没有上前硬拼，避免了自身受到伤害，是在保护好自己的前提下同违法犯罪作斗争。②他记住了对方的外貌特征和离开方向，并及时拨打 110 报警，为公安机关破案提供了帮助，是同违法犯罪作斗争的机智做法。③遇到不法侵害或者发现违法犯罪行为，要及时报警、机智求助，注意保全证据，善于运用智慧和法律保护自己，既不冒险硬拼，也不纵容违法犯罪。","explain":"","tags":["同违法犯罪作斗争","自我保护","原因类"],"rubric":["答出同违法犯罪作斗争既要勇敢又要机智（有勇有谋）","答出小宁采取机智方式避免了自身受到伤害","答出及时报警、为公安机关提供线索","答出善于运用智慧和法律保护自己，不冒险硬拼"]},{"id":"pol-youth-4-q2","type":"choice","stem":"靠国家强制力保证实施是法律区别于道德等行为规范的最主要特征。下列情境最能直接体现这一特征的是","answer":"C","explain":"人民法院依法判处刑罚，以国家强制力为后盾，直接体现法律靠国家强制力保证实施，C 项符合。A 项属于道德倡导，靠社会舆论和人们的自觉；B 项属于学校纪律处分，不是法律制裁；D 项属于集体约定的规则，靠同学自觉遵守。","options":["某社区通过宣传栏倡导居民文明养犬","某学校对在校园内打架的学生给予通报批评","人民法院依法判处盗窃他人财物的赵某有期徒刑","某班同学共同制定班级卫生公约并互相监督"],"difficulty":2,"tags":["法律的特征","国家强制力"]},{"id":"pol-youth-4-q7","type":"choice","stem":"下列行为中，属于犯罪（刑事违法行为）的是","answer":"A","explain":"张某的行为触犯刑法、具有严重社会危害性，受到刑罚处罚，属于犯罪，A 项正确。B 项违反行政管理方面的法律法规，由交警给予行政处罚，属于行政违法行为（一般违法行为）；C 项违反民事法律，承担民事责任，属于民事违法行为；D 项尚未构成违法，属于不文明行为。","options":["张某多次盗窃他人财物，数额较大，被人民法院判处有期徒刑","李某骑电动车闯红灯，被交警依法处以罚款","王某向同学借款到期不还，被要求承担违约责任","赵某在小区内大声喧哗，被物业公司劝阻"],"difficulty":2,"tags":["违法行为的分类","犯罪"]},{"id":"pol-youth-4-q8","type":"choice","stem":"面对不良诱惑和违法犯罪行为，下列做法正确的是","answer":"C","explain":"遇到不法侵害要及时求助、报警，依法维护自己的合法权益，同时自觉抵制不良诱惑，C 项正确。A 项和 D 项都是以违法手段处理问题，自己也要承担法律责任；B 项是纵容违法犯罪，也不符合公民同违法犯罪作斗争的要求。","options":["为了讲「哥们义气」，帮朋友打架出气","发现同学被敲诈勒索，认为与自己无关，不予理会","自觉抵制不良诱惑，遇到不法侵害时及时告诉家长、老师并报警，依法维护自己的合法权益","合法权益受到侵害后，叫上朋友去找对方「算账」"],"difficulty":1,"tags":["自我保护","依法维权","抵制不良诱惑"]},{"id":"pol-youth-4-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 我国已经形成以宪法为核心的中国特色社会主义法律体系，宪法是国家的根本法，在法律体…\n② 法律是由国家制定或认可、靠国家强制力保证实施、对全体社会成员具有普遍约束力的行为…\n③ 法律具有规范作用和保护作用：法律通过规定公民的权利和义务，规范全体社会成员的行为…\n④ 认为违法就是犯罪，犯罪也就是违法，二者是一回事。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的陷阱。判断的依据是「违反的法律 + 危害程度 + 承担的责任」：民事违法、行政违法承担民事责任或行政责任（如赔偿损失、罚款、行政拘留）；只有犯罪才承担刑事责任、受到刑罚处罚。答题时必须把两者的区别与联系都写出来，并补一句「一般违法行为与犯罪之间没有不可逾越的鸿沟」；正确表述应为：违法行为包括一般违法行为和犯罪。犯罪一定是违法行为，但违法行为不一定是犯罪：只有同时具有严重社会危害性、刑事违法性、应受刑罚处罚性的行为才是犯罪。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·生活在法治社会（第9—11课：法律为我们护航 · 走近民法典 · 远离违法犯罪）"]}]},{"id":"cat-pol-8a-1-1","title":"第1课 丰富的社会生活","subtitle":"八年级上册 · 第一单元 走进社会生活","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 走进社会生活"},{"k":"课题","v":"第1课 丰富的社会生活"},{"k":"框题","v":"认识社会生活 / 我们都是社会的一员"}]},{"type":"note","title":"本课在单元中的位置","text":"人不能脱离社会而生存和发展，人的身份是在社会关系中确定的，成长就是不断社会化的过程；网络是这个时代最重要的生活空间之一，它既丰富日常生活、推动社会进步，也可能带来信息良莠不齐、沉迷网络、隐私受侵害等问题，因此要学会理性参与网络生活、传播网络正能量。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["认识社会生活","我们都是社会的一员"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们具有不同的身份。","explain":"选择题常给具体情境问「这属于哪种社会关系」：以血缘定亲疏的是血缘关系（父母子女、祖孙），以空间地域定归属的是地缘关系（邻居、同乡），以社会分工为基础的是业缘关系（同学、同事、师生）。答题先判断关系类型，再回扣「身份由社会关系确定」这句结论。"},{"level":"重点","text":"人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、价值观念日渐养成，逐步成长为一名合格的社会成员；人的生存和发展离不开社会，每个人都从社会中获得物质支持和精神滋养。","explain":"这是「人的生存和发展离不开社会」类辨析题的正面答案。凡是题目出现「我可以完全靠自己、不需要社会」的说法，一律先答这一条，再从物质支持（衣食住行）与精神滋养（知识、情感、规则意识、价值观念）两方面展开，不要只写一句结论。"},{"level":"了解","text":"随着身体的成长、智力的发展、能力的提高，我们的社会生活空间不断延展，对社会生活的感受越来越丰富、认识越来越深刻；社会生活是绚丽多彩的，我们要主动融入社会，在社会中健康成长。","explain":"多作为材料的情境铺垫或作文式设问的收束句，考「为什么要走进社会」。答「社会生活空间不断延展」＋「主动融入社会、在社会实践中成长」即可，不必展开。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["个人是社会的有机组成部分，人的身份是在社会关系中确定的。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为人的身份是与生俱来、一成不变的，由血缘固定下来。","个人是社会的有机组成部分，人的身份是在社会关系中确定的；同一个人在不同的社会关系中具有不同的身份，随着社会关系的扩展，我们的身份也在不断增加。","常与「我是谁」的身份情境表结合考查。判断的关键是看这一身份由哪一种社会关系决定，而不是看年龄或血缘本身。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辩证分析类：网络是把双刃剑","给出一组「网络便利」与一组「网络问题」的材料，设问「结合材料谈谈你对网络的认识」。答题框架固定：积极作用（日常生活、经济发展、民主政治、文化科技）+ 消极影响（信息良莠不齐、沉迷网络、隐私受侵害）+ 关键在于提高媒介素养、理性参与网络生活。只答一面或只抄材料都不给满分。"],["情境判断类：个人与社会的关系、亲社会行为","以「我是谁」的身份情境表（在家庭是子女、在学校是学生、在社区是居民）考社会关系的三种类型与「身份由社会关系确定」；以志愿服务、社区活动的情境考亲社会行为的判断与养成途径。"],["做法建议类：理性参与网络生活、传播网络正能量","设问常写「作为中学生，请你为健康上网提几条建议」。作答必须用术语：提高媒介素养、学会『信息节食』、学会辨析网络信息、自觉抵制不良信息、恪守道德与遵守法律、传播网络正能量。建议要可操作，写「合理安排上网时间」比写「少玩手机」有效。"],["法治意识类：网络不是法外之地","以编造传播网络谣言、侵犯他人隐私被依法处理的材料，考「网络生活为什么也要遵守规则」「违法要承担什么责任」，与本册第二单元第6课的违法行为分类打通命题。"]]},{"type":"quote","text":"【材料一】初二学生小宇的一天：早上用手机查询公交实时到站信息，中午与在外地工作的表哥视频通话，晚上通过线上平台观看博物馆的专题展览，还把自己拍摄的家乡非遗项目短视频发布到平台上，向网友介绍本地传统文化，获得不少点赞。\n【材料二】同一部手机，也让小宇吃过苦头：他曾因轻信网络上「免费领取游戏皮肤」的信息，泄露了家长的身份信息和银行卡号；也曾为刷短视频熬到深夜，第二天上课无精打采；还在班级群聊里看到有人造谣同学，一度跟着转发。\n【材料三】我国已出台《未成年人网络保护条例》等法规，从网络素养促进、网络信息内容规范、个人信息网络保护、网络沉迷防治等方面，为未成年人健康上网提供法治保障。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·走进社会生活（第1—3课：丰富的社会生活 · 在社会中健康成长 · 共建网络美好家园）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-1-q1","type":"choice","stem":"下列关于个人与社会关系的表述，正确的是","answer":"C","explain":"个人是社会的有机组成部分，人的身份是在社会关系中确定的：同一个人在不同的社会关系中具有不同的身份。A 项错在「与生俱来、不会变化」；B、D 两项否认个人对社会的依赖，人的生存和发展离不开社会。","options":["人的身份是与生俱来的，不会随社会关系的变化而变化","个人与社会相互独立，个人的成长与社会无关","个人是社会的有机组成部分，人的身份是在社会关系中确定的","人的生存和发展可以脱离社会而独立实现"],"difficulty":1,"tags":["个人与社会的关系"]},{"id":"pol-moral-1-q2","type":"choice","stem":"小丽在社区邻里互助群里认识了同住一个小区的张阿姨，又在学校社团活动中结识了同校的学长。小丽与张阿姨、学长之间的社会关系依次属于","answer":"B","explain":"以空间地域上的共同生活为基础形成的是地缘关系（邻居、同乡），以社会分工为基础形成的是业缘关系（同学、同事）。张阿姨是邻居，属地缘关系；学长是同校同学，属业缘关系。","options":["业缘关系、地缘关系","地缘关系、业缘关系","血缘关系、业缘关系","地缘关系、血缘关系"],"difficulty":2,"tags":["社会关系的类型"]},{"id":"pol-moral-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们…\n② 人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、…\n③ 亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享…\n④ 认为网络空间是虚拟的，网上的言行可以不受道德和法律的约束。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本课最经典的陷阱。题目给出「匿名发帖辱骂同学」「编造谣言」等情境，就要同时答出「道德上不尊重他人」与「法律上要承担相应责任」两层，与本册第6课提升法治素养的内容打通命题；正确表述应为：网络生活也要恪守道德、遵守法律，网络不是法外之地；网络交往中要尊重他人、对自己的言论负责，不能造谣、传谣、侵犯他人隐私。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第一单元·走进社会生活（第1—3课：丰富的社会生活 · 在社会中健康成长 · 共建网络美好家园）"]},{"id":"cat-pol-8a-1-1-short","type":"short","stem":"某班围绕「丰富的社会生活」开展主题探究活动，围绕「认识社会生活」、「我们都是社会的一员」。请运用本课所学，谈谈你的认识。","answer":"个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们具有不同的身份。人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、价值观念日渐养成，逐步成长为一名合格的社会成员；人的生存和发展离不开社会，每个人都从社会中获得物质支持和精神滋养。","explain":"","rubric":["个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们…","人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、…","随着身体的成长、智力的发展、能力的提高，我们的社会生活空间不断延展，对社会生活的…"],"tags":["丰富的社会生活"]},{"id":"cat-pol-8a-1-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们…\n② 人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、…\n③ 随着身体的成长、智力的发展、能力的提高，我们的社会生活空间不断延展，对社会生活的…\n④ 认为人的身份是与生俱来、一成不变的，由血缘固定下来。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——常与「我是谁」的身份情境表结合考查。判断的关键是看这一身份由哪一种社会关系决定，而不是看年龄或血缘本身；正确表述应为：个人是社会的有机组成部分，人的身份是在社会关系中确定的；同一个人在不同的社会关系中具有不同的身份，随着社会关系的扩展，我们的身份也在不断增加。","difficulty":3,"tags":["第1课 丰富的社会生活"]}]},{"id":"cat-pol-8a-1-2","title":"第2课 在社会中健康成长","subtitle":"八年级上册 · 第一单元 走进社会生活","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 走进社会生活"},{"k":"课题","v":"第2课 在社会中健康成长"},{"k":"框题","v":"人的社会化 / 养成亲社会行为"}]},{"type":"note","title":"本课在单元中的位置","text":"人不能脱离社会而生存和发展，人的身份是在社会关系中确定的，成长就是不断社会化的过程；网络是这个时代最重要的生活空间之一，它既丰富日常生活、推动社会进步，也可能带来信息良莠不齐、沉迷网络、隐私受侵害等问题，因此要学会理性参与网络生活、传播网络正能量。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人的社会化","养成亲社会行为"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、价值观念日渐养成，逐步成长为一名合格的社会成员；人的生存和发展离不开社会，每个人都从社会中获得物质支持和精神滋养。","explain":"这是「人的生存和发展离不开社会」类辨析题的正面答案。凡是题目出现「我可以完全靠自己、不需要社会」的说法，一律先答这一条，再从物质支持（衣食住行）与精神滋养（知识、情感、规则意识、价值观念）两方面展开，不要只写一句结论。"},{"level":"重点","text":"亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享、帮助他人、关心社会发展等；养成亲社会行为，有利于我们养成良好的行为习惯，塑造健康的人格，形成正确的价值观念，获得他人和社会的接纳与认可。","explain":"常考「判断是不是亲社会行为」：关键看行为是否指向他人和社会、是否有利于社会，为自己取乐、损害他人的行为一律不是。意义类设问按「行为习惯—健康人格—正确价值观念—他人与社会的接纳认可」四点作答；途径类设问答「主动了解社会，关注社会发展变化，积极投身于社会实践」。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["人的成长是不断社会化的过程，人的生存和发展离不开社会，每个人都从社会中获得物质支持和精神滋养。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["认为网络空间是虚拟的，网上的言行可以不受道德和法律的约束。","网络生活也要恪守道德、遵守法律，网络不是法外之地；网络交往中要尊重他人、对自己的言论负责，不能造谣、传谣、侵犯他人隐私。","这是本课最经典的陷阱。题目给出「匿名发帖辱骂同学」「编造谣言」等情境，就要同时答出「道德上不尊重他人」与「法律上要承担相应责任」两层，与本册第6课提升法治素养的内容打通命题。"],["认为人的身份是与生俱来、一成不变的，由血缘固定下来。","个人是社会的有机组成部分，人的身份是在社会关系中确定的；同一个人在不同的社会关系中具有不同的身份，随着社会关系的扩展，我们的身份也在不断增加。","常与「我是谁」的身份情境表结合考查。判断的关键是看这一身份由哪一种社会关系决定，而不是看年龄或血缘本身。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辩证分析类：网络是把双刃剑","给出一组「网络便利」与一组「网络问题」的材料，设问「结合材料谈谈你对网络的认识」。答题框架固定：积极作用（日常生活、经济发展、民主政治、文化科技）+ 消极影响（信息良莠不齐、沉迷网络、隐私受侵害）+ 关键在于提高媒介素养、理性参与网络生活。只答一面或只抄材料都不给满分。"],["情境判断类：个人与社会的关系、亲社会行为","以「我是谁」的身份情境表（在家庭是子女、在学校是学生、在社区是居民）考社会关系的三种类型与「身份由社会关系确定」；以志愿服务、社区活动的情境考亲社会行为的判断与养成途径。"],["做法建议类：理性参与网络生活、传播网络正能量","设问常写「作为中学生，请你为健康上网提几条建议」。作答必须用术语：提高媒介素养、学会『信息节食』、学会辨析网络信息、自觉抵制不良信息、恪守道德与遵守法律、传播网络正能量。建议要可操作，写「合理安排上网时间」比写「少玩手机」有效。"],["法治意识类：网络不是法外之地","以编造传播网络谣言、侵犯他人隐私被依法处理的材料，考「网络生活为什么也要遵守规则」「违法要承担什么责任」，与本册第二单元第6课的违法行为分类打通命题。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·走进社会生活（第1—3课：丰富的社会生活 · 在社会中健康成长 · 共建网络美好家园）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-1-q5","type":"choice","stem":"下列行为属于亲社会行为的是","answer":"A","explain":"亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享、帮助他人、关心社会发展等。B 项是作弊，C 项是冷漠，D 项侵犯他人权益，都不属于亲社会行为。","options":["小明周末到敬老院为老人表演节目、陪老人聊天","小华在考试中偷偷翻看课本","小刚看到同学遇到困难，假装没有看见","小强在网络上编造同学谣言取乐"],"difficulty":1,"tags":["亲社会行为"]},{"id":"pol-moral-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 个人是社会的有机组成部分，人的身份是在社会关系中确定的；在不同的社会关系中，我们…\n② 人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、…\n③ 亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享…\n④ 认为网络空间是虚拟的，网上的言行可以不受道德和法律的约束。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本课最经典的陷阱。题目给出「匿名发帖辱骂同学」「编造谣言」等情境，就要同时答出「道德上不尊重他人」与「法律上要承担相应责任」两层，与本册第6课提升法治素养的内容打通命题；正确表述应为：网络生活也要恪守道德、遵守法律，网络不是法外之地；网络交往中要尊重他人、对自己的言论负责，不能造谣、传谣、侵犯他人隐私。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第一单元·走进社会生活（第1—3课：丰富的社会生活 · 在社会中健康成长 · 共建网络美好家园）"]},{"id":"pol-moral-1-q3","type":"choice","stem":"对网络的认识，下列说法正确的是","answer":"C","explain":"网络是一把双刃剑：它丰富日常生活、推动社会进步，也可能造成信息良莠不齐、沉迷网络、个人隐私被侵犯等问题。A 项错在网络不是法外之地；B 项否认消极影响；D 项缩小了危害范围，沉迷网络还会危害身心健康、影响现实交往。","options":["网络是虚拟空间，网民可以随意发表言论而不必负责","网络只有积极作用，没有消极影响","网络是一把双刃剑，既带来便利，也可能带来消极影响","沉迷网络只会影响学习成绩，不会危害身心健康"],"difficulty":1,"tags":["网络是把双刃剑"]},{"id":"cat-pol-8a-1-2-short","type":"short","stem":"某班围绕「在社会中健康成长」开展主题探究活动，围绕「人的社会化」、「养成亲社会行为」。请运用本课所学，谈谈你的认识。","answer":"人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、价值观念日渐养成，逐步成长为一名合格的社会成员；人的生存和发展离不开社会，每个人都从社会中获得物质支持和精神滋养。亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享、帮助他人、关心社会发展等；养成亲社会行为，有利于我们养成良好的行为习惯，塑造健康的人格，形成正确的价值观念，获得他人和社会的接纳与认可。","explain":"","rubric":["人的成长是不断社会化的过程：我们的知识不断丰富、能力不断提高、规则意识不断增强、…","亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享…"],"tags":["在社会中健康成长"]},{"id":"pol-moral-1-q4","type":"choice","stem":"面对海量网络信息，中学生应学会「信息节食」。下列做法符合这一要求的是","answer":"D","explain":"『信息节食』是指有选择地浏览信息，注意浏览、寻找与学习和生活有关的信息，同时学会辨析网络信息、自觉抵制不良信息。A 项是不加辨析；B 项是沉迷网络；C 项因噎废食，网络有利有弊，应当理性参与而不是拒绝使用。","options":["不加分辨地转发各类消息，以扩大信息来源","为不错过任何信息，长时间刷手机到深夜","因为担心不良信息，从此完全拒绝上网","注意浏览、寻找与学习和生活有关的信息，学会辨析网络信息"],"difficulty":2,"tags":["信息节食","理性参与网络生活"]}]},{"id":"cat-pol-8a-1-3","title":"第3课 共建网络美好家园","subtitle":"八年级上册 · 第一单元 走进社会生活","grade":"8a","tags":["八年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第一单元 走进社会生活"},{"k":"课题","v":"第3课 共建网络美好家园"},{"k":"框题","v":"网络改变世界 / 营造清朗空间"}]},{"type":"note","title":"本课在单元中的位置","text":"人不能脱离社会而生存和发展，人的身份是在社会关系中确定的，成长就是不断社会化的过程；网络是这个时代最重要的生活空间之一，它既丰富日常生活、推动社会进步，也可能带来信息良莠不齐、沉迷网络、隐私受侵害等问题，因此要学会理性参与网络生活、传播网络正能量。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["网络改变世界","营造清朗空间"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"理性参与网络生活：要提高媒介素养，积极利用互联网获取新知、促进沟通、完善自我；要学会『信息节食』，注意浏览、寻找与学习和生活有关的信息；要学会辨析网络信息，自觉抵制不良信息；网络生活也要恪守道德、遵守法律。","explain":"做法建议类设问的骨干答案。注意四个术语不能混：提高媒介素养、信息节食、辨析网络信息（自觉抵制不良信息）、恪守道德与遵守法律。写「少玩手机」不得分，写「学会信息节食」才踩点。"},{"level":"重点","text":"网络丰富日常生活：让日常生活中的信息传递和交流变得方便迅捷，让生活变得更加便利和丰富多彩；网络推动社会进步：为经济发展注入新的活力，促进民主政治的进步，为文化传播和科技创新搭建新平台。","explain":"材料题给一组「网络带来便利」的材料，问「网络的作用」，就按「日常生活—经济发展—民主政治—文化科技」四个层次分点作答，每一层都要用材料中的例子印证，只背知识点、不结合材料拿不满分。"},{"level":"重点","text":"网络是一把双刃剑：网络信息良莠不齐，沉迷网络会影响学习、工作和生活，个人隐私容易被侵犯。","explain":"凡是材料里同时出现「利」与「弊」两类事实，设问多半要求「辩证分析」。固定答法：先承认积极作用（丰富日常生活、推动社会进步），再指出消极影响（信息良莠不齐、沉迷网络、隐私受侵害），最后落到「关键在人怎么用」。只答一面一定扣分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["我们要提高媒介素养，学会『信息节食』，学会辨析网络信息，自觉抵制不良信息。","网络是一把双刃剑：它丰富日常生活、推动社会进步，也可能带来信息良莠不齐、沉迷网络、个人隐私被侵犯等问题。","传播网络正能量，践行社会主义核心价值观，共同培育积极健康、向上向善的网络文化。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为网络空间是虚拟的，网上的言行可以不受道德和法律的约束。","网络生活也要恪守道德、遵守法律，网络不是法外之地；网络交往中要尊重他人、对自己的言论负责，不能造谣、传谣、侵犯他人隐私。","这是本课最经典的陷阱。题目给出「匿名发帖辱骂同学」「编造谣言」等情境，就要同时答出「道德上不尊重他人」与「法律上要承担相应责任」两层，与本册第6课提升法治素养的内容打通命题。"],["认为网络交往完全可以取代现实交往，网上朋友多就不需要现实中的交往。","网络交往拓展了人际交往的范围和方式，但它不能取代现实交往；沉迷网络会影响学习、工作和生活，现实中的亲情、友情与真实的社会实践对人的成长不可替代。","材料题常设「有人认为网络让人与人更亲近，有人认为网络让人更孤独，你怎么看」，必须答出「网络交往是补充而不是替代」这一层，否则只算答了一半。"]]},{"type":"table","title":"网络的积极作用与消极影响（同一部手机的正反两面：网络是把双刃剑）（本单元概念对比）","head":["比较项","积极作用","消极影响"],"rows":[["日常生活","信息传递和交流方便迅捷，生活变得更加便利和丰富多彩","沉迷网络影响学习、工作和生活，挤占现实交往与休息时间"],["经济发展","为经济发展注入新的活力，催生新业态、提供购物与就业便利","网络诈骗、虚假宣传等行为可能侵害他人财产权益"],["民主政治","促进民主政治的进步，公民可以更便捷地表达意见、参与公共事务","网络谣言、情绪化表达干扰公共秩序，需要依法治理"],["文化与科技","为文化传播和科技创新搭建新平台，优秀传统文化传播更广","网络信息良莠不齐，低俗、不良信息影响价值判断"],["信息与隐私","获取新知、促进沟通、完善自我","个人隐私容易被侵犯，个人信息可能被非法收集和使用"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辩证分析类：网络是把双刃剑","给出一组「网络便利」与一组「网络问题」的材料，设问「结合材料谈谈你对网络的认识」。答题框架固定：积极作用（日常生活、经济发展、民主政治、文化科技）+ 消极影响（信息良莠不齐、沉迷网络、隐私受侵害）+ 关键在于提高媒介素养、理性参与网络生活。只答一面或只抄材料都不给满分。"],["情境判断类：个人与社会的关系、亲社会行为","以「我是谁」的身份情境表（在家庭是子女、在学校是学生、在社区是居民）考社会关系的三种类型与「身份由社会关系确定」；以志愿服务、社区活动的情境考亲社会行为的判断与养成途径。"],["做法建议类：理性参与网络生活、传播网络正能量","设问常写「作为中学生，请你为健康上网提几条建议」。作答必须用术语：提高媒介素养、学会『信息节食』、学会辨析网络信息、自觉抵制不良信息、恪守道德与遵守法律、传播网络正能量。建议要可操作，写「合理安排上网时间」比写「少玩手机」有效。"],["法治意识类：网络不是法外之地","以编造传播网络谣言、侵犯他人隐私被依法处理的材料，考「网络生活为什么也要遵守规则」「违法要承担什么责任」，与本册第二单元第6课的违法行为分类打通命题。"]]},{"type":"quote","text":"【材料一】初二学生小宇的一天：早上用手机查询公交实时到站信息，中午与在外地工作的表哥视频通话，晚上通过线上平台观看博物馆的专题展览，还把自己拍摄的家乡非遗项目短视频发布到平台上，向网友介绍本地传统文化，获得不少点赞。\n【材料二】同一部手机，也让小宇吃过苦头：他曾因轻信网络上「免费领取游戏皮肤」的信息，泄露了家长的身份信息和银行卡号；也曾为刷短视频熬到深夜，第二天上课无精打采；还在班级群聊里看到有人造谣同学，一度跟着转发。\n【材料三】我国已出台《未成年人网络保护条例》等法规，从网络素养促进、网络信息内容规范、个人信息网络保护、网络沉迷防治等方面，为未成年人健康上网提供法治保障。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·走进社会生活（第1—3课：丰富的社会生活 · 在社会中健康成长 · 共建网络美好家园）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-1-m1-q1","type":"short","stem":"（1）结合材料一，说明网络给我们的生活带来了哪些积极影响。（4 分）","answer":"①网络让我们日常生活中的信息传递和交流变得方便迅捷：小宇用手机查询公交到站信息、与表哥视频通话。②网络让我们的生活变得更加便利和丰富多彩：小宇通过线上平台观看博物馆的专题展览。③网络为文化传播和科技创新搭建新平台：小宇发布家乡非遗短视频，向网友介绍本地传统文化。④网络为经济发展注入新的活力，也促进了民主政治的进步。","explain":"","tags":["网络的作用","材料分析"],"rubric":["答出信息传递和交流方便迅捷，并举出材料中的例证","答出生活更加便利和丰富多彩，并举出材料中的例证","答出网络为文化传播搭建新平台，并举出材料中的例证","答出网络为经济发展注入新的活力（或促进民主政治的进步）"]},{"id":"pol-moral-1-m1-q2","type":"short","stem":"（2）结合材料二，谈谈中学生应当如何理性参与网络生活。（6 分）","answer":"①提高媒介素养，积极利用互联网获取新知、促进沟通、完善自我，把网络用到学习和成长上。②学会『信息节食』，注意浏览、寻找与学习和生活有关的信息，不沉迷网络，合理安排上网时间，不影响学习和休息。③学会辨析网络信息，自觉抵制不良信息，不轻信「免费领取」之类的诱惑，注意保护个人隐私，不随意泄露自己和家人的身份信息、银行卡号。④网络生活也要恪守道德、遵守法律，不造谣、不信谣、不传谣，不转发未经证实的信息，对自己的网络言论负责。⑤传播网络正能量，践行社会主义核心价值观，共同培育积极健康、向上向善的网络文化。","explain":"","tags":["理性参与网络生活","做法建议"],"rubric":["答出提高媒介素养","答出学会『信息节食』、不沉迷网络","答出学会辨析网络信息、自觉抵制不良信息、保护个人隐私","答出恪守道德、遵守法律，不造谣不信谣不传谣、对自己的言论负责","答出传播网络正能量、践行社会主义核心价值观，并结合材料中泄露信息、熬夜刷视频、转发谣言等具体情境作答"]},{"id":"pol-moral-1-q3","type":"choice","stem":"对网络的认识，下列说法正确的是","answer":"C","explain":"网络是一把双刃剑：它丰富日常生活、推动社会进步，也可能造成信息良莠不齐、沉迷网络、个人隐私被侵犯等问题。A 项错在网络不是法外之地；B 项否认消极影响；D 项缩小了危害范围，沉迷网络还会危害身心健康、影响现实交往。","options":["网络是虚拟空间，网民可以随意发表言论而不必负责","网络只有积极作用，没有消极影响","网络是一把双刃剑，既带来便利，也可能带来消极影响","沉迷网络只会影响学习成绩，不会危害身心健康"],"difficulty":1,"tags":["网络是把双刃剑"]},{"id":"pol-moral-1-q4","type":"choice","stem":"面对海量网络信息，中学生应学会「信息节食」。下列做法符合这一要求的是","answer":"D","explain":"『信息节食』是指有选择地浏览信息，注意浏览、寻找与学习和生活有关的信息，同时学会辨析网络信息、自觉抵制不良信息。A 项是不加辨析；B 项是沉迷网络；C 项因噎废食，网络有利有弊，应当理性参与而不是拒绝使用。","options":["不加分辨地转发各类消息，以扩大信息来源","为不错过任何信息，长时间刷手机到深夜","因为担心不良信息，从此完全拒绝上网","注意浏览、寻找与学习和生活有关的信息，学会辨析网络信息"],"difficulty":2,"tags":["信息节食","理性参与网络生活"]},{"id":"pol-moral-1-q5","type":"choice","stem":"下列行为属于亲社会行为的是","answer":"A","explain":"亲社会行为是指人们在社会交往中表现出来的那些有利于他人和社会的行为，如谦让、分享、帮助他人、关心社会发展等。B 项是作弊，C 项是冷漠，D 项侵犯他人权益，都不属于亲社会行为。","options":["小明周末到敬老院为老人表演节目、陪老人聊天","小华在考试中偷偷翻看课本","小刚看到同学遇到困难，假装没有看见","小强在网络上编造同学谣言取乐"],"difficulty":1,"tags":["亲社会行为"]},{"id":"pol-moral-1-q6","type":"choice","stem":"中学生利用网络传播正能量，下列做法恰当的是","answer":"B","explain":"传播网络正能量要求充分利用网络平台为社会发展建言献策、践行社会主义核心价值观、共同培育积极健康向上向善的网络文化。A 项传播未经证实的信息，C 项侵犯他人人格尊严，D 项侵犯隐私，都是违反道德和法律的行为。","options":["在班级群里转发未经证实的「地震预警」消息","为学校社团活动拍摄短视频，在网络上传播优秀传统文化","用匿名账号在评论区辱骂与自己意见不同的人","为博取关注，虚构并发布他人的隐私信息"],"difficulty":2,"tags":["传播网络正能量","网络规则"]}]},{"id":"cat-pol-8a-2-1","title":"第4课 遵守社会规则","subtitle":"八年级上册 · 第二单元 维护社会秩序","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 维护社会秩序"},{"k":"课题","v":"第4课 遵守社会规则"},{"k":"框题","v":"维护秩序靠规则 / 遵守规则"}]},{"type":"note","title":"本课在单元中的位置","text":"社会秩序需要社会规则来维护，自由与规则不可分——规则划定了自由的边界，也是人们享有自由的保障，遵守规则既靠他律也靠自律，还要维护规则、改进规则；在社会生活中，尊重是交往的起点，文明有礼是立身处世的前提，诚信是安身立命之本，三者共同构成社会生活的基本道德要求。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["维护秩序靠规则","遵守规则"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"社会秩序是社会生活的一种有序化状态；社会正常运行需要秩序，社会秩序是人民安居乐业的保障。社会规则是人们为了维护有秩序的社会环境，在逐渐达成默契与共识的基础上形成的，它明确社会秩序的内容，保障社会秩序的实现。","explain":"常考「为什么要有规则」。答题要写清两个层次：规则与秩序的关系（规则明确社会秩序的内容、保障社会秩序的实现），秩序与生活的关系（社会正常运行需要秩序、社会秩序是人民安居乐业的保障）。只写「没有规矩不成方圆」不得分。"},{"level":"重点","text":"自觉遵守规则，既需要他律，也需要自律：他律是来自外部的约束与监督，自律是发自内心的自我约束；我们要发自内心地敬畏规则，把规则作为自己行动的准绳，将规则内化于心、外化于行。","explain":"做法类设问的必答句。他律对应外部监督、他人提醒、纪律与法律的约束；自律对应自我约束与内心敬畏。凡设问「怎样做一个守规则的人」，两句都要写，只写一句扣一半分。"},{"level":"次重点","text":"我们要坚定维护规则：一方面从自身做起，自觉遵守规则；另一方面要在保证自身安全的前提下，提醒、监督、帮助他人遵守规则。我们还要积极改进规则：规则不是一成不变的，要积极参与规则的改进和完善，善于与他人沟通交流、寻求共识，积极为新规则的形成建言献策。","explain":"「维护规则」与「改进规则」是两件事，设问「怎样对待规则」时两层都要写。材料若给出「某项规定已不适应现实需要并被修改」（如借阅、交通、社区管理规定），一定要答出「规则不是一成不变的，要积极为新规则的形成建言献策」。"},{"level":"重点","text":"树立法治观念，要树立守法光荣、违法可耻的观念：从细节抓起、从小事做起、从遵守规则做起，如遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间；自觉践行社会主义核心价值观，自觉履行法定义务、社会责任、家庭责任。","explain":"材料题爱用「闯红灯、乱扔垃圾、攀比浪费、在班级群里转发不实消息」这类看似很小的情境设问，答案要从「这是小事」上升到「守法光荣、违法可耻的观念」和「从细节抓起、从小事做起、从遵守规则做起」，再落到自觉践行社会主义核心价值观、自觉履行法定义务、社会责任、家庭责任。举例只举教材里的四个例子：遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["社会秩序是社会生活的一种有序化状态，社会规则明确社会秩序的内容、保障社会秩序的实现。","树立守法光荣、违法可耻的观念，从细节抓起、从小事做起、从遵守规则做起。","自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障。","遵守社会规则既需要他律，也需要自律，要发自内心地敬畏规则。","我们要坚定维护规则，并积极参与规则的改进和完善，为新规则的形成建言献策。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为遵守交通规则、做好垃圾分类、杜绝餐饮浪费这些只是生活小事，与法治观念没有关系。","树立守法光荣、违法可耻的观念，要从细节抓起、从小事做起、从遵守规则做起，遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间都是具体的表现；还要自觉践行社会主义核心价值观，自觉履行法定义务、社会责任、家庭责任。","材料题常拿「看似很小的行为」作素材，考的就是「小事与法治观念的关系」。正确答法是把小事上升到规则意识和法治观念：遵守规则是从细节抓起的表现，守法光荣、违法可耻的观念正体现在这些日常行为中，不能写成「小事不影响法治」。"],["认为社会规则限制了自由，规则与自由是对立的。","自由与规则不可分：自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界。","这是本单元最高频的辨析题。凡遇「我的自由别人管不着」「规则太麻烦」一类观点，都要先答「自由与规则不可分」，再指出越界行为会损害他人和社会利益，最后落到他律与自律。"],["认为只要有人监督、有人处罚就能守住规则，不需要自律。","遵守社会规则既需要他律，也需要自律：他律使人不敢违规，自律使人不愿违规，二者缺一不可；守规则的最高境界是发自内心地敬畏规则，把规则内化于心、外化于行。","常以「有监控和没有监控时表现不一样」设问，考「为什么不能只靠他律」。答案是自律把外在要求变成内在自觉，而不是否认他律的必要性。"]]},{"type":"table","title":"道德与法律（两种社会规则的比较：刚性与柔性）（本单元概念对比）","head":["比较项","道德","法律"],"rows":[["产生方式","在长期社会生活中逐渐形成，靠人们的默契与共识","由国家制定或认可"],["实施手段","主要靠社会舆论、传统习惯和内心信念来维持，靠自觉遵守","靠国家强制力保证实施"],["约束范围","几乎涉及社会生活的方方面面，范围更宽","对全体社会成员具有普遍约束力，调整法律规定范围内的行为"],["违反的后果","受到道德谴责，影响个人信誉","承担相应的法律责任"],["相互关系","法律是刚性的社会规则，道德是柔性的社会规则，二者相辅相成","同左：道德是法律的基础，法律是道德的保障"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与规则的关系","给「抢几秒钟不算什么」「在小区里怎么养犬是我的自由」等观点，要求评析。作答结构：先判断观点错误，再答「自由不是随心所欲，受道德、纪律、法律等社会规则的约束」与「规则划定了自由的边界，是人们享有自由的保障」，最后落到「遵守规则既需要他律也需要自律」。"],["道德类：尊重、文明有礼、诚信的情境分析","以校园、社区、网络交往中的具体情境考查「为什么讲道德、怎样讲道德」。尊重题答四点做法（关注重视、平等对待、换位思考、欣赏他人）；文明有礼题答「立身处世的前提—促进社会和谐—体现国家形象」；诚信题答「诚信的重要性 + 树立诚信意识、运用诚信智慧、珍惜个人诚信记录」。"],["规则改进类：规则不是一成不变的","以某项规定修订（借阅规则、交通管理规定、社区公约、班级公约）为材料，设问「这说明了什么」「我们应怎样对待规则」。要点：规则明确社会秩序的内容、保障社会秩序的实现；规则不是一成不变的，要积极为新规则的形成建言献策，同时自觉遵守现行规则。"],["关系类设问：用规范表述回答「秩序、规则、自由是什么关系」","这是道法材料题最稳定的题型。答案必须出现教材原话式术语：社会规则明确社会秩序的内容、保障社会秩序的实现；社会规则划定了自由的边界，是人们享有自由的保障。用自己的话概括不得分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·维护社会秩序（第4—5课：遵守社会规则 · 社会生活讲道德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-2"},{"t":"专题精讲 · 第6课 提升法治素养（6.1 树立法治观念 · 6.2 学会依法办事）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-2-m1-q1","type":"short","stem":"（1）结合材料一，运用自由与规则的相关知识，评析小周的观点。（4 分）","answer":"小周的观点是错误的。①自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；闯红灯越过了自由的边界，危害自己和他人的生命安全。②社会规则划定了自由的边界，社会规则是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界，促进社会有序运行。③社会规则明确社会秩序的内容，保障社会秩序的实现，交通规则正是为了维护道路交通秩序、保障人民安居乐业。④遵守社会规则既需要他律，也需要自律，小周应当发自内心地敬畏规则，把规则作为自己行动的准绳。","explain":"","tags":["自由与规则","社会秩序","评析题"],"rubric":["判断小周的观点错误","答出自由不是随心所欲，受道德、纪律、法律等社会规则的约束","答出社会规则划定自由的边界、是人们享有自由的保障","答出社会规则明确社会秩序的内容、保障社会秩序的实现","答出遵守规则既需要他律也需要自律（或要发自内心地敬畏规则）"]},{"id":"pol-moral-2-m1-q3","type":"short","stem":"（3）材料一中「只是抢了几秒钟」，材料二中「一本书而已，同学之间不必当真」，都是把守规则、讲诚信当作「小事」。请运用所学知识，说明为什么「小事」也不能这样做。（2 分）","answer":"①社会规则划定了自由的边界，也是人们享有自由的保障；越过边界的行为会危害他人和社会利益，不会因为「事小」而改变其性质。②诚信是一个人安身立命之本，小事上的失信会损害个人信誉，久而久之失去他人的信任与尊重。③我们要发自内心地敬畏规则，从小事做起、从自身做起，把规则和诚信要求内化于心、外化于行。","explain":"","tags":["规则意识","诚信","综合评析"],"rubric":["答出规则划定了自由的边界（或小事也会危害他人和社会利益）","答出诚信是安身立命之本、失信会损害个人信誉","答出从小事做起、敬畏规则，把要求内化于心、外化于行"]},{"id":"pol-moral-2-q1","type":"choice","stem":"关于社会规则与自由的关系，下列说法正确的是","answer":"D","explain":"自由与规则不可分：规则划定了自由的边界，也是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界。A 项把二者对立；B 项否认自由的边界；C 项混淆了社会规则的种类，道德、纪律同样是必须遵守的规则。","options":["社会规则限制了自由，二者是对立的","自由就是不受任何约束，想做什么就做什么","只要不违反法律，就可以不受道德和纪律的约束","社会规则划定了自由的边界，是人们享有自由的保障"],"difficulty":1,"tags":["自由与规则"]},{"id":"pol-moral-2-q2","type":"choice","stem":"对于社会秩序与社会规则的关系，下列理解正确的是","answer":"A","explain":"社会规则是人们为了维护有秩序的社会环境，在逐渐达成默契与共识的基础上形成的，它明确社会秩序的内容，保障社会秩序的实现。B 项割裂二者关系；C 项把规则的保障作用绝对化，秩序的形成还需要人们自觉遵守；D 项说法片面，规则要与实际相适应，并非越多越细越好。","options":["社会规则明确社会秩序的内容，保障社会秩序的实现","社会秩序是社会规则形成的前提，与规则没有关系","只要有社会规则，就一定能形成良好的社会秩序","社会规则越多，社会秩序就越稳定，因此规则越细越好"],"difficulty":2,"tags":["社会秩序与社会规则"]},{"id":"pol-moral-2-q5","type":"choice","stem":"某校图书馆原规定「闭馆前读者须将全部书籍归还原架」，常引发争执；后改为「读者可自助归还至还书车，由工作人员统一上架」，并增加网上预约借书服务，馆内秩序明显改善。这启示我们","answer":"B","explain":"规则不是一成不变的，随着社会的发展和社会生活的变迁，一些原来没有的规则需要制定，一些原有的规则失去了存在的合理性需要废除，一些原有的规则不能完全适应实际生活的变化需要加以调整和完善。我们要积极参与规则的改进和完善，积极为新规则的形成建言献策，同时自觉遵守现行的规则。A、C、D 三项分别错在否认规则的改进、任意挑选规则、否认自觉遵守规则的必要性。","options":["规则一旦制定就不能修改","规则不是一成不变的，我们要积极参与规则的改进和完善","读者可以不遵守自己不喜欢的规则","只要改进规则，就不再需要人们自觉遵守规则"],"difficulty":2,"tags":["改进规则","维护规则"]},{"id":"pol-moral-2-q7","type":"choice","stem":"小明发现班级「卫生值日表」安排不合理，同一名同学连续多天承担最繁重的清洁任务。对此，他的正确做法是","answer":"B","explain":"规则不是一成不变的，我们要积极参与规则的改进和完善，善于与他人沟通交流、寻求共识，积极为新规则的形成建言献策；在规则修改之前，仍要自觉遵守现行规则。A 项是以不守规则对抗不合理规则，C 项是破坏规则，D 项是放弃参与公共生活的责任。","options":["拒绝参加值日，以此表示不满","在班级意见征集时提出调整建议，与同学沟通协商、寻求共识，形成新的公约","私下把值日表撕掉，让值日自行取消","认为规则与自己无关，事不关己、高高挂起"],"difficulty":2,"tags":["改进规则","规则意识"]}]},{"id":"cat-pol-8a-2-2","title":"第5课 社会生活讲道德","subtitle":"八年级上册 · 第二单元 维护社会秩序","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 维护社会秩序"},{"k":"课题","v":"第5课 社会生活讲道德"},{"k":"框题","v":"文明有礼 / 诚实守信 / 友善待人"}]},{"type":"note","title":"本课在单元中的位置","text":"社会秩序需要社会规则来维护，自由与规则不可分——规则划定了自由的边界，也是人们享有自由的保障，遵守规则既靠他律也靠自律，还要维护规则、改进规则；在社会生活中，尊重是交往的起点，文明有礼是立身处世的前提，诚信是安身立命之本，三者共同构成社会生活的基本道德要求。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["文明有礼","诚实守信","友善待人"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"了解","text":"尊重他人、文明有礼、诚实守信共同构成社会生活中的基本道德要求，也是社会主义核心价值观在公民个人层面价值准则的具体体现；道德是社会关系的基石，是人际和谐的基础。","explain":"用于材料题最后一问的收束句，也用于「社会生活为什么需要讲道德」这类宏观设问。作答时要把三种品质与社会主义核心价值观中的「诚信」「友善」对应起来，比空喊「要讲道德」得分高。"},{"level":"重点","text":"诚信就是诚实、守信用，是社会主义核心价值观在公民个人层面的一个价值准则，是一种道德规范和品质，是中华民族的传统美德，也是一项民法原则；诚信是一个人安身立命之本，是企业的无形资产，能够促进社会文明、国家兴旺。","explain":"这一定义必须背全五个身份（价值准则、道德规范和品质、传统美德、民法原则、安身立命之本）。设问「诚信为什么重要」，按「个人—企业—社会国家」三层次作答，缺一层少一分。做法类设问答「树立诚信意识、运用诚信智慧、珍惜个人诚信记录」三点。"},{"level":"重点","text":"自由与规则不可分：自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障。人们建立规则的目的不是限制自由，而是保证每个人不越过自由的边界，促进社会有序运行。","explain":"这是本单元分值最高的一句，辨析题几乎必考。答「规则与自由的关系」必须出现三个关键词：划定自由的边界、人们享有自由的保障、不是限制自由而是保证不越过边界。写成「规则限制了自由」直接判错。"},{"level":"次重点","text":"文明有礼是一个人立身处世的前提，促进社会和谐，体现国家形象；礼体现一个人的尊重、谦让、与人为善等良好品质。做文明有礼的人，要态度谦和、用语文明，仪表整洁、举止端庄，并在社会生活中不断学习、观察、思考和践行。","explain":"多与「涉外交往、公共场所言行」的材料结合，考「文明有礼为什么重要」。答题层次：个人立身处世 → 社会和谐 → 国家形象，三句都要有；做法题要写「态度谦和、用语文明」「仪表整洁、举止端庄」。"},{"level":"重点","text":"法律是一种社会规则和行为规范，是评价人们的行为是否合法有效的准绳。我们必须在法律范围内活动，以法律为行为准则，依照法律行使权利、履行义务。","explain":"选择题常把「法律」「道德」「纪律」放在一起设误：判断一种行为是否合法有效，只能以法律为准绳，不能用道德评价代替。凡选项出现「只要不伤害别人就可以做」「只要自己没被抓到就不算违法」「不违法就可以不受任何约束」，一律判错——不违法只是底线，行为仍要在法律范围内、依照法律进行。材料题问「法律对公民的行为提出了什么要求」，答「以法律为行为准则，依照法律行使权利、履行义务」这两句。"},{"level":"重点","text":"法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从。法律的权威源自人民的内心拥护和真诚信仰。坚持宪法法律至上，牢固树立法律红线不能触碰、法律底线不可逾越的观念。","explain":"「发自内心的认可、崇尚、遵守和服从」「法律的权威源自人民的内心拥护和真诚信仰」是教材原话，答「法治观念的内涵」必须原样写出，换成「知道法律」「害怕被处罚」都不得分。「法律红线不能触碰、法律底线不可逾越」中的两个否定词不能改成「尽量不」「最好不」。凡出现「法不责众」「偶尔越线没关系」的选项，一律判错。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["诚信是社会主义核心价值观在公民个人层面的一个价值准则，也是一种道德规范和品质，是一项民法原则，是一个人安身立命之本。","自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障。","法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从；法律的权威源自人民的内心拥护和真诚信仰。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为社会规则限制了自由，规则与自由是对立的。","自由与规则不可分：自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界。","这是本单元最高频的辨析题。凡遇「我的自由别人管不着」「规则太麻烦」一类观点，都要先答「自由与规则不可分」，再指出越界行为会损害他人和社会利益，最后落到他律与自律。"],["认为讲诚信就是任何时候都必须说出全部实情，不能有任何例外。","诚信的核心是诚实守信，但当尊重他人隐私、保护他人正当利益与「说出实情」发生冲突时，要运用诚信智慧，在遵循伦理原则和法律要求的前提下作出正确选择；出于善意的、不损害他人和社会利益的考虑并不违背诚信的要求。","题目常以「把同学的隐私当谈资」「面对重病患者家属怎样告知」设问，考的是「诚信不等于无条件说真话」，同时必须强调不得损害他人和社会利益，否则会变成为撒谎辩护。"],["认为道德要求与法律规定是一回事，违反了道德就要受到法律制裁。","道德与法律都是社会规则，但法律靠国家强制力保证实施、对全体社会成员具有普遍约束力，道德主要靠社会舆论、传统习惯和内心信念来维持；一般的不道德行为受到舆论谴责，只有违法行为才承担法律责任。","这一辨析是本单元与本册第6课的连接点，选择题与材料题都可能出现，答题时两个规则的区别要写成对照。"]]},{"type":"table","title":"道德与法律（两种社会规则的比较：刚性与柔性）（本单元概念对比）","head":["比较项","道德","法律"],"rows":[["产生方式","在长期社会生活中逐渐形成，靠人们的默契与共识","由国家制定或认可"],["实施手段","主要靠社会舆论、传统习惯和内心信念来维持，靠自觉遵守","靠国家强制力保证实施"],["约束范围","几乎涉及社会生活的方方面面，范围更宽","对全体社会成员具有普遍约束力，调整法律规定范围内的行为"],["违反的后果","受到道德谴责，影响个人信誉","承担相应的法律责任"],["相互关系","法律是刚性的社会规则，道德是柔性的社会规则，二者相辅相成","同左：道德是法律的基础，法律是道德的保障"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与规则的关系","给「抢几秒钟不算什么」「在小区里怎么养犬是我的自由」等观点，要求评析。作答结构：先判断观点错误，再答「自由不是随心所欲，受道德、纪律、法律等社会规则的约束」与「规则划定了自由的边界，是人们享有自由的保障」，最后落到「遵守规则既需要他律也需要自律」。"],["道德类：尊重、文明有礼、诚信的情境分析","以校园、社区、网络交往中的具体情境考查「为什么讲道德、怎样讲道德」。尊重题答四点做法（关注重视、平等对待、换位思考、欣赏他人）；文明有礼题答「立身处世的前提—促进社会和谐—体现国家形象」；诚信题答「诚信的重要性 + 树立诚信意识、运用诚信智慧、珍惜个人诚信记录」。"],["规则改进类：规则不是一成不变的","以某项规定修订（借阅规则、交通管理规定、社区公约、班级公约）为材料，设问「这说明了什么」「我们应怎样对待规则」。要点：规则明确社会秩序的内容、保障社会秩序的实现；规则不是一成不变的，要积极为新规则的形成建言献策，同时自觉遵守现行规则。"],["关系类设问：用规范表述回答「秩序、规则、自由是什么关系」","这是道法材料题最稳定的题型。答案必须出现教材原话式术语：社会规则明确社会秩序的内容、保障社会秩序的实现；社会规则划定了自由的边界，是人们享有自由的保障。用自己的话概括不得分。"]]},{"type":"quote","text":"【材料一】初二学生小周骑车上学途中闯红灯，被交警依法给予处罚。他起初很不服气：「我只是抢了几秒钟，又没有撞到人，这算什么事？」\n【材料二】小林向同学借了一本参考书，答应三天后归还，到期却以「还没看完」为由一直拖着，还说「一本书而已，同学之间不必当真」；他的同桌小雅答应帮邻居奶奶取快递，当天下大雨，她仍撑着伞准时把快递送到，被邻里称赞「说话算数」。\n【材料三】《中华人民共和国民法典》规定，民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·维护社会秩序（第4—5课：遵守社会规则 · 社会生活讲道德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-2"},{"t":"专题精讲 · 第6课 提升法治素养（6.1 树立法治观念 · 6.2 学会依法办事）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-2-m1-q2","type":"short","stem":"（2）结合材料二、材料三，说明为什么必须讲诚信，以及怎样做一个诚实守信的人。（4 分）","answer":"为什么：①诚信就是诚实、守信用，是社会主义核心价值观在公民个人层面的一个价值准则，是一种道德规范和品质，是中华民族的传统美德，也是一项民法原则。②诚信是一个人安身立命之本：小林失信于人，会失去同学的信任；小雅言而有信，赢得邻里的称赞与尊重。③诚信是企业的无形资产，能够促进社会文明、国家兴旺；《民法典》要求民事主体从事民事活动应当遵循诚信原则，说明诚信不仅是道德要求，也是法律要求。怎样做：①树立诚信意识，说老实话、办老实事、做老实人，答应别人的事就要努力做到。②运用诚信智慧，当尊重他人隐私与对人诚实发生冲突时，权衡利弊、作出正确选择。③珍惜个人的诚信记录，守信者处处受益、失信者处处受限。","explain":"","tags":["诚信","道德与法律","做法建议"],"rubric":["答出诚信的含义（诚实、守信用）及其准则与规范地位","答出诚信对个人、企业、社会国家的意义","结合材料二、材料三的具体情境（失信与守信、诚信原则）","答出树立诚信意识","答出运用诚信智慧、珍惜个人诚信记录"]},{"id":"pol-moral-2-m1-q3","type":"short","stem":"（3）材料一中「只是抢了几秒钟」，材料二中「一本书而已，同学之间不必当真」，都是把守规则、讲诚信当作「小事」。请运用所学知识，说明为什么「小事」也不能这样做。（2 分）","answer":"①社会规则划定了自由的边界，也是人们享有自由的保障；越过边界的行为会危害他人和社会利益，不会因为「事小」而改变其性质。②诚信是一个人安身立命之本，小事上的失信会损害个人信誉，久而久之失去他人的信任与尊重。③我们要发自内心地敬畏规则，从小事做起、从自身做起，把规则和诚信要求内化于心、外化于行。","explain":"","tags":["规则意识","诚信","综合评析"],"rubric":["答出规则划定了自由的边界（或小事也会危害他人和社会利益）","答出诚信是安身立命之本、失信会损害个人信誉","答出从小事做起、敬畏规则，把要求内化于心、外化于行"]},{"id":"pol-moral-2-q1","type":"choice","stem":"关于社会规则与自由的关系，下列说法正确的是","answer":"D","explain":"自由与规则不可分：规则划定了自由的边界，也是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界。A 项把二者对立；B 项否认自由的边界；C 项混淆了社会规则的种类，道德、纪律同样是必须遵守的规则。","options":["社会规则限制了自由，二者是对立的","自由就是不受任何约束，想做什么就做什么","只要不违反法律，就可以不受道德和纪律的约束","社会规则划定了自由的边界，是人们享有自由的保障"],"difficulty":1,"tags":["自由与规则"]},{"id":"pol-moral-2-q4","type":"choice","stem":"下列关于诚信的说法，正确的是","answer":"B","explain":"诚信既是社会主义核心价值观在公民个人层面的一个价值准则，也是一种道德规范和品质，是中华民族的传统美德，是一项民法原则，是一个人安身立命之本。A 项否认其法律意义；C 项忽略了运用诚信智慧；D 项错误，珍惜个人诚信记录对每个人都有意义。","options":["诚信只是一种道德要求，与法律毫无关系","诚信是社会主义核心价值观在公民个人层面的一个价值准则，也是一项民法原则","讲诚信就要在任何情况下都如实相告，不能有任何例外","个人诚信记录只会对成年人产生影响"],"difficulty":2,"tags":["诚信"]},{"id":"pol-moral-2-q6","type":"choice","stem":"「礼体现一个人的尊重、谦让、与人为善等良好品质。」做文明有礼的人，应当","answer":"A","explain":"做文明有礼的人，要态度谦和、用语文明，仪表整洁、举止端庄，并在社会生活中不断学习、观察、思考和践行。B 项把文明有礼当成场合性表演；C 项是没有原则的允诺，与「礼」是内在修养的外在表现不符；D 项否认了礼与内在修养的联系。","options":["态度谦和、用语文明，仪表整洁、举止端庄","只在正式场合讲礼貌，在熟人面前不必讲究","为了显得有礼，凡事先答应别人再说","认为讲礼貌是客套，与自身的修养无关"],"difficulty":2,"tags":["文明有礼"]},{"id":"pol-moral-2-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 社会秩序是社会生活的一种有序化状态；社会正常运行需要秩序，社会秩序是人民安居乐业…\n② 自由与规则不可分：自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规…\n③ 自觉遵守规则，既需要他律，也需要自律：他律是来自外部的约束与监督，自律是发自内心…\n④ 认为社会规则限制了自由，规则与自由是对立的。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的辨析题。凡遇「我的自由别人管不着」「规则太麻烦」一类观点，都要先答「自由与规则不可分」，再指出越界行为会损害他人和社会利益，最后落到他律与自律；正确表述应为：自由与规则不可分：自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；社会规则划定了自由的边界，社会规则是人们享有自由的保障，建立规则的目的不是限制自由，而是保证每个人不越过自由的边界。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第二单元·维护社会秩序（第4—5课：遵守社会规则 · 社会生活讲道德）"]}]},{"id":"cat-pol-8a-2-3","title":"第6课 提升法治素养","subtitle":"八年级上册 · 第二单元 维护社会秩序","grade":"8a","tags":["八年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第二单元 维护社会秩序"},{"k":"课题","v":"第6课 提升法治素养"},{"k":"框题","v":"树立法治意识 / 学会依法办事"}]},{"type":"note","title":"本课在单元中的位置","text":"社会秩序需要社会规则来维护，自由与规则不可分——规则划定了自由的边界，也是人们享有自由的保障，遵守规则既靠他律也靠自律，还要维护规则、改进规则；在社会生活中，尊重是交往的起点，文明有礼是立身处世的前提，诚信是安身立命之本，三者共同构成社会生活的基本道德要求。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["树立法治意识","学会依法办事"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"树立法治观念，要敬畏和信仰法律：敬畏法律规则，相信法律的力量，自觉自愿遵守法律，把依法办事当成生活习惯。","explain":"这是「怎样树立法治观念」的第一条，设问常把它与「积极主动地学习法律」「树立守法光荣、违法可耻的观念」合在一起考，三点缺一不可。踩分点关键词是「敬畏法律规则」「相信法律的力量」「自觉自愿」「把依法办事当成生活习惯」；只写「要遵纪守法」过于笼统，拿不到分。"},{"level":"重点","text":"法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从。法律的权威源自人民的内心拥护和真诚信仰。坚持宪法法律至上，牢固树立法律红线不能触碰、法律底线不可逾越的观念。","explain":"「发自内心的认可、崇尚、遵守和服从」「法律的权威源自人民的内心拥护和真诚信仰」是教材原话，答「法治观念的内涵」必须原样写出，换成「知道法律」「害怕被处罚」都不得分。「法律红线不能触碰、法律底线不可逾越」中的两个否定词不能改成「尽量不」「最好不」。凡出现「法不责众」「偶尔越线没关系」的选项，一律判错。"},{"level":"重点","text":"树立法治观念，要积极主动地学习法律：学习个人成长和参与社会生活必备的基本法律常识，正确理解法律；积极参与各种法治实践活动，理性分析社会生活中的法律问题，提升维护自身合法权益、参与社会生活的能力。","explain":"命题常以模拟法庭、法治讲座、法治宣传进社区、以案说法为背景，设问「参加这些活动有什么意义」。作答按两层：一是学习个人成长和参与社会生活必备的基本法律常识，正确理解法律；二是在法治实践活动中理性分析社会生活中的法律问题，提升维护自身合法权益、参与社会生活的能力。落脚点必须落在「能力」上，不能只写「增长见识」「开阔眼界」这类非教材表述。"},{"level":"重点","text":"树立法治观念，要树立守法光荣、违法可耻的观念：从细节抓起、从小事做起、从遵守规则做起，如遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间；自觉践行社会主义核心价值观，自觉履行法定义务、社会责任、家庭责任。","explain":"材料题爱用「闯红灯、乱扔垃圾、攀比浪费、在班级群里转发不实消息」这类看似很小的情境设问，答案要从「这是小事」上升到「守法光荣、违法可耻的观念」和「从细节抓起、从小事做起、从遵守规则做起」，再落到自觉践行社会主义核心价值观、自觉履行法定义务、社会责任、家庭责任。举例只举教材里的四个例子：遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间。"},{"level":"次重点","text":"学会依法办事，要自觉守法：经常想一想自己的行为是否合法、违反法律会有什么后果，行动上以法律为准绳。遵守宪法和法律是公民的一项基本义务。","explain":"辨析题常把「我没有违法，所以我已经做到了自觉守法」当作错误观点来考：自觉守法不是消极地不违法，而是经常想一想自己的行为是否合法、违反法律会有什么后果，行动上以法律为准绳。设问涉及义务时必须写出「遵守宪法和法律是公民的一项基本义务」，这一句是固定表述，不能写成「公民的权利」。"},{"level":"次重点","text":"学会依法办事，遇事要找法：遇到法律问题或者合法权益受到侵害时，主动咨询相关专业人士，利用人民调解委员会、律师事务所、公证处、法律援助中心、法律服务所等法律服务机构获得及时有效的法律帮助。","explain":"选择题高频考「遇到什么事该找谁」：民间纠纷的化解找人民调解委员会；需要专业意见、代理诉讼找律师事务所；需要证明与保全证据等公证服务找公证处；经济困难又需要法律帮助的找法律援助中心；需要一般性法律咨询、代写法律文书的找法律服务所。答题格式是「机构名称 + 它能提供什么帮助」，只写机构名称拿不到全分。题干若出现「叫上朋友上门讨说法」「把对方的个人信息发到网上」，都是错误做法。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从；法律的权威源自人民的内心拥护和真诚信仰。","敬畏法律规则，相信法律的力量，自觉自愿遵守法律，把依法办事当成生活习惯。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为树立法治观念就是把法律条文背下来，谁记住的法律知识多，谁的法治观念就强。","法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从，法律的权威源自人民的内心拥护和真诚信仰。懂得一定的法律知识是前提，但只有敬畏和信仰法律、以法律为行为准则、把依法办事当成生活习惯，才叫真正树立了法治观念。","这是本课最典型的辨析题陷阱：把「知法」等同于「信法」「守法」。判断时先指出二者不能等同，再说明法治观念是发自内心的认可、崇尚、遵守和服从，最后落到「把法律知识转化为依法办事的行动」，并用「敬畏和信仰法律、积极主动地学习法律、树立守法光荣违法可耻的观念」三点收束。"],["认为自己从来不违法，「自觉守法」这一条已经做到了，用不着再想什么法律问题。","自觉守法不是消极地不违法，而是经常想一想自己的行为是否合法、违反法律会有什么后果，行动上以法律为准绳；遵守宪法和法律是公民的一项基本义务。","「不违法」只是行为的底线，不等于有法治观念、会依法办事。辨析时要把「消极守法」与「自觉守法」分开：前者是被动地怕被处罚，后者是主动地用法律衡量自己的行为，并把依法办事当成生活习惯。"],["认为遵守交通规则、做好垃圾分类、杜绝餐饮浪费这些只是生活小事，与法治观念没有关系。","树立守法光荣、违法可耻的观念，要从细节抓起、从小事做起、从遵守规则做起，遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间都是具体的表现；还要自觉践行社会主义核心价值观，自觉履行法定义务、社会责任、家庭责任。","材料题常拿「看似很小的行为」作素材，考的就是「小事与法治观念的关系」。正确答法是把小事上升到规则意识和法治观念：遵守规则是从细节抓起的表现，守法光荣、违法可耻的观念正体现在这些日常行为中，不能写成「小事不影响法治」。"]]},{"type":"table","title":"法治观念与法律知识（「有法治观念」和「知道法律知识」不是一回事）（本单元概念对比）","head":["比较项","法治观念","法律知识"],"rows":[["内涵","人们对法律发自内心的认可、崇尚、遵守和服从","对法律规定、法律制度的了解和记忆"],["怎么形成","在敬畏和信仰法律、积极主动地学习法律、参与法治实践活动的过程中逐步树立","主要通过课堂学习、阅读和识记获得"],["行为上的表现","以法律为行为准则，依照法律行使权利、履行义务，把依法办事当成生活习惯","能说出、能判断，但不一定用来约束自己的行为"],["二者关系","法治观念以一定的法律知识为前提，但背熟条文不等于树立了法治观念","同左：知识是基础，观念才是把知识变成行动的关键"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与规则的关系","给「抢几秒钟不算什么」「在小区里怎么养犬是我的自由」等观点，要求评析。作答结构：先判断观点错误，再答「自由不是随心所欲，受道德、纪律、法律等社会规则的约束」与「规则划定了自由的边界，是人们享有自由的保障」，最后落到「遵守规则既需要他律也需要自律」。"],["道德类：尊重、文明有礼、诚信的情境分析","以校园、社区、网络交往中的具体情境考查「为什么讲道德、怎样讲道德」。尊重题答四点做法（关注重视、平等对待、换位思考、欣赏他人）；文明有礼题答「立身处世的前提—促进社会和谐—体现国家形象」；诚信题答「诚信的重要性 + 树立诚信意识、运用诚信智慧、珍惜个人诚信记录」。"],["规则改进类：规则不是一成不变的","以某项规定修订（借阅规则、交通管理规定、社区公约、班级公约）为材料，设问「这说明了什么」「我们应怎样对待规则」。要点：规则明确社会秩序的内容、保障社会秩序的实现；规则不是一成不变的，要积极为新规则的形成建言献策，同时自觉遵守现行规则。"],["关系类设问：用规范表述回答「秩序、规则、自由是什么关系」","这是道法材料题最稳定的题型。答案必须出现教材原话式术语：社会规则明确社会秩序的内容、保障社会秩序的实现；社会规则划定了自由的边界，是人们享有自由的保障。用自己的话概括不得分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·维护社会秩序（第4—5课：遵守社会规则 · 社会生活讲道德）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-2"},{"t":"专题精讲 · 第6课 提升法治素养（6.1 树立法治观念 · 6.2 学会依法办事）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-6-m1-q1","type":"short","stem":"（1）结合材料一，说明小睿的做法体现了依法办事的哪些要求。（4 分）","answer":"①自觉守法：他懂得凡是先让交钱的网络兼职都要提高警惕，说明他能在法律范围内活动，以法律为行为准则，依照法律行使权利、履行义务，不轻信、不越线。②遇事找法：遇到法律问题，他没有私下再去找对方「理论」，而是把情况告诉父母，并在父母陪同下去派出所报案，主动寻求专业人士和国家机关的帮助。③解决问题靠法：他保存聊天记录和转账凭证，以合法方式表达诉求，依法到公安机关控告、举报，寻求国家的法律救济。④这启示我们，合法权益受到侵害时要及时寻求法律帮助、依法维护自身权益，而不能用违法手段去解决问题。","explain":"","tags":["依法办事","遇事找法","材料分析"],"rubric":["答出自觉守法：在法律范围内活动，警惕并远离骗局（或增强自我保护意识）","答出遇事找法：主动咨询专业人士，在父母陪同下向公安机关报案","答出解决问题靠法：保存证据、以合法方式表达诉求、依法控告举报、寻求国家的法律救济","答出不能以违法手段维护权益，要依法维护自身合法权益"]},{"id":"pol-moral-6-m1-q3","type":"short","stem":"（3）结合三则材料，说明为什么说「法律的权威源自人民的内心拥护和真诚信仰」，并谈谈青少年应当怎样树立法治观念。（4 分）","answer":"①法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从，法律的权威源自人民的内心拥护和真诚信仰——只有从内心信仰法律，人们才会自觉自愿地遵守法律、把依法办事当成生活习惯。②三则材料中的当事人遇到问题都选择走法律途径，正是因为他们相信法律的力量，坚持法律红线不能触碰、法律底线不可逾越。③树立法治观念，要敬畏和信仰法律：敬畏法律规则，相信法律的力量，自觉自愿遵守法律，把依法办事当成生活习惯。④要积极主动地学习法律：学习个人成长和参与社会生活必备的基本法律常识，正确理解法律；积极参与各种法治实践活动，理性分析社会生活中的法律问题，提升维护自身合法权益、参与社会生活的能力。⑤要树立守法光荣、违法可耻的观念：从细节抓起、从小事做起、从遵守规则做起，如遵守交通规则、做好垃圾分类、杜绝餐饮浪费、营造清朗网络空间，自觉践行社会主义核心价值观，自觉履行法定义务、社会责任、家庭责任。","explain":"","tags":["法治观念","树立法治观念的做法","材料分析"],"rubric":["答出法治观念的内涵（发自内心的认可、崇尚、遵守和服从）或「法律的权威源自人民的内心拥护和真诚信仰」","答出敬畏和信仰法律：敬畏法律规则、相信法律的力量、把依法办事当成生活习惯","答出积极主动地学习法律：学习必备的法律常识、参与法治实践活动、提升相关能力","答出树立守法光荣、违法可耻的观念：从细节抓起、从小事做起、从遵守规则做起，践行社会主义核心价值观，履行法定义务、社会责任、家庭责任"]},{"id":"pol-moral-6-q2","type":"choice","stem":"「法律的权威源自人民的内心拥护和真诚信仰。」下列对这句话的理解，正确的是","answer":"A","explain":"法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从，法律的权威源自人民的内心拥护和真诚信仰，A 项表述正确。B 项混淆了法律知识与法治观念：背熟条文只是前提，关键是以法律为行为准则、把依法办事当成生活习惯。C 项把观念与行动割裂开来，法治观念最终要落到依法办事上。D 项与「牢固树立法律红线不能触碰、法律底线不可逾越的观念」正好相反。","options":["法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从","只要把法律条文背熟，就等于树立了法治观念","法治观念属于个人修养，与平时是否依法办事没有关系","树立法治观念意味着法律红线可以偶尔逾越，只要不被发现"],"difficulty":2,"tags":["法治观念的内涵"]},{"id":"pol-moral-6-q3","type":"choice","stem":"树立法治观念，下列同学的做法正确的是","answer":"D","explain":"树立法治观念要敬畏和信仰法律，敬畏法律规则、相信法律的力量、自觉自愿遵守法律，把依法办事当成生活习惯，D 项符合这一要求。A 项把遵守交通规则这类小事与法律割裂开，忘记了树立守法光荣、违法可耻的观念要「从细节抓起、从小事做起、从遵守规则做起」；B 项把学习法律当成应考的手段，没有积极主动地学习法律；C 项混淆了学法的年龄，青少年更需要在成长中学习必备的法律常识。","options":["小强认为闯红灯、乱扔垃圾只是生活小事，与法律没有关系","小美觉得法律知识枯燥，只在考试前背一背，平时并不关心","小刚认为守法是大人的事，等长大以后再学法律也不迟","小亮敬畏法律规则，相信法律的力量，自觉自愿遵守法律，把依法办事当成生活习惯"],"difficulty":1,"tags":["敬畏和信仰法律","树立法治观念"]},{"id":"pol-moral-6-q6","type":"choice","stem":"下列同学的做法，属于依法办事的是","answer":"C","explain":"依法办事要求自觉守法、遇事找法、解决问题靠法，小强保存证据、咨询律师、依法提起诉讼，符合这一要求。A 项和 D 项都是自己找人「讨说法」式的私力报复，行为本身就违法，还要承担相应的法律责任。B 项认为「法不责众」，恰恰是缺乏法治观念的表现：转发未经核实的消息可能扰乱社会秩序，同样要承担法律责任，不能拿「大家都在转」当理由。","options":["小刚被同学撞倒擦伤后，叫上几个朋友把对方堵在楼道里「讨说法」","小丽觉得「法不责众」，跟着别人在网络上转发未经核实的消息","小强发现自己的照片被某商家擅自用于广告宣传，他保存好证据、咨询律师，必要时向人民法院提起诉讼","小华买到过期食品，为了出气把商店货架上的商品推倒"],"difficulty":1,"tags":["依法办事","自觉守法"]},{"id":"pol-moral-6-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 法律是一种社会规则和行为规范，是评价人们的行为是否合法有效的准绳。我们必须在法律…\n② 法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从。法律的权威源自人民的内…\n③ 树立法治观念，要敬畏和信仰法律：敬畏法律规则，相信法律的力量，自觉自愿遵守法律，…\n④ 认为树立法治观念就是把法律条文背下来，谁记住的法律知识多，谁的法治观念就强。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本课最典型的辨析题陷阱：把「知法」等同于「信法」「守法」。判断时先指出二者不能等同，再说明法治观念是发自内心的认可、崇尚、遵守和服从，最后落到「把法律知识转化为依法办事的行动」，并用「敬畏和信仰法律、积极主动地学习法律、树立守法光荣违法可耻的观念」三点收束；正确表述应为：法治观念体现为人们对法律发自内心的认可、崇尚、遵守和服从，法律的权威源自人民的内心拥护和真诚信仰。懂得一定的法律知识是前提，但只有敬畏和信仰法律、以法律为行为准则、把依法办事当成生活习惯，才叫真正树立了法治观念。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第6课 提升法治素养（6.1 树立法治观念 · 6.2 学会依法办事）"]}]},{"id":"cat-pol-8a-3-1","title":"第7课 追求自由平等","subtitle":"八年级上册 · 第三单元 勇担社会责任","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 勇担社会责任"},{"k":"课题","v":"第7课 追求自由平等"},{"k":"框题","v":"珍视自由 / 践行平等"}]},{"type":"note","title":"本课在单元中的位置","text":"自由不是随心所欲，它受道德、纪律、法律等社会规则的约束，法治既规范自由又保障自由；平等有两层含义——同等情况同等对待、不同情况差别对待，我国宪法规定「中华人民共和国公民在法律面前一律平等」。公平是个人生存和发展的重要保障、社会稳定和进步的重要基础，正义是社会文明的尺度，制度的生命在于正义。自由平等、公平正义不会自动实现，需要个人守护、制度保障、司法维护，也需要每个公民抵制特权与不平等、敢于并善于同非正义行为作斗争。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["珍视自由","践行平等"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"践行平等，就要反对特权：特权是平等的大敌；就要平等对待他人的合法权利，尊重他人的合法权益；就要敢于抵制不平等的行为，对不平等的行为说「不」。珍视自由，就要珍惜宪法和法律赋予我们的权利，自觉依法行使权利。","explain":"反特权是「践行平等」的第一条，材料题若出现「利用职务或关系搞特殊」，必须写「特权是平等的大敌」。珍视自由的两句常被漏答，答题时把「珍惜宪法和法律赋予的权利」「依法行使权利」一起写。"},{"level":"了解","text":"实现公平正义，是国家、社会和全体公民的共同责任；自由平等、公平正义是社会主义核心价值观在社会层面的价值取向。","explain":"用于材料题最后一问的收束句，也用于「为什么要维护公平正义」这类宏观设问。把「自由、平等、公正、法治」这一社会层面的价值取向点出来，比只喊「要公平」有分量。"},{"level":"重点","text":"自由主要指人们在法律规定的范围内，依照自己意志活动的权利。自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；自由是有限制的、相对的，必要的限制是对自由的保护。法治既规范自由又保障自由：社会生活中，有边界才有秩序，守底线才享自由。","explain":"这一条是把本册第4课「自由与规则」提升到法治层面，辨析题的必答句。三个固定表述要背死：自由是有限制的、相对的；必要的限制是对自由的保护；法治既规范自由又保障自由。凡出现「自由就是不受任何限制」「法治与自由是对立的」，都按这三句逐层批驳。"},{"level":"重点","text":"平等有两层含义：一是同等情况同等对待，如男女同工同酬、一次选举一人一票；二是不同情况差别对待，如老人、儿童、孕妇、残疾人在乘坐公共交通工具时应获得优先权和得到特殊关照。","explain":"选择题最爱考「哪一种做法属于不同情况差别对待」：给老人让座、设无障碍通道、对低收入家庭给予救助属于差别对待，而「同样情况不同待遇」「按关系远近分配机会」则是违背平等。答题必须写清「两层含义」，只写「人人一样」就把平等的第二层丢了。"},{"level":"重点","text":"我国宪法规定：「中华人民共和国公民在法律面前一律平等。」法律面前人人平等，是社会文明进步的标志，也是社会主义法治的基本原则之一。","explain":"这是本课唯一的宪法条文原文，也是最不能写错的一句：是「公民在法律面前一律平等」，不是「公民在法律上平等」，也不是「人人绝对平均」。常与「反对特权」一起考，凡出现「有特殊身份就可以不受约束」，一律答这一条。"},{"level":"重点","text":"公平通常指人们基于一定标准或原则，处理事情合情合理、不偏袒任何一方。公平有着丰富的内涵，包括权利公平、规则公平、机会公平：权利公平要求每个人依法平等参与社会活动，规则公平要求每个人都受到行为规范的约束，机会公平要求社会为每个人提供同等的发展机会和条件。公平是个人生存和发展的重要保障，是社会稳定和进步的重要基础。","explain":"材料题给「招聘中设置不合理门槛」「比赛规则因人而异」「教育资源分配」等情境，要求判别属于哪一类公平，再答公平的价值。作答要点：「权利公平—规则公平—机会公平」要与材料一一对应，最后落到「重要保障」「重要基础」两个固定搭配。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["自由不是随心所欲，它受道德、纪律、法律等社会规则的约束；自由是有限制的、相对的，必要的限制是对自由的保护。","法治既规范自由又保障自由：社会生活中，有边界才有秩序，守底线才享自由。","我国宪法规定：「中华人民共和国公民在法律面前一律平等。」","平等有两层含义：一是同等情况同等对待，二是不同情况差别对待。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把平等理解为「一切平均」「所有人完全一样」，认为对不同的人给予差别对待就是违背平等。","平等有两层含义：一是同等情况同等对待；二是不同情况差别对待。对老人、儿童、孕妇、残疾人等给予优先和特殊关照，属于不同情况差别对待，是平等的应有之义，而不是违背平等。","材料题常设「给老人让座是不是不平等」「无障碍设施是不是特权」这样的问题。答题必须先写平等的两层含义，再指出「平均」与「平等」的区别：平等是同等对待与合理差别对待的统一。"],["认为自由就是想做什么就做什么，法律和规则限制了自由，二者是对立的。","自由主要指人们在法律规定的范围内，依照自己意志活动的权利；自由是有限制的、相对的，必要的限制是对自由的保护；法治既规范自由又保障自由，有边界才有秩序，守底线才享自由。","这是本课最高频的辨析题，也与本册第4课「自由与规则不可分」直接打通。答题要把「有限制」「相对」「必要的限制是对自由的保护」「法治既规范自由又保障自由」四层写全，只写「要遵守法律」拿不到满分。"],["认为公平就是「每个人分到的一样多」。","公平通常指人们基于一定标准或原则，处理事情合情合理、不偏袒任何一方；公平包括权利公平、规则公平、机会公平，强调的是依法平等参与、受到同样的规范约束、获得同等的发展机会，而不是简单平均。","选择题常把「平均分配」当作公平的干扰项。判断的关键是有没有统一的标准和原则、有没有偏袒任何一方；「多劳多得」同样体现公平。"]]},{"type":"table","title":"自由与法治（一对看似矛盾实则统一的关系：边界与保障）（本单元概念对比）","head":["比较项","自由","法治"],"rows":[["含义","人们在法律规定的范围内，依照自己意志活动的权利","依法治理国家与社会，法律至上、良法之治"],["是否有边界","自由是有限制的、相对的，不受约束的自由并不存在","划定了自由的边界，明确了自由的底线"],["对另一方的作用","自由是法治的价值追求，法治为了保障自由","法治既规范自由又保障自由"],["常见错误理解","把自由当成随心所欲、想做什么就做什么","把法治当成限制自由、与自由对立"],["共同结论","有边界才有秩序，守底线才享自由","同左：必要的限制是对自由的保护"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与法治、平等与平均","给「自由就是不受任何限制」「给老人让座是不平等」一类观点要求评析。自由题按「自由是有限制的、相对的—必要的限制是对自由的保护—法治既规范自由又保障自由」三层作答；平等题必须先写平等的两层含义，再指出合理差别对待不违背平等。"],["判断类：公平的内涵与保障方式","给招聘设门槛、比赛规则因人而异、公共资源分配等情境，要求判断涉及权利公平、规则公平还是机会公平，并说明公平的价值。作答要「术语 + 材料」并列，最后落到「个人守护—制度保障—司法维护」三方面。"],["做法建议类：中学生怎样守护公平正义","设问常写「作为中学生，你打算怎样守护公平正义」。作答要点：坚守公平，以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段；守护正义要有勇气和智慧、讲究策略；反对特权、平等对待他人、敢于抵制不平等的行为；相信并支持制度保障与司法维护。"],["宪法条文类：法律面前人人平等","直接考「中华人民共和国公民在法律面前一律平等」这一宪法规定的含义与落实：既包括同等情况同等对待，也包括不同情况差别对待；既反对特权，也反对歧视。此类设问要求表述准确，改写宪法原句会失分。"]]},{"type":"quote","text":"【材料一】某企业在招聘公告中写明「本岗位仅限男性」，求职者小吴认为这一要求与自己能否胜任工作无关，向有关部门反映后，该企业被责令改正招聘公告。\n【材料二】某市在推进老旧小区改造时，专门为独居老人和残疾居民加装扶手、修建无障碍坡道，并在分配小区临时停车位时优先照顾残疾人家庭。\n【材料三】我国宪法规定，中华人民共和国公民在法律面前一律平等。我国劳动法律规定，劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·追求自由平等·维护公平正义（第7—8课：自由平等的真谛与追求 · 公平正义的守护）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-7"},{"t":"专题精讲 · 第9课 积极奉献社会（责任与角色同在 · 关爱他人 · 服务社会）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-7-m1-q1","type":"short","stem":"（1）结合材料一，运用平等的相关知识，评析该企业「仅限男性」的做法。（4 分）","answer":"该企业的做法违背了平等原则，是错误的。①我国宪法规定：「中华人民共和国公民在法律面前一律平等。」平等有两层含义：一是同等情况同等对待，二是不同情况差别对待。劳动者的性别与能否胜任该岗位无关，属于「同等情况」，应当同等对待。②该企业以性别为由拒绝求职者，属于就业歧视，违背了平等原则，也违反了我国劳动法律关于劳动者就业不因民族、种族、性别、宗教信仰不同而受歧视的规定。③践行平等就要平等对待他人的合法权利，敢于抵制不平等的行为；面对这类不平等行为，小吴向有关部门反映，是依法维护自身合法权益、抵制不平等行为的正确做法。④企业应当依法改正，公平地对待每一位求职者，保障每个人的权利公平与机会公平。","explain":"","tags":["平等","反对歧视","评析题"],"rubric":["作出判断：该企业做法违背平等原则（错误）","引用「中华人民共和国公民在法律面前一律平等」或写出平等的两层含义","指出以性别为由拒绝求职者属于就业歧视、违反法律规定","答出践行平等要平等对待他人的合法权利、敢于抵制不平等的行为","结合材料说明企业应当依法改正、保障权利公平与机会公平"]},{"id":"pol-moral-7-m1-q2","type":"short","stem":"（2）结合材料二，说明为独居老人和残疾人提供特殊照顾是否违背平等原则，并说明理由。（3 分）","answer":"不违背平等原则。①平等有两层含义：一是同等情况同等对待，二是不同情况差别对待。②独居老人和残疾居民在出行、生活自理等方面面临的困难与一般居民不同，属于「不同情况」，给予与他们的情况相适应的特殊照顾，正是不同情况差别对待的体现。③这种差别对待是为了让每个人都能平等地参与社会生活、共享发展成果，维护的是权利公平与机会公平，与「特权」有本质区别——特权是平等的大敌，而合理的差别对待恰恰是实现实质平等的必要措施。","explain":"","tags":["平等的两层含义","差别对待","辨析"],"rubric":["明确回答不违背平等原则","写出平等的两层含义（同等情况同等对待、不同情况差别对待）","说明老人、残疾人的情况不同，特殊照顾属于不同情况差别对待","答出这种做法有利于实现权利公平、机会公平（或与特权有本质区别）"]},{"id":"pol-moral-7-q1","type":"choice","stem":"关于自由与法治的关系，下列说法正确的是","answer":"B","explain":"自由主要指人们在法律规定的范围内，依照自己意志活动的权利，自由是有限制的、相对的，必要的限制是对自由的保护，法治既规范自由又保障自由。A 项把法治与自由对立；C 项忽视了道德、纪律等社会规则的约束；D 项颠倒了「必要的限制是对自由的保护」这一结论。","options":["自由就是不受任何限制，法治是对自由的否定","法治既规范自由又保障自由，社会生活中，有边界才有秩序，守底线才享自由","只要法律没有明文禁止，就可以不顾道德和纪律为所欲为","必要的限制是对自由的侵犯，应当尽可能取消各种限制"],"difficulty":1,"tags":["自由与法治"]},{"id":"pol-moral-7-q2","type":"choice","stem":"下列做法体现「不同情况差别对待」的是","answer":"C","explain":"平等有两层含义：一是同等情况同等对待，二是不同情况差别对待。老人、儿童、孕妇、残疾人在乘坐公共交通工具时应获得优先权和得到特殊关照，属于后者。A 项与工作能力无关的性别限制是就业歧视；B 项按关系亲疏分配名额是违背规则公平；D 项为个别考生降低标准破坏了规则的统一约束，都不是平等。","options":["某招聘单位规定「本岗位仅限男性」","某班按与班主任关系的亲疏分配三好学生名额","公共交通工具上设置爱心专座，供老弱病残孕乘客优先使用","同一场考试中，为个别考生单独降低评分标准"],"difficulty":2,"tags":["平等的两层含义"]},{"id":"pol-moral-7-q3","type":"choice","stem":"关于法律面前人人平等，下列说法正确的是","answer":"A","explain":"我国宪法规定：「中华人民共和国公民在法律面前一律平等。」法律面前人人平等是社会文明进步的标志，也是社会主义法治的基本原则之一。B 项把平等等同于平均；C 项正是特权思想，而特权是平等的大敌；D 项漏掉了平等的第二层含义——不同情况差别对待。","options":["我国宪法规定，中华人民共和国公民在法律面前一律平等","法律面前人人平等意味着所有人获得的财富必须一样多","有特殊身份的人可以不受法律的约束","法律面前人人平等只要求同等情况同等对待，不包括差别对待"],"difficulty":1,"tags":["法律面前人人平等","宪法规定"]},{"id":"pol-moral-7-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 自由主要指人们在法律规定的范围内，依照自己意志活动的权利。自由不是随心所欲，它受…\n② 平等有两层含义：一是同等情况同等对待，如男女同工同酬、一次选举一人一票；二是不同…\n③ 我国宪法规定：「中华人民共和国公民在法律面前一律平等。」法律面前人人平等，是社会…\n④ 把平等理解为「一切平均」「所有人完全一样」，认为对不同的人给予差别对待就是违背平…","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——材料题常设「给老人让座是不是不平等」「无障碍设施是不是特权」这样的问题。答题必须先写平等的两层含义，再指出「平均」与「平等」的区别：平等是同等对待与合理差别对待的统一；正确表述应为：平等有两层含义：一是同等情况同等对待；二是不同情况差别对待。对老人、儿童、孕妇、残疾人等给予优先和特殊关照，属于不同情况差别对待，是平等的应有之义，而不是违背平等。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·追求自由平等·维护公平正义（第7—8课：自由平等的真谛与追求 · 公平正义的守护）"]}]},{"id":"cat-pol-8a-3-2","title":"第8课 维护公平正义","subtitle":"八年级上册 · 第三单元 勇担社会责任","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 勇担社会责任"},{"k":"课题","v":"第8课 维护公平正义"},{"k":"框题","v":"坚守公平 / 守护正义"}]},{"type":"note","title":"本课在单元中的位置","text":"自由不是随心所欲，它受道德、纪律、法律等社会规则的约束，法治既规范自由又保障自由；平等有两层含义——同等情况同等对待、不同情况差别对待，我国宪法规定「中华人民共和国公民在法律面前一律平等」。公平是个人生存和发展的重要保障、社会稳定和进步的重要基础，正义是社会文明的尺度，制度的生命在于正义。自由平等、公平正义不会自动实现，需要个人守护、制度保障、司法维护，也需要每个公民抵制特权与不平等、敢于并善于同非正义行为作斗争。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["坚守公平","守护正义"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"守护公平正义是每个公民的责任：个人要坚守公平，以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段，谋求最大限度的公平；守护正义需要勇气和智慧，面对非正义行为，一方面要敢于斗争，另一方面要讲究策略，寻求有效方法。","explain":"做法类设问的主力答案。注意两个层次不能混：坚守公平讲「原则立场 + 合理合法的方式和手段」，守护正义讲「勇气 + 智慧（讲究策略）」。写「见到坏人坏事就冲上去」不给分，体现不出「讲究策略」。"},{"level":"次重点","text":"公平正义需要制度保障、司法维护：对于立法而言，在规定权利义务、分配社会资源时，要公平地对待每个人，保障每个人得到他应得的；对于司法而言，在解决纠纷、化解矛盾时，要公平地对待当事人，切实维护其合法权益。司法是捍卫社会公平正义的最后一道防线，要求司法机关依法独立公正行使司法权，坚持以事实为根据、以法律为准绳，严格遵循诉讼程序，平等对待当事人。","explain":"设问若写「公平正义怎样才能实现」，就要从「个人守护—制度保障—司法维护」三个层面作答。最高频的一句是「司法是捍卫社会公平正义的最后一道防线」，「以事实为根据、以法律为准绳」是司法机关办案的基本要求，两句都不能改写。"},{"level":"了解","text":"实现公平正义，是国家、社会和全体公民的共同责任；自由平等、公平正义是社会主义核心价值观在社会层面的价值取向。","explain":"用于材料题最后一问的收束句，也用于「为什么要维护公平正义」这类宏观设问。把「自由、平等、公正、法治」这一社会层面的价值取向点出来，比只喊「要公平」有分量。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["司法是捍卫社会公平正义的最后一道防线。","公平是个人生存和发展的重要保障，是社会稳定和进步的重要基础；公平包括权利公平、规则公平、机会公平。","正义是社会文明的尺度；制度的生命在于正义，制度的效用在于保障正义。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为守护正义只要勇敢就够了，见到非正义行为必须立刻冲上去硬拼；或者认为维护公平正义只是司法机关的事。","守护正义需要勇气和智慧，面对非正义行为，一方面要敢于斗争，另一方面要讲究策略，寻求有效方法；实现公平正义是国家、社会和全体公民的共同责任，需要个人守护、制度保障、司法维护共同发挥作用。","材料题常以未成年人制止违法行为受伤的情境设问，答案必须落在「有勇气也要有智慧、讲究策略」上，同时点出制度保障与司法维护，只答个人一面是不完整的。"],["认为公平就是「每个人分到的一样多」。","公平通常指人们基于一定标准或原则，处理事情合情合理、不偏袒任何一方；公平包括权利公平、规则公平、机会公平，强调的是依法平等参与、受到同样的规范约束、获得同等的发展机会，而不是简单平均。","选择题常把「平均分配」当作公平的干扰项。判断的关键是有没有统一的标准和原则、有没有偏袒任何一方；「多劳多得」同样体现公平。"]]},{"type":"table","title":"公平与正义（社会文明进步的两个尺度）（本单元概念对比）","head":["比较项","公平","正义"],"rows":[["含义","人们基于一定标准或原则，处理事情合情合理、不偏袒任何一方","有利于促进社会进步、维护公共利益的行为；是社会文明的尺度"],["内涵或要求","包括权利公平、规则公平、机会公平","是社会制度的重要价值，也是社会和谐的基本条件"],["价值","个人生存和发展的重要保障，社会稳定和进步的重要基础","制度的生命在于正义，制度的效用在于保障正义"],["个人怎样守护","以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段","敢于斗争并讲究策略，需要勇气和智慧"],["共同保障","制度保障公平：立法公平对待每个人，司法公平对待当事人","司法维护正义：司法是捍卫社会公平正义的最后一道防线"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与法治、平等与平均","给「自由就是不受任何限制」「给老人让座是不平等」一类观点要求评析。自由题按「自由是有限制的、相对的—必要的限制是对自由的保护—法治既规范自由又保障自由」三层作答；平等题必须先写平等的两层含义，再指出合理差别对待不违背平等。"],["判断类：公平的内涵与保障方式","给招聘设门槛、比赛规则因人而异、公共资源分配等情境，要求判断涉及权利公平、规则公平还是机会公平，并说明公平的价值。作答要「术语 + 材料」并列，最后落到「个人守护—制度保障—司法维护」三方面。"],["做法建议类：中学生怎样守护公平正义","设问常写「作为中学生，你打算怎样守护公平正义」。作答要点：坚守公平，以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段；守护正义要有勇气和智慧、讲究策略；反对特权、平等对待他人、敢于抵制不平等的行为；相信并支持制度保障与司法维护。"],["宪法条文类：法律面前人人平等","直接考「中华人民共和国公民在法律面前一律平等」这一宪法规定的含义与落实：既包括同等情况同等对待，也包括不同情况差别对待；既反对特权，也反对歧视。此类设问要求表述准确，改写宪法原句会失分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·追求自由平等·维护公平正义（第7—8课：自由平等的真谛与追求 · 公平正义的守护）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-7"},{"t":"专题精讲 · 第9课 积极奉献社会（责任与角色同在 · 关爱他人 · 服务社会）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-7-m1-q3","type":"short","stem":"（3）结合三则材料，谈谈青少年应当怎样践行平等、守护公平正义。（3 分）","answer":"①践行平等，就要反对特权，特权是平等的大敌；就要平等对待他人的合法权利，不因性别、民族、家庭条件等与他人无关的因素区别对待同学；就要敢于抵制不平等的行为，像小吴那样依法反映问题、对不平等说「不」。②坚守公平，要以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段，谋求最大限度的公平。③守护正义需要勇气和智慧，面对非正义行为，既要敢于斗争，又要讲究策略、寻求有效方法；同时要相信并支持制度保障与司法维护，司法是捍卫社会公平正义的最后一道防线。","explain":"","tags":["践行平等","守护公平正义","做法建议"],"rubric":["答出反对特权、平等对待他人的合法权利","答出敢于抵制不平等的行为，并结合材料一的做法","答出以公平之心为人处世、坚守原则立场、采用合理合法的方式和手段","答出守护正义要有勇气和智慧、讲究策略","答出制度保障与司法维护（或司法是最后一道防线）"]},{"id":"pol-moral-7-q4","type":"choice","stem":"某市在分配公共租赁住房时，公开摇号、统一排序规则，并向社会公示结果。这一做法主要体现了","answer":"A","explain":"公平包括权利公平、规则公平、机会公平：公开摇号、统一排序规则体现规则公平，使每个人依法平等参与、获得同等的发展机会，体现权利公平与机会公平。B 项把公平等同于平均；C 项误解了公平的含义；D 项否认规则对公平的保障作用。","options":["权利公平与机会公平","只要结果平均就是公平","公平就是让每个人都得到完全相同的住房","公平与规则无关，取决于运气"],"difficulty":2,"tags":["公平的内涵"]},{"id":"pol-moral-7-q5","type":"choice","stem":"「制度的生命在于正义，制度的效用在于保障正义。」对这句话理解正确的是","answer":"B","explain":"正义是社会制度的重要价值，制度的生命在于正义，制度的效用在于保障正义；正义是社会和谐的基本条件。A 项否认正义与制度的关系；C 项把制度的作用绝对化；D 项把正义等同于平均。","options":["正义只是一种道德要求，与制度无关","正义是社会制度的重要价值，制度应当保障每个人得到他应得的","只要建立了制度，社会就一定充满正义","正义就是让每个人都得到完全相同的结果"],"difficulty":2,"tags":["正义","制度与正义"]},{"id":"pol-moral-7-q6","type":"choice","stem":"放学路上，小华看到一名社会青年正在向低年级同学索要财物。下列做法最恰当的是","answer":"C","explain":"守护正义需要勇气和智慧，面对非正义行为，一方面要敢于斗争，另一方面要讲究策略、寻求有效方法。A 项缺乏自我保护意识；B 项是纵容非正义行为；D 项以违法手段「算账」，本身就可能违法，也不利于真正维护正义。","options":["立即冲上去与对方搏斗，把同学救出来","悄悄离开，当作没有看见","记住对方体貌特征，及时报告老师或拨打报警电话，并在保证自身安全的前提下帮助同学","事后叫上几个同学去找对方「算账」"],"difficulty":2,"tags":["守护正义","勇气与智慧"]},{"id":"pol-moral-7-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 自由主要指人们在法律规定的范围内，依照自己意志活动的权利。自由不是随心所欲，它受…\n② 平等有两层含义：一是同等情况同等对待，如男女同工同酬、一次选举一人一票；二是不同…\n③ 我国宪法规定：「中华人民共和国公民在法律面前一律平等。」法律面前人人平等，是社会…\n④ 把平等理解为「一切平均」「所有人完全一样」，认为对不同的人给予差别对待就是违背平…","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——材料题常设「给老人让座是不是不平等」「无障碍设施是不是特权」这样的问题。答题必须先写平等的两层含义，再指出「平均」与「平等」的区别：平等是同等对待与合理差别对待的统一；正确表述应为：平等有两层含义：一是同等情况同等对待；二是不同情况差别对待。对老人、儿童、孕妇、残疾人等给予优先和特殊关照，属于不同情况差别对待，是平等的应有之义，而不是违背平等。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·追求自由平等·维护公平正义（第7—8课：自由平等的真谛与追求 · 公平正义的守护）"]}]},{"id":"cat-pol-8a-3-3","title":"第9课 积极奉献社会","subtitle":"八年级上册 · 第三单元 勇担社会责任","grade":"8a","tags":["八年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第三单元 勇担社会责任"},{"k":"课题","v":"第9课 积极奉献社会"},{"k":"框题","v":"社会责任我担当 / 奉献社会我践行"}]},{"type":"note","title":"本课在单元中的位置","text":"自由不是随心所欲，它受道德、纪律、法律等社会规则的约束，法治既规范自由又保障自由；平等有两层含义——同等情况同等对待、不同情况差别对待，我国宪法规定「中华人民共和国公民在法律面前一律平等」。公平是个人生存和发展的重要保障、社会稳定和进步的重要基础，正义是社会文明的尺度，制度的生命在于正义。自由平等、公平正义不会自动实现，需要个人守护、制度保障、司法维护，也需要每个公民抵制特权与不平等、敢于并善于同非正义行为作斗争。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["社会责任我担当","奉献社会我践行"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"服务社会体现人生价值，能够促进我们全面发展：使我们的视野不断拓展、知识不断丰富、能力不断提高、道德境界不断提升。服务和奉献社会需要我们青年担当责任，积极参与社会公益活动与志愿服务。","explain":"设问「参加志愿服务有什么意义」，按「体现人生价值—促进全面发展（视野、知识、能力、道德境界）」两点作答，第二点常被漏掉。做法类则写「积极参与社会公益活动、志愿服务，从身边小事做起」。"},{"level":"重点","text":"守护公平正义是每个公民的责任：个人要坚守公平，以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段，谋求最大限度的公平；守护正义需要勇气和智慧，面对非正义行为，一方面要敢于斗争，另一方面要讲究策略，寻求有效方法。","explain":"做法类设问的主力答案。注意两个层次不能混：坚守公平讲「原则立场 + 合理合法的方式和手段」，守护正义讲「勇气 + 智慧（讲究策略）」。写「见到坏人坏事就冲上去」不给分，体现不出「讲究策略」。"},{"level":"了解","text":"实现公平正义，是国家、社会和全体公民的共同责任；自由平等、公平正义是社会主义核心价值观在社会层面的价值取向。","explain":"用于材料题最后一问的收束句，也用于「为什么要维护公平正义」这类宏观设问。把「自由、平等、公正、法治」这一社会层面的价值取向点出来，比只喊「要公平」有分量。"},{"level":"重点","text":"责任是一个人分内应该做的事情；责任来自对他人的承诺、职业要求、道德规范和法律规定等。","explain":"选择题给出「答应同学帮忙」「医生的职业操守」「法律规定子女要赡养父母」等情境，问「责任来自哪里」，要能一一对应到承诺、职业要求、道德规范、法律规定四类来源，一个也不能漏。"},{"level":"重点","text":"责任与角色同在：在社会生活中，每个人因不同的社会身份而承担不同的责任，每一种角色都意味着承担相应的责任。","explain":"常以「我在家庭中是子女、在学校是学生、在社区是居民」的角色表命题，要求填写对应责任。答题格式：作为（角色），我应当承担（具体责任）。责任要写具体行为，不能只写「做好自己」。"},{"level":"重点","text":"承担责任往往伴随着获得回报的权利，如良好的自我感觉、他人的赞许、获得新的知识和技能等；同时也会付出时间、精力，甚至可能受到责备或处罚。对于可以选择的责任，一旦作出选择，就应该义无反顾地担当起应负的责任；对于不可选择的责任，我们仍然应该自觉承担相应的责任，做到『我承担，我无悔』。","explain":"这是本单元提问频率最高的一条，分两层：可选择的责任（如报名参加志愿服务）要言出必行；不可选择的责任（如照顾生病的家人、班级值日）不能推卸。答题时两层都要写，「我承担，我无悔」是教材原话，要照写。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["责任是一个人分内应该做的事情，每一种角色都意味着承担相应的责任。","对于可以选择的责任，一旦作出选择，就应该义无反顾地担当起应负的责任；对于不可选择的责任，我们仍然应该自觉承担，做到『我承担，我无悔』。","承担责任往往伴随着获得回报的权利，也会付出时间、精力等代价；不言代价与回报，是社会责任感的集中体现。","关爱他人是一种幸福，也是一门艺术：要心怀善意、尽己所能、讲究策略。","服务社会体现人生价值，能够促进我们全面发展。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为服务社会、奉献社会是大人的事，与中学生无关；或者认为只要学习成绩好，其他都不重要。","服务和奉献社会人人可为、处处可为。中学生可以从身边小事做起：参加社会公益活动、志愿服务，参与社区建设，爱护公共环境，努力学习、积极探索，都是承担社会责任的表现。","这类说法常出现在「有人说中学生只要学习好就行」的辨析题里。答题要指出「学习好」与「担责任」并不矛盾，责任与角色同在，每一种角色都意味着承担相应的责任。"],["认为守护正义只要勇敢就够了，见到非正义行为必须立刻冲上去硬拼；或者认为维护公平正义只是司法机关的事。","守护正义需要勇气和智慧，面对非正义行为，一方面要敢于斗争，另一方面要讲究策略，寻求有效方法；实现公平正义是国家、社会和全体公民的共同责任，需要个人守护、制度保障、司法维护共同发挥作用。","材料题常以未成年人制止违法行为受伤的情境设问，答案必须落在「有勇气也要有智慧、讲究策略」上，同时点出制度保障与司法维护，只答个人一面是不完整的。"],["认为承担责任只有代价、没有回报，因此能不承担就不承担。","承担责任往往伴随着获得回报的权利，如良好的自我感觉、他人的赞许、获得新的知识和技能等；同时也可能付出时间、精力甚至生命健康等代价。代价与回报并存，不能只看一面。","这是「承担责任值不值得」类辨析题的核心。答题既要点出代价，也要点出回报，最后落到「不言代价与回报是社会责任感的集中体现」。"]]},{"type":"table","title":"承担责任的代价与回报（同一行为的两个方面：不能只算一面账）（本单元概念对比）","head":["比较项","承担责任的代价","承担责任的回报"],"rows":[["时间与精力","付出更多的时间和精力，可能影响休息与娱乐","获得新的知识和技能，增长才干"],["经济与身体","可能付出一定的经济代价，危急时刻甚至可能损害健康与生命","赢得他人的尊重、赞许与信任"],["人际与心理","可能因坚持原则而受到误解、责备，甚至被处罚","获得良好的自我感觉，内心充实、有成就感"],["对待态度","不能因为要付出代价就逃避责任","不能因为贪图回报才承担责任"],["共同结论","不言代价与回报，是社会责任感的集中体现","同左：应自觉承担责任，做到『我承担，我无悔』"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：自由与法治、平等与平均","给「自由就是不受任何限制」「给老人让座是不平等」一类观点要求评析。自由题按「自由是有限制的、相对的—必要的限制是对自由的保护—法治既规范自由又保障自由」三层作答；平等题必须先写平等的两层含义，再指出合理差别对待不违背平等。"],["判断类：公平的内涵与保障方式","给招聘设门槛、比赛规则因人而异、公共资源分配等情境，要求判断涉及权利公平、规则公平还是机会公平，并说明公平的价值。作答要「术语 + 材料」并列，最后落到「个人守护—制度保障—司法维护」三方面。"],["做法建议类：中学生怎样守护公平正义","设问常写「作为中学生，你打算怎样守护公平正义」。作答要点：坚守公平，以公平之心为人处世，坚守原则立场，采用合理合法的方式和手段；守护正义要有勇气和智慧、讲究策略；反对特权、平等对待他人、敢于抵制不平等的行为；相信并支持制度保障与司法维护。"],["宪法条文类：法律面前人人平等","直接考「中华人民共和国公民在法律面前一律平等」这一宪法规定的含义与落实：既包括同等情况同等对待，也包括不同情况差别对待；既反对特权，也反对歧视。此类设问要求表述准确，改写宪法原句会失分。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·追求自由平等·维护公平正义（第7—8课：自由平等的真谛与追求 · 公平正义的守护）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-7"},{"t":"专题精讲 · 第9课 积极奉献社会（责任与角色同在 · 关爱他人 · 服务社会）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-3-m1-q1","type":"short","stem":"（1）结合材料一，谈谈你对『我承担，我无悔』的理解。（4 分）","answer":"①责任是一个人分内应该做的事情，每一种角色都意味着承担相应的责任。小林作为子女要承担照顾家人的责任，作为班级劳动委员要承担班级管理的责任。②有些责任不是自愿选择的，如照顾生病的家人、承担班级值日，我们仍然应该自觉承担，做到『我承担，我无悔』。③承担责任往往伴随着获得回报的权利，如良好的自我感觉、他人的赞许、获得新的知识和技能，同时也会付出时间、精力等代价，不能只算代价、只讲回报。④不言代价与回报，是社会责任感的集中体现；小林的做法正体现了这种责任感。","explain":"","tags":["责任与角色","我承担我无悔","评析题"],"rubric":["答出责任的含义与「责任与角色同在」","答出对不可选择的责任应自觉承担、做到『我承担，我无悔』","答出承担责任既有代价也有回报（或「不能只算代价、只讲回报」）","答出不言代价与回报是社会责任感的集中体现"]},{"id":"pol-moral-3-m1-q2","type":"short","stem":"（2）结合材料二，说明中学生参加志愿服务活动的意义，并为自己设计一项可行的服务社会行动。（4 分）","answer":"意义：①服务社会体现人生价值。在帮助老年人学习使用智能手机的过程中，志愿者的付出得到他人和社会的认可，实现了自身价值。②服务社会能够促进我们全面发展，使我们的视野不断拓展、知识不断丰富、能力不断提高、道德境界不断提升。③关爱他人是一种幸福，关爱他人也是关爱和善待自己，在帮助他人的过程中获得内心的满足，使社会生活更加和谐融洽。行动（示例）：利用周末参加社区的「银龄数字课堂」志愿服务，每月至少服务两次、每次一小时，耐心帮助老年人学会扫码支付、视频通话等常用功能；或参加校园「图书漂流」志愿服务，负责整理图书角、登记借阅情况。","explain":"","tags":["服务社会","公益志愿","做法建议"],"rubric":["答出服务社会体现人生价值","答出服务社会促进我们全面发展（视野、知识、能力、道德境界）","答出关爱他人是一种幸福（或关爱他人也是关爱和善待自己）","设计的行动具体可行，有明确的服务内容和时间安排"]},{"id":"pol-moral-3-q1","type":"choice","stem":"小刚作为班级课代表每天收发作业，作为子女在家主动分担家务。这说明","answer":"A","explain":"责任是一个人分内应该做的事情，其来源包括对他人的承诺、职业要求、道德规范和法律规定等；每一种角色都意味着承担相应的责任，角色不同、责任也不同。B、C、D 三项分别错在对责任的来源、角色与责任的关系、代价与回报的关系的理解上。","options":["责任是一个人分内应该做的事情，来自对他人的承诺、职业要求、道德规范和法律规定等","责任都是自愿选择的，不愿意就可以不承担","社会角色不同，但承担的责任是一样的","承担责任只讲代价，没有回报"],"difficulty":1,"tags":["责任的来源","责任与角色"]},{"id":"pol-moral-3-q2","type":"choice","stem":"对于不是自己自愿选择的责任（如班级值日、照顾家中的长辈），正确的态度是","answer":"C","explain":"有些责任不是自愿选择的，我们仍然应该自觉承担相应的责任，做到『我承担，我无悔』。A、D 两项是逃避或敷衍责任，B 项是只想获得回报、不愿付出代价，都不符合负责任的要求。","options":["想方设法推给别人去做","只做那些能得到表扬的部分","自觉承担相应的责任，做到『我承担，我无悔』","敷衍应付，只要不出错就行"],"difficulty":1,"tags":["我承担我无悔"]},{"id":"pol-moral-3-q3","type":"choice","stem":"关爱他人是一门艺术。下列做法恰当的是","answer":"B","explain":"关爱他人要讲究策略：帮助他人时要考虑他人的内心感受，不伤及他人的自尊心；面对复杂情形要作出明智判断，增强安全防范意识和自我保护能力。A 项伤害他人自尊；C 项缺乏自我保护意识，应大声呼救、寻求成年人帮助；D 项是没有原则的「有求必应」，不是真正的关爱。","options":["在公共场合大声谈论受助同学的家庭困难","帮助他人时注意考虑对方的内心感受，不伤及其自尊心","不顾自身安危，独自进入危险水域救助落水者","只要对方提出要求，就无条件答应"],"difficulty":2,"tags":["关爱他人","讲究策略"]},{"id":"pol-moral-3-q4","type":"choice","stem":"中学生利用周末参加社区志愿服务活动，其意义在于","answer":"A","explain":"服务社会体现人生价值，能够促进我们全面发展（视野不断拓展、知识不断丰富、能力不断提高、道德境界不断提升）。B 项否认了志愿服务的价值，C 项忽视了服务社会人人可为，D 项把承担责任的目的等同于获取回报。","options":["服务社会体现人生价值，能够促进我们全面发展","参加志愿服务一定会耽误学习，没有任何意义","只有成年人才有能力服务社会","服务社会就是为了获得荣誉和回报"],"difficulty":1,"tags":["服务社会"]}]},{"id":"cat-pol-8a-4-1","title":"第10课 国家利益至上","subtitle":"八年级上册 · 第四单元 维护国家利益","grade":"8a","tags":["八年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第四单元 维护国家利益"},{"k":"课题","v":"第10课 国家利益至上"},{"k":"框题","v":"国家利益高于一切 / 捍卫国家利益"}]},{"type":"note","title":"本课在单元中的位置","text":"国家利益是一个主权国家生存需求和发展需求的总和，涉及政治、经济、文化、社会、军事等领域，包括安全利益、政治利益、经济利益、文化利益等；国家利益反映广大人民的共同需求，是人民利益的集中表现，二者高度统一，因此要坚持国家利益至上，树立维护国家利益意识、坚决捍卫国家利益。强国必须强军，军强才能国安——党对人民军队的绝对领导是人民军队的建军之本、强军之魂；国家安全是安邦定国的重要基石，必须树立总体国家安全观，维护国家安全人人可为，履行公民的法定义务。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["国家利益高于一切","捍卫国家利益"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一，国家利益至上，人民利益高于一切，二者相辅相成。","explain":"这是本单元最核心的一句，也是辨析题答案的骨架。凡出现「国家利益与个人利益是对立的」「维护国家利益就要完全放弃个人利益」的说法，都要先答「高度统一、相辅相成」，再答「发生冲突时把国家利益放在第一位」。"},{"level":"重点","text":"坚持国家利益至上，要树立维护国家利益意识：心怀爱国之情，牢固树立国家利益至上的观念；树立和增强危机意识和防范意识；增强维护国家利益的责任感和使命感。","explain":"设问「思想上应该怎样维护国家利益」，就按这三点作答。「危机意识和防范意识」这一条最常被漏答，而它恰恰对应网络窃密、境外机构拉拢等情境题，一定要写。"},{"level":"重点","text":"国家利益是一个主权国家在国际社会中生存需求和发展需求的总和，它关系民族生存、国家兴亡；国家利益涉及政治、经济、文化、社会、军事等领域，包括安全利益、政治利益、经济利益、文化利益等。","explain":"选择题常给一组事项让学生判断「哪些属于国家利益」。答题时抓住「主权、安全、领土完整、国家统一、政治制度、社会大局稳定、可持续发展」这几个关键词，以及安全利益、政治利益、经济利益、文化利益四类内容。"},{"level":"重点","text":"坚决捍卫国家利益：要着眼长远、顾全大局，以国家利益为重，把国家利益放在第一位；为了国家利益，有时不仅需要放弃个人利益，甚至要献出自己的生命；要坚决同一切损害国家利益的行为作斗争。在日常生活中，我们要自觉遵守道德和法律，积极维护国家团结稳定的局面。","explain":"行动层面的标准答案，四句话按「着眼长远顾全大局—以国家利益为重—必要时放弃个人利益—同损害国家利益的行为作斗争」排列，最后补上日常要求。材料题最后一句常写「自觉遵守道德和法律，维护国家团结稳定」，漏掉会少一分。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["坚持国家利益至上，要树立维护国家利益意识，坚决捍卫国家利益，把国家利益放在第一位。","国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为国家利益与个人利益是对立的，维护国家利益就必须完全放弃个人利益。","国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成；维护国家利益并不排斥个人的正当利益，但当二者发生冲突时，要把国家利益放在第一位，必要时放弃个人利益甚至献出生命。","这是本单元最高频的辨析题。正确答法分三层：高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先。只答「要牺牲个人利益」是不全面的。"]]},{"type":"table","title":"国家利益与个人利益（一个命运共同体中的两个层面）（本单元概念对比）","head":["比较项","国家利益","个人利益"],"rows":[["内涵","一个主权国家在国际社会中生存需求和发展需求的总和","个人生存和发展的各种需要与正当权益"],["地位","反映广大人民的共同需求，是人民利益的集中表现，国家利益至上","正当的个人利益受法律保护，人民利益高于一切"],["相互关系","国家利益与人民利益高度统一、相辅相成，二者息息相关、命运与共","个人利益的实现离不开国家的发展与稳定"],["冲突时的处理","把国家利益放在第一位，着眼长远、顾全大局","必要时放弃个人利益，甚至献出生命"],["日常要求","心怀爱国之情，树立和增强危机意识、防范意识","遵纪守法，维护国家团结稳定，同损害国家利益的行为作斗争"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：国家利益与个人利益、国防建设与经济建设的关系","以「维护国家利益就要牺牲个人利益」「和平年代不必花大力气搞国防」等观点设问，要求评析。作答框架：国家利益是人民利益的集中表现 → 二者高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先；国防题则要点出「强国必须强军，军强才能国安」与「富国和强军相统一」。"],["识记运用类：国家安全的内涵与总体国家安全观","一类题考「宗旨／根本／基础」的对应与「总体」的含义，另一类题给情境要求判断涉及哪个安全领域、公民该如何做。作答要把「维护国家安全是每个公民的法定义务」写出来，并给出具体做法（学习保密法律法规、遵守规定、举报危害国家安全的行为）。"],["军队与国防类：党对人民军队的绝对领导、人民军队的任务","以卫国戍边、抢险救灾、国防教育活动的材料设问「这说明了什么」「青少年应怎样关心国防」。要点：党对人民军队的绝对领导是人民军队的建军之本、强军之魂；人民军队的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务；青少年要学习国防知识、增强国防观念、自觉履行保卫祖国、抵抗侵略的神圣职责。"],["做法建议类：公民怎样维护国家安全","材料常给「军事禁区拍照」「陌生网友索要内部资料」「发现可疑测绘活动」等情境，设问「你该怎么做」。作答按「意识—知识—行动」三层：增强国家安全意识、树立国家安全利益高于一切的观念；学习有关国家安全和保密工作的法律法规；严格遵守规定，为维护国家安全工作提供便利和协助，检举、制止危害国家安全的行为。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·维护国家利益（第10—12课：国家利益至上 · 军强才能国安 · 树立总体国家安全观）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-4-q1","type":"choice","stem":"关于国家利益与人民利益的关系，下列说法正确的是","answer":"B","explain":"国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成，国家利益至上，人民利益高于一切。A、D 两项把二者对立或颠倒位置；C 项忽视了正当的个人利益并不需要放弃，只有在二者发生冲突时才把国家利益放在第一位。","options":["国家利益与人民利益是根本对立的","国家利益反映广大人民的共同需求，是人民利益的集中表现","维护国家利益就必须完全放弃个人的正当利益","人民利益高于国家利益，国家利益应当服从个人利益"],"difficulty":1,"tags":["国家利益与人民利益"]},{"id":"pol-moral-4-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 国家利益是一个主权国家在国际社会中生存需求和发展需求的总和，它关系民族生存、国家…\n② 国家的核心利益包括国家主权、国家安全、领土完整、国家统一、宪法确立的国家政治制度…\n③ 国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一…\n④ 认为国家利益与个人利益是对立的，维护国家利益就必须完全放弃个人利益。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的辨析题。正确答法分三层：高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先。只答「要牺牲个人利益」是不全面的；正确表述应为：国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成；维护国家利益并不排斥个人的正当利益，但当二者发生冲突时，要把国家利益放在第一位，必要时放弃个人利益甚至献出生命。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·维护国家利益（第10—12课：国家利益至上 · 军强才能国安 · 树立总体国家安全观）"]},{"id":"pol-moral-4-q3","type":"choice","stem":"总体国家安全观以（ ）为宗旨，以（ ）为根本，以（ ）为基础","answer":"A","explain":"总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托；总体国家安全观的关键是「总体」。「宗旨／根本／基础」是固定搭配，不能对调。","options":["人民安全；政治安全；经济安全","政治安全；经济安全；人民安全","经济安全；人民安全；政治安全","军事安全；政治安全；经济安全"],"difficulty":1,"tags":["总体国家安全观"]},{"id":"cat-pol-8a-4-1-short","type":"short","stem":"某班围绕「国家利益至上」开展主题探究活动，围绕「国家利益高于一切」、「捍卫国家利益」。请运用本课所学，谈谈你的认识。","answer":"国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一，国家利益至上，人民利益高于一切，二者相辅相成。坚持国家利益至上，要树立维护国家利益意识：心怀爱国之情，牢固树立国家利益至上的观念；树立和增强危机意识和防范意识；增强维护国家利益的责任感和使命感。","explain":"","rubric":["国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一…","坚持国家利益至上，要树立维护国家利益意识：心怀爱国之情，牢固树立国家利益至上的观…","国家利益是一个主权国家在国际社会中生存需求和发展需求的总和，它关系民族生存、国家…"],"tags":["国家利益至上"]},{"id":"cat-pol-8a-4-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一…\n② 坚持国家利益至上，要树立维护国家利益意识：心怀爱国之情，牢固树立国家利益至上的观…\n③ 国家利益是一个主权国家在国际社会中生存需求和发展需求的总和，它关系民族生存、国家…\n④ 认为国家利益与个人利益是对立的，维护国家利益就必须完全放弃个人利益。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的辨析题。正确答法分三层：高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先。只答「要牺牲个人利益」是不全面的；正确表述应为：国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成；维护国家利益并不排斥个人的正当利益，但当二者发生冲突时，要把国家利益放在第一位，必要时放弃个人利益甚至献出生命。","difficulty":3,"tags":["第10课 国家利益至上"]}]},{"id":"cat-pol-8a-4-2","title":"第11课 军强才能国安","subtitle":"八年级上册 · 第四单元 维护国家利益","grade":"8a","tags":["八年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第四单元 维护国家利益"},{"k":"课题","v":"第11课 军强才能国安"},{"k":"框题","v":"党和人民信赖的英雄军队 / 全面推进国防和军队现代化"}]},{"type":"note","title":"本课在单元中的位置","text":"国家利益是一个主权国家生存需求和发展需求的总和，涉及政治、经济、文化、社会、军事等领域，包括安全利益、政治利益、经济利益、文化利益等；国家利益反映广大人民的共同需求，是人民利益的集中表现，二者高度统一，因此要坚持国家利益至上，树立维护国家利益意识、坚决捍卫国家利益。强国必须强军，军强才能国安——党对人民军队的绝对领导是人民军队的建军之本、强军之魂；国家安全是安邦定国的重要基石，必须树立总体国家安全观，维护国家安全人人可为，履行公民的法定义务。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["党和人民信赖的英雄军队","全面推进国防和军队现代化"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"强国必须强军，军强才能国安。党对人民军队的绝对领导是人民军队的建军之本、强军之魂；建设强大的人民军队，是维护国家主权、安全、发展利益的坚强保障。","explain":"第11课新增内容的核心句。「建军之本、强军之魂」是固定表述，一个字都不能改，也不能写成「重要保证」「根本原则」。凡设问「为什么必须坚持党对人民军队的绝对领导」，就答这一条，并补充「人民军队是执行党的政治任务的武装集团」。"},{"level":"次重点","text":"党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队；要全面推进政治建军、改革强军、科技强军、人才强军、依法治军，加快国防和军队现代化。","explain":"「听党指挥、能打胜仗、作风优良」三个词是固定搭配，顺序也不能换：听党指挥是灵魂，能打胜仗是核心，作风优良是保证。答「怎样建设强大军队」时要点出「政治建军、改革强军、科技强军、人才强军、依法治军」五个方面。"},{"level":"重点","text":"中华人民共和国的武装力量属于人民。人民军队的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。","explain":"这五句话出自宪法，是「人民军队的任务」的标准答案，术语不能改写成「打仗」「救灾」等口语。材料给出抢险救灾、卫国戍边、联合演训等情境，问「这体现了人民军队的什么任务」，要一一对应到「保卫祖国」「保卫人民的和平劳动」「参加国家建设事业」「努力为人民服务」。"},{"level":"次重点","text":"坚持富国和强军相统一，推动军民融合深度发展，巩固军政军民团结；国家通过多种形式开展国防教育，每年 9 月的第三个星期六是全民国防教育日。青少年要关心国防、热爱国防，学习国防知识，自觉履行保卫祖国、抵抗侵略的神圣职责，依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。","explain":"「保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责」与「依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务」都是宪法规定，属规范引用。青少年做法要具体：参加国防教育宣传活动、参观国防教育基地、学习国防知识和军事技能、增强国防观念。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["强国必须强军，军强才能国安；党对人民军队的绝对领导是人民军队的建军之本、强军之魂。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["认为和平年代国防和军队建设不那么重要了，军费不如用来发展经济。","强国必须强军，军强才能国安；国家安全是安邦定国的重要基石，没有强大的国防和军队，国家主权、安全、发展利益就得不到保障。我国坚持富国和强军相统一，经济建设与国防建设相互支撑、协调发展。","这类说法常出现在辨析题里，答题要同时点出「军强才能国安」与「富国和强军相统一」两层，不能只说「要有军队」。"],["认为国家安全只是国家和军队的事，与中学生无关。","维护国家安全是每个公民的法定义务，人人可为、人人能为。中学生可以增强国家安全意识，学习有关国家安全和保密工作的法律法规，遵守有关规定，为维护国家安全工作提供便利和协助，检举、制止危害国家安全的行为。","材料题常以「发现有人在军事禁区拍照」「陌生网友索要内部资料」设问，考的就是「公民个人也是维护国家安全的主体」，并要落到「法定义务」这个术语上。"]]},{"type":"table","title":"传统安全与非传统安全（国家安全体系不断丰富的外延）（本单元概念对比）","head":["比较项","传统安全领域","非传统安全领域"],"rows":[["主要指向","国家政权、主权、统一和领土完整面临的军事与政治威胁","经济社会发展中出现的、跨越国界的综合性安全问题"],["典型领域","政治安全、国土安全、军事安全","经济安全、文化安全、社会安全、科技安全、信息安全、生态安全、资源安全、核安全等"],["常见表现","外来军事威胁、分裂国家的行为","网络攻击与信息泄露、生态环境破坏、资源短缺、重大疫病等"],["维护方式","依靠国防和军队建设，坚决维护国家主权和领土完整","依靠法治保障、科技创新、全民参与和国际合作"],["共同要求","都属于总体国家安全观统筹的范围，都是国家利益的重要组成部分","同左：维护国家安全是每个公民的法定义务"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：国家利益与个人利益、国防建设与经济建设的关系","以「维护国家利益就要牺牲个人利益」「和平年代不必花大力气搞国防」等观点设问，要求评析。作答框架：国家利益是人民利益的集中表现 → 二者高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先；国防题则要点出「强国必须强军，军强才能国安」与「富国和强军相统一」。"],["识记运用类：国家安全的内涵与总体国家安全观","一类题考「宗旨／根本／基础」的对应与「总体」的含义，另一类题给情境要求判断涉及哪个安全领域、公民该如何做。作答要把「维护国家安全是每个公民的法定义务」写出来，并给出具体做法（学习保密法律法规、遵守规定、举报危害国家安全的行为）。"],["军队与国防类：党对人民军队的绝对领导、人民军队的任务","以卫国戍边、抢险救灾、国防教育活动的材料设问「这说明了什么」「青少年应怎样关心国防」。要点：党对人民军队的绝对领导是人民军队的建军之本、强军之魂；人民军队的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务；青少年要学习国防知识、增强国防观念、自觉履行保卫祖国、抵抗侵略的神圣职责。"],["做法建议类：公民怎样维护国家安全","材料常给「军事禁区拍照」「陌生网友索要内部资料」「发现可疑测绘活动」等情境，设问「你该怎么做」。作答按「意识—知识—行动」三层：增强国家安全意识、树立国家安全利益高于一切的观念；学习有关国家安全和保密工作的法律法规；严格遵守规定，为维护国家安全工作提供便利和协助，检举、制止危害国家安全的行为。"]]},{"type":"quote","text":"【材料一】某高校学生小陈在网上遇到陌生人以「高薪兼职」「学术调研」为名，索要他所在课题组的研究资料和校园内部照片。小陈察觉异常，拒绝了对方，并向国家安全机关举报。\n【材料二】我国宪法规定，中华人民共和国的武装力量属于人民。它的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。在卫国戍边、抢险救灾等任务中，人民子弟兵始终冲锋在前。\n【材料三】每年 9 月的第三个星期六是全民国防教育日，各地通过参观国防教育基地、开展军事体验、宣讲国防法规等形式开展国防教育活动。我国宪法规定，保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责，依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·维护国家利益（第10—12课：国家利益至上 · 军强才能国安 · 树立总体国家安全观）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-4-m1-q2","type":"short","stem":"（2）结合材料二，说明为什么说「军强才能国安」，并指出人民军队的任务。（4 分）","answer":"为什么：①强国必须强军，军强才能国安。国家安全是安邦定国的重要基石，是国家生存与发展的重要保障、人民幸福安康的前提，建设强大的人民军队是维护国家主权、安全、发展利益的坚强保障。②党对人民军队的绝对领导是人民军队的建军之本、强军之魂，人民军队始终在党的领导下行动和战斗。③我国坚持富国和强军相统一，国防和军队现代化为国家发展提供安全保障。任务：中华人民共和国的武装力量属于人民，人民军队的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务——材料中人民子弟兵在卫国戍边、抢险救灾中冲锋在前，正体现了这一点。","explain":"","tags":["军强才能国安","人民军队的任务","材料分析"],"rubric":["答出强国必须强军，军强才能国安","答出国家安全是安邦定国的重要基石（或国家生存与发展的重要保障、人民幸福安康的前提）","答出党对人民军队的绝对领导是人民军队的建军之本、强军之魂","完整答出人民军队的任务（巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务）","结合材料二的情境说明"]},{"id":"pol-moral-4-m1-q3","type":"short","stem":"（3）结合材料三，谈谈青少年应当怎样关心国防、热爱国防。（2 分）","answer":"①增强国防观念，认识到保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责，国家安全与每个人息息相关。②积极参加全民国防教育日活动，参观国防教育基地，学习国防知识和军事技能，了解国防法律法规，主动接受国防教育。③尊重和爱护人民军队，学习子弟兵的优良作风；努力学习、强健体魄，长大后自觉履行依照法律服兵役和参加民兵组织的光荣义务，为国防建设贡献力量。","explain":"","tags":["国防教育","青少年做法","启示类"],"rubric":["答出增强国防观念（或保卫祖国、抵抗侵略是公民的神圣职责）","答出参加国防教育活动、学习国防知识和军事技能、学习国防法律法规","答出尊重爱护人民军队、努力学习、依法服兵役是公民的光荣义务"]},{"id":"pol-moral-4-q5","type":"choice","stem":"「党对人民军队的绝对领导是人民军队的建军之本、强军之魂。」坚持党对人民军队的绝对领导，是因为","answer":"A","explain":"党对人民军队的绝对领导是人民军队的建军之本、强军之魂，人民军队是执行党的政治任务的武装集团，只有坚持党的领导，才能始终保持人民军队的性质和宗旨。B 项否认了党的领导对军队建设的作用；C 项错误，我国坚持富国和强军相统一；D 项缩小了人民军队的任务，其首要任务是巩固国防、抵抗侵略、保卫祖国、保卫人民的和平劳动。","options":["人民军队是执行党的政治任务的武装集团，只有坚持党的领导才能始终保持人民军队的性质和宗旨","人民军队只要装备先进就一定能打胜仗，与领导体制无关","国防和军队建设与经济建设是对立的，必须优先发展军队","军队的任务只是参加国家建设事业，不承担保卫祖国的职责"],"difficulty":2,"tags":["党对人民军队的绝对领导","军强才能国安"]},{"id":"pol-moral-4-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 国家利益是一个主权国家在国际社会中生存需求和发展需求的总和，它关系民族生存、国家…\n② 国家的核心利益包括国家主权、国家安全、领土完整、国家统一、宪法确立的国家政治制度…\n③ 国家利益反映广大人民的共同需求，是人民利益的集中表现；国家利益与人民利益高度统一…\n④ 认为国家利益与个人利益是对立的，维护国家利益就必须完全放弃个人利益。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——这是本单元最高频的辨析题。正确答法分三层：高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先。只答「要牺牲个人利益」是不全面的；正确表述应为：国家利益反映广大人民的共同需求，是人民利益的集中表现，国家利益与人民利益高度统一、相辅相成；维护国家利益并不排斥个人的正当利益，但当二者发生冲突时，要把国家利益放在第一位，必要时放弃个人利益甚至献出生命。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·维护国家利益（第10—12课：国家利益至上 · 军强才能国安 · 树立总体国家安全观）"]},{"id":"pol-moral-4-q6","type":"choice","stem":"对「国家安全是安邦定国的重要基石」这句话，理解正确的是","answer":"A","explain":"国家安全是安邦定国的重要基石，是国家生存与发展的重要保障，是人民幸福安康的前提。B 项把国家安全的内涵缩小为军事安全；C 项把国家安全与经济发展简单等同，发展并不自动带来安全；D 项错误，维护国家安全是每个公民的法定义务。","options":["国家安全是国家生存与发展的重要保障，是人民幸福安康的前提","国家安全只是军事安全，与其他领域无关","只要经济发展了，国家安全就自然有保障","国家安全属于国家大事，公民个人没有维护的义务"],"difficulty":2,"tags":["国家安全的重要性"]}]},{"id":"cat-pol-8a-4-3","title":"第12课 树立总体国家安全观","subtitle":"八年级上册 · 第四单元 维护国家利益","grade":"8a","tags":["八年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级上册"},{"k":"单元","v":"第四单元 维护国家利益"},{"k":"课题","v":"第12课 树立总体国家安全观"},{"k":"框题","v":"认识国家安全 / 维护国家安全"}]},{"type":"note","title":"本课在单元中的位置","text":"国家利益是一个主权国家生存需求和发展需求的总和，涉及政治、经济、文化、社会、军事等领域，包括安全利益、政治利益、经济利益、文化利益等；国家利益反映广大人民的共同需求，是人民利益的集中表现，二者高度统一，因此要坚持国家利益至上，树立维护国家利益意识、坚决捍卫国家利益。强国必须强军，军强才能国安——党对人民军队的绝对领导是人民军队的建军之本、强军之魂；国家安全是安邦定国的重要基石，必须树立总体国家安全观，维护国家安全人人可为，履行公民的法定义务。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["认识国家安全","维护国家安全"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"国家安全是安邦定国的重要基石，是国家生存与发展的重要保障，是人民幸福安康的前提。总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托；总体国家安全观的关键是「总体」。","explain":"「宗旨／根本／基础／保障／依托」是固定搭配，一字不可换：把「以政治安全为根本」写成「以经济安全为根本」是最典型的错误。另外要能解释「关键在总体」——国家安全各领域相互关联、相互支撑，必须用整体视角统筹看待，不能只盯住军事安全。"},{"level":"重点","text":"国家的核心利益包括国家主权、国家安全、领土完整、国家统一、宪法确立的国家政治制度和社会大局稳定、经济社会可持续发展的基本保障。","explain":"这是本课必背的六个要点，顺序与表述都不能改动：主权、安全、领土完整、国家统一、政治制度和社会大局稳定、经济社会可持续发展的基本保障。选择题常以「下列不属于国家核心利益的是」设问，把「企业利益」「个人利益」混入选项。"},{"level":"次重点","text":"国家安全体系包括政治安全、国土安全、军事安全、经济安全、文化安全、社会安全、科技安全、信息安全、生态安全、资源安全、核安全等，其内涵和外延随着时代发展不断丰富。","explain":"多以「下列属于国家安全领域的是」的选择题形式出现，也常在材料题中要求「指出材料涉及哪一领域的安全」。答题时按材料关键词对应领域：涉及网络数据安全答「信息安全」，涉及生态环境答「生态安全」，涉及粮食安全答「经济安全」。"},{"level":"次重点","text":"维护国家安全是每个公民的法定义务。我们要增强国家安全意识，树立国家安全利益高于一切的观念；认真学习有关国家安全和保密工作的法律法规、规章制度，增强维护国家安全的法治意识；严格遵守有关国家安全的法律规定，不断提高防范意识和防范能力，善于识别危害国家安全的各种伪装；为维护国家安全工作提供便利和协助，为维护国家安全积极建言献策，检举、制止危害国家安全的行为。","explain":"做法类设问的主力答案。注意落脚词是「法定义务」而不是「道德义务」。涉及举报时可以说向国家安全机关举报（举报受理电话 12339），但不要编造具体案例与数据。"},{"level":"了解","text":"每年 4 月 15 日是全民国家安全教育日；国家通过多种形式开展国家安全宣传教育，增强全民国家安全意识。","explain":"常作为材料的时间背景出现，属于常识性表述，记住日期与「全民国家安全教育日」这一名称即可，不涉及具体年份的题目原文。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托；关键是「总体」。","国家安全是安邦定国的重要基石，是国家生存与发展的重要保障，是人民幸福安康的前提。","维护国家安全是每个公民的法定义务，我们要增强国家安全意识，树立国家安全利益高于一切的观念。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["把国家安全等同于军事安全、国土安全，或认为总体国家安全观「以经济安全为根本」。","国家安全的内涵十分丰富，除政治安全、国土安全、军事安全外，还包括经济安全、文化安全、社会安全、科技安全、信息安全、生态安全、资源安全、核安全等，与每个人的生活密切相关；总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托。","「宗旨／根本／基础」三个词是固定搭配，把「根本」与「基础」对调是选择题最常见的错误选项；「国家安全就是军事安全」也是高频干扰项。"],["认为和平年代国防和军队建设不那么重要了，军费不如用来发展经济。","强国必须强军，军强才能国安；国家安全是安邦定国的重要基石，没有强大的国防和军队，国家主权、安全、发展利益就得不到保障。我国坚持富国和强军相统一，经济建设与国防建设相互支撑、协调发展。","这类说法常出现在辨析题里，答题要同时点出「军强才能国安」与「富国和强军相统一」两层，不能只说「要有军队」。"],["认为国家安全只是国家和军队的事，与中学生无关。","维护国家安全是每个公民的法定义务，人人可为、人人能为。中学生可以增强国家安全意识，学习有关国家安全和保密工作的法律法规，遵守有关规定，为维护国家安全工作提供便利和协助，检举、制止危害国家安全的行为。","材料题常以「发现有人在军事禁区拍照」「陌生网友索要内部资料」设问，考的就是「公民个人也是维护国家安全的主体」，并要落到「法定义务」这个术语上。"]]},{"type":"table","title":"传统安全与非传统安全（国家安全体系不断丰富的外延）（本单元概念对比）","head":["比较项","传统安全领域","非传统安全领域"],"rows":[["主要指向","国家政权、主权、统一和领土完整面临的军事与政治威胁","经济社会发展中出现的、跨越国界的综合性安全问题"],["典型领域","政治安全、国土安全、军事安全","经济安全、文化安全、社会安全、科技安全、信息安全、生态安全、资源安全、核安全等"],["常见表现","外来军事威胁、分裂国家的行为","网络攻击与信息泄露、生态环境破坏、资源短缺、重大疫病等"],["维护方式","依靠国防和军队建设，坚决维护国家主权和领土完整","依靠法治保障、科技创新、全民参与和国际合作"],["共同要求","都属于总体国家安全观统筹的范围，都是国家利益的重要组成部分","同左：维护国家安全是每个公民的法定义务"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["辨析类：国家利益与个人利益、国防建设与经济建设的关系","以「维护国家利益就要牺牲个人利益」「和平年代不必花大力气搞国防」等观点设问，要求评析。作答框架：国家利益是人民利益的集中表现 → 二者高度统一 → 不排斥正当个人利益 → 冲突时国家利益优先；国防题则要点出「强国必须强军，军强才能国安」与「富国和强军相统一」。"],["识记运用类：国家安全的内涵与总体国家安全观","一类题考「宗旨／根本／基础」的对应与「总体」的含义，另一类题给情境要求判断涉及哪个安全领域、公民该如何做。作答要把「维护国家安全是每个公民的法定义务」写出来，并给出具体做法（学习保密法律法规、遵守规定、举报危害国家安全的行为）。"],["军队与国防类：党对人民军队的绝对领导、人民军队的任务","以卫国戍边、抢险救灾、国防教育活动的材料设问「这说明了什么」「青少年应怎样关心国防」。要点：党对人民军队的绝对领导是人民军队的建军之本、强军之魂；人民军队的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务；青少年要学习国防知识、增强国防观念、自觉履行保卫祖国、抵抗侵略的神圣职责。"],["做法建议类：公民怎样维护国家安全","材料常给「军事禁区拍照」「陌生网友索要内部资料」「发现可疑测绘活动」等情境，设问「你该怎么做」。作答按「意识—知识—行动」三层：增强国家安全意识、树立国家安全利益高于一切的观念；学习有关国家安全和保密工作的法律法规；严格遵守规定，为维护国家安全工作提供便利和协助，检举、制止危害国家安全的行为。"]]},{"type":"quote","text":"【材料一】某高校学生小陈在网上遇到陌生人以「高薪兼职」「学术调研」为名，索要他所在课题组的研究资料和校园内部照片。小陈察觉异常，拒绝了对方，并向国家安全机关举报。\n【材料二】我国宪法规定，中华人民共和国的武装力量属于人民。它的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。在卫国戍边、抢险救灾等任务中，人民子弟兵始终冲锋在前。\n【材料三】每年 9 月的第三个星期六是全民国防教育日，各地通过参观国防教育基地、开展军事体验、宣讲国防法规等形式开展国防教育活动。我国宪法规定，保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责，依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·维护国家利益（第10—12课：国家利益至上 · 军强才能国安 · 树立总体国家安全观）","url":"/learn/politics/pages/detail/detail?moduleId=pol-moral&entryId=pol-moral-4"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-moral-4-m1-q1","type":"short","stem":"（1）结合材料一，说明公民应当怎样维护国家安全。（4 分）","answer":"①维护国家安全是每个公民的法定义务，要增强国家安全意识，树立国家安全利益高于一切的观念。②认真学习有关国家安全和保密工作的法律法规、规章制度，增强维护国家安全的法治意识。③严格遵守有关国家安全的法律规定，积极履行维护国家安全的法定义务，不断提高防范意识和防范能力，善于识别危害国家安全的各种伪装——像材料中的小陈那样，对「高薪兼职」「学术调研」之类的名义保持警惕，不随意提供内部资料。④为维护国家安全工作提供便利和协助，为维护国家安全积极建言献策，检举、制止危害国家安全的行为，发现可疑情况可以向国家安全机关举报。","explain":"","tags":["维护国家安全","法定义务","做法建议"],"rubric":["答出维护国家安全是每个公民的法定义务、增强国家安全意识","答出学习有关国家安全和保密工作的法律法规、增强法治意识","答出遵守有关法律规定、提高防范意识和防范能力、识别危害国家安全的伪装","答出检举、制止危害国家安全的行为，并结合材料一的情境"]},{"id":"pol-moral-4-q2","type":"choice","stem":"下列不属于国家核心利益的是","answer":"D","explain":"国家的核心利益包括国家主权、国家安全、领土完整、国家统一、宪法确立的国家政治制度和社会大局稳定、经济社会可持续发展的基本保障。企业的市场份额与利润属于企业和市场的经济事项，不属于国家核心利益，D 项符合题意。","options":["国家主权、国家安全、领土完整、国家统一","宪法确立的国家政治制度和社会大局稳定","经济社会可持续发展的基本保障","某企业在本行业中的市场份额与利润"],"difficulty":2,"tags":["国家的核心利益"]},{"id":"pol-moral-4-q3","type":"choice","stem":"总体国家安全观以（ ）为宗旨，以（ ）为根本，以（ ）为基础","answer":"A","explain":"总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托；总体国家安全观的关键是「总体」。「宗旨／根本／基础」是固定搭配，不能对调。","options":["人民安全；政治安全；经济安全","政治安全；经济安全；人民安全","经济安全；人民安全；政治安全","军事安全；政治安全；经济安全"],"difficulty":1,"tags":["总体国家安全观"]},{"id":"pol-moral-4-q4","type":"choice","stem":"中学生维护国家安全，下列做法正确的是","answer":"C","explain":"维护国家安全是每个公民的法定义务。发现危害国家安全的行为应当检举、制止，可以向国家安全机关举报。A、B 两项都可能泄露国家秘密、危害国家安全；D 项是没有履行维护国家安全的法定义务。","options":["为获得点赞，在网络上发布自己拍摄的军事禁区照片","把捡到的涉密文件带回家中保存留念","发现危害国家安全的行为，及时向国家安全机关举报","认为国家安全与自己无关，不闻不问"],"difficulty":1,"tags":["维护国家安全"]},{"id":"pol-moral-4-q6","type":"choice","stem":"对「国家安全是安邦定国的重要基石」这句话，理解正确的是","answer":"A","explain":"国家安全是安邦定国的重要基石，是国家生存与发展的重要保障，是人民幸福安康的前提。B 项把国家安全的内涵缩小为军事安全；C 项把国家安全与经济发展简单等同，发展并不自动带来安全；D 项错误，维护国家安全是每个公民的法定义务。","options":["国家安全是国家生存与发展的重要保障，是人民幸福安康的前提","国家安全只是军事安全，与其他领域无关","只要经济发展了，国家安全就自然有保障","国家安全属于国家大事，公民个人没有维护的义务"],"difficulty":2,"tags":["国家安全的重要性"]}]},{"id":"cat-pol-8b-1-1","title":"第1课 治国安邦的总章程","subtitle":"八年级下册 · 第一单元 坚持宪法至上","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 坚持宪法至上"},{"k":"课题","v":"第1课 治国安邦的总章程"},{"k":"框题","v":"党领导人民制定宪法 / 宪法的内容和作用"}]},{"type":"note","title":"本课在单元中的位置","text":"宪法是国家的根本法，是治国安邦的总章程、公民权利的保障书：它确认国家的一切权力属于人民、确认并保障公民的基本权利，又通过组织国家机构、规范国家权力运行，把权力关进制度的笼子；坚持依法治国首先要坚持依宪治国，加强宪法监督、维护宪法权威是全体公民的共同责任。这一单元是全册的「总纲」，中考材料题问「为什么」「说明了什么」，答案的第一句几乎都从这里起笔。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["党领导人民制定宪法","宪法的内容和作用"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。","explain":"这是「维护宪法权威」一课的必背句，选择题常把「首先」换成「全面」「必须」「就要」来设误。材料题问「为什么要坚持依宪治国」，答法是：宪法是国家的根本法，是治国安邦的总章程，是党和人民意志的集中体现；依法治国是党领导人民治理国家的基本方略，法治是治国理政的基本方式；坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。"},{"level":"重点","text":"我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。","explain":"选择题考「宪法与普通法律的关系」的辨别，材料题常问「为什么说宪法是国家的根本法」。得分固定答三层：一是内容上，宪法规定国家生活中最根本、最重要的问题，如国家性质、根本制度、根本任务、公民的基本权利和义务、国家机构的组织及其职权等；二是效力上，宪法具有最高的法律效力，是其他法律的立法基础和立法依据，一切法律、行政法规和地方性法规都不得同宪法相抵触；三是程序上，宪法的制定和修改程序比普通法律更加严格。只写「宪法很重要」不给分。"},{"level":"次重点","text":"宪法是一切组织和个人的根本活动准则。一切组织和个人都必须在宪法和法律规定的范围内活动，任何组织或者个人都不得有超越宪法和法律的特权。","explain":"这是「维护宪法权威」的落脚点，判断改错题经常把「根本活动准则」改成「一般活动准则」，或把「任何组织或者个人」缩小为「一切国家机关」。答题可补一句「宪法是党和人民意志的集中体现，中国共产党领导人民制定宪法，也领导人民执行宪法，党自身必须在宪法和法律范围内活动」，这是公开的权威口径。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["宪法是国家的根本法，是治国安邦的总章程，是党和人民意志的集中体现。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法。"],["公民享有宪法规定的权利，所以公民可以直接依据宪法条文到人民法院起诉。","宪法是国家的根本法，具有最高的法律效力，一般不作司法裁判的直接依据；公民维护自己的具体权利，依据的是普通法律规定的权利内容和法定程序。","混淆了「宪法权利的最高性」与「法律适用的具体性」。遇到「依据宪法起诉」的选项要判为错误，正确的说法是「宪法是公民权利的保障书，公民依法享有宪法和法律规定的权利」。"]]},{"type":"table","title":"宪法与普通法律（二者都是我国法律体系中的法律，但在规定内容、法律效力、制定和修改程序上不同）（本单元概念对比）","head":["比较项","宪法","普通法律"],"rows":[["规定内容","国家生活中最根本、最重要的问题：国家性质、根本制度、根本任务、公民的基本权利和义务、国家机构的组织及其职权等","国家生活中某一方面的具体问题，如未成年人保护法只规定未成年人保护问题"],["法律效力","具有最高的法律效力，是其他法律的立法基础和立法依据","不得同宪法相抵触，否则无效"],["制定和修改程序","比普通法律更加严格：宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过","由全国人民代表大会以全体代表的过半数通过"],["地位","国家的根本法、治国安邦的总章程、公民权利的保障书","宪法的子法，只规范特定领域的社会关系"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["宪法地位的「三层式」论证","材料多给宪法条文、法律修订说明、国家宪法日活动或法律草案公开征求意见，设问为「为什么说宪法是国家的根本法」「宪法与普通法律有什么不同」。答题固定三层：内容上规定国家生活中最根本、最重要的问题；效力上具有最高的法律效力，其他法律不得同宪法相抵触，宪法是其他法律的立法基础和立法依据；程序上制定和修改比普通法律更加严格。三层缺一层就丢分。"],["宪法组织国家机构、规范权力运行","常以国家机构依法履职、政务公开、监督问责、备案审查纠正违宪违法的法规等素材设问，答题落在「宪法确认国家的一切权力属于人民」「宪法通过组织国家机构、授予国家机构特定职权，使国家权力的运行稳定有序」「我国国家机构实行民主集中制的原则」「加强对权力运行的制约和监督，把权力关进制度的笼子里」。作答时要写清「宪法授权」与「宪法限权」两条线。"],["依宪治国、宪法监督与公民宪法意识","设问多为「为什么要坚持依宪治国」「怎样加强宪法监督」「作为青少年，你打算怎样增强宪法意识」。答案三块：一是坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政；二是全国人民代表大会及其常务委员会行使监督宪法实施的职权，推进合宪性审查工作，加强备案审查制度和能力建设；三是学习宪法、认同宪法、践行宪法，维护宪法权威，同违反宪法的行为作斗争。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·坚持宪法至上（第1—2课：治国安邦的总章程 · 维护宪法权威）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-1-q1","type":"choice","stem":"下列关于我国宪法的说法正确的是","answer":"B","explain":"宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但不是普通法律的总和，A 错；宪法的制定和修改程序比普通法律更加严格，C 错；宪法既规定公民的基本权利，也规定公民的基本义务，D 错。","options":["宪法是普通法律的总和，涵盖了社会生活的各个方面","宪法是国家的根本法，具有最高的法律效力","宪法的制定和修改程序与普通法律完全相同","宪法只规定公民享有的权利，不规定公民应履行的义务"],"difficulty":1,"tags":["宪法地位","宪法与普通法律"]},{"id":"pol-law-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。\n② 国家的一切权力属于人民；人民行使国家权力的机关是全国人民代表大会和地方各级人民代…\n③ 中华人民共和国的国家机构实行民主集中制的原则。\n④ 宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法；正确表述应为：宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第一单元·坚持宪法至上（第1—2课：治国安邦的总章程 · 维护宪法权威）"]},{"id":"pol-law-1-q2","type":"choice","stem":"我国宪法规定，国家的一切权力属于人民。人民行使国家权力的机关是","answer":"D","explain":"宪法规定，人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。国务院是最高国家行政机关；人民法院是国家的审判机关，人民检察院是国家的法律监督机关；中国人民政治协商会议是中国共产党领导的多党合作和政治协商的重要机构，是中国人民爱国统一战线组织。四者都不是人民行使国家权力的机关。","options":["中国人民政治协商会议","国务院和地方各级人民政府","人民法院和人民检察院","全国人民代表大会和地方各级人民代表大会"],"difficulty":1,"tags":["国家权力属于人民","国家权力机关"]},{"id":"cat-pol-8b-1-1-short","type":"short","stem":"某班围绕「治国安邦的总章程」开展主题探究活动，围绕「党领导人民制定宪法」、「宪法的内容和作用」。请运用本课所学，谈谈你的认识。","answer":"坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。","explain":"","rubric":["坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。","我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。","宪法是一切组织和个人的根本活动准则。一切组织和个人都必须在宪法和法律规定的范围内…"],"tags":["治国安邦的总章程"]},{"id":"cat-pol-8b-1-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。\n② 我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。\n③ 宪法是一切组织和个人的根本活动准则。一切组织和个人都必须在宪法和法律规定的范围内…\n④ 宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法；正确表述应为：宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","difficulty":3,"tags":["第1课 治国安邦的总章程"]}]},{"id":"cat-pol-8b-1-2","title":"第2课 维护宪法权威","subtitle":"八年级下册 · 第一单元 坚持宪法至上","grade":"8b","tags":["八年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第一单元 坚持宪法至上"},{"k":"课题","v":"第2课 维护宪法权威"},{"k":"框题","v":"依宪治国 / 尊崇宪法"}]},{"type":"note","title":"本课在单元中的位置","text":"宪法是国家的根本法，是治国安邦的总章程、公民权利的保障书：它确认国家的一切权力属于人民、确认并保障公民的基本权利，又通过组织国家机构、规范国家权力运行，把权力关进制度的笼子；坚持依法治国首先要坚持依宪治国，加强宪法监督、维护宪法权威是全体公民的共同责任。这一单元是全册的「总纲」，中考材料题问「为什么」「说明了什么」，答案的第一句几乎都从这里起笔。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["依宪治国","尊崇宪法"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。","explain":"这是「维护宪法权威」一课的必背句，选择题常把「首先」换成「全面」「必须」「就要」来设误。材料题问「为什么要坚持依宪治国」，答法是：宪法是国家的根本法，是治国安邦的总章程，是党和人民意志的集中体现；依法治国是党领导人民治理国家的基本方略，法治是治国理政的基本方式；坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。"},{"level":"次重点","text":"宪法是一切组织和个人的根本活动准则。一切组织和个人都必须在宪法和法律规定的范围内活动，任何组织或者个人都不得有超越宪法和法律的特权。","explain":"这是「维护宪法权威」的落脚点，判断改错题经常把「根本活动准则」改成「一般活动准则」，或把「任何组织或者个人」缩小为「一切国家机关」。答题可补一句「宪法是党和人民意志的集中体现，中国共产党领导人民制定宪法，也领导人民执行宪法，党自身必须在宪法和法律范围内活动」，这是公开的权威口径。"},{"level":"次重点","text":"增强宪法意识，就要学习宪法、认同宪法、践行宪法；国家工作人员就职时应当依照法律规定公开进行宪法宣誓；每年 12 月 4 日是国家宪法日。","explain":"以宪法宣誓、国家宪法日活动、宪法宣传教育材料设问，答案落在「有利于增强国家工作人员和公民的宪法意识，维护宪法权威，保证宪法实施」。注意两点：一是宪法宣誓的主体是国家工作人员，选项写成「全体公民都必须宣誓」是错的；二是问「青少年怎样增强宪法意识」时按「学习—认同—践行」三层写，并加一句「积极参加国家宪法日等宣传活动，把宪法原则落实到日常行动中」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。","宪法的生命和权威在于实施；我们要增强宪法意识，学习宪法、认同宪法、践行宪法，维护宪法权威。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法。"],["国家的一切权力属于人民，所以每个公民都可以直接行使国家权力。","国家的一切权力属于人民，人民通过民主选举选出代表，组成各级人民代表大会代表人民行使国家权力；公民个人依法享有的是宪法和法律规定的各项权利，通过民主选举、民主协商、民主决策、民主管理、民主监督等途径参与国家和社会事务管理。","「权力」与「权利」同音不同义，是道法选择题最经典的设误点。凡见「公民直接行使国家权力」「公民行使国家权力」一律判错，规范的写法是「人民行使国家权力」「公民依法行使权利」。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["宪法地位的「三层式」论证","材料多给宪法条文、法律修订说明、国家宪法日活动或法律草案公开征求意见，设问为「为什么说宪法是国家的根本法」「宪法与普通法律有什么不同」。答题固定三层：内容上规定国家生活中最根本、最重要的问题；效力上具有最高的法律效力，其他法律不得同宪法相抵触，宪法是其他法律的立法基础和立法依据；程序上制定和修改比普通法律更加严格。三层缺一层就丢分。"],["宪法组织国家机构、规范权力运行","常以国家机构依法履职、政务公开、监督问责、备案审查纠正违宪违法的法规等素材设问，答题落在「宪法确认国家的一切权力属于人民」「宪法通过组织国家机构、授予国家机构特定职权，使国家权力的运行稳定有序」「我国国家机构实行民主集中制的原则」「加强对权力运行的制约和监督，把权力关进制度的笼子里」。作答时要写清「宪法授权」与「宪法限权」两条线。"],["依宪治国、宪法监督与公民宪法意识","设问多为「为什么要坚持依宪治国」「怎样加强宪法监督」「作为青少年，你打算怎样增强宪法意识」。答案三块：一是坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政；二是全国人民代表大会及其常务委员会行使监督宪法实施的职权，推进合宪性审查工作，加强备案审查制度和能力建设；三是学习宪法、认同宪法、践行宪法，维护宪法权威，同违反宪法的行为作斗争。"]]},{"type":"quote","text":"【材料一】《中华人民共和国宪法》规定：「一切法律、行政法规和地方性法规都不得同宪法相抵触。」「中华人民共和国的国家机构实行民主集中制的原则。」\n【材料二】我国现行宪法是 1982 年宪法，并历经 1988 年、1993 年、1999 年、2004 年、2018 年五次修改。宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。\n【材料三】每年 12 月 4 日是国家宪法日。国家工作人员就职时应当依照法律规定公开进行宪法宣誓，宪法宣誓誓词中有「维护宪法权威，履行法定职责」等内容。近年来，国家加强备案审查制度和能力建设，对与法律相抵触的地方性法规依法予以纠正。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第一单元·坚持宪法至上（第1—2课：治国安邦的总章程 · 维护宪法权威）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-1"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-1-m1-q2","type":"short","stem":"（2）材料三体现了我国在维护宪法权威方面采取了哪些举措？这些举措有什么意义？（6 分）","answer":"举措：①设立国家宪法日，加强宪法宣传教育；②实行宪法宣誓制度，国家工作人员就职时依照法律规定公开进行宪法宣誓；③加强宪法监督，推进合宪性审查工作，加强备案审查制度和能力建设，对与法律相抵触的地方性法规依法予以纠正。意义：①有利于增强国家工作人员和公民的宪法意识，维护宪法权威，保证宪法实施；②有利于加强对权力运行的制约和监督，把权力关进制度的笼子里，保障公民的合法权益；③有利于维护国家法制统一、尊严和权威，落实依宪治国、依宪执政的要求。","explain":"","tags":["宪法宣誓","宪法监督"],"rubric":["答出设立国家宪法日、加强宪法宣传教育","答出宪法宣誓制度及其主体是国家工作人员","答出加强宪法监督（合宪性审查、备案审查）","答出增强宪法意识、维护宪法权威、保证宪法实施","答出维护国家法制统一或规范权力运行"]},{"id":"pol-law-1-q5","type":"choice","stem":"国家工作人员就职时应当依照法律规定公开进行宪法宣誓。这一制度","answer":"B","explain":"宪法宣誓体现对宪法的尊崇，有利于增强国家工作人员的宪法意识、维护宪法权威、保证宪法实施。A 错，宪法是一切组织和个人的根本活动准则；C 错，宪法不能代替其他法律；D 错，任何组织或者个人都不得有超越宪法和法律的特权。","options":["表明宪法只对国家工作人员有约束力","有利于增强国家工作人员的宪法意识，维护宪法权威","说明宪法可以代替其他一切法律","表明国家工作人员享有超越宪法和法律的特权"],"difficulty":1,"tags":["宪法宣誓","宪法权威"]},{"id":"pol-law-1-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 我国宪法是国家的根本法，在国家法律体系中具有最高的法律地位、法律权威和法律效力。\n② 国家的一切权力属于人民；人民行使国家权力的机关是全国人民代表大会和地方各级人民代…\n③ 中华人民共和国的国家机构实行民主集中制的原则。\n④ 宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法；正确表述应为：宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第一单元·坚持宪法至上（第1—2课：治国安邦的总章程 · 维护宪法权威）"]},{"id":"pol-law-1-q3","type":"choice","stem":"我国宪法规定：「中华人民共和国的国家机构实行民主集中制的原则。」下列做法体现这一原则的是","answer":"A","explain":"民主集中制原则在国家机构与人民的关系上表现为国家权力来自人民、由人民选举产生国家权力机关，国家权力机关居于主导地位，其他国家机关由人民代表大会产生、对它负责、受它监督；在中央与地方国家机构的关系上，遵循在中央统一领导下，充分发挥地方的主动性、积极性的原则。B 错，我国不实行三权分立；C 错，违背在中央统一领导下的原则；D 错，国家机关必须依法行使职权。","options":["国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督","国家机关之间相互分立、相互制衡","地方国家机构完全不受中央国家机构的领导","国家机关行使权力不需要遵循法定程序"],"difficulty":3,"tags":["民主集中制","国家机构"]},{"id":"cat-pol-8b-1-2-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。\n② 宪法是一切组织和个人的根本活动准则。一切组织和个人都必须在宪法和法律规定的范围内…\n③ 增强宪法意识，就要学习宪法、认同宪法、践行宪法；国家工作人员就职时应当依照法律规…\n④ 宪法是国家的根本法，所以宪法是「法律大全」，其他法律都是宪法的一部分。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——常见设误是把「宪法是根本法」理解成「宪法管所有事」「其他法律都从宪法里抄来的」。答题要说清内容、效力、程序三层差别，用「立法基础和立法依据」「不得同宪法相抵触」这些规范说法；正确表述应为：宪法规定国家生活中最根本、最重要的问题，是其他法律的立法基础和立法依据，但宪法不是普通法律的总和，二者是「母法」与「子法」的关系，不能互相代替。","difficulty":3,"tags":["第2课 维护宪法权威"]}]},{"id":"cat-pol-8b-2-1","title":"第3课 公民的基本权利和义务","subtitle":"八年级下册 · 第二单元 理解权利义务","grade":"8b","tags":["八年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第二单元 理解权利义务"},{"k":"课题","v":"第3课 公民的基本权利和义务"},{"k":"框题","v":"公民基本权利 / 公民基本义务"}]},{"type":"note","title":"本课在单元中的位置","text":"宪法确认并保障公民的基本权利，也规定公民必须履行的基本义务；公民的权利与义务相互依存、相互促进，公民既是合法权利的享有者，又是法定义务的承担者。因此行使权利不能超越界限、不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利，维护权利要依法定途径，违反义务要依法承担相应的法律责任。这一单元是广州中考材料题的「常驻客」：给一个生活情境，问评析、问维权、问责任。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["公民基本权利","公民基本义务"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"了解","text":"在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。","explain":"属于识记型考点，常用来考「下列既属于权利又属于义务的是」，答案只能在劳动和受教育之间选。材料题若考「怎样理解」，要从权利与义务两个角度分别说明：作为权利，国家和社会应当予以保障，任何组织和个人不得非法剥夺；作为义务，公民不能随意放弃，不履行要承担相应的法律责任。"},{"level":"重点","text":"我国宪法规定的公民基本义务包括：遵守宪法和法律，维护国家利益，依法服兵役，依法纳税，以及劳动、受教育、夫妻双方实行计划生育、父母抚养教育未成年子女、成年子女赡养扶助父母等义务。","explain":"选择题常考「下列属于公民基本义务的是」，要把基本义务与公民权利区分开：选举权和被选举权、财产权、继承权、申请专利都是权利，不是义务。「维护国家利益」包括维护国家统一和全国各民族团结，维护国家安全、荣誉和利益。答题要写义务的具体名称，不写「要爱国」「要听话」这类口语。"},{"level":"重点","text":"我国公民依法享有政治权利，包括选举权和被选举权、政治自由和监督权；选举权和被选举权是公民的一项基本政治权利，是公民参与管理国家和管理社会的基础。","explain":"选择题常在「谁享有选举权和被选举权」上设误：必须是年满十八周岁的我国公民，且未被依法剥夺政治权利。政治自由指言论、出版、集会、结社、游行、示威的自由；监督权包括批评权、建议权、申诉权、控告权、检举权。答题要写全「权利名称 + 地位」，如「选举权和被选举权是公民参与管理国家和管理社会的基础」。"},{"level":"重点","text":"人身自由是公民最基本、最重要的权利，包括人身自由不受侵犯、人格尊严不受侵犯、住宅不受侵犯、通信自由和通信秘密受法律保护。","explain":"常以非法搜身、强行搜包、公开他人隐私、私拆信件、擅自公开他人电话号码等生活情境设题，问「侵犯了公民的什么权利」。答题要点名具体权利：「人身自由不受侵犯」「人格尊严不受侵犯」「住宅不受侵犯」「通信自由和通信秘密受法律保护」，不要笼统写「侵犯了公民权利」。人格尊严不受侵犯还包括姓名权、肖像权、名誉权、荣誉权、隐私权不受侵犯。"},{"level":"重点","text":"我国公民依法享有社会经济与文化教育权利，包括财产权、劳动权、物质帮助权、受教育权和文化权利；公民还平等地享有宗教信仰自由等权利，妇女、儿童、残疾人等特定人群的权利受到宪法和法律的保障。","explain":"多以选择题出现，考「这属于哪一类权利」的归类。归类口诀：钱、工作、救助属社会经济权利；上学、进行科学研究、文艺创作属文化教育权利。答题时写清权利类别与具体名称，不要只写「这是他的权利」。"},{"level":"重点","text":"公民行使权利不能超越它本身的界限，不能滥用权利；公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。","explain":"这是「依法行使权利」一课的核心句，也是宪法第五十一条的规范表述。材料题常以「我的地盘我做主」「我自己家的东西想怎么用就怎么用」「网上说话是我自己的自由」等说法设问，要求评析。答题三步：先指出权利有界限、不能滥用；再指出该行为损害了他人什么合法权益；最后落到「依法行使权利，尊重他人权利，违反法律要承担相应的法律责任」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["选举权和被选举权是公民的一项基本政治权利，是公民参与管理国家和管理社会的基础。","人身自由是公民最基本、最重要的权利。","任何权利都是有范围的，公民行使权利不能超越它本身的界限，不能滥用权利；公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。","公民的权利与义务相互依存、相互促进，权利的实现需要义务的履行，义务的履行促进权利的实现；我们既要依法行使权利，又要自觉履行法定义务。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["权利就是义务，义务就是权利，二者是一回事，可以互相替代。","权利与义务相互依存、相互促进，但不是一回事：权利是宪法和法律赋予公民享有的权益，义务是公民必须履行的责任；权利一般可以依法放弃，义务具有强制性，必须履行。只有劳动、受教育等既是公民的基本权利，也是公民的基本义务。","最常见的设误是「既然权利与义务相统一，那么不履行义务也就等于放弃了权利，不用承担法律责任」。「相统一」讲的是二者的关系，不能推出「义务可以放弃」。"],["公民的住宅不受侵犯，所以公安机关在任何情况下都不能进入公民住宅。","宪法规定，中华人民共和国公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅。也就是说，法律禁止的是「非法」搜查或侵入；公安、司法机关依照法定程序、依法定事由进行的搜查，是依法履行职责，不属于侵犯公民住宅权。","把「不受侵犯」理解成「绝对不许进入」，就掉进了绝对化的陷阱。答题要抓住「非法」二字，并把「依法定程序」写出来；同理，人身自由不受侵犯禁止的是非法拘禁和以其他方法非法剥夺、限制公民人身自由，以及非法搜查公民的身体。"]]},{"type":"table","title":"公民的权利与公民的义务（同一主体身上的两种法律地位，既相互依存又性质不同）（本单元概念对比）","head":["比较项","公民的权利","公民的义务"],"rows":[["含义","宪法和法律赋予公民享有的权益","宪法和法律规定公民必须履行的责任"],["能否放弃","一般可以依法放弃（法律规定不得放弃的除外）","具有强制性，必须履行，不能放弃"],["典型例子","选举权和被选举权、政治自由、人身自由、财产权、受教育权、劳动权","遵守宪法和法律、维护国家利益、依法服兵役、依法纳税、受教育、劳动"],["不行使／不履行的后果","不行使权利一般只影响自身利益，不承担法律责任","违反法定义务必须依法承担民事责任、行政责任或刑事责任"],["关系","权利的实现需要义务的履行，义务的履行促进权利的实现，二者相互依存、相互促进","同左：坚持权利与义务相统一，既要依法行使权利，又要自觉履行义务"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["以生活情境考查「依法行使权利」","材料多为高空抛物、遛狗不拴绳、噪声扰民、网上发布他人隐私、公共场所大声喧哗等情境，设问「请从权利与义务关系的角度评析某某的言行」。答题四步：①判断言行对错；②答出公民的权利与义务相统一；③指出行使权利不能超越界限、不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利；④指出该行为侵犯了他人什么权利、应承担什么法律责任。"],["维权方式的判断与选择","给纠纷情境问「可以通过哪些途径解决」。先把协商、调解、仲裁、诉讼四种方式答全，再按纠纷性质选择：平等主体之间的财产、人身纠纷可协商、调解、仲裁或提起民事诉讼；与行政机关的争议提起行政诉讼；涉及犯罪由公安、司法机关依法处理，被害人可以依法提起刑事诉讼。补一句「诉讼是维护合法权益的最后屏障」，并提示「要依法收集和保存证据」。"],["公民基本义务与法律责任的承担","常以拒服兵役、偷税漏税、泄露国家秘密、打架斗殴、侵犯他人财产等素材设问「他应承担什么责任」。答题要分清三种法律责任：侵犯他人人身、财产权益的承担民事责任；违反行政管理秩序的承担行政责任（警告、罚款、行政拘留等）；触犯刑法构成犯罪的承担刑事责任（受刑罚处罚）。要特别强调「法定义务具有强制性」「法律要求做的必须去做，法律禁止做的坚决不做」。"]]},{"type":"quote","text":"【材料一】我国宪法规定：「中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。」\n【材料二】某小区居民王某在自家阳台养花，花盆放置不牢固，邻居多次提醒他也不理会。一天花盆坠落，砸坏了楼下李某停放的汽车。李某要求赔偿，王某却说：「我在自己家里养花是我的权利，跟你没关系。」\n【材料三】我国宪法规定：「任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。」在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·理解权利义务（第3—4课：公民的基本权利和义务 · 依法行使权利和履行义务）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-2"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-2-m1-q3","type":"short","stem":"（3）结合材料三，谈谈你对「劳动和受教育既是公民的基本权利，也是公民的基本义务」的理解。（4 分）","answer":"①在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。②作为权利，公民有权依法获得劳动就业、接受教育的机会，国家和社会应当予以保障，任何组织和个人不得非法剥夺。③作为义务，公民应当依法参加劳动、接受教育，不能随意放弃，不履行要承担相应的法律责任。④这说明公民的权利与义务相互依存、相互促进，我们既要依法行使权利，又要自觉履行义务。","explain":"","tags":["基本权利与基本义务","权利与义务相统一"],"rubric":["答出劳动和受教育既是公民的基本权利又是基本义务","从权利角度说明应受国家和社会保障","从义务角度说明不可随意放弃、不履行要承担责任","答出坚持权利与义务相统一"]},{"id":"pol-law-2-q1","type":"choice","stem":"我国公民的一项基本政治权利，也是公民参与管理国家和管理社会的基础，这项权利是","answer":"A","explain":"选举权和被选举权是公民的一项基本政治权利，是公民参与管理国家和管理社会的基础；财产权属于社会经济权利，受教育权属于文化教育权利，宗教信仰自由是公民享有的其他权利。","options":["选举权和被选举权","财产权","受教育权","宗教信仰自由"],"difficulty":1,"tags":["政治权利","选举权和被选举权"]},{"id":"pol-law-2-q2","type":"choice","stem":"下列行为中，侵犯公民人身自由的是","answer":"D","explain":"人身自由不受侵犯，禁止非法搜查公民的身体，商场保安强行搜身侵犯了顾客的人身自由。A、B 是公安、审判机关依法履行职责；C 属于侵犯他人隐私、人格尊严的行为，不是直接侵害人身自由。","options":["公安机关依法对犯罪嫌疑人执行刑事拘留","人民法院依法对被告人进行审判","小张未经同意在网上公开同学的家庭住址和身份证号码","商场保安怀疑顾客偷拿商品，强行对该顾客搜身"],"difficulty":2,"tags":["人身自由","人格尊严"]},{"id":"pol-law-2-q3","type":"choice","stem":"「我的地盘我做主，我想干什么就干什么。」这一说法","answer":"C","explain":"任何权利都是有范围的，公民行使权利不能超越它本身的界限，不能滥用权利，行使自由和权利时不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。D 错，我国宪法和法律确认并保障公民享有广泛的自由和权利。","options":["正确，公民的权利是不受任何限制的","正确，公民有权自由支配自己的财产","错误，公民行使权利不能超越界限，不得损害其他公民的合法的自由和权利","错误，因为我国公民不享有自由和权利"],"difficulty":1,"tags":["依法行使权利","权利的界限"]},{"id":"pol-law-2-q4","type":"choice","stem":"下列属于我国公民基本义务的是","answer":"A","explain":"依法纳税是宪法规定的公民基本义务。依法参加选举是公民的政治权利；申请专利、继承遗产都是公民依法享有的民事权利，不是义务。","options":["依法纳税","依法参加选举","依法申请专利","依法继承遗产"],"difficulty":1,"tags":["公民基本义务"]}]},{"id":"cat-pol-8b-2-2","title":"第4课 依法行使权利和履行义务","subtitle":"八年级下册 · 第二单元 理解权利义务","grade":"8b","tags":["八年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第二单元 理解权利义务"},{"k":"课题","v":"第4课 依法行使权利和履行义务"},{"k":"框题","v":"权利与义务相统一 / 依法行使权利 / 依法履行义务"}]},{"type":"note","title":"本课在单元中的位置","text":"宪法确认并保障公民的基本权利，也规定公民必须履行的基本义务；公民的权利与义务相互依存、相互促进，公民既是合法权利的享有者，又是法定义务的承担者。因此行使权利不能超越界限、不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利，维护权利要依法定途径，违反义务要依法承担相应的法律责任。这一单元是广州中考材料题的「常驻客」：给一个生活情境，问评析、问维权、问责任。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["权利与义务相统一","依法行使权利","依法履行义务"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"公民的权利与义务相统一：公民的权利与义务相互依存、相互促进，公民既是合法权利的享有者，又是法定义务的承担者；权利的实现需要义务的履行，义务的履行促进权利的实现。","explain":"凡涉及权利与义务关系的设问，先写这一句再展开，它是本单元材料题的第一得分点。举例时用劳动、受教育最稳妥，不要举「纳税既是权利又是义务」这种错误例子。若题干给「只想享受权利、不愿履行义务」的言行，还要补一句「坚持权利与义务相统一，增强权利意识和义务观念」。"},{"level":"了解","text":"在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。","explain":"属于识记型考点，常用来考「下列既属于权利又属于义务的是」，答案只能在劳动和受教育之间选。材料题若考「怎样理解」，要从权利与义务两个角度分别说明：作为权利，国家和社会应当予以保障，任何组织和个人不得非法剥夺；作为义务，公民不能随意放弃，不履行要承担相应的法律责任。"},{"level":"重点","text":"公民行使权利不能超越它本身的界限，不能滥用权利；公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。","explain":"这是「依法行使权利」一课的核心句，也是宪法第五十一条的规范表述。材料题常以「我的地盘我做主」「我自己家的东西想怎么用就怎么用」「网上说话是我自己的自由」等说法设问，要求评析。答题三步：先指出权利有界限、不能滥用；再指出该行为损害了他人什么合法权益；最后落到「依法行使权利，尊重他人权利，违反法律要承担相应的法律责任」。"},{"level":"重点","text":"我国宪法规定的公民基本义务包括：遵守宪法和法律，维护国家利益，依法服兵役，依法纳税，以及劳动、受教育、夫妻双方实行计划生育、父母抚养教育未成年子女、成年子女赡养扶助父母等义务。","explain":"选择题常考「下列属于公民基本义务的是」，要把基本义务与公民权利区分开：选举权和被选举权、财产权、继承权、申请专利都是权利，不是义务。「维护国家利益」包括维护国家统一和全国各民族团结，维护国家安全、荣誉和利益。答题要写义务的具体名称，不写「要爱国」「要听话」这类口语。"},{"level":"次重点","text":"法定义务具有强制性，必须履行：法律要求做的，我们必须去做；法律禁止做的，我们坚决不做。违反法定义务，必须依法承担相应的法律责任。","explain":"常与「承担什么责任」合考。三种责任要分清：侵犯他人人身、财产权益的承担民事责任（如赔偿损失、赔礼道歉）；违反行政管理秩序的承担行政责任（如警告、罚款、没收违法所得、行政拘留）；触犯刑法构成犯罪的承担刑事责任（受刑罚处罚）。特别提醒「罚款」是行政处罚、「罚金」是刑罚，一字之差决定对错。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["公民的权利与义务相互依存、相互促进，权利的实现需要义务的履行，义务的履行促进权利的实现；我们既要依法行使权利，又要自觉履行法定义务。","选举权和被选举权是公民的一项基本政治权利，是公民参与管理国家和管理社会的基础。","人身自由是公民最基本、最重要的权利。","任何权利都是有范围的，公民行使权利不能超越它本身的界限，不能滥用权利；公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。","法定义务具有强制性：法律要求做的必须去做，法律禁止做的坚决不做，违反法定义务必须依法承担相应的法律责任。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["权利就是义务，义务就是权利，二者是一回事，可以互相替代。","权利与义务相互依存、相互促进，但不是一回事：权利是宪法和法律赋予公民享有的权益，义务是公民必须履行的责任；权利一般可以依法放弃，义务具有强制性，必须履行。只有劳动、受教育等既是公民的基本权利，也是公民的基本义务。","最常见的设误是「既然权利与义务相统一，那么不履行义务也就等于放弃了权利，不用承担法律责任」。「相统一」讲的是二者的关系，不能推出「义务可以放弃」。"],["法定义务和道德义务一样，不履行只会受到道德谴责。","法定义务是由我国宪法和法律规定的，具有强制性，不履行要承担相应的法律责任（民事责任、行政责任或刑事责任）；道德义务是在社会生活中形成的，靠社会舆论、风俗习惯和人们的信念来维持，不履行会受到道德谴责，但不是法律制裁。","「道德义务」与「法定义务」极易混用。判断规则：看有没有法律明文规定、看违反后承担的是法律责任还是道德谴责。答题时写「法律要求做的必须去做，法律禁止做的坚决不做」最稳。"],["公民的住宅不受侵犯，所以公安机关在任何情况下都不能进入公民住宅。","宪法规定，中华人民共和国公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅。也就是说，法律禁止的是「非法」搜查或侵入；公安、司法机关依照法定程序、依法定事由进行的搜查，是依法履行职责，不属于侵犯公民住宅权。","把「不受侵犯」理解成「绝对不许进入」，就掉进了绝对化的陷阱。答题要抓住「非法」二字，并把「依法定程序」写出来；同理，人身自由不受侵犯禁止的是非法拘禁和以其他方法非法剥夺、限制公民人身自由，以及非法搜查公民的身体。"]]},{"type":"table","title":"公民的权利与公民的义务（同一主体身上的两种法律地位，既相互依存又性质不同）（本单元概念对比）","head":["比较项","公民的权利","公民的义务"],"rows":[["含义","宪法和法律赋予公民享有的权益","宪法和法律规定公民必须履行的责任"],["能否放弃","一般可以依法放弃（法律规定不得放弃的除外）","具有强制性，必须履行，不能放弃"],["典型例子","选举权和被选举权、政治自由、人身自由、财产权、受教育权、劳动权","遵守宪法和法律、维护国家利益、依法服兵役、依法纳税、受教育、劳动"],["不行使／不履行的后果","不行使权利一般只影响自身利益，不承担法律责任","违反法定义务必须依法承担民事责任、行政责任或刑事责任"],["关系","权利的实现需要义务的履行，义务的履行促进权利的实现，二者相互依存、相互促进","同左：坚持权利与义务相统一，既要依法行使权利，又要自觉履行义务"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["以生活情境考查「依法行使权利」","材料多为高空抛物、遛狗不拴绳、噪声扰民、网上发布他人隐私、公共场所大声喧哗等情境，设问「请从权利与义务关系的角度评析某某的言行」。答题四步：①判断言行对错；②答出公民的权利与义务相统一；③指出行使权利不能超越界限、不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利；④指出该行为侵犯了他人什么权利、应承担什么法律责任。"],["维权方式的判断与选择","给纠纷情境问「可以通过哪些途径解决」。先把协商、调解、仲裁、诉讼四种方式答全，再按纠纷性质选择：平等主体之间的财产、人身纠纷可协商、调解、仲裁或提起民事诉讼；与行政机关的争议提起行政诉讼；涉及犯罪由公安、司法机关依法处理，被害人可以依法提起刑事诉讼。补一句「诉讼是维护合法权益的最后屏障」，并提示「要依法收集和保存证据」。"],["公民基本义务与法律责任的承担","常以拒服兵役、偷税漏税、泄露国家秘密、打架斗殴、侵犯他人财产等素材设问「他应承担什么责任」。答题要分清三种法律责任：侵犯他人人身、财产权益的承担民事责任；违反行政管理秩序的承担行政责任（警告、罚款、行政拘留等）；触犯刑法构成犯罪的承担刑事责任（受刑罚处罚）。要特别强调「法定义务具有强制性」「法律要求做的必须去做，法律禁止做的坚决不做」。"]]},{"type":"quote","text":"【材料一】我国宪法规定：「中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。」\n【材料二】某小区居民王某在自家阳台养花，花盆放置不牢固，邻居多次提醒他也不理会。一天花盆坠落，砸坏了楼下李某停放的汽车。李某要求赔偿，王某却说：「我在自己家里养花是我的权利，跟你没关系。」\n【材料三】我国宪法规定：「任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。」在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第二单元·理解权利义务（第3—4课：公民的基本权利和义务 · 依法行使权利和履行义务）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-2"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-2-m1-q1","type":"short","stem":"（1）材料二中王某的说法对吗？请运用权利与义务的关系加以评析。（6 分）","answer":"王某的说法是错误的。①公民的权利与义务相互依存、相互促进，公民既是合法权利的享有者，又是法定义务的承担者，坚持权利与义务相统一。②任何权利都是有范围的，公民行使权利不能超越它本身的界限，不能滥用权利；公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。③王某在自家阳台养花是他的权利，但他放置花盆不牢固、对邻居提醒置之不理，导致花盆坠落砸坏他人汽车，侵犯了李某的财产权。④王某应当依法承担民事责任，赔偿李某的损失；我们应增强权利意识和义务观念，依法行使权利、自觉履行义务，尊重他人的合法权利。","explain":"","tags":["权利与义务相统一","依法行使权利"],"rubric":["作出判断：王某的说法错误","答出权利与义务相统一（相互依存、相互促进）","答出行使权利不能超越界限、不得损害他人合法的自由和权利","指出王某侵犯了李某的财产权","答出应承担民事责任／赔偿损失，并提出应有的态度"]},{"id":"pol-law-2-m1-q3","type":"short","stem":"（3）结合材料三，谈谈你对「劳动和受教育既是公民的基本权利，也是公民的基本义务」的理解。（4 分）","answer":"①在我国，劳动和受教育既是公民的基本权利，也是公民的基本义务。②作为权利，公民有权依法获得劳动就业、接受教育的机会，国家和社会应当予以保障，任何组织和个人不得非法剥夺。③作为义务，公民应当依法参加劳动、接受教育，不能随意放弃，不履行要承担相应的法律责任。④这说明公民的权利与义务相互依存、相互促进，我们既要依法行使权利，又要自觉履行义务。","explain":"","tags":["基本权利与基本义务","权利与义务相统一"],"rubric":["答出劳动和受教育既是公民的基本权利又是基本义务","从权利角度说明应受国家和社会保障","从义务角度说明不可随意放弃、不履行要承担责任","答出坚持权利与义务相统一"]},{"id":"pol-law-2-q1","type":"choice","stem":"我国公民的一项基本政治权利，也是公民参与管理国家和管理社会的基础，这项权利是","answer":"A","explain":"选举权和被选举权是公民的一项基本政治权利，是公民参与管理国家和管理社会的基础；财产权属于社会经济权利，受教育权属于文化教育权利，宗教信仰自由是公民享有的其他权利。","options":["选举权和被选举权","财产权","受教育权","宗教信仰自由"],"difficulty":1,"tags":["政治权利","选举权和被选举权"]},{"id":"pol-law-2-q3","type":"choice","stem":"「我的地盘我做主，我想干什么就干什么。」这一说法","answer":"C","explain":"任何权利都是有范围的，公民行使权利不能超越它本身的界限，不能滥用权利，行使自由和权利时不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。D 错，我国宪法和法律确认并保障公民享有广泛的自由和权利。","options":["正确，公民的权利是不受任何限制的","正确，公民有权自由支配自己的财产","错误，公民行使权利不能超越界限，不得损害其他公民的合法的自由和权利","错误，因为我国公民不享有自由和权利"],"difficulty":1,"tags":["依法行使权利","权利的界限"]},{"id":"pol-law-2-q4","type":"choice","stem":"下列属于我国公民基本义务的是","answer":"A","explain":"依法纳税是宪法规定的公民基本义务。依法参加选举是公民的政治权利；申请专利、继承遗产都是公民依法享有的民事权利，不是义务。","options":["依法纳税","依法参加选举","依法申请专利","依法继承遗产"],"difficulty":1,"tags":["公民基本义务"]},{"id":"pol-law-2-q6","type":"choice","stem":"违反法定义务要依法承担相应的法律责任。下列属于行政责任的是","answer":"C","explain":"罚款是行政处罚，属于行政责任；赔偿损失是民事责任；罚金和管制都是刑事责任中的刑罚（管制属于主刑，罚金属于附加刑）。「罚款」与「罚金」一字之差、责任性质完全不同，是高频易错点。","options":["赔偿损失","罚金","罚款","管制"],"difficulty":3,"tags":["法律责任","罚款与罚金"]}]},{"id":"cat-pol-8b-3-1","title":"第5课 我国的政治制度","subtitle":"八年级下册 · 第三单元 认识国家制度","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 认识国家制度"},{"k":"课题","v":"第5课 我国的政治制度"},{"k":"框题","v":"人民代表大会制度 / 中国共产党领导的多党合作和政治协商制度 / 民族区域自治制度 / 基层群众自治制度"}]},{"type":"note","title":"本课在单元中的位置","text":"国家的一切权力属于人民，人民通过人民代表大会制度当家作主：人民代表大会制度是我国的根本政治制度，中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国的基本政治制度，发展全过程人民民主，保障人民当家作主；我国还坚持公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度，为实现共同富裕提供制度保障。这一单元在中考里以「制度名称 + 制度地位 + 优越性」的规范表述给分。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人民代表大会制度","中国共产党领导的多党合作和政治协商制度","民族区域自治制度","基层群众自治制度"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"我国的基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。","explain":"选择题常考「下列属于我国基本政治制度的是」。「根本」只有一个，「基本」有三个，记忆口诀：根本是人民代表大会制度，基本是政党制度、民族区域自治、基层群众自治。中国人民政治协商会议是中国共产党领导的多党合作和政治协商的重要机构，是中国人民爱国统一战线组织，不是国家机关，也不是「我国的国家权力机关」。"},{"level":"次重点","text":"我国实行民族区域自治，在少数民族聚居的地方实行区域自治，设立自治机关，行使自治权；民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。","explain":"考「自治机关是哪些」时只有人民代表大会和人民政府，写成人民法院、人民检察院、人民政协都是错的；我国民族自治地方分为自治区、自治州、自治县三级。答题要补一句「民族区域自治制度是我国的一项基本政治制度，有利于把国家的集中、统一与各民族的自主、平等结合起来」。"},{"level":"次重点","text":"基层群众自治制度是我国的一项基本政治制度；村民委员会、居民委员会是基层群众性自治组织，实行基层群众自治有利于人民群众直接行使民主权利，管理基层公共事务和公益事业，是社会主义民主政治的基础性工程。","explain":"以村民议事会、社区议事厅、居民公约等材料设问，答案落在「人民群众直接行使民主权利」「社会主义民主政治的基础性工程」。提醒两点：一是村民委员会、居民委员会不是国家机关，不能说成「基层政权」或「基层政府」；二是这里用的是「直接行使民主权利」，与「人民通过人民代表大会间接行使国家权力」要分清。"},{"level":"重点","text":"人民代表大会制度是我国的根本政治制度，是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排。","explain":"必背结论，常考「我国的根本政治制度是什么」以及「为什么说人民代表大会制度是好制度」。答「基本内容」要写全四层：国家的一切权力属于人民；人民通过民主选举选出代表，组成各级人民代表大会作为国家权力机关；由人民代表大会产生国家行政机关、监察机关、审判机关、检察机关，这些国家机关依法行使各自的职权，并对人民代表大会负责，受人民代表大会监督；实行民主集中制。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["我国的基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。","人民代表大会制度是我国的根本政治制度，是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排。","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["民族区域自治制度是我国的根本政治制度。","人民代表大会制度是我国的根本政治制度；中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国的基本政治制度。","「根本」只有一个，「基本」有三个，是选择题最常设的陷阱。记忆口诀：根本是人民代表大会制度，基本是政党制度、民族区域自治、基层群众自治。"],["人民代表大会和人民代表大会制度是一回事，都指人民代表大会这个国家机关。","人民代表大会是我国的国家权力机关，包括全国人民代表大会和地方各级人民代表大会，是一个具体的国家机关；人民代表大会制度是我国的根本政治制度，是包括国家权力机关与其他国家机关的产生、职权、相互关系在内的一整套制度安排，是我国人民当家作主的重要途径和最高实现形式。","「机关」与「制度」不能混为一谈。答题时问「我国的根本政治制度是什么」，只能答「人民代表大会制度」；问「国家权力机关是什么」，只能答「人民代表大会」；问「人民行使国家权力的机关是什么」，答「全国人民代表大会和地方各级人民代表大会」。"]]},{"type":"table","title":"我国的根本政治制度与基本政治制度（三组政治制度的名称、地位与核心内容，考「是哪一类制度」时不能错位）（本单元概念对比）","head":["比较项","根本政治制度","基本政治制度"],"rows":[["名称","人民代表大会制度","中国共产党领导的多党合作和政治协商制度；民族区域自治制度；基层群众自治制度"],["核心内容","国家的一切权力属于人民；人民通过民主选举选出代表，组成各级人民代表大会作为国家权力机关；由人民代表大会产生其他国家机关，对它负责、受它监督；实行民主集中制","政党制度：中国共产党同各民主党派实行「长期共存、互相监督、肝胆相照、荣辱与共」的基本方针；民族区域自治：在少数民族聚居的地方实行区域自治，设立自治机关，行使自治权；基层群众自治：村民委员会、居民委员会是基层群众性自治组织"],["答题落点","人民当家作主的重要途径和最高实现形式，是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排","都是社会主义民主政治的重要内容，基层群众自治是社会主义民主政治的基础性工程"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["人民代表大会制度的「一条链条」论证","常给全国人民代表大会会议议程、人大代表提出议案、基层立法联系点、人大代表联络站等材料，设问「这些材料体现了人民代表大会制度的哪些内容」。答题用一条链条：国家的一切权力属于人民 → 人民通过民主选举选出代表，组成人民代表大会作为国家权力机关 → 由人民代表大会产生其他国家机关并对它负责、受它监督 → 实行民主集中制 → 落脚在「人民代表大会制度是我国的根本政治制度」，最后补一句优越性的规范表述。"],["全过程人民民主的「五个民主」","以社区议事、立法征求意见、价格听证、村务公开、政府评议等情境设问「材料体现了公民参与民主生活的哪些形式」「为什么说全过程人民民主是最广泛、最真实、最管用的民主」。答案先把民主选举、民主协商、民主决策、民主管理、民主监督写全，再落到「全过程人民民主是社会主义民主政治的本质属性」「人民民主的真谛是有事好商量，众人的事情由众人商量」。"],["基本经济制度与共同富裕","以民营经济发展、国有企业改革、居民收入分配、乡村振兴等素材设问。答题落在「公有制为主体、多种所有制经济共同发展」「公有制经济和非公有制经济都是社会主义市场经济的重要组成部分」「坚持按劳分配为主体、多种分配方式并存」「市场在资源配置中起决定性作用，更好发挥政府作用」，并要求答出「两个毫不动摇」的完整表述。"],["基层群众自治与民族区域自治的「主体判断」","给村（居）民议事、居民公约、民族自治地方行使自治权等材料，设问「材料体现了哪一项政治制度」「自治机关是哪些」。判断口诀：主体是村民委员会、居民委员会的是基层群众自治制度，注意它们不是国家机关；主体是自治区、自治州、自治县的人民代表大会和人民政府的才是民族区域自治的自治机关，人民法院、人民检察院与人民政协都不是自治机关。"]]},{"type":"quote","text":"【材料一】全国人民代表大会会议听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告。\n【材料二】某市在制定生活垃圾管理条例时，通过基层立法联系点、网络平台公开征求市民意见，召开多场座谈会听取居民、企业、专家意见，许多建议被采纳；某社区通过居民议事会商议解决小区停车难问题，居民充分发表意见，形成一致方案后由居民委员会组织实施。\n【材料三】近年来，国家坚持和落实「两个毫不动摇」，出台一系列政策措施促进民营经济发展壮大，同时深化国有企业改革，推动国有资本和国有企业做强做优做大。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·认识国家制度（第5—6课：我国的政治制度 · 我国的基本经济制度）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-3-m1-q1","type":"short","stem":"（1）据材料一，说明我国人民是怎样当家作主的。（6 分）","answer":"①我国是人民民主专政的社会主义国家，国家的一切权力属于人民，人民是国家的主人。②人民通过民主选举选出代表，组成各级人民代表大会作为国家权力机关，由人民代表大会代表人民行使国家权力。③国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督，从而保证国家权力始终掌握在人民手中。④实行民主集中制，人民代表大会统一行使国家权力，其他国家机关依法行使各自的职权。⑤人民代表大会制度是我国的根本政治制度，是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排。","explain":"","tags":["人民代表大会制度","人民当家作主"],"rubric":["答出国家的一切权力属于人民","答出人民通过民主选举选出代表，组成人民代表大会行使国家权力","答出其他国家机关由人民代表大会产生，对它负责，受它监督","答出实行民主集中制","答出人民代表大会制度是我国的根本政治制度","分点作答、术语规范"]},{"id":"pol-law-3-q1","type":"choice","stem":"我国的根本政治制度是","answer":"D","explain":"人民代表大会制度是我国的根本政治制度；中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度都是我国的基本政治制度，不能与「根本政治制度」混淆。","options":["中国共产党领导的多党合作和政治协商制度","民族区域自治制度","基层群众自治制度","人民代表大会制度"],"difficulty":1,"tags":["根本政治制度","基本政治制度"]},{"id":"pol-law-3-q3","type":"choice","stem":"我国在少数民族聚居的地方实行区域自治，设立自治机关，行使自治权。民族自治地方的自治机关是","answer":"A","explain":"民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。人民法院、人民检察院是国家的审判机关和法律监督机关，人民政协是爱国统一战线组织，都不是自治机关。","options":["自治区、自治州、自治县的人民代表大会和人民政府","自治区、自治州、自治县的人民法院和人民检察院","民族自治地方的人民政治协商会议","民族自治地方的所有国家机关"],"difficulty":3,"tags":["民族区域自治制度","自治机关"]},{"id":"pol-law-3-q4","type":"choice","stem":"某社区居民通过居民议事会商议解决小区停车难问题，形成一致方案后由居民委员会组织实施。这体现了","answer":"C","explain":"村民委员会、居民委员会是基层群众性自治组织，居民通过居民议事会商议解决社区公共事务，体现的是基层群众自治制度，它有利于人民群众直接行使民主权利，是社会主义民主政治的基础性工程。注意居民委员会不是国家机关。","options":["人民代表大会制度","民族区域自治制度","基层群众自治制度","中国共产党领导的多党合作和政治协商制度"],"difficulty":1,"tags":["基层群众自治制度","基本政治制度"]},{"id":"pol-law-3-q6","type":"choice","stem":"下列不属于我国基本经济制度内容的是","answer":"D","explain":"基层群众自治制度是我国的一项基本政治制度，不属于基本经济制度。我国的基本经济制度包括公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制三个方面。「政治制度」与「经济制度」不能混为一类。","options":["公有制为主体、多种所有制经济共同发展","按劳分配为主体、多种分配方式并存","社会主义市场经济体制","基层群众自治制度"],"difficulty":2,"tags":["基本经济制度","基本政治制度"]}]},{"id":"cat-pol-8b-3-2","title":"第6课 我国的基本经济制度","subtitle":"八年级下册 · 第三单元 认识国家制度","grade":"8b","tags":["八年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第三单元 认识国家制度"},{"k":"课题","v":"第6课 我国的基本经济制度"},{"k":"框题","v":"公有制为主体、多种所有制经济共同发展 / 按劳分配为主体、多种分配方式并存 / 社会主义市场经济体制"}]},{"type":"note","title":"本课在单元中的位置","text":"国家的一切权力属于人民，人民通过人民代表大会制度当家作主：人民代表大会制度是我国的根本政治制度，中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国的基本政治制度，发展全过程人民民主，保障人民当家作主；我国还坚持公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度，为实现共同富裕提供制度保障。这一单元在中考里以「制度名称 + 制度地位 + 优越性」的规范表述给分。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["公有制为主体、多种所有制经济共同发展","按劳分配为主体、多种分配方式并存","社会主义市场经济体制"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"我国的基本经济制度包括：公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制。","explain":"常用民营经济发展、国有企业改革、居民收入分配等材料设问，要求写出「基本经济制度包括哪三个方面」。答题要点：公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础；坚持毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展；坚持按劳分配为主体、多种分配方式并存；发挥市场在资源配置中的决定性作用，更好发挥政府作用。"},{"level":"次重点","text":"国有经济是国民经济的主导力量；集体经济是公有制经济的重要组成部分；公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础。","explain":"这三个「地位句」是高频命题点，一个字都不能错。典型设误有：「非公有制经济是我国社会主义经济的重要组成部分」（丢掉「市场」二字）、「非公有制经济是我国国民经济的主体」（主体是公有制经济）、「国有经济是我国国民经济的主体」（国有经济是主导力量）。答「两个毫不动摇」时两句话都要写全，只写一句不给满分。"},{"level":"了解","text":"我国实行按劳分配为主体、多种分配方式并存的分配制度；共同富裕是社会主义的本质要求，是中国式现代化的重要特征，共同富裕不是同步富裕，也不是平均主义。","explain":"常与「提高居民收入」「缩小收入差距」「乡村振兴」等材料合考。答题要写「坚持按劳分配为主体、多种分配方式并存」「多种分配方式包括劳动、资本、土地、知识、技术、管理、数据等生产要素由市场评价贡献、按贡献决定报酬」，不要写成「平均分配」。"},{"level":"了解","text":"我国实行社会主义市场经济体制，市场在资源配置中起决定性作用，更好发挥政府作用；这一体制把社会主义制度和市场经济有机结合起来，激发各类市场主体活力。","explain":"多在选择题或材料题最后一问出现，考「社会主义市场经济体制的优越性」。规范答法：既发挥市场在资源配置中的决定性作用，又更好发挥政府作用，把社会主义制度的优越性与市场经济的优势结合起来，集中力量办大事，促进经济持续健康发展。不要把「决定性作用」写成「基础性作用」（旧表述），也不要写成「政府起决定性作用」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础；坚持毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。","国有经济是国民经济的主导力量；公有制经济是国民经济的主体。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["人民代表大会和人民代表大会制度是一回事，都指人民代表大会这个国家机关。","人民代表大会是我国的国家权力机关，包括全国人民代表大会和地方各级人民代表大会，是一个具体的国家机关；人民代表大会制度是我国的根本政治制度，是包括国家权力机关与其他国家机关的产生、职权、相互关系在内的一整套制度安排，是我国人民当家作主的重要途径和最高实现形式。","「机关」与「制度」不能混为一谈。答题时问「我国的根本政治制度是什么」，只能答「人民代表大会制度」；问「国家权力机关是什么」，只能答「人民代表大会」；问「人民行使国家权力的机关是什么」，答「全国人民代表大会和地方各级人民代表大会」。"],["民族区域自治制度是我国的根本政治制度。","人民代表大会制度是我国的根本政治制度；中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国的基本政治制度。","「根本」只有一个，「基本」有三个，是选择题最常设的陷阱。记忆口诀：根本是人民代表大会制度，基本是政党制度、民族区域自治、基层群众自治。"]]},{"type":"table","title":"公有制经济与非公有制经济（我国基本经济制度中的所有制结构：地位不同、政策不同，但都是重要组成部分）（本单元概念对比）","head":["比较项","公有制经济","非公有制经济"],"rows":[["包括","国有经济、集体经济和混合所有制经济中的国有成分和集体成分","个体经济、私营经济、外资经济等"],["地位","是我国国民经济的主体，其中国有经济是国民经济的主导力量","是社会主义市场经济的重要组成部分，是我国经济社会发展的重要基础"],["国家政策","毫不动摇巩固和发展公有制经济","毫不动摇鼓励、支持、引导非公有制经济发展"],["作用","为国家建设提供物质基础，保障国家安全和公共利益，增强国民经济控制力","支撑就业、促进创新、增加税收，激发市场活力"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["人民代表大会制度的「一条链条」论证","常给全国人民代表大会会议议程、人大代表提出议案、基层立法联系点、人大代表联络站等材料，设问「这些材料体现了人民代表大会制度的哪些内容」。答题用一条链条：国家的一切权力属于人民 → 人民通过民主选举选出代表，组成人民代表大会作为国家权力机关 → 由人民代表大会产生其他国家机关并对它负责、受它监督 → 实行民主集中制 → 落脚在「人民代表大会制度是我国的根本政治制度」，最后补一句优越性的规范表述。"],["全过程人民民主的「五个民主」","以社区议事、立法征求意见、价格听证、村务公开、政府评议等情境设问「材料体现了公民参与民主生活的哪些形式」「为什么说全过程人民民主是最广泛、最真实、最管用的民主」。答案先把民主选举、民主协商、民主决策、民主管理、民主监督写全，再落到「全过程人民民主是社会主义民主政治的本质属性」「人民民主的真谛是有事好商量，众人的事情由众人商量」。"],["基本经济制度与共同富裕","以民营经济发展、国有企业改革、居民收入分配、乡村振兴等素材设问。答题落在「公有制为主体、多种所有制经济共同发展」「公有制经济和非公有制经济都是社会主义市场经济的重要组成部分」「坚持按劳分配为主体、多种分配方式并存」「市场在资源配置中起决定性作用，更好发挥政府作用」，并要求答出「两个毫不动摇」的完整表述。"],["基层群众自治与民族区域自治的「主体判断」","给村（居）民议事、居民公约、民族自治地方行使自治权等材料，设问「材料体现了哪一项政治制度」「自治机关是哪些」。判断口诀：主体是村民委员会、居民委员会的是基层群众自治制度，注意它们不是国家机关；主体是自治区、自治州、自治县的人民代表大会和人民政府的才是民族区域自治的自治机关，人民法院、人民检察院与人民政协都不是自治机关。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第三单元·认识国家制度（第5—6课：我国的政治制度 · 我国的基本经济制度）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-3"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-3-m1-q3","type":"short","stem":"（3）结合材料三，说明我国坚持和落实「两个毫不动摇」的原因。（4 分）","answer":"①我国实行公有制为主体、多种所有制经济共同发展的基本经济制度。②公有制经济和非公有制经济都是社会主义市场经济的重要组成部分，都是我国经济社会发展的重要基础；国有经济是国民经济的主导力量。③坚持毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展，有利于激发各类市场主体活力，支撑就业、促进创新、增加税收，推动经济高质量发展，为实现共同富裕提供坚实的物质基础。④因此必须坚持和落实「两个毫不动摇」，促进各种所有制经济优势互补、共同发展。","explain":"","tags":["基本经济制度","两个毫不动摇"],"rubric":["答出公有制为主体、多种所有制经济共同发展","答出公有制经济和非公有制经济都是社会主义市场经济的重要组成部分","答出「两个毫不动摇」的完整表述","答出有利于激发市场活力、促进经济发展或共同富裕"]},{"id":"pol-law-3-q5","type":"choice","stem":"在我国基本经济制度中，国民经济的主导力量是","answer":"A","explain":"国有经济是国民经济的主导力量；集体经济是公有制经济的重要组成部分；个体经济、私营经济属于非公有制经济，是社会主义市场经济的重要组成部分，是我国经济社会发展的重要基础，但不能说它们是「国民经济的主导力量」，也不能说它们是「国民经济的主体」（主体是公有制经济）。","options":["国有经济","集体经济","个体经济","私营经济"],"difficulty":2,"tags":["基本经济制度","国有经济"]},{"id":"pol-law-3-q6","type":"choice","stem":"下列不属于我国基本经济制度内容的是","answer":"D","explain":"基层群众自治制度是我国的一项基本政治制度，不属于基本经济制度。我国的基本经济制度包括公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制三个方面。「政治制度」与「经济制度」不能混为一类。","options":["公有制为主体、多种所有制经济共同发展","按劳分配为主体、多种分配方式并存","社会主义市场经济体制","基层群众自治制度"],"difficulty":2,"tags":["基本经济制度","基本政治制度"]},{"id":"pol-law-3-q7","type":"choice","stem":"「非公有制经济是我国社会主义经济的重要组成部分。」这一说法","answer":"B","explain":"规范表述是「非公有制经济是社会主义市场经济的重要组成部分，是我国经济社会发展的重要基础」，丢掉「市场」二字即为错误。A 错，公有制经济与非公有制经济在国民经济中的地位不同，公有制经济是主体；C 错，主体是公有制经济；D 错，国有经济才是国民经济的主导力量。","options":["正确，非公有制经济与公有制经济地位完全相同","错误，非公有制经济是社会主义市场经济的重要组成部分","错误，非公有制经济是我国国民经济的主体","正确，非公有制经济是国民经济的主导力量"],"difficulty":3,"tags":["非公有制经济","基本经济制度"]},{"id":"pol-law-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 人民代表大会制度是我国的根本政治制度，是坚持党的领导、人民当家作主、依法治国有机…\n② 人民代表大会制度是符合中国国情和实际、体现社会主义国家性质、保证人民当家作主、保…\n③ 全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主。\n④ 人民代表大会和人民代表大会制度是一回事，都指人民代表大会这个国家机关。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——「机关」与「制度」不能混为一谈。答题时问「我国的根本政治制度是什么」，只能答「人民代表大会制度」；问「国家权力机关是什么」，只能答「人民代表大会」；问「人民行使国家权力的机关是什么」，答「全国人民代表大会和地方各级人民代表大会」；正确表述应为：人民代表大会是我国的国家权力机关，包括全国人民代表大会和地方各级人民代表大会，是一个具体的国家机关；人民代表大会制度是我国的根本政治制度，是包括国家权力机关与其他国家机关的产生、职权、相互关系在内的一整套制度安排，是我国人民当家作主的重要途径和最高实现形式。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第三单元·认识国家制度（第5—6课：我国的政治制度 · 我国的基本经济制度）"]}]},{"id":"cat-pol-8b-4-1","title":"第7课 国家权力机关","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第7课 国家权力机关"},{"k":"框题","v":"国家权力机关的组成和地位 / 人民代表大会的职权"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["国家权力机关的组成和地位","人民代表大会的职权"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"中华人民共和国全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。","explain":"必背的地位句，选择题最常考「最高国家权力机关是哪一个」。要区分三层：全国人民代表大会是最高国家权力机关；全国人民代表大会常务委员会是它的常设机关；国家立法权由全国人民代表大会和全国人民代表大会常务委员会共同行使。地方各级人民代表大会是地方国家权力机关，不能说成「地方立法机关」或「最高国家权力机关」。"},{"level":"重点","text":"人民代表大会的职权包括立法权、决定权、任免权、监督权。","explain":"本单元最高频的考点，材料题给一段人大会议议程就要求逐项识别：制定和修改法律体现立法权；审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，决定战争和和平的问题等体现决定权；选举和决定国家机关领导人员体现任免权；监督宪法和法律的实施、听取和审议其他国家机关的工作报告体现监督权。作答格式固定为「行使了……权，因为……」，「职权名称 + 材料对应」缺一半就丢分。"},{"level":"重点","text":"地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规的遵守和执行；讨论和决定本行政区域内的重大事项，监督本级人民政府、监察委员会、人民法院和人民检察院的工作。","explain":"常与基层治理、地方立法、地方政府工作报告等材料合考。答题要写清「地方国家权力机关」这个性质，再写它在本行政区域内保证宪法、法律、行政法规的遵守和执行；注意地方各级人民代表大会与地方各级人民政府不是一回事：前者是权力机关，后者是它的执行机关。"},{"level":"重点","text":"人大代表是国家权力机关的组成人员，依照宪法和法律赋予的各项职权，参加行使国家权力，依法享有审议各项议案、表决各项决定、提出议案和建议以及对国家机关工作提出质询等职权；同时必须模范地遵守宪法和法律，与人民群众保持密切联系，听取和反映他们的意见和要求，努力为人民服务。","explain":"设问多为「人大代表的职权与义务」「人大代表怎样才能不负人民重托」。职权一侧写「审议、表决、提出议案和建议、提出质询」，义务一侧写「模范守法、密切联系群众、听取和反映意见和要求、为人民服务」。特别提醒：人大代表个人不能直接处理问题、不能直接决定重大事项，「人大代表是国家权力机关的组成人员，集体行使职权」，选项里写「人大代表个人可以决定……」一律判错。"},{"level":"重点","text":"中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令；中华人民共和国主席代表中华人民共和国，进行国事活动，接受外国使节，根据全国人民代表大会常务委员会的决定，派遣和召回驻外全权代表，批准和废除同外国缔结的条约和重要协定。","explain":"这是国家主席职权的完整表述，材料题给「国家主席签署主席令公布法律」「为功勋人物颁授国家勋章」「接受外国驻华使节递交国书」等情境，就按「公布法律、发布命令」「任免」「荣典」「外交」四类职权作答。关键限定语不能漏：公布法律、任免国务院组成人员、发布特赦令等职权，都是国家主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使的，选项中写成「国家主席自行决定」即为错误。"},{"level":"重点","text":"国务院即中央人民政府，是最高国家行政机关；国家行政机关由人民代表大会产生，对人民代表大会负责，受人民代表大会监督。","explain":"常以政府公开办事流程、简化审批、优化营商环境、整治不作为慢作为等材料设问。遇到「人民政府是权力机关」的选项一律判错：人民代表大会才是国家权力机关，人民政府是国家权力机关的执行机关。作答时先答机关性质（国家行政机关／最高国家行政机关），再答产生方式与负责对象。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。","人民代表大会的职权包括立法权、决定权、任免权、监督权。","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。","中华人民共和国中央军事委员会领导全国武装力量，实行主席负责制；中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["全国人民代表大会和全国人民代表大会常务委员会的职权完全相同，都可以修改宪法。","二者性质与职权范围不同。全国人民代表大会是最高国家权力机关，行使国家立法权，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；全国人民代表大会常务委员会是它的常设机关，有权解释宪法、监督宪法的实施，有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。","两个机关同属国家权力机关，但职权不能混为一谈：「修改宪法」只能由全国人民代表大会行使，「解释宪法」则是全国人民代表大会常务委员会的职权。答题时要写清是谁的职权，不能笼统写「全国人大」。"],["行政机关和监察机关是一回事，监察委员会是政府的一个部门，由政府领导。","行政机关（国务院和地方各级人民政府）行使行政管理职权，是国家权力机关的执行机关；监察委员会是行使国家监察职能的专责机关，与行政机关、审判机关、检察机关并列，国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督。","设置监察机关的目的正是实现对所有行使公权力的公职人员的监察全覆盖，监察机关不能隶属于行政机关，否则无法监督行政机关。凡见「监察委员会是政府机关」「受政府领导」一律判错。"],["国家主席可以自行决定公布法律、发布特赦令。","国家主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院组成人员，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令；国家主席代表中华人民共和国进行国事活动，接受外国使节。","国家主席是国家元首，但这些职权是依照国家权力机关的决定行使的，不是自行决定。答题时把「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这半句写出来，才算答全；漏掉就变成「国家主席自行决定」，是政治性错误。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"quote","text":"【材料一】全国人民代表大会会议听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，审议并通过了有关法律；会议选举和决定任命了新一届国家机关领导人员。\n【材料二】国家主席签署主席令，公布全国人民代表大会通过的法律；根据全国人民代表大会常务委员会的决定，国家主席为作出突出贡献的功勋人物颁授国家勋章和荣誉称号，并接受外国驻华使节递交的国书。\n【材料三】某市深入推进政务服务改革，公开权力清单和责任清单，简化审批环节、压缩办事时限，开通政务服务便民热线；该市监察委员会对窗口单位工作人员不作为、慢作为问题依法开展调查处置，并对相关人员依法作出处理。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-m1-q1","type":"short","stem":"（1）据材料一，说明全国人民代表大会行使了哪些职权。（6 分）","answer":"①审议并通过有关法律，行使立法权。②审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，行使决定权。③选举和决定任命国家机关领导人员，行使任免权。④听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，行使监督权。这说明全国人民代表大会是最高国家权力机关，国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。","explain":"","tags":["国家权力机关","人民代表大会职权"],"rubric":["答出立法权并对应「审议通过法律」","答出决定权并对应「审查批准计划、预算」","答出任免权并对应「选举和决定任命国家机关领导人员」","答出监督权并对应「听取和审议工作报告」","答出全国人民代表大会是最高国家权力机关","职权名称与材料一一对应、分点作答"]},{"id":"pol-law-6-m1-q2","type":"short","stem":"（2）据材料二，说明中华人民共和国主席是怎样产生的，并指出材料中主席行使的职权。（4 分）","answer":"产生方式：中华人民共和国主席、副主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同。材料中行使的职权：①签署主席令公布法律，行使公布法律的职权；②根据全国人民代表大会常务委员会的决定为功勋人物颁授国家勋章和荣誉称号，行使授予国家勋章和荣誉称号的职权；③接受外国驻华使节递交国书，代表中华人民共和国进行国事活动、接受外国使节，行使外交方面的职权。可见国家主席的这些职权是根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使的。","explain":"","tags":["中华人民共和国主席","国家主席职权"],"rubric":["答出国家主席由全国人民代表大会选举产生","答出每届任期同全国人民代表大会每届任期相同","答出公布法律的职权","答出授予国家勋章和荣誉称号的职权","答出代表国家进行国事活动、接受外国使节的职权"]},{"id":"pol-law-6-q1","type":"choice","stem":"我国的最高国家权力机关是","answer":"B","explain":"全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；国务院是最高国家行政机关；最高人民法院是最高国家审判机关；最高人民检察院是最高国家法律监督机关。四个「最高」要一一对应，不能错位。","options":["国务院","全国人民代表大会","最高人民法院","最高人民检察院"],"difficulty":1,"tags":["国家权力机关","国家机关性质"]},{"id":"pol-law-6-q2","type":"choice","stem":"全国人民代表大会审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告。这属于行使","answer":"B","explain":"审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，属于对国家生活中重大事项作出决定，体现决定权。立法权指制定和修改法律；任免权指选举和决定国家机关领导人员；监督权指监督宪法和法律的实施、监督其他国家机关的工作。","options":["立法权","决定权","任免权","监督权"],"difficulty":2,"tags":["人民代表大会职权","决定权"]},{"id":"pol-law-6-q3","type":"choice","stem":"中华人民共和国主席、副主席的产生方式和任期是","answer":"A","explain":"宪法规定，中华人民共和国主席、副主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同。B 错，不是由全国人民代表大会常务委员会选举产生；C 错，不是由人民直接选举产生；D 错，表述不准确，主席、副主席由全国人民代表大会选举产生，而非「决定产生」。","options":["由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同","由全国人民代表大会常务委员会选举产生，任期五年，可以连任三届","由人民直接选举产生，每届任期同全国人民代表大会每届任期相同","由全国人民代表大会决定产生，每届任期与国务院每届任期相同"],"difficulty":2,"tags":["中华人民共和国主席","国家主席产生"]},{"id":"pol-law-6-q4","type":"choice","stem":"下列职权中，属于中华人民共和国主席行使的是","answer":"C","explain":"公布法律、授予国家的勋章和荣誉称号是国家主席的职权，且须根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使。A 是国家权力机关行使国家立法权；B 是人民法院行使审判权；D 是监察机关履行调查职责。","options":["制定和修改法律","审理刑事案件并作出判决","根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定公布法律，授予国家的勋章和荣誉称号","对公职人员涉嫌职务违法进行调查"],"difficulty":2,"tags":["国家主席职权","国家机关职权"]}]},{"id":"cat-pol-8b-4-2","title":"第8课 中华人民共和国主席","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第8课 中华人民共和国主席"},{"k":"框题","v":"国家主席的产生和地位 / 国家主席的职权"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["国家主席的产生和地位","国家主席的职权"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"中华人民共和国主席、副主席由全国人民代表大会选举产生；有选举权和被选举权的年满四十五周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席；中华人民共和国主席、副主席每届任期同全国人民代表大会每届任期相同。","explain":"考「国家主席怎样产生」时答「由全国人民代表大会选举产生」，考资格时注意两个条件：有选举权和被选举权、年满四十五周岁，缺一不可；考任期时答「每届任期同全国人民代表大会每届任期相同」。不要把国家主席说成「由人民直接选举产生」，也不要说「国家主席向全国人民代表大会报告工作」。"},{"level":"重点","text":"中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令；中华人民共和国主席代表中华人民共和国，进行国事活动，接受外国使节，根据全国人民代表大会常务委员会的决定，派遣和召回驻外全权代表，批准和废除同外国缔结的条约和重要协定。","explain":"这是国家主席职权的完整表述，材料题给「国家主席签署主席令公布法律」「为功勋人物颁授国家勋章」「接受外国驻华使节递交国书」等情境，就按「公布法律、发布命令」「任免」「荣典」「外交」四类职权作答。关键限定语不能漏：公布法律、任免国务院组成人员、发布特赦令等职权，都是国家主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使的，选项中写成「国家主席自行决定」即为错误。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语（本课金句未单列，以下取所属单元必背金句）","items":["全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。","人民代表大会的职权包括立法权、决定权、任免权、监督权。","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。","国务院即中央人民政府，是最高国家行政机关；国家行政机关必须依法行政，坚持法定职责必须为、法无授权不可为，做到有权必有责、用权受监督、违法必追究。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["国家主席可以自行决定公布法律、发布特赦令。","国家主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院组成人员，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令；国家主席代表中华人民共和国进行国事活动，接受外国使节。","国家主席是国家元首，但这些职权是依照国家权力机关的决定行使的，不是自行决定。答题时把「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这半句写出来，才算答全；漏掉就变成「国家主席自行决定」，是政治性错误。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"quote","text":"【材料一】全国人民代表大会会议听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，审议并通过了有关法律；会议选举和决定任命了新一届国家机关领导人员。\n【材料二】国家主席签署主席令，公布全国人民代表大会通过的法律；根据全国人民代表大会常务委员会的决定，国家主席为作出突出贡献的功勋人物颁授国家勋章和荣誉称号，并接受外国驻华使节递交的国书。\n【材料三】某市深入推进政务服务改革，公开权力清单和责任清单，简化审批环节、压缩办事时限，开通政务服务便民热线；该市监察委员会对窗口单位工作人员不作为、慢作为问题依法开展调查处置，并对相关人员依法作出处理。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-m1-q2","type":"short","stem":"（2）据材料二，说明中华人民共和国主席是怎样产生的，并指出材料中主席行使的职权。（4 分）","answer":"产生方式：中华人民共和国主席、副主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同。材料中行使的职权：①签署主席令公布法律，行使公布法律的职权；②根据全国人民代表大会常务委员会的决定为功勋人物颁授国家勋章和荣誉称号，行使授予国家勋章和荣誉称号的职权；③接受外国驻华使节递交国书，代表中华人民共和国进行国事活动、接受外国使节，行使外交方面的职权。可见国家主席的这些职权是根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使的。","explain":"","tags":["中华人民共和国主席","国家主席职权"],"rubric":["答出国家主席由全国人民代表大会选举产生","答出每届任期同全国人民代表大会每届任期相同","答出公布法律的职权","答出授予国家勋章和荣誉称号的职权","答出代表国家进行国事活动、接受外国使节的职权"]},{"id":"pol-law-6-q3","type":"choice","stem":"中华人民共和国主席、副主席的产生方式和任期是","answer":"A","explain":"宪法规定，中华人民共和国主席、副主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同。B 错，不是由全国人民代表大会常务委员会选举产生；C 错，不是由人民直接选举产生；D 错，表述不准确，主席、副主席由全国人民代表大会选举产生，而非「决定产生」。","options":["由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同","由全国人民代表大会常务委员会选举产生，任期五年，可以连任三届","由人民直接选举产生，每届任期同全国人民代表大会每届任期相同","由全国人民代表大会决定产生，每届任期与国务院每届任期相同"],"difficulty":2,"tags":["中华人民共和国主席","国家主席产生"]},{"id":"pol-law-6-q4","type":"choice","stem":"下列职权中，属于中华人民共和国主席行使的是","answer":"C","explain":"公布法律、授予国家的勋章和荣誉称号是国家主席的职权，且须根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定行使。A 是国家权力机关行使国家立法权；B 是人民法院行使审判权；D 是监察机关履行调查职责。","options":["制定和修改法律","审理刑事案件并作出判决","根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定公布法律，授予国家的勋章和荣誉称号","对公职人员涉嫌职务违法进行调查"],"difficulty":2,"tags":["国家主席职权","国家机关职权"]},{"id":"pol-law-6-q5","type":"choice","stem":"中华人民共和国中央军事委员会的领导体制和负责对象是","answer":"B","explain":"宪法规定，中华人民共和国中央军事委员会领导全国武装力量，由主席、副主席、委员组成，实行主席负责制，每届任期同全国人民代表大会每届任期相同；中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。中央军事委员会不对国务院负责。","options":["实行委员会集体负责制，对国务院负责","实行主席负责制，中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责","实行主席负责制，对国务院和国防部负责","实行首长分工负责制，对最高人民法院负责"],"difficulty":3,"tags":["中央军事委员会","国家机构"]},{"id":"pol-law-6-q6","type":"choice","stem":"关于国家监察机关，下列说法正确的是","answer":"B","explain":"各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关，对所有行使公权力的公职人员依法进行监察，实现国家监察全覆盖。A 错，监察委员会不是政府的部门，不受政府领导；C 错，监察对象是所有行使公权力的公职人员，不是所有公民；D 错，监察机关由本级人民代表大会产生，对产生它的国家权力机关和上一级监察委员会负责。","options":["监察委员会是政府的一个部门，受本级人民政府领导","监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察","监察委员会依法履行监督、调查、处置职责，可以对所有公民进行调查","监察委员会由人民法院产生，对人民法院负责"],"difficulty":3,"tags":["国家监察机关","行政与监察"]}]},{"id":"cat-pol-8b-4-3","title":"第9课 国家行政机关","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第9课 国家行政机关"},{"k":"框题","v":"国家行政机关的性质和职权 / 依法行政，建设法治政府"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["国家行政机关的性质和职权","依法行政，建设法治政府"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权；国家行政机关必须坚持法定职责必须为、法无授权不可为，勇于担当，坚决纠正不作为、乱作为；全面推进政务公开，保障公民的知情权、参与权、表达权和监督权；加强对行政权的监督和制约，做到有权必有责、用权受监督、违法必追究。","explain":"「国家行政机关」一课的核心句，也是与第五单元「法治政府」交叉的高频点。材料题问「政府应该怎样做」，按五层答：依法行政、规范行政权、法定职责必须为法无授权不可为、政务公开接受监督、有权必有责用权受监督违法必追究。只写「政府要好好办事」不得分。"},{"level":"重点","text":"我国是人民民主专政的社会主义国家，政府的宗旨是为人民服务，政府必须对人民负责，建设人民满意的服务型政府；行政机关行使职权必须坚持人民至上，努力为人民服务。","explain":"常与「放管服」改革、政务服务便民热线、基层便民服务中心等材料合考，问「政府的做法说明了什么」。答题落在「政府的宗旨是为人民服务」「对人民负责」「建设人民满意的服务型政府」，再补一句「依法行政，维护人民群众的合法权益」。"},{"level":"重点","text":"国务院即中央人民政府，是最高国家行政机关；国家行政机关由人民代表大会产生，对人民代表大会负责，受人民代表大会监督。","explain":"常以政府公开办事流程、简化审批、优化营商环境、整治不作为慢作为等材料设问。遇到「人民政府是权力机关」的选项一律判错：人民代表大会才是国家权力机关，人民政府是国家权力机关的执行机关。作答时先答机关性质（国家行政机关／最高国家行政机关），再答产生方式与负责对象。"},{"level":"次重点","text":"各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关；监察机关对所有行使公权力的公职人员进行监察，实现国家监察全覆盖，依法履行监督、调查、处置职责，依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。","explain":"三个得分点：性质是「行使国家监察职能的专责机关」；对象是「所有行使公权力的公职人员」，实现国家监察全覆盖；职责是「监督、调查、处置」。答题时不要写成「监察机关管所有公民」「监察机关是行政机关」，监察机关是独立的国家机关，与行政机关、审判机关、检察机关并列。"},{"level":"次重点","text":"人民法院是国家的审判机关，行使审判权；人民检察院是国家的法律监督机关，行使检察权；人民法院、人民检察院依照法律规定独立行使审判权、检察权，不受行政机关、社会团体和个人的干涉，必须坚持公正司法，坚持以事实为根据、以法律为准绳。","explain":"归类题必须分清：人民法院行使审判权，审理案件、作出判决；人民检察院行使检察权，是国家的法律监督机关，依法提起公诉。答题补两点：一是「人民法院、人民检察院对人民代表大会负责，受人民代表大会监督」；二是「公正司法要求做到事实认定符合客观真相、办案结果符合实体公正、办案程序符合程序公正」。不要把人民检察院写成「审判机关」，也不要把人民法院写成「法律监督机关」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["国务院即中央人民政府，是最高国家行政机关；国家行政机关必须依法行政，坚持法定职责必须为、法无授权不可为，做到有权必有责、用权受监督、违法必追究。","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。","人民法院是国家的审判机关，人民检察院是国家的法律监督机关，依照法律规定独立行使审判权、检察权，不受行政机关、社会团体和个人的干涉。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["行政机关和监察机关是一回事，监察委员会是政府的一个部门，由政府领导。","行政机关（国务院和地方各级人民政府）行使行政管理职权，是国家权力机关的执行机关；监察委员会是行使国家监察职能的专责机关，与行政机关、审判机关、检察机关并列，国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督。","设置监察机关的目的正是实现对所有行使公权力的公职人员的监察全覆盖，监察机关不能隶属于行政机关，否则无法监督行政机关。凡见「监察委员会是政府机关」「受政府领导」一律判错。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-m1-q3","type":"short","stem":"（3）结合材料三，说明国家行政机关和国家监察机关分别应怎样行使职权。（6 分）","answer":"国家行政机关：①国务院即中央人民政府，是最高国家行政机关；地方各级人民政府是地方国家行政机关，都由人民代表大会产生，对人民代表大会负责，受人民代表大会监督。②必须依法行政，坚持法定职责必须为、法无授权不可为，坚决纠正不作为、乱作为。③全面推进政务公开，保障公民的知情权、参与权、表达权和监督权，自觉接受监督，做到有权必有责、用权受监督、违法必追究。④政府的宗旨是为人民服务，必须对人民负责，建设人民满意的服务型政府。国家监察机关：①各级监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察，实现国家监察全覆盖。②依法履行监督、调查、处置职责，依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。③地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责，并接受其监督。","explain":"","tags":["国家行政机关","国家监察机关"],"rubric":["答出行政机关由人民代表大会产生，对人民代表大会负责，受人民代表大会监督","答出依法行政，法定职责必须为、法无授权不可为","答出政务公开、接受监督（有权必有责、用权受监督、违法必追究）","答出监察委员会是行使国家监察职能的专责机关，实现国家监察全覆盖","答出监督、调查、处置职责，独立行使监察权","答出监察机关对谁负责、受谁监督"]},{"id":"pol-law-6-q7","type":"choice","stem":"某县人民检察院对一起涉嫌污染环境案件的犯罪嫌疑人依法提起公诉。这表明人民检察院","answer":"B","explain":"人民检察院是国家的法律监督机关，行使检察权，依法提起公诉是其履行职责的重要方式。人民法院才是国家的审判机关；行政机关是各级人民政府；国家权力机关是人民代表大会。","options":["是国家的审判机关，行使审判权","是国家的法律监督机关，行使检察权","是国家的行政机关，行使行政管理职权","是国家权力机关，行使监督权"],"difficulty":2,"tags":["国家司法机关","审判机关与法律监督机关"]},{"id":"pol-law-6-q8","type":"choice","stem":"「国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。」这一规定说明","answer":"A","explain":"这一规定体现我国国家机构实行民主集中制的原则：国家权力来自人民，由人民选举产生国家权力机关，国家权力机关居于主导地位，其他国家机关由它产生、对它负责、受它监督，从而保证国家权力始终掌握在人民手中。B 错，其他国家机关由人民代表大会产生并受其监督；C 错，各国家机关依法行使各自的职权，人民代表大会不能代替；D 错，国家机关的职权由宪法和法律授予。","options":["我国的国家机构实行民主集中制，人民当家作主有制度保障","其他国家机关与人民代表大会地位平等、互不隶属","人民代表大会可以直接代替其他国家机关行使职权","其他国家机关可以自行决定自己的职权范围"],"difficulty":3,"tags":["民主集中制","国家机构"]},{"id":"pol-law-6-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华人民共和国全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会…\n② 人民代表大会的职权包括立法权、决定权、任免权、监督权。\n③ 地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规…\n④ 全国人民代表大会和全国人民代表大会常务委员会的职权完全相同，都可以修改宪法。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——两个机关同属国家权力机关，但职权不能混为一谈：「修改宪法」只能由全国人民代表大会行使，「解释宪法」则是全国人民代表大会常务委员会的职权。答题时要写清是谁的职权，不能笼统写「全国人大」；正确表述应为：二者性质与职权范围不同。全国人民代表大会是最高国家权力机关，行使国家立法权，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；全国人民代表大会常务委员会是它的常设机关，有权解释宪法、监督宪法的实施，有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）"]},{"id":"cat-pol-8b-4-3-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权；国家行…\n② 我国是人民民主专政的社会主义国家，政府的宗旨是为人民服务，政府必须对人民负责，建…\n③ 国务院即中央人民政府，是最高国家行政机关；国家行政机关由人民代表大会产生，对人民…\n④ 行政机关和监察机关是一回事，监察委员会是政府的一个部门，由政府领导。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——设置监察机关的目的正是实现对所有行使公权力的公职人员的监察全覆盖，监察机关不能隶属于行政机关，否则无法监督行政机关。凡见「监察委员会是政府机关」「受政府领导」一律判错；正确表述应为：行政机关（国务院和地方各级人民政府）行使行政管理职权，是国家权力机关的执行机关；监察委员会是行使国家监察职能的专责机关，与行政机关、审判机关、检察机关并列，国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督。","difficulty":3,"tags":["第9课 国家行政机关"]}]},{"id":"cat-pol-8b-4-4","title":"第10课 中央军事委员会","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第10课 中央军事委员会"},{"k":"框题","v":"中央军事委员会的性质和产生 / 中央军事委员会的领导体制和职权"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["中央军事委员会的性质和产生","中央军事委员会的领导体制和职权"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"中华人民共和国中央军事委员会领导全国武装力量；中央军事委员会由主席、副主席、委员组成，实行主席负责制；中央军事委员会每届任期同全国人民代表大会每届任期相同；中央军事委员会主席由全国人民代表大会选举产生，中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。","explain":"考「我国武装力量的领导机关」答「中央军事委员会」；考它的领导体制答「实行主席负责制」；考它由谁产生、对谁负责答「中央军事委员会主席由全国人民代表大会选举产生，对全国人民代表大会和全国人民代表大会常务委员会负责」。这一课的表述必须照着宪法写，「中央军委对国务院负责」是典型错误。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["中华人民共和国中央军事委员会领导全国武装力量，实行主席负责制；中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。"]},{"type":"table","title":"易错辨析（本课易错点未单列，以下取所属单元易错辨析）","head":["错误表述","正确表述","原因"],"rows":[["全国人民代表大会和全国人民代表大会常务委员会的职权完全相同，都可以修改宪法。","二者性质与职权范围不同。全国人民代表大会是最高国家权力机关，行使国家立法权，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；全国人民代表大会常务委员会是它的常设机关，有权解释宪法、监督宪法的实施，有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。","两个机关同属国家权力机关，但职权不能混为一谈：「修改宪法」只能由全国人民代表大会行使，「解释宪法」则是全国人民代表大会常务委员会的职权。答题时要写清是谁的职权，不能笼统写「全国人大」。"],["人民检察院是国家的审判机关，人民法院是国家的法律监督机关。","人民法院是国家的审判机关，行使审判权，依法审理案件、作出判决；人民检察院是国家的法律监督机关，行使检察权，依法提起公诉、进行法律监督。二者都由人民代表大会产生，对它负责，受它监督。","「审判」与「法律监督」两个身份一旦互换，选择题必错、材料题不得分。判断口诀：审案子、下判决的是人民法院；批捕、提起公诉、法律监督的是人民检察院。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-q5","type":"choice","stem":"中华人民共和国中央军事委员会的领导体制和负责对象是","answer":"B","explain":"宪法规定，中华人民共和国中央军事委员会领导全国武装力量，由主席、副主席、委员组成，实行主席负责制，每届任期同全国人民代表大会每届任期相同；中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。中央军事委员会不对国务院负责。","options":["实行委员会集体负责制，对国务院负责","实行主席负责制，中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责","实行主席负责制，对国务院和国防部负责","实行首长分工负责制，对最高人民法院负责"],"difficulty":3,"tags":["中央军事委员会","国家机构"]},{"id":"pol-law-6-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华人民共和国全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会…\n② 人民代表大会的职权包括立法权、决定权、任免权、监督权。\n③ 地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规…\n④ 全国人民代表大会和全国人民代表大会常务委员会的职权完全相同，都可以修改宪法。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——两个机关同属国家权力机关，但职权不能混为一谈：「修改宪法」只能由全国人民代表大会行使，「解释宪法」则是全国人民代表大会常务委员会的职权。答题时要写清是谁的职权，不能笼统写「全国人大」；正确表述应为：二者性质与职权范围不同。全国人民代表大会是最高国家权力机关，行使国家立法权，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；全国人民代表大会常务委员会是它的常设机关，有权解释宪法、监督宪法的实施，有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）"]},{"id":"pol-law-6-q7","type":"choice","stem":"某县人民检察院对一起涉嫌污染环境案件的犯罪嫌疑人依法提起公诉。这表明人民检察院","answer":"B","explain":"人民检察院是国家的法律监督机关，行使检察权，依法提起公诉是其履行职责的重要方式。人民法院才是国家的审判机关；行政机关是各级人民政府；国家权力机关是人民代表大会。","options":["是国家的审判机关，行使审判权","是国家的法律监督机关，行使检察权","是国家的行政机关，行使行政管理职权","是国家权力机关，行使监督权"],"difficulty":2,"tags":["国家司法机关","审判机关与法律监督机关"]},{"id":"cat-pol-8b-4-4-short","type":"short","stem":"某班围绕「中央军事委员会」开展主题探究活动，围绕「中央军事委员会的性质和产生」、「中央军事委员会的领导体制和职权」。请运用本课所学，谈谈你的认识。","answer":"中华人民共和国中央军事委员会领导全国武装力量；中央军事委员会由主席、副主席、委员组成，实行主席负责制；中央军事委员会每届任期同全国人民代表大会每届任期相同；中央军事委员会主席由全国人民代表大会选举产生，中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。","explain":"","rubric":["中华人民共和国中央军事委员会领导全国武装力量；中央军事委员会由主席、副主席、委员…"],"tags":["中央军事委员会"]},{"id":"pol-law-6-q8","type":"choice","stem":"「国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。」这一规定说明","answer":"A","explain":"这一规定体现我国国家机构实行民主集中制的原则：国家权力来自人民，由人民选举产生国家权力机关，国家权力机关居于主导地位，其他国家机关由它产生、对它负责、受它监督，从而保证国家权力始终掌握在人民手中。B 错，其他国家机关由人民代表大会产生并受其监督；C 错，各国家机关依法行使各自的职权，人民代表大会不能代替；D 错，国家机关的职权由宪法和法律授予。","options":["我国的国家机构实行民主集中制，人民当家作主有制度保障","其他国家机关与人民代表大会地位平等、互不隶属","人民代表大会可以直接代替其他国家机关行使职权","其他国家机关可以自行决定自己的职权范围"],"difficulty":3,"tags":["民主集中制","国家机构"]}]},{"id":"cat-pol-8b-4-5","title":"第11课 国家监察机关","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第11课 国家监察机关"},{"k":"框题","v":"国家监察机关的产生和性质 / 国家监察机关的职责"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["国家监察机关的产生和性质","国家监察机关的职责"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"次重点","text":"各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关；监察机关对所有行使公权力的公职人员进行监察，实现国家监察全覆盖，依法履行监督、调查、处置职责，依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。","explain":"三个得分点：性质是「行使国家监察职能的专责机关」；对象是「所有行使公权力的公职人员」，实现国家监察全覆盖；职责是「监督、调查、处置」。答题时不要写成「监察机关管所有公民」「监察机关是行政机关」，监察机关是独立的国家机关，与行政机关、审判机关、检察机关并列。"},{"level":"重点","text":"地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规的遵守和执行；讨论和决定本行政区域内的重大事项，监督本级人民政府、监察委员会、人民法院和人民检察院的工作。","explain":"常与基层治理、地方立法、地方政府工作报告等材料合考。答题要写清「地方国家权力机关」这个性质，再写它在本行政区域内保证宪法、法律、行政法规的遵守和执行；注意地方各级人民代表大会与地方各级人民政府不是一回事：前者是权力机关，后者是它的执行机关。"},{"level":"次重点","text":"国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责，并接受其监督。","explain":"考「监察委员会对谁负责」是辨析题的高频陷阱：它对本级人民代表大会及其常务委员会和上一级监察委员会负责（国家监察委员会对全国人民代表大会及其常务委员会负责），不是「对政府负责」，也不是「只对上一级监察委员会负责」。答题要写全负责对象与「受其监督」两层。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。","监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察，实行国家监察全覆盖。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["行政机关和监察机关是一回事，监察委员会是政府的一个部门，由政府领导。","行政机关（国务院和地方各级人民政府）行使行政管理职权，是国家权力机关的执行机关；监察委员会是行使国家监察职能的专责机关，与行政机关、审判机关、检察机关并列，国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督。","设置监察机关的目的正是实现对所有行使公权力的公职人员的监察全覆盖，监察机关不能隶属于行政机关，否则无法监督行政机关。凡见「监察委员会是政府机关」「受政府领导」一律判错。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"quote","text":"【材料一】全国人民代表大会会议听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，审议并通过了有关法律；会议选举和决定任命了新一届国家机关领导人员。\n【材料二】国家主席签署主席令，公布全国人民代表大会通过的法律；根据全国人民代表大会常务委员会的决定，国家主席为作出突出贡献的功勋人物颁授国家勋章和荣誉称号，并接受外国驻华使节递交的国书。\n【材料三】某市深入推进政务服务改革，公开权力清单和责任清单，简化审批环节、压缩办事时限，开通政务服务便民热线；该市监察委员会对窗口单位工作人员不作为、慢作为问题依法开展调查处置，并对相关人员依法作出处理。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-m1-q3","type":"short","stem":"（3）结合材料三，说明国家行政机关和国家监察机关分别应怎样行使职权。（6 分）","answer":"国家行政机关：①国务院即中央人民政府，是最高国家行政机关；地方各级人民政府是地方国家行政机关，都由人民代表大会产生，对人民代表大会负责，受人民代表大会监督。②必须依法行政，坚持法定职责必须为、法无授权不可为，坚决纠正不作为、乱作为。③全面推进政务公开，保障公民的知情权、参与权、表达权和监督权，自觉接受监督，做到有权必有责、用权受监督、违法必追究。④政府的宗旨是为人民服务，必须对人民负责，建设人民满意的服务型政府。国家监察机关：①各级监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察，实现国家监察全覆盖。②依法履行监督、调查、处置职责，依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。③地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责，并接受其监督。","explain":"","tags":["国家行政机关","国家监察机关"],"rubric":["答出行政机关由人民代表大会产生，对人民代表大会负责，受人民代表大会监督","答出依法行政，法定职责必须为、法无授权不可为","答出政务公开、接受监督（有权必有责、用权受监督、违法必追究）","答出监察委员会是行使国家监察职能的专责机关，实现国家监察全覆盖","答出监督、调查、处置职责，独立行使监察权","答出监察机关对谁负责、受谁监督"]},{"id":"pol-law-6-q6","type":"choice","stem":"关于国家监察机关，下列说法正确的是","answer":"B","explain":"各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关，对所有行使公权力的公职人员依法进行监察，实现国家监察全覆盖。A 错，监察委员会不是政府的部门，不受政府领导；C 错，监察对象是所有行使公权力的公职人员，不是所有公民；D 错，监察机关由本级人民代表大会产生，对产生它的国家权力机关和上一级监察委员会负责。","options":["监察委员会是政府的一个部门，受本级人民政府领导","监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察","监察委员会依法履行监督、调查、处置职责，可以对所有公民进行调查","监察委员会由人民法院产生，对人民法院负责"],"difficulty":3,"tags":["国家监察机关","行政与监察"]},{"id":"pol-law-6-q8","type":"choice","stem":"「国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。」这一规定说明","answer":"A","explain":"这一规定体现我国国家机构实行民主集中制的原则：国家权力来自人民，由人民选举产生国家权力机关，国家权力机关居于主导地位，其他国家机关由它产生、对它负责、受它监督，从而保证国家权力始终掌握在人民手中。B 错，其他国家机关由人民代表大会产生并受其监督；C 错，各国家机关依法行使各自的职权，人民代表大会不能代替；D 错，国家机关的职权由宪法和法律授予。","options":["我国的国家机构实行民主集中制，人民当家作主有制度保障","其他国家机关与人民代表大会地位平等、互不隶属","人民代表大会可以直接代替其他国家机关行使职权","其他国家机关可以自行决定自己的职权范围"],"difficulty":3,"tags":["民主集中制","国家机构"]},{"id":"pol-law-6-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 中华人民共和国全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会…\n② 人民代表大会的职权包括立法权、决定权、任免权、监督权。\n③ 地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规…\n④ 全国人民代表大会和全国人民代表大会常务委员会的职权完全相同，都可以修改宪法。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——两个机关同属国家权力机关，但职权不能混为一谈：「修改宪法」只能由全国人民代表大会行使，「解释宪法」则是全国人民代表大会常务委员会的职权。答题时要写清是谁的职权，不能笼统写「全国人大」；正确表述应为：二者性质与职权范围不同。全国人民代表大会是最高国家权力机关，行使国家立法权，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过；全国人民代表大会常务委员会是它的常设机关，有权解释宪法、监督宪法的实施，有权撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）"]},{"id":"cat-pol-8b-4-5-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关；监察机…\n② 地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规…\n③ 国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接…\n④ 行政机关和监察机关是一回事，监察委员会是政府的一个部门，由政府领导。","options":["①②③","①②④","①③④","②③④"],"answer":"A","explanation":"①②③取自本专题「核心观点与考点」；④属易错表述——设置监察机关的目的正是实现对所有行使公权力的公职人员的监察全覆盖，监察机关不能隶属于行政机关，否则无法监督行政机关。凡见「监察委员会是政府机关」「受政府领导」一律判错；正确表述应为：行政机关（国务院和地方各级人民政府）行使行政管理职权，是国家权力机关的执行机关；监察委员会是行使国家监察职能的专责机关，与行政机关、审判机关、检察机关并列，国家监察委员会由全国人民代表大会产生，对全国人民代表大会及其常务委员会负责，并接受其监督。","difficulty":3,"tags":["第11课 国家监察机关"]}]},{"id":"cat-pol-8b-4-6","title":"第12课 国家司法机关","subtitle":"八年级下册 · 第四单元 走近国家机构","grade":"8b","tags":["八年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第四单元 走近国家机构"},{"k":"课题","v":"第12课 国家司法机关"},{"k":"框题","v":"人民法院 / 人民检察院"}]},{"type":"note","title":"本课在单元中的位置","text":"国家机构由宪法组织并授予职权：全国人民代表大会是最高国家权力机关，行使立法权、决定权、任免权、监督权；中华人民共和国主席由全国人民代表大会选举产生，依法行使公布法律、发布命令、任免、荣典、外交等职权；国务院是最高国家行政机关，必须依法行政；中央军事委员会领导全国武装力量，实行主席负责制；监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员监察全覆盖；人民法院行使审判权，人民检察院行使检察权。这一单元的命题套路极稳定——给一段机关履职的材料，问「这是哪一类国家机关、行使什么职权、对谁负责」，机关性质与职权一个字都不能错位。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["人民法院","人民检察院"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"了解","text":"公民要尊重司法权威，尊重人民法院、人民检察院依法作出的判决和决定，依法行使诉讼权利、履行诉讼义务；维护司法公正需要全社会的共同努力。","explain":"多作为材料题最后一问出现，问「作为公民／中学生，你能为公正司法做些什么」。答题落点：尊重司法权威，不无理缠讼、不干扰司法机关依法办案；依法行使诉讼权利、履行诉讼义务；发现违法犯罪行为及时举报；学习法律知识，增强法治意识。"},{"level":"重点","text":"地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规的遵守和执行；讨论和决定本行政区域内的重大事项，监督本级人民政府、监察委员会、人民法院和人民检察院的工作。","explain":"常与基层治理、地方立法、地方政府工作报告等材料合考。答题要写清「地方国家权力机关」这个性质，再写它在本行政区域内保证宪法、法律、行政法规的遵守和执行；注意地方各级人民代表大会与地方各级人民政府不是一回事：前者是权力机关，后者是它的执行机关。"},{"level":"次重点","text":"人民法院是国家的审判机关，行使审判权；人民检察院是国家的法律监督机关，行使检察权；人民法院、人民检察院依照法律规定独立行使审判权、检察权，不受行政机关、社会团体和个人的干涉，必须坚持公正司法，坚持以事实为根据、以法律为准绳。","explain":"归类题必须分清：人民法院行使审判权，审理案件、作出判决；人民检察院行使检察权，是国家的法律监督机关，依法提起公诉。答题补两点：一是「人民法院、人民检察院对人民代表大会负责，受人民代表大会监督」；二是「公正司法要求做到事实认定符合客观真相、办案结果符合实体公正、办案程序符合程序公正」。不要把人民检察院写成「审判机关」，也不要把人民法院写成「法律监督机关」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["人民法院是国家的审判机关，人民检察院是国家的法律监督机关，依照法律规定独立行使审判权、检察权，不受行政机关、社会团体和个人的干涉。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["人民检察院是国家的审判机关，人民法院是国家的法律监督机关。","人民法院是国家的审判机关，行使审判权，依法审理案件、作出判决；人民检察院是国家的法律监督机关，行使检察权，依法提起公诉、进行法律监督。二者都由人民代表大会产生，对它负责，受它监督。","「审判」与「法律监督」两个身份一旦互换，选择题必错、材料题不得分。判断口诀：审案子、下判决的是人民法院；批捕、提起公诉、法律监督的是人民检察院。"]]},{"type":"table","title":"国家机关对比表：产生方式、性质、主要职权与对谁负责（国家权力机关与由它产生的其他国家机构在四个维度上的对照，是「是哪一类国家机关、行使什么职权」类试题的判断工具）（本单元概念对比）","head":["比较项","人民代表大会（国家权力机关）","由人民代表大会产生的其他国家机构"],"rows":[["产生方式","由人民民主选举产生，对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生；中华人民共和国主席、副主席和中央军事委员会主席由全国人民代表大会选举产生"],["性质","国家权力机关，全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；地方各级人民代表大会是地方国家权力机关","中华人民共和国主席是国家元首；国务院即中央人民政府，是最高国家行政机关；中央军事委员会领导全国武装力量；各级监察委员会是行使国家监察职能的专责机关（国家监察委员会是最高监察机关）；人民法院是国家的审判机关；人民检察院是国家的法律监督机关"],["主要职权","立法权、决定权、任免权、监督权；全国人民代表大会和全国人民代表大会常务委员会行使国家立法权","国家主席：公布法律、发布命令，任免国务院组成人员，授予国家勋章和荣誉称号，进行国事活动、接受外国使节等；国务院：行使行政管理职权；中央军事委员会：领导全国武装力量，实行主席负责制；监察委员会：履行监督、调查、处置职责；人民法院：行使审判权；人民检察院：行使检察权"],["对谁负责","对人民负责，受人民监督","国家行政机关、监察机关、审判机关、检察机关对人民代表大会负责，受人民代表大会监督；中央军事委员会主席、国家监察委员会对全国人民代表大会及其常务委员会负责；地方各级监察委员会对本级人民代表大会及其常务委员会和上一级监察委员会负责"],["履职要求","代表人民行使国家权力，反映人民意愿，接受人民监督；人大代表依法参加行使国家权力，集体行使职权","依法行使职权：行政机关坚持依法行政、法定职责必须为、法无授权不可为；人民法院、人民检察院依照法律规定独立行使审判权、检察权；监察机关依照法律规定独立行使监察权"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["国家机关的性质与职权判断（材料对应型）","给一段机关活动情境，问「材料中的机关属于哪一类国家机关」「行使了什么职权」。答题两步：先答机关性质（国家权力机关／国家行政机关／国家的审判机关／国家的法律监督机关／行使国家监察职能的专责机关），再答职权名称并对应材料。判断口诀：制定或修改法律、审查批准计划和预算、选举任免国家机关领导人员的是国家权力机关；发布行政法规、进行行政管理、提供公共服务的是国家行政机关；审理案件、作出判决的是人民法院；提起公诉、法律监督的是人民检察院；对公职人员调查处置的是监察机关。"],["「对谁负责、受谁监督」的关系题","常以「某机关向人民代表大会报告工作」「人民代表大会听取和审议工作报告」「对某机关工作进行满意度测评」等素材设问。答题核心是一句话链条：国家的一切权力属于人民 → 人民通过民主选举产生国家权力机关 → 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督 → 国家权力始终掌握在人民手中。若涉及中央军事委员会或国家监察委员会，要答「对全国人民代表大会及其常务委员会负责」。"],["国家主席职权的限定语考查","材料给国家主席签署主席令公布法律、颁授国家勋章和荣誉称号、接受外国驻华使节递交国书、宣布进入紧急状态等情境，问「国家主席行使了哪些职权」。答题按「公布法律、发布命令」「任免」「荣典」「外交」分类作答，并写出「根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定」这一限定语，同时点出「中华人民共和国主席由全国人民代表大会选举产生，每届任期同全国人民代表大会每届任期相同」。"],["依法行政与政务公开（与第五单元交叉命题）","以政府推进政务服务改革、公开权力清单、整治不作为慢作为、行政复议纠正违法行政行为等材料设问，答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。这一角度常与建设法治政府合并设问，两处术语可通用。"]]},{"type":"quote","text":"【材料一】全国人民代表大会会议听取和审议国务院政府工作报告、最高人民法院工作报告、最高人民检察院工作报告，审查和批准国民经济和社会发展计划和计划执行情况的报告、国家的预算和预算执行情况的报告，审议并通过了有关法律；会议选举和决定任命了新一届国家机关领导人员。\n【材料二】国家主席签署主席令，公布全国人民代表大会通过的法律；根据全国人民代表大会常务委员会的决定，国家主席为作出突出贡献的功勋人物颁授国家勋章和荣誉称号，并接受外国驻华使节递交的国书。\n【材料三】某市深入推进政务服务改革，公开权力清单和责任清单，简化审批环节、压缩办事时限，开通政务服务便民热线；该市监察委员会对窗口单位工作人员不作为、慢作为问题依法开展调查处置，并对相关人员依法作出处理。","source":"材料研读 · 与本课相关的教材素材"},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第四单元·走进国家机构（第7—12课：国家权力机关 · 中华人民共和国主席 · 国家行政机关 · 中央军事委员会 · 国家监察机关 · 国家司法机关）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-6"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-6-q1","type":"choice","stem":"我国的最高国家权力机关是","answer":"B","explain":"全国人民代表大会是最高国家权力机关，它的常设机关是全国人民代表大会常务委员会；国务院是最高国家行政机关；最高人民法院是最高国家审判机关；最高人民检察院是最高国家法律监督机关。四个「最高」要一一对应，不能错位。","options":["国务院","全国人民代表大会","最高人民法院","最高人民检察院"],"difficulty":1,"tags":["国家权力机关","国家机关性质"]},{"id":"pol-law-6-q5","type":"choice","stem":"中华人民共和国中央军事委员会的领导体制和负责对象是","answer":"B","explain":"宪法规定，中华人民共和国中央军事委员会领导全国武装力量，由主席、副主席、委员组成，实行主席负责制，每届任期同全国人民代表大会每届任期相同；中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。中央军事委员会不对国务院负责。","options":["实行委员会集体负责制，对国务院负责","实行主席负责制，中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责","实行主席负责制，对国务院和国防部负责","实行首长分工负责制，对最高人民法院负责"],"difficulty":3,"tags":["中央军事委员会","国家机构"]},{"id":"pol-law-6-q6","type":"choice","stem":"关于国家监察机关，下列说法正确的是","answer":"B","explain":"各级监察委员会是行使国家监察职能的专责机关，国家监察委员会是最高监察机关，对所有行使公权力的公职人员依法进行监察，实现国家监察全覆盖。A 错，监察委员会不是政府的部门，不受政府领导；C 错，监察对象是所有行使公权力的公职人员，不是所有公民；D 错，监察机关由本级人民代表大会产生，对产生它的国家权力机关和上一级监察委员会负责。","options":["监察委员会是政府的一个部门，受本级人民政府领导","监察委员会是行使国家监察职能的专责机关，对所有行使公权力的公职人员依法进行监察","监察委员会依法履行监督、调查、处置职责，可以对所有公民进行调查","监察委员会由人民法院产生，对人民法院负责"],"difficulty":3,"tags":["国家监察机关","行政与监察"]},{"id":"pol-law-6-q7","type":"choice","stem":"某县人民检察院对一起涉嫌污染环境案件的犯罪嫌疑人依法提起公诉。这表明人民检察院","answer":"B","explain":"人民检察院是国家的法律监督机关，行使检察权，依法提起公诉是其履行职责的重要方式。人民法院才是国家的审判机关；行政机关是各级人民政府；国家权力机关是人民代表大会。","options":["是国家的审判机关，行使审判权","是国家的法律监督机关，行使检察权","是国家的行政机关，行使行政管理职权","是国家权力机关，行使监督权"],"difficulty":2,"tags":["国家司法机关","审判机关与法律监督机关"]},{"id":"cat-pol-8b-4-6-short","type":"short","stem":"某班围绕「国家司法机关」开展主题探究活动，围绕「人民法院」、「人民检察院」。请运用本课所学，谈谈你的认识。","answer":"公民要尊重司法权威，尊重人民法院、人民检察院依法作出的判决和决定，依法行使诉讼权利、履行诉讼义务；维护司法公正需要全社会的共同努力。地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规的遵守和执行；讨论和决定本行政区域内的重大事项，监督本级人民政府、监察委员会、人民法院和人民检察院的工作。","explain":"","rubric":["公民要尊重司法权威，尊重人民法院、人民检察院依法作出的判决和决定，依法行使诉讼权…","地方各级人民代表大会是地方国家权力机关，在本行政区域内，保证宪法、法律、行政法规…","人民法院是国家的审判机关，行使审判权；人民检察院是国家的法律监督机关，行使检察权…"],"tags":["国家司法机关"]}]},{"id":"cat-pol-8b-5-1","title":"第13课 坚持全面依法治国","subtitle":"八年级下册 · 第五单元 建设法治中国","grade":"8b","tags":["八年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第五单元 建设法治中国"},{"k":"课题","v":"第13课 坚持全面依法治国"},{"k":"框题","v":"全面依法治国的指导思想 / 全面依法治国的基本要求"}]},{"type":"note","title":"本课在单元中的位置","text":"法治是现代政治文明的核心、治国理政的基本方式，全面依法治国是中国特色社会主义的本质要求和重要保障，总目标是建设中国特色社会主义法治体系、建设社会主义法治国家，基本要求是科学立法、严格执法、公正司法、全民守法，并坚持法治国家、法治政府、法治社会一体建设；国家和社会治理需要法律和道德共同发挥作用，法治与德治相得益彰。这一单元是道法「怎么办」类设问的术语仓库：凡是问「怎样坚持全面依法治国」「怎样以法治推进国家治理现代化」，得分点几乎全在这里。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["全面依法治国的指导思想","全面依法治国的基本要求"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"全面依法治国是中国特色社会主义的本质要求和重要保障；全面推进依法治国的总目标是建设中国特色社会主义法治体系，建设社会主义法治国家。","explain":"必背结论，选择题常把总目标写成「建设社会主义法治体系，建设中国特色社会主义法治国家」（两个定语互换）来设误，一定要按原文顺序写。材料题问「全面依法治国的总目标是什么」，照写即可；问「为什么要全面依法治国」，先写「是中国特色社会主义的本质要求和重要保障」，再写「法治是国家治理体系和治理能力现代化的重要标志」。"},{"level":"重点","text":"全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。","explain":"十六字方针是本单元最高频的得分点，材料题给四种不同主体的做法就要求逐项对应：立法机关公开征求意见、提高立法质量是科学立法；执法机关规范执法、纠正不作为乱作为是严格执法；司法机关以事实为根据、以法律为准绳，纠正冤错案件是公正司法；开展法治宣传教育、公民自觉守法是全民守法。作答格式固定为「要求名称 + 材料对应」，「科学立法」「严格执法」「公正司法」「全民守法」四个词一个字都不能改。"},{"level":"重点","text":"坚持法治国家、法治政府、法治社会一体建设；法治政府就是按照法治原则运作的政府，政府的各项权力都应该在法治轨道上运行。","explain":"考「怎样坚持全面依法治国」时要先答「一体建设」这一总体要求，再分述：法治国家是目标，法治政府是重点，法治社会是基础。法治政府的定义要写「按照法治原则运作的政府」「各项权力都应该在法治轨道上运行」，不要写成「有法律的政府」或「政府自己制定规则」。"},{"level":"了解","text":"全面依法治国需要全社会的共同努力：政府及其工作人员要率先做尊法守法的榜样，带动全体公民共同守法；社会要弘扬法治精神，共同营造良好的法治文化环境。","explain":"作为「怎么办」类设问的收尾句使用，多与「人人参与、人人共享」的表述连用。答题可写「全面依法治国是全社会共同的责任，需要国家机关、社会组织和全体公民共同努力，弘扬法治精神，营造尊法学法守法用法的良好氛围」。不必展开，但不能漏。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["全面依法治国是中国特色社会主义的本质要求和重要保障；全面推进依法治国的总目标是建设中国特色社会主义法治体系，建设社会主义法治国家。","全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。","法律与道德相辅相成，法治与德治相得益彰；国家和社会治理需要法律和道德共同发挥作用，坚持依法治国和以德治国相结合。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["「法制」与「法治」是一回事，都是指有法律、依法办事。","法制是法律制度的简称，侧重静态的法律和制度；法治是依法治理，强调法律在国家治理中具有最高权威，一切组织和个人都要依法办事，侧重治国理政的方式。我国的表述是「全面依法治国」「建设法治国家」，不是「法制国家」。","一字之差，指向完全不同。「法制」解决「有没有法」，「法治」解决「法大还是权大」。写答案时一律用「法治」：「坚持全面依法治国」「法治政府」「法治社会」「增强法治意识」，写成「法制政府」「加强法制意识」即为术语错误。"],["建设法治国家只是国家机关的事，与普通公民没有关系。","厉行法治是对全体社会成员的要求：国家机关要依法行使职权，政府及其工作人员要率先做尊法守法的榜样；公民也必须在宪法和法律规定的范围内行使权利、履行义务，增强尊法学法守法用法意识，依法办事、依法维权，做社会主义法治的忠实崇尚者、自觉遵守者、坚定捍卫者。","「法治只是政府的事」是常见的错误认识，也是评析题的固定设误。判断依据：法治社会是法治国家的基础，全民守法是全面依法治国的基本要求之一，缺少公民参与就没有法治社会。"],["既然要全面依法治国，就不必再讲道德了，法律可以解决一切问题。","国家和社会治理需要法律和道德共同发挥作用：法律具有规范作用，道德具有教化作用，二者相辅相成、相得益彰。以法治体现道德理念，强化法律对道德建设的促进作用；以道德滋养法治精神，强化道德对法治文化的支撑作用。法律解决不了所有问题，必须坚持依法治国和以德治国相结合。","「法律万能」与「道德万能」都是片面观点。答题时既不能只写法律，也不能只写道德，规范答法是「法律的规范作用 + 道德的教化作用 + 二者相辅相成、相得益彰」。"]]},{"type":"table","title":"法制与法治（一字之差、含义不同，是道法术语题最经典的对照）（本单元概念对比）","head":["比较项","法制","法治"],"rows":[["含义","法律制度的简称，指一国现行的法律和制度","依法治国、依法治理，指法律在国家治理中具有最高权威，一切组织和个人都要依法办事"],["侧重","静态的「有没有法、有哪些法」","动态的「法怎么用、权与法谁大」"],["规范搭配","完善法律制度、加强法制宣传教育（旧表述）","全面依法治国、建设法治国家、法治政府、法治社会，增强法治意识，弘扬法治精神"],["答题提醒","涉及法律和制度的建设时可用「法律制度」","凡涉及治国理政方式、法治意识、法治政府的表述，一律用「法治」"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["「十六字方针」的材料对应","给四则不同主体的材料（立法征求意见、执法规范化、纠正冤错案件、社区法治宣传等），设问「材料分别体现了全面依法治国的哪一项基本要求」。答题必须先写全「科学立法、严格执法、公正司法、全民守法」，再逐则对应说明「体现了……，因为……」。只写要求名称不对应材料、或把「严格执法」写成「公正执法」，都拿不到对应分。"],["法治与德治相结合的关系论证","材料往往一半给立法、执法、司法新闻，一半给道德模范、诚信建设、志愿者服务、文明行为促进条例。设问是「结合材料，说明国家和社会治理为什么需要法律和道德共同发挥作用」，踩分点就是「法律的规范作用 + 道德的教化作用 + 二者相辅相成、相得益彰」，最后补「坚持依法治国和以德治国相结合」。这一角度常与第一单元、第三单元的内容合并命题。"],["依法行政、政务公开与法治政府","以政府公开权力清单、推行行政执法公示、开通政务服务热线、纠正违法行政行为等材料设问「政府是怎样建设法治政府的」。答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。"],["青少年增强法治意识与依法有序参与民主生活","设问多为「作为青少年，你打算怎样为建设法治国家作贡献」「公民应怎样依法有序参与民主生活」。答案分三层：一是学法知法，增强尊法学法守法用法意识，弘扬法治精神，强化规则意识；二是守法用法，依法办事、依法维权，同违法犯罪行为作斗争；三是依法有序参与，遵守宪法和法律的要求，依照法定程序参与民主生活，增强社会责任感和主人翁意识。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第五单元·建设法治国家（第13—14课：坚持全面依法治国 · 以法治推进国家治理现代化）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-7"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-7-m1-q1","type":"short","stem":"（1）据材料一、材料二，说明我国全面依法治国的基本要求在材料中是如何体现的。（6 分）","answer":"全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。①法律草案公开征求意见、吸收合理意见并修改完善，体现科学立法，有利于提高立法质量，使法律反映人民意愿。②推行行政执法公示制度、纠正不作为慢作为、推行政务服务改革，体现严格执法和依法行政，有利于规范政府的行政权，做到法定职责必须为、法无授权不可为。③公开权力清单和责任清单、开通便民热线，体现全面推进政务公开，保障公民的知情权、参与权、表达权和监督权，接受人民监督。④公众积极参与提出意见建议，也体现了全民守法和公民依法有序参与，共同推动法治建设。","explain":"","tags":["全面依法治国","基本要求"],"rubric":["写全「科学立法、严格执法、公正司法、全民守法」","答出公开征求意见体现科学立法（或民主立法）","答出执法公示、纠正不作为体现严格执法","答出公开权力清单、便民热线体现政务公开与接受监督","答出依法行政、规范政府的行政权","要求名称与材料一一对应、分点作答"]},{"id":"pol-law-7-q1","type":"choice","stem":"全面推进依法治国的总目标是","answer":"B","explain":"全面推进依法治国的总目标是建设中国特色社会主义法治体系，建设社会主义法治国家，两个定语的顺序不能互换，A 项即属于典型设误。C 项是全面依法治国的基本要求，D 项是法治国家、法治政府、法治社会一体建设中的具体目标，都不是总目标。","options":["建设社会主义法治体系，建设中国特色社会主义法治国家","建设中国特色社会主义法治体系，建设社会主义法治国家","实现科学立法、严格执法、公正司法、全民守法","建设法治政府，建成法治社会"],"difficulty":2,"tags":["全面依法治国","总目标"]},{"id":"pol-law-7-q2","type":"choice","stem":"全面依法治国的基本要求是","answer":"A","explain":"全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。B 项是旧的社会主义法制建设方针的表述；C 项是「依法治国、依法执政、依法行政共同推进」的相近说法，不是基本要求；D 项不是规范表述（法治国家、法治政府、法治社会一体建设是总体要求）。","options":["科学立法、严格执法、公正司法、全民守法","有法可依、有法必依、执法必严、违法必究","依法治国、依法执政、依法行政、依法办事","法治国家、法治政府、法治社会、法治公民"],"difficulty":1,"tags":["全面依法治国","基本要求"]},{"id":"pol-law-7-q4","type":"choice","stem":"「法制」与「法治」一字之差，含义不同。下列表述正确的是","answer":"B","explain":"法治是依法治理，强调法律在国家治理中具有最高权威，我国坚持全面依法治国，建设社会主义法治国家，增强全民法治意识。A 项把「法治」误写成「法制」；C 项否认二者区别，「法制」侧重静态的法律制度，「法治」侧重治国理政方式；D 项把法治简化为「多立法」，忽略了严格执法、公正司法和全民守法。","options":["我国坚持全面依法制国，建设社会主义法制国家","我国坚持全面依法治国，建设社会主义法治国家，增强全民法治意识","法制与法治含义完全相同，可以互相替换使用","法治就是制定更多的法律，做到有法可依"],"difficulty":3,"tags":["法制与法治","法治意识"]},{"id":"pol-law-7-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 法治是现代政治文明的核心，是发展市场经济、实现强国富民的基本保障，是解决社会矛盾…\n② 全面依法治国是中国特色社会主义的本质要求和重要保障；全面推进依法治国的总目标是建…\n③ 全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。\n④ 「法制」与「法治」是一回事，都是指有法律、依法办事。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——一字之差，指向完全不同。「法制」解决「有没有法」，「法治」解决「法大还是权大」。写答案时一律用「法治」：「坚持全面依法治国」「法治政府」「法治社会」「增强法治意识」，写成「法制政府」「加强法制意识」即为术语错误；正确表述应为：法制是法律制度的简称，侧重静态的法律和制度；法治是依法治理，强调法律在国家治理中具有最高权威，一切组织和个人都要依法办事，侧重治国理政的方式。我国的表述是「全面依法治国」「建设法治国家」，不是「法制国家」。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第五单元·建设法治国家（第13—14课：坚持全面依法治国 · 以法治推进国家治理现代化）"]}]},{"id":"cat-pol-8b-5-2","title":"第14课 以法治推进国家治理现代化","subtitle":"八年级下册 · 第五单元 建设法治中国","grade":"8b","tags":["八年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"八年级下册"},{"k":"单元","v":"第五单元 建设法治中国"},{"k":"课题","v":"第14课 以法治推进国家治理现代化"},{"k":"框题","v":"法治与改革相互促进 / 法治与德治相得益彰"}]},{"type":"note","title":"本课在单元中的位置","text":"法治是现代政治文明的核心、治国理政的基本方式，全面依法治国是中国特色社会主义的本质要求和重要保障，总目标是建设中国特色社会主义法治体系、建设社会主义法治国家，基本要求是科学立法、严格执法、公正司法、全民守法，并坚持法治国家、法治政府、法治社会一体建设；国家和社会治理需要法律和道德共同发挥作用，法治与德治相得益彰。这一单元是道法「怎么办」类设问的术语仓库：凡是问「怎样坚持全面依法治国」「怎样以法治推进国家治理现代化」，得分点几乎全在这里。"},{"type":"h","text":"课本框题"},{"type":"list","title":"本课框题（按课本顺序）","items":["法治与改革相互促进","法治与德治相得益彰"]},{"type":"points","title":"本课核心知识 · 中考考点分层","items":[{"level":"重点","text":"国家和社会治理需要法律和道德共同发挥作用，既重视发挥法律的规范作用，又重视发挥道德的教化作用；以法治体现道德理念，强化法律对道德建设的促进作用；以道德滋养法治精神，强化道德对法治文化的支撑作用；法律与道德相辅相成，法治与德治相得益彰。","explain":"「法治与德治相结合」的完整表述，材料题常一半给立法执法新闻、一半给道德模范或诚信建设，设问「为什么国家和社会治理需要法律和道德共同发挥作用」。踩分点是「法律的规范作用 + 道德的教化作用 + 二者相辅相成、相得益彰」，最后补一句「坚持依法治国和以德治国相结合」。"},{"level":"重点","text":"法治是国家治理体系和治理能力现代化的重要标志；要在法治轨道上推进国家治理体系和治理能力现代化，坚持依法治国、依法执政、依法行政共同推进，实现国家治理的制度化、规范化、程序化。","explain":"本单元新增的落点，材料题设问「为什么要以法治推进国家治理现代化」「法治在国家治理中发挥什么作用」。答题三层：一是法治是国家治理体系和治理能力现代化的重要标志；二是法治能够为经济社会发展提供根本性、全局性、稳定性、长期性的制度保障；三是要在法治轨道上推进国家治理现代化，做到依法治国、依法执政、依法行政共同推进。"}]},{"type":"note","title":"考点覆盖说明","text":"现有单元条目对本课只单列了少量核心观点，其余内容请结合本课框题和单元主线学习；配套练习中含所属单元的综合题。"},{"type":"note","title":"考点分级说明","text":"「重点」要能默写教材规范表述；「次重点」要能再认细节；「了解」层级多以选择题、判断题出现。"},{"type":"list","title":"必背金句与答题术语","items":["法律与道德相辅相成，法治与德治相得益彰；国家和社会治理需要法律和道德共同发挥作用，坚持依法治国和以德治国相结合。"]},{"type":"table","title":"易错辨析","head":["错误表述","正确表述","原因"],"rows":[["既然要全面依法治国，就不必再讲道德了，法律可以解决一切问题。","国家和社会治理需要法律和道德共同发挥作用：法律具有规范作用，道德具有教化作用，二者相辅相成、相得益彰。以法治体现道德理念，强化法律对道德建设的促进作用；以道德滋养法治精神，强化道德对法治文化的支撑作用。法律解决不了所有问题，必须坚持依法治国和以德治国相结合。","「法律万能」与「道德万能」都是片面观点。答题时既不能只写法律，也不能只写道德，规范答法是「法律的规范作用 + 道德的教化作用 + 二者相辅相成、相得益彰」。"]]},{"type":"table","title":"中考命题角度 · 所属单元常见考法","head":["命题角度","说明"],"rows":[["「十六字方针」的材料对应","给四则不同主体的材料（立法征求意见、执法规范化、纠正冤错案件、社区法治宣传等），设问「材料分别体现了全面依法治国的哪一项基本要求」。答题必须先写全「科学立法、严格执法、公正司法、全民守法」，再逐则对应说明「体现了……，因为……」。只写要求名称不对应材料、或把「严格执法」写成「公正执法」，都拿不到对应分。"],["法治与德治相结合的关系论证","材料往往一半给立法、执法、司法新闻，一半给道德模范、诚信建设、志愿者服务、文明行为促进条例。设问是「结合材料，说明国家和社会治理为什么需要法律和道德共同发挥作用」，踩分点就是「法律的规范作用 + 道德的教化作用 + 二者相辅相成、相得益彰」，最后补「坚持依法治国和以德治国相结合」。这一角度常与第一单元、第三单元的内容合并命题。"],["依法行政、政务公开与法治政府","以政府公开权力清单、推行行政执法公示、开通政务服务热线、纠正违法行政行为等材料设问「政府是怎样建设法治政府的」。答案落在「依法行政是现代法治政府行使权力普遍奉行的基本准则，核心是规范政府的行政权」「法定职责必须为、法无授权不可为」「全面推进政务公开，保障公民的知情权、参与权、表达权和监督权」「有权必有责、用权受监督、违法必追究」。"],["青少年增强法治意识与依法有序参与民主生活","设问多为「作为青少年，你打算怎样为建设法治国家作贡献」「公民应怎样依法有序参与民主生活」。答案分三层：一是学法知法，增强尊法学法守法用法意识，弘扬法治精神，强化规则意识；二是守法用法，依法办事、依法维权，同违法犯罪行为作斗争；三是依法有序参与，遵守宪法和法律的要求，依照法定程序参与民主生活，增强社会责任感和主人翁意识。"]]},{"type":"links","title":"专题精讲与配套练习","items":[{"t":"专题精讲 · 第五单元·建设法治国家（第13—14课：坚持全面依法治国 · 以法治推进国家治理现代化）","url":"/learn/politics/pages/detail/detail?moduleId=pol-law&entryId=pol-law-7"},{"t":"模块测试与模拟卷","url":"/learn/politics-exam/pages/list/list?moduleId=pol-papers"},{"t":"道法中考题型专题","url":"/learn/politics/pages/list/list?moduleId=pol-exam"}]}],"questions":[{"id":"pol-law-7-m1-q2","type":"short","stem":"（2）结合材料三，说明国家和社会治理为什么需要法律和道德共同发挥作用。（4 分）","answer":"①法律具有规范作用，通过规定人们可以做什么、必须做什么、禁止做什么，为治理提供刚性约束，把道德要求写进法规，能够以法治体现道德理念，强化法律对道德建设的促进作用。②道德具有教化作用，评选道德模范、开展诚信建设和法治宣传教育，能够提高人们的道德觉悟和文明素养，以道德滋养法治精神，强化道德对法治文化的支撑作用。③法律与道德相辅相成，法治与德治相得益彰，法律的实施需要道德的支撑，道德的践行也离不开法律的保障。④因此国家和社会治理需要法律和道德共同发挥作用，必须坚持依法治国和以德治国相结合。","explain":"","tags":["法治与德治","法律与道德"],"rubric":["答出法律的规范作用","答出道德的教化作用","答出以法治体现道德理念、以道德滋养法治精神","答出法律与道德相辅相成、法治与德治相得益彰"]},{"id":"pol-law-7-q5","type":"choice","stem":"某市把尊老爱幼、诚实守信、爱护环境等道德要求写进文明行为促进条例，同时开展道德模范评选和法治宣传教育活动。这一做法说明","answer":"A","explain":"把道德要求写进法规，是以法治体现道德理念；开展道德模范评选和法治宣传，是以道德滋养法治精神，说明法律与道德相辅相成、法治与德治相得益彰，国家和社会治理需要法律和道德共同发挥作用。B、C 都是「道德万能」或「法律万能」的片面观点；D 错，道德靠内心信念和社会舆论维持，不具有国家强制力。","options":["法律与道德相辅相成，法治与德治相得益彰","道德可以代替法律发挥作用，不必再制定法规","只要加强法治建设，就不需要进行道德建设","法律和道德都由人民法院强制执行"],"difficulty":2,"tags":["法治与德治","法律与道德"]},{"id":"pol-law-7-q6","type":"choice","stem":"关于法治在国家治理中的作用，下列认识正确的是","answer":"A","explain":"法治是国家治理体系和治理能力现代化的重要标志，要在法治轨道上推进国家治理体系和治理能力现代化，实现国家治理的制度化、规范化、程序化。B 项忽视法治的作用；C 项把法治等同于严刑峻法，法治的目的是规范权力运行、保障公民权利；D 项错误，一切组织和个人都必须在宪法和法律规定的范围内活动，国家机关及其工作人员更要依法行使职权。","options":["法治是国家治理体系和治理能力现代化的重要标志，要在法治轨道上推进国家治理现代化","国家治理只需要依靠道德教化，法治可有可无","法治就是严刑峻法，与保障公民权利相互对立","法治只约束公民，不约束国家机关及其工作人员"],"difficulty":2,"tags":["法治与国家治理","国家治理现代化"]},{"id":"pol-law-7-combo","type":"choice","stem":"关于本专题，下列表述正确的有\n① 法治是现代政治文明的核心，是发展市场经济、实现强国富民的基本保障，是解决社会矛盾…\n② 全面依法治国是中国特色社会主义的本质要求和重要保障；全面推进依法治国的总目标是建…\n③ 全面依法治国的基本要求是科学立法、严格执法、公正司法、全民守法。\n④ 「法制」与「法治」是一回事，都是指有法律、依法办事。","answer":"A","explain":"①②③取自本专题「核心观点与考点」；④属易错表述——一字之差，指向完全不同。「法制」解决「有没有法」，「法治」解决「法大还是权大」。写答案时一律用「法治」：「坚持全面依法治国」「法治政府」「法治社会」「增强法治意识」，写成「法制政府」「加强法制意识」即为术语错误；正确表述应为：法制是法律制度的简称，侧重静态的法律和制度；法治是依法治理，强调法律在国家治理中具有最高权威，一切组织和个人都要依法办事，侧重治国理政的方式。我国的表述是「全面依法治国」「建设法治国家」，不是「法制国家」。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["第五单元·建设法治国家（第13—14课：坚持全面依法治国 · 以法治推进国家治理现代化）"]},{"id":"pol-law-7-q7","type":"choice","stem":"某市就调整自来水价格举行听证会，邀请消费者代表、经营者代表、专家学者和政府部门人员参加。作为中学生，如果受邀参加这类活动，正确的做法是","answer":"B","explain":"公民参与民主生活要遵守宪法和法律的要求，依照法律法规规定的程序，正确行使自己的民主权利，理性表达意见并尊重他人意见，同时增强社会责任感和主人翁意识。A、D 是以非法方式表达诉求；C 项缺乏社会责任感，没有认真行使民主权利；只有 B 项符合依法有序参与民主生活的要求。","options":["为引起重视，在会场大声吵闹，迫使主办方接受自己的意见","事先了解相关法律政策和实际情况，依照法定程序理性表达意见，同时尊重他人的意见","认为自己人微言轻，随便投一票应付了事","在网络上发布未经核实的消息，给主办方施加压力"],"difficulty":2,"tags":["依法有序参与","民主意识"]}]}];
